function normalizePlatformName(value){
  const raw = String(value || '').trim().replace(/\s+/g, ' ');
  if(!raw) return '';
  const key = raw.toLowerCase().replace(/[\s_-]+/g, '');
  const aliases = {
    fc:'FC', famicom:'FC', 'ファミコン':'FC', 'ファミリーコンピュータ':'FC',
    fds:'FDS', 'ディスクシステム':'FDS', 'ファミコンディスクシステム':'FDS',
    gb:'GB', gbc:'GB', gameboy:'GB', gameboycolor:'GB', 'ゲームボーイ':'GB', 'ゲームボーイカラー':'GB',
    gba:'GBA', gameboyadvance:'GBA', 'ゲームボーイアドバンス':'GBA',
    sfc:'SFC', snes:'SFC', superfamicom:'SFC', 'スーファミ':'SFC', 'スーパーファミコン':'SFC',
    n64:'N64', 'ニンテンドー64':'N64', gc:'GC', gamecube:'GC', 'ゲームキューブ':'GC',
    wii:'WII', wiiu:'WIIU', ds:'DS', nds:'DS', 'ニンテンドーds':'DS', '3ds':'3DS',
    vb:'VB', virtualboy:'VB', mark3:'MARK3', segamark3:'MARK3', sg:'SG', sg1000:'SG',
    md:'MD', megadrive:'MD', 'メガドライブ':'MD', ss:'SS', saturn:'SS', 'セガサターン':'SS',
    dc:'DC', dreamcast:'DC', 'ドリームキャスト':'DC', pce:'PCE', pcengine:'PCE', 'pcエンジン':'PCE',
    pcfx:'PCFX', ps:'PS', ps1:'PS', playstation:'PS', 'プレイステーション':'PS',
    ps2:'PS2', ps3:'PS3', ps4:'PS4', ps5:'PS5', psp:'PSP',
    vita:'PSVITA', psvita:'PSVITA', playstationvita:'PSVITA', 'psvita':'PSVITA', 'プレイステーションvita':'PSVITA', 'ヴィータ':'PSVITA',
    switch:'SWITCH', nintendoswitch:'SWITCH', 'ニンテンドースイッチ':'SWITCH',
    '3do':'3DO', ng:'NG', neogeo:'NG', 'ネオジオ':'NG',
    ncd:'NCD', neogeocd:'NCD', ws:'WS', wsc:'WS', wonderswan:'WS', 'ワンダースワン':'WS',
    xbox:'XBOX', x360:'X360', xbox360:'X360', xone:'XONE', xboxone:'XONE', xsx:'XSX', xboxseries:'XSX', xboxseriesx:'XSX', xboxseriess:'XSX', pc:'PC'
  };
  return aliases[key] || raw;
}

function isSharedPlatform(value){
  return platforms.includes(normalizePlatformName(value));
}

function allCollectionPlatforms(){
  // 一覧の機種絞り込みは、実際に登録されているカードの機種だけを表示する。
  // 旧版に混入した PS6 は候補として再表示しない。
  const invalid = new Set(['PS6']);
  const fromEntries = [...new Set((state.entries || [])
    .map(e => normalizePlatformName(e.platform))
    .filter(p => p && !invalid.has(p)))];
  const ordered = PLATFORM_SUGGESTIONS.filter(p => fromEntries.includes(p));
  const extras = fromEntries.filter(p => !PLATFORM_SUGGESTIONS.includes(p))
    .sort((a,b) => a.localeCompare(b, 'ja'));
  return [...ordered, ...extras];
}

function updatePlatformOptions(){
  const field = $('platform');
  const datalist = $('platformSuggestions');
  const filter = $('filterPlatform');
  const currentField = normalizePlatformName(field?.value || '');
  const currentFilter = filter?.value || '';
  const entryPlatforms = (state.entries || []).map(e => normalizePlatformName(e.platform)).filter(Boolean);
  const suggestions = [...new Set([...PLATFORM_SUGGESTIONS, ...entryPlatforms])];
  if(datalist){
    datalist.innerHTML = suggestions.map(p => `<option value="${esc(p)}"></option>`).join('');
  }
  if(filter){
    const values = allCollectionPlatforms();
    filter.innerHTML = '<option value="">全機種</option>' + values.map(p => `<option value="${esc(p)}">${esc(p)}</option>`).join('');
    if(values.includes(currentFilter)) filter.value = currentFilter;
  }
  if(field && currentField && field.value !== currentField) field.value = currentField;
  if($('platformPickerMenu') && !$('platformPickerMenu').hidden) renderPlatformPickerMenu();
}

function getPlatformPickerSuggestions(){
  const current = normalizePlatformName($('platform')?.value || '');
  const entryPlatforms = (state.entries || []).map(e => normalizePlatformName(e.platform)).filter(Boolean);
  const values = [...new Set([current, ...PLATFORM_SUGGESTIONS, ...entryPlatforms].filter(Boolean))];
  return values;
}

function renderPlatformPickerMenu(){
  const menu = $('platformPickerMenu');
  if(!menu) return;
  const current = normalizePlatformName($('platform')?.value || '');
  const values = getPlatformPickerSuggestions();
  const shared = values.filter(isSharedPlatform);
  const others = values.filter(p => !isSharedPlatform(p));
  const groupHtml = (title, items) => {
    if(!items.length) return '';
    return `<div class="platform-picker-group"><div class="platform-picker-group-title">${esc(title)}</div><div class="platform-picker-options">${items.map(p => `<button type="button" class="platform-picker-option${p === current ? ' active' : ''}" data-platform-pick="${esc(p)}">${esc(p)}</button>`).join('')}</div></div>`;
  };
  menu.innerHTML = groupHtml('共有図鑑対応', shared) + groupHtml('その他の機種', others);
}

function openPlatformPicker(){
  const menu = $('platformPickerMenu');
  const btn = $('platformPickerBtn');
  if(!menu) return;
  renderPlatformPickerMenu();
  menu.hidden = false;
  btn?.setAttribute('aria-expanded', 'true');
}

function closePlatformPicker(){
  const menu = $('platformPickerMenu');
  const btn = $('platformPickerBtn');
  if(menu) menu.hidden = true;
  btn?.setAttribute('aria-expanded', 'false');
}

function updatePlatformShareNote(){
  const note = $('platformShareNote');
  if(!note) return;
  const platform = normalizePlatformName($('platform')?.value || '');
  note.classList.toggle('shared', !!platform && isSharedPlatform(platform));
  note.classList.toggle('local-only', !!platform && !isSharedPlatform(platform));
  if(!platform){
    note.textContent = '機種名を入力してください。登録済みの機種は候補に表示されます。';
  }else if(isSharedPlatform(platform)){
    note.textContent = `${platform}は共有図鑑・共有所持率・レア判定にも反映されます。`;
  }else{
    note.textContent = `${platform}はコレクション登録と一覧検索に対応します。共有図鑑・共有所持率・レア判定は対象外です。`;
  }
}

