function platformSearchLabel(platform){
  const p = String(platform || '').toUpperCase();
  const map = {
    FC:'ファミコン', FDS:'ファミコン ディスクシステム', SFC:'スーパーファミコン',
    N64:'ニンテンドウ64', GC:'ゲームキューブ', WII:'Wii', WIIU:'Wii U',
    GB:'ゲームボーイ', GBA:'ゲームボーイアドバンス', DS:'ニンテンドーDS',
    '3DS':'ニンテンドー3DS', VB:'バーチャルボーイ', MARK3:'セガ マークIII',
    SG:'SG-1000', MD:'メガドライブ', SS:'セガサターン', DC:'ドリームキャスト',
    PCE:'PCエンジン', PCFX:'PC-FX', PS:'プレイステーション', PS2:'プレイステーション2',
    PS3:'プレイステーション3', PSP:'PSP', '3DO':'3DO', NG:'ネオジオ',
    NCD:'ネオジオCD', WS:'ワンダースワン', XBOX:'Xbox', X360:'Xbox 360'
  };
  return map[p] || p;
}

function marketSearchQuery(entry){
  const e = hydrateEntryFromMaster({...entry});
  const title = String(e.title || '').trim();
  const platform = platformSearchLabel(e.platform);
  return [title, platform].filter(Boolean).join(' ').trim();
}

function fujiyaStoreSearchQuery(entry){
  // 藤や玩具店STORES検索は機種名を入れない方針
  const e = hydrateEntryFromMaster({...entry});
  return String(e.title || '').trim();
}

function marketLinksForEntry(entry){
  const e = hydrateEntryFromMaster({...entry});
  const q = encodeURIComponent(marketSearchQuery(e));
  const titleQ = encodeURIComponent(fujiyaStoreSearchQuery(e));
  return {
    mercari: `https://jp.mercari.com/search?keyword=${q}`,
    yahooAuctions: `https://auctions.yahoo.co.jp/search/search?p=${q}`,
    surugaya: `https://www.suruga-ya.jp/search?category=&search_word=${q}`,
    amazon: `https://www.amazon.co.jp/s?k=${q}`,
    fujiya: `https://stores.jp/search?q=${titleQ}&store=retrogame248`,
    asofro: `https://asofro.thebase.in/search?q=${titleQ}`,
    google: `https://www.google.com/search?q=${q}`
  };
}

