function masterToMarketEntry(master){
  const m = master || {};
  return {
    id: m.sharedTitleId || `${m.platform || ''}-${m.canonicalTitle || m.title || ''}`,
    title: m.canonicalTitle || m.title || '',
    platform: m.platform || '',
    maker: m.maker || '',
    genre: m.genre || '',
    productCode: m.productCode || '',
    sharedTitleId: m.sharedTitleId || ''
  };
}

function findMasterBySharedTitleId(sharedTitleId){
  const key = String(sharedTitleId || '');
  if(!key) return null;

  const titles = (typeof MASTER_TITLES !== 'undefined' && Array.isArray(MASTER_TITLES)) ? MASTER_TITLES : [];
  const direct = titles.find(m => String(m.sharedTitleId || '') === key);
  if(direct) return direct;

  const grouped = (typeof MASTERS !== 'undefined' && MASTERS) ? Object.values(MASTERS).flat() : [];
  return grouped.find(m => String(m.sharedTitleId || '') === key) || null;
}

const STABLE_BASELINE_VERSION = 'V7.18.37';
const STABLE_BASELINE_NOTE = 'V7.16.47を安定版として整理。図鑑みけナビはクリーン構成を維持。';

function dexNaviJs(value){
  return String(value ?? '')
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/\r?\n/g, ' ');
}

function dexNaviEntry(sharedTitleId='', title='', platform=''){
  const key = String(sharedTitleId || '').trim();
  const master = key ? findMasterBySharedTitleId(key) : null;
  if(master) return masterToMarketEntry(master);
  return {
    id:key || title || 'dex',
    title:String(title || key || 'タイトル未設定').trim(),
    platform:String(platform || '').trim(),
    maker:'',
    genre:'',
    productCode:'',
    sharedTitleId:key
  };
}

function dexNaviActionBar(entry, active='menu'){
  const e = entry || {};
  const sid = dexNaviJs(e.sharedTitleId || '');
  const title = dexNaviJs(e.title || '');
  const platform = dexNaviJs(e.platform || '');
  const cls = action => active === action ? ' active' : '';
  return `<div class="mike-entry-action-bar dex-mike-action-bar">
    <button type="button" class="mike-entry-action-btn${cls('store')}" onclick="window.fujiyaDexNaviStore('${sid}','${title}','${platform}')">ストアリンク</button>
    <button type="button" class="mike-entry-action-btn${cls('info')}" onclick="window.fujiyaDexNaviInfo('${sid}','${title}','${platform}')">ゲーム説明</button>
    <button type="button" class="mike-entry-action-btn${cls('community')}" onclick="window.fujiyaDexNaviCommunity('${sid}','${title}','${platform}')">みんなの声</button>
    <button type="button" class="mike-entry-action-btn${cls('videos')}" onclick="window.fujiyaDexNaviVideos('${sid}','${title}','${platform}')">参加動画</button>
    <button type="button" class="mike-entry-action-btn${cls('mitereco')}" onclick="window.fujiyaDexNaviMiteReco('${sid}','${title}','${platform}')">みてレコ</button>
  </div>`;
}

