async function openDexMikeNaviInfoClean(sharedTitleId='', title='', platform=''){
  const e = dexNaviEntry(sharedTitleId, title, platform);

  const cached=anyTitleMikeNaviCache(e);
  if(!cached)renderTitleMikeNaviLocalShell(e,true);

  try{
    const loaded = await loadTitleMikeNaviSummary(e, false);
    const data = loaded.data;
    const links = titleMikeNaviLinks(e);
    const points = Array.isArray(data.points) ? data.points : [];
    const fallbackPoint = String(data.extract || data.description || '').trim();
    const source = titleSummarySourceMeta(data, loaded.fromCache);

    showMikeTalkHtml(`
      <div class="title-mike-navi points-only dex-mike-info">
        <div class="title-mike-navi-cap">${esc(source.cap)}</div>
        <div class="talk-title">ゲーム説明「${esc(e.title)}」</div>
        ${dexNaviActionBar(e, 'info')}
        <div class="title-mike-points-title">ざっくり言うと…</div>
        ${points.length ? `
          <ul class="title-mike-points">
            ${points.slice(0,5).map(p => `<li>${esc(p)}</li>`).join('')}
          </ul>
        ` : `
          <ul class="title-mike-points">
            <li>${esc(fallbackPoint || '概要の要点を取得できなかったよ。')}</li>
          </ul>
        `}
        <div class="mike-talk-links">
          ${data.pageUrl ? `<a href="${esc(data.pageUrl)}" target="_blank" rel="noopener">出典：${esc(source.label)}</a>` : `<span class="talk-note">出典：${esc(source.label)}</span>`}
          <a href="${links.google}" target="_blank" rel="noopener">Googleで調べる</a>
          <a href="${links.review}" target="_blank" rel="noopener">レビュー/攻略</a>
        </div>
      </div>
    `);
    appendMikeCommunityTeaser(e, true);
  }catch(err){
    console.warn(err);
    const links = titleMikeNaviLinks(e);
    const reportable = isDescriptionMissingError(err);
    const alreadyReported = reportable && hasReportedMissingDescription(e);
    showMikeTalkHtml(`
      <div class="title-mike-navi points-only dex-mike-info">
        <div class="title-mike-navi-cap">DEX GAME INFO</div>
        <div class="talk-title">ゲーム説明「${esc(e.title)}」</div>
        ${dexNaviActionBar(e, 'info')}
        <div class="talk-note">説明取得に失敗したよ。検索リンクから確認してね。</div>
        ${reportable ? `<div class="description-report-note${alreadyReported ? ' sent' : ''}" id="descriptionReportStatus">${alreadyReported ? 'このタイトルは店長へ報告済みだよ。' : '説明未登録として店長へ自動報告するよ…'}</div>` : ''}
        <div class="mike-talk-links">
          <a href="${links.google}" target="_blank" rel="noopener">Googleで調べる</a>
          <a href="${links.wiki}" target="_blank" rel="noopener">ピコピコ大百科</a>
          <a href="${links.youtube}" target="_blank" rel="noopener">動画で見る</a>
          <a href="${links.review}" target="_blank" rel="noopener">レビュー/攻略</a>
        </div>
      </div>
    `);
    scheduleMissingDescriptionReport(e, err);
    appendMikeCommunityTeaser(e, true);
  }
}

