const FUJIYA_VIDEO_HASHTAG = 'みてコレ';

function normalizeVideoHashtagText(text){
  const raw = String(text || '').normalize ? String(text || '').normalize('NFKC') : String(text || '');
  const stripped = raw
    .replace(/[＃#]/g, '')
    .replace(/\s+/g, '')
    .replace(/[・･.,，、。:：;；!！?？'"“”‘’「」『』（）()【】\[\]<>《》\/\\|｜\-―〜～~]/g, '')
    .trim();
  const clean = stripped.replace(/[^0-9A-Za-zぁ-んァ-ヶー一-龠々〆ヵヶⅠⅡⅢⅣⅤⅥⅦⅧⅨⅩ]/g, '');
  return clean || 'タイトル未設定';
}

function videoHashtagInfo(entry){
  const e = hydrateEntryFromMaster({...entry});
  const titleSource = e.videoHashtag || e.canonicalTitle || e.title || e.sharedTitleId || '';
  const titleTag = normalizeVideoHashtagText(titleSource);
  const baseTag = FUJIYA_VIDEO_HASHTAG;
  const titlePlain = String(e.canonicalTitle || e.title || titleSource || titleTag || '').trim();
  const searchText = `#${baseTag} #${titleTag}`;
  return {
    baseTag,
    titleTag,
    titlePlain,
    searchText,
    tags:[`#${baseTag}`, `#${titleTag}`],
    youtubeSearchUrl:`https://www.youtube.com/results?search_query=${encodeURIComponent(searchText)}`,
    youtubeHashtagUrl:`https://www.youtube.com/hashtag/${encodeURIComponent(titleTag)}`,
    googleSearchUrl:`https://www.google.com/search?q=${encodeURIComponent('site:youtube.com/watch ' + baseTag + ' ' + titleTag)}`,
    title:e.title || e.canonicalTitle || titleSource || ''
  };
}

function videoHashtagPostTemplate(entry){
  const info = videoHashtagInfo(entry);
  return `${info.searchText}

みてコレ参加動画です。
対象タイトル：${info.title || info.titleTag}

※関係ある動画だけに付けてください。`;
}

async function copyTextToClipboard(text, okMessage='コピーしました'){
  try{
    await navigator.clipboard.writeText(text);
    toast(okMessage);
    return true;
  }catch(e){
    toast('コピーできませんでした');
    showMikeTalk(String(text || ''));
    return false;
  }
}


function normalizeGasEndpoint(url){
  return String(url || '')
    .trim()
    .replace(/[?#].*$/, '')
    .replace(/\/+$/, '');
}

function migrateLegacyDefaultGasEndpoint(){
  try{
    const savedRaw = String(localStorage.getItem(GAS_ENDPOINT_KEY) || '').trim();
    const saved = normalizeGasEndpoint(savedRaw);
    const latest = normalizeGasEndpoint(DEFAULT_GAS_ENDPOINT);
    const migrated = localStorage.getItem(GAS_ENDPOINT_MIGRATION_KEY) === '1';
    const isKnownLegacy = LEGACY_DEFAULT_GAS_ENDPOINTS.some(url => normalizeGasEndpoint(url) === saved);

    // 配布版が過去に使っていた既定URLだけを最新版へ移行する。
    // 店長が手動設定した別プロジェクトのGAS URLは上書きしない。
    if(!migrated && saved && saved !== latest && isKnownLegacy){
      localStorage.setItem(GAS_ENDPOINT_KEY, DEFAULT_GAS_ENDPOINT);
      localStorage.setItem(GAS_ENDPOINT_MIGRATION_KEY, '1');
      return;
    }

    // 末尾スラッシュや空白だけの差は最新版表記へ統一する。
    if(saved && saved === latest && savedRaw !== DEFAULT_GAS_ENDPOINT){
      localStorage.setItem(GAS_ENDPOINT_KEY, DEFAULT_GAS_ENDPOINT);
    }
    if(!migrated) localStorage.setItem(GAS_ENDPOINT_MIGRATION_KEY, '1');
  }catch(e){
    console.error(e);
  }
}

function browserSummary(){
  const ua = String(navigator.userAgent || '');
  let browser = '不明';
  let m = ua.match(/Edg\/([\d.]+)/);
  if(m) browser = `Edge ${m[1]}`;
  else if((m = ua.match(/Chrome\/([\d.]+)/))) browser = `Chrome ${m[1]}`;
  else if((m = ua.match(/Firefox\/([\d.]+)/))) browser = `Firefox ${m[1]}`;
  else if((m = ua.match(/Version\/([\d.]+).*Safari/))) browser = `Safari ${m[1]}`;
  const platform = String(navigator.userAgentData?.platform || navigator.platform || '不明');
  return {browser, platform};
}

function sharedSyncReportText(){
  const summary = remoteStatsSummary();
  const fetched = state.remoteStatsFetchedAt ? fmt(state.remoteStatsFetchedAt) : '未取得';
  return `${getShareOptIn() ? '参加ON' : '参加OFF'} / 自動受信${getAutoReceiveEnabled() ? 'ON' : 'OFF'} / 共有${summary.count || 0}件 / 最終取得${fetched}`;
}


function versionDisplayIsConsistent(){
  const titleOk = document.title.includes(APP_VERSION_LABEL);
  const badge = document.querySelector('.hero .badge')?.textContent || '';
  const footer = document.querySelector('footer .admin-only')?.textContent || '';
  return titleOk && badge.includes(APP_VERSION_LABEL) && footer.includes(APP_VERSION_LABEL);
}

function distributionChecks(){
  const endpoint = normalizeGasEndpoint(getGasEndpoint());
  const latestEndpoint = normalizeGasEndpoint(DEFAULT_GAS_ENDPOINT);
  const mockSaved = !!localStorage.getItem(MOCK_CROWD_KEY);
  return [
    {
      level:endpoint === latestEndpoint ? 'good' : (endpoint ? 'warn' : 'bad'),
      label:'GAS URL',
      detail:endpoint === latestEndpoint ? '最新版を設定済み' : (endpoint ? '標準URLと異なるURLが保存されています' : '未設定です')
    },
    {
      level:(!state.mockCrowdActive && !mockSaved) ? 'good' : 'bad',
      label:'水増しテストデータ',
      detail:(!state.mockCrowdActive && !mockSaved) ? 'OFF・保存なし' : '水増しを解除してください'
    },
    {
      level:RUNTIME_ERRORS.length === 0 ? 'good' : 'bad',
      label:'JavaScriptエラー',
      detail:RUNTIME_ERRORS.length === 0 ? 'この起動中は検出なし' : `${RUNTIME_ERRORS.length}件検出 / 最新：${RUNTIME_ERRORS[RUNTIME_ERRORS.length - 1]?.message || '不明'}`
    },
    {
      level:versionDisplayIsConsistent() ? 'good' : 'bad',
      label:'バージョン表記',
      detail:versionDisplayIsConsistent() ? `${APP_VERSION_LABEL}で統一` : 'ブラウザタイトル・画面・フッターに不一致があります'
    },
    {
      level:isAdminMode() ? 'warn' : 'good',
      label:'表示モード',
      detail:isAdminMode() ? '確認後に通常モードへ戻してください' : '通常モード'
    }
  ];
}

function renderDistributionPreflight(){
  const list = $('distributionCheckList');
  const summary = $('distributionCheckSummary');
  if(!list || !summary) return;
  const checks = distributionChecks();
  const mark = {good:'✓', warn:'!', bad:'×'};
  list.innerHTML = checks.map(item => `
    <div class="distribution-check-item ${item.level}">
      <span class="mark">${mark[item.level]}</span>
      <div><div>${esc(item.label)}</div><div class="sub">${esc(item.detail)}</div></div>
    </div>
  `).join('');
  const bad = checks.filter(x => x.level === 'bad').length;
  const warnCount = checks.filter(x => x.level === 'warn').length;
  summary.className = 'distribution-preflight-summary ' + (bad ? 'warn' : (warnCount ? 'warn' : 'ready'));
  summary.textContent = bad
    ? `要修正：${bad}項目あります。`
    : (warnCount ? '主要項目はOKです。最後に通常モードへ戻してください。' : '配布準備OKです。');
}

function finishDistributionPreparation(){
  if(state.mockCrowdActive || localStorage.getItem(MOCK_CROWD_KEY)){
    state.mockCrowdActive = false;
    state.mockCrowdCount = 0;
    try{ localStorage.removeItem(MOCK_CROWD_KEY); }catch(e){}
  }
  localStorage.removeItem(ADMIN_MODE_KEY);
  render();
  toast('配布準備完了：通常モードに戻しました');
  showMikeTalk('配布前チェックを終えて、通常モードに戻したよ。配布するHTML本体には、このブラウザの登録データは埋め込まれていないよ。');
}

