function videoMikeNaviCacheKey(entry){
  const info = videoHashtagInfo(entry);
  return String(entry.sharedTitleId || entry.id || info.titleTag || '').trim() + '::' + info.titleTag;
}

function getVideoMikeNaviCache(){
  try{
    const raw = localStorage.getItem(VIDEO_MIKE_NAVI_CACHE_KEY);
    const data = raw ? JSON.parse(raw) : {};
    return data && typeof data === 'object' ? data : {};
  }catch(e){
    return {};
  }
}

function setVideoMikeNaviCache(key, data){
  try{
    const cache = getVideoMikeNaviCache();
    cache[key] = {...data, cachedAt: nowIso()};
    localStorage.setItem(VIDEO_MIKE_NAVI_CACHE_KEY, JSON.stringify(cache));
  }catch(e){}
}

function cachedVideoMikeNavi(entry){
  const key = videoMikeNaviCacheKey(entry);
  const cache = getVideoMikeNaviCache();
  const item = cache[key];
  if(!item) return null;
  const cachedAtMs = item.cachedAt ? Date.parse(item.cachedAt) : 0;
  const fresh = Number.isFinite(cachedAtMs) && (Date.now() - cachedAtMs < 6 * 60 * 60 * 1000);
  return fresh ? item : null;
}

function normalizeYoutubeVideoItems(data){
  const src = Array.isArray(data?.videos) ? data.videos : (Array.isArray(data?.items) ? data.items : []);
  return src.map(item => {
    const id = item.videoId || item.id?.videoId || item.id || '';
    const snip = item.snippet || {};
    const thumbs = item.thumbnails || snip.thumbnails || {};
    const thumb = item.thumbnail || thumbs.medium?.url || thumbs.high?.url || thumbs.default?.url || '';
    const title = item.title || snip.title || '';
    const channelTitle = item.channelTitle || snip.channelTitle || '';
    const publishedAt = item.publishedAt || snip.publishedAt || '';
    const url = item.url || (id ? `https://www.youtube.com/watch?v=${encodeURIComponent(id)}` : '');
    return {videoId:String(id || ''), title:String(title || ''), channelTitle:String(channelTitle || ''), publishedAt:String(publishedAt || ''), thumbnail:String(thumb || ''), url:String(url || '')};
  }).filter(v => v.videoId && v.title && v.url).slice(0,5);
}

function fetchGasYoutubeVideosJsonp(entry, options={}){
  const url = getGasEndpoint();
  const timeoutMs = Number(options.timeoutMs || 9500);
  const info = videoHashtagInfo(entry);
  const mode = options.mode === 'general' ? 'general' : 'tagged';
  const query = mode === 'general'
    ? String(info.titlePlain || info.titleTag || entry.title || '').trim()
    : info.searchText;

  if(!url){
    return Promise.reject(new Error('共有同期URLが未設定です'));
  }

  return new Promise((resolve, reject) => {
    const callbackName = '__fujiyaYoutubeVideosCallback_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2,6);
    const script = document.createElement('script');
    let settled = false;
    const timer = setTimeout(() => {
      cleanup();
      reject(new Error('動画取得がタイムアウトしました'));
    }, timeoutMs);

    function cleanup(){
      if(settled) return;
      settled = true;
      clearTimeout(timer);
      window.fujiyaKeepLateJsonpCallback_(callbackName);
      script.remove();
    }

    window[callbackName] = data => {
      cleanup();
      if(!data || data.ok === false){
        reject(new Error(data?.message || data?.error || '動画取得APIが未対応です'));
        return;
      }
      const videos = normalizeYoutubeVideoItems(data);
      resolve({
        ok:true,
        videos,
        fetchedAt:data.fetchedAt || data.now || nowIso(),
        query:data.query || query,
        source:data.source || 'gas_youtube',
        mode:data.mode || mode
      });
    };

    script.onerror = () => {
      cleanup();
      reject(new Error('動画取得APIを読み込めませんでした'));
    };

    script.src = buildGasUrl({
      action:'youtube_videos',
      callback:callbackName,
      shared_title_id:entry.sharedTitleId || '',
      title:entry.canonicalTitle || entry.title || '',
      platform:entry.platform || '',
      video_hashtag:info.titleTag,
      q:query,
      mode,
      max:5,
      t:Date.now()
    });
    document.body.appendChild(script);
  });
}

function fmtVideoDate(value){
  const text = String(value || '');
  if(!text) return '';
  const d = new Date(text);
  if(Number.isNaN(d.getTime())) return text.slice(0,10);
  return `${d.getFullYear()}/${String(d.getMonth()+1).padStart(2,'0')}/${String(d.getDate()).padStart(2,'0')}`;
}

function cssUrl(value=''){
  return String(value || '').replace(/\\/g, '\\\\').replace(/"/g, '%22').replace(/\n/g, '');
}

function renderYoutubeVideoCards(videos, compact=false){
  if(!Array.isArray(videos) || !videos.length) return '';
  return `<div class="mike-video-grid ${compact ? 'compact' : ''}">
    ${videos.slice(0, compact ? 3 : 5).map(v => `
      <a class="mike-video-card" href="${esc(v.url)}" target="_blank" rel="noopener">
        <span class="mike-video-thumb-wrap">
          ${v.thumbnail ? `<img class="mike-video-thumb" src="${esc(v.thumbnail)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="var p=this.parentNode;if(p)p.classList.add('thumb-error');this.remove();">` : `<span class="mike-video-thumb-empty" aria-hidden="true"></span>`}
        </span>
        <span class="mike-video-meta">
          <strong>${esc(v.title)}</strong>
          <small>${esc([v.channelTitle, fmtVideoDate(v.publishedAt)].filter(Boolean).join(' / '))}</small>
        </span>
      </a>
    `).join('')}
  </div>`;
}

