async function hydrateEntryVideoPreview(id){
  const box = $('entryVideoPreview');
  if(!box) return;
  const entry = state.entries.find(e => e.id === id);
  if(!entry){
    box.innerHTML = '<div class="talk-note">動画候補の対象が見つかりません。</div>';
    return;
  }
  const e = hydrateEntryFromMaster({...entry});
  const cached = cachedVideoMikeNavi(e);
  if(cached){
    box.innerHTML = renderEntryVideoPreviewBox(e, cached, 'キャッシュから表示しています');
    return;
  }
  try{
    const data = await fetchGasYoutubeVideosJsonp(e, {timeoutMs:7000});
    setVideoMikeNaviCache(videoMikeNaviCacheKey(e), data);
    box.innerHTML = renderEntryVideoPreviewBox(e, data, data.videos?.length ? '' : 'タイトル一致する参加動画はまだ見つかりませんでした');
  }catch(err){
    box.innerHTML = renderEntryVideoPreviewBox(e, null, String(err && err.message ? err.message : err));
  }
}

