function entryDuplicateKeys(entry){
  if(!entry) return [];
  const keys = [];
  const mediaType = normalizeMediaType(entry.mediaType);
  const shared = String(entry.sharedTitleId || '').trim();
  if(shared) keys.push(`shared:${shared}::${mediaType}`);
  const platform = String(entry.platform || '').trim();
  const key = entry.titleKey || titleKey(entry.title || '');
  if(platform && key) keys.push(`title:${platform}::${key}::${mediaType}`);
  return keys;
}

function sameTitleEntries(entry){
  const keys = new Set(entryDuplicateKeys(entry));
  if(!keys.size) return entry ? [entry] : [];
  return (state.entries || []).filter(e => {
    const eKeys = entryDuplicateKeys(e);
    return eKeys.some(k => keys.has(k));
  }).sort((a,b) => {
    if(a.id === entry.id) return -1;
    if(b.id === entry.id) return 1;
    return String(a.createdAt || '').localeCompare(String(b.createdAt || ''));
  });
}

function duplicateCountInfo(entry){
  const group = sameTitleEntries(entry);
  const owned = group.filter(e => !!e.owned);
  const want = group.filter(e => !e.owned);
  return {
    group,
    total: group.length,
    owned: owned.length,
    want: want.length,
    duplicateOwned: Math.max(0, owned.length - 1)
  };
}


function titleDisplayGroupKey(entry){
  if(!entry) return '';
  const mediaType = normalizeMediaType(entry.mediaType);
  const shared = String(entry.sharedTitleId || '').trim();
  if(shared) return `shared:${shared}::${mediaType}`;
  const platform = String(entry.platform || '').trim();
  const key = entry.titleKey || titleKey(entry.title || '');
  if(platform && key) return `title:${platform}::${key}::${mediaType}`;
  return `id:${entry.id || uid()}`;
}

function groupedTitleRepresentative(list){
  const arr = Array.isArray(list) ? list.filter(Boolean) : [];
  return arr.slice().sort((a,b) => {
    if(!!a.owned !== !!b.owned) return a.owned ? -1 : 1;
    const ac = a.sharedTitleId && a.sharedStatus === 'confirmed';
    const bc = b.sharedTitleId && b.sharedStatus === 'confirmed';
    if(!!ac !== !!bc) return ac ? -1 : 1;
    const scoreA = (typeof duplicateMergeScore === 'function') ? duplicateMergeScore(a) : ratingNumber(a.rating);
    const scoreB = (typeof duplicateMergeScore === 'function') ? duplicateMergeScore(b) : ratingNumber(b.rating);
    if(scoreA !== scoreB) return scoreB - scoreA;
    return String(a.createdAt || '').localeCompare(String(b.createdAt || ''));
  })[0] || arr[0] || null;
}

function groupEntriesForTitleCards(list){
  const map = new Map();
  (Array.isArray(list) ? list : []).forEach(entry => {
    const key = titleDisplayGroupKey(entry);
    if(!map.has(key)) map.set(key, []);
    map.get(key).push(entry);
  });

  return Array.from(map.values())
    .map(groupedTitleRepresentative)
    .filter(Boolean);
}

function groupedTitleNoteHtml(entry){
  const info = duplicateCountInfo(entry);
  if(info.total <= 1) return '';
  return `<span class="grouped-title-note">まとめ表示</span>`;
}

function duplicateCountBadgeHtml(entry){
  const info = duplicateCountInfo(entry);
  if(info.owned >= 2){
    return `<span class="pill duplicate-count-badge">所持数 ${info.owned}</span>`;
  }
  if(info.total >= 2){
    return `<span class="pill duplicate-count-badge mild">登録数 ${info.total}</span>`;
  }
  return '';
}

function sameTitleCopiesPanelHtml(entry){
  const info = duplicateCountInfo(entry);
  if(info.total <= 1) return '';
  const rows = info.group.map((e, idx) => {
    const labels = autoLabels(e).map(l => l.text).slice(0,2).join(' / ') || '内容物未設定';
    const price = e.purchasePrice ? `${yen(e.purchasePrice)}` : '価格—';
    const date = e.purchaseDate ? fmtDateOnly(e.purchaseDate) : '購入日—';
    const state = e.owned ? '所持' : '欲しい';
    return `
      <div class="same-title-copy-row ${e.id === entry.id ? 'current' : ''}">
        <div class="same-title-copy-no">${e.id === entry.id ? '表示中' : `${idx+1}本目`}</div>
        <div class="same-title-copy-main">
          <div class="same-title-copy-title">${esc(e.platform)} / ${esc(e.title)}</div>
          <div class="same-title-copy-sub">${esc(state)} / ${esc(labels)} / 評価${ratingNumber(e.rating)} / ${esc(date)} / ${esc(price)}${e.purchaseStore ? ' / ' + esc(e.purchaseStore) : ''}</div>
          ${e.memo ? `<div class="same-title-copy-sub">メモ：${esc(e.memo)}</div>` : ''}
        </div>
        <div class="same-title-copy-actions">
          <button type="button" class="ghost" data-detail-action="edit-copy" data-copy-entry-id="${esc(e.id)}">編集</button>
          <button type="button" class="buyback-btn" data-detail-action="buyback-copy" data-copy-entry-id="${esc(e.id)}">${buybackHas(e.id) ? '買取リスト済み' : '買取へ追加'}</button>
        </div>
      </div>
    `;
  }).join('');
  return `
    <div class="detail-section">
      <div class="detail-section-title">同一タイトル登録</div>
      <div class="same-title-summary">同一タイトル登録：${info.total}件 / 所持数：${info.owned}本${info.want ? ` / 欲しい：${info.want}件` : ''}</div>
      <div class="same-title-copies">${rows}</div>
    </div>
  `;
}


function loadBuyback(){
  try{
    const raw = localStorage.getItem(BUYBACK_KEY);
    const ids = raw ? JSON.parse(raw) : [];
    state.buybackEntryIds = Array.isArray(ids) ? ids.map(String).filter(Boolean) : [];
  }catch(e){
    state.buybackEntryIds = [];
  }
}

function saveBuyback(){
  localStorage.setItem(BUYBACK_KEY, JSON.stringify(state.buybackEntryIds || []));
}


function loadBuybackMeta(){
  try{
    const raw = localStorage.getItem(BUYBACK_META_KEY);
    const data = raw ? JSON.parse(raw) : {};
    state.buybackMeta = data && typeof data === 'object' && !Array.isArray(data) ? data : {};
  }catch(e){
    state.buybackMeta = {};
  }
  cleanupBuybackMeta();
}

function saveBuybackMeta(){
  localStorage.setItem(BUYBACK_META_KEY, JSON.stringify(state.buybackMeta || {}));
}

function normalizeBuybackMeta(raw, id=''){
  const data = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {};
  const status = ['assessing','confirming'].includes(data.status) ? data.status : 'unsent';
  return {
    status,
    addedAt:String(data.addedAt || (id ? nowIso() : '')),
    sentAt:String(data.sentAt || ''),
    lastSentAt:String(data.lastSentAt || ''),
    lastAttemptAt:String(data.lastAttemptAt || data.pendingAt || ''),
    pendingAt:String(data.pendingAt || ''),
    pendingSubmissionId:String(data.pendingSubmissionId || ''),
    needsResend:data.needsResend === true,
    editedAfterSentAt:String(data.editedAfterSentAt || '')
  };
}

function cleanupBuybackMeta(){
  const ids = new Set(state.buybackEntryIds || []);
  const next = {};
  Object.keys(state.buybackMeta || {}).forEach(id => {
    if(ids.has(id)) next[id] = normalizeBuybackMeta(state.buybackMeta[id], id);
  });
  state.buybackMeta = next;
  saveBuybackMeta();
}

function buybackMeta(id){
  id = String(id || '');
  if(!id) return normalizeBuybackMeta(null);
  if(!state.buybackMeta) state.buybackMeta = {};
  if(!state.buybackMeta[id]){
    state.buybackMeta[id] = normalizeBuybackMeta(null, id);
    saveBuybackMeta();
  }else{
    state.buybackMeta[id] = normalizeBuybackMeta(state.buybackMeta[id], id);
  }
  return state.buybackMeta[id];
}

function buybackStatusLabel(status, meta=null){
  if(status === 'confirming') return meta?.needsResend ? '確認待ち・変更あり' : '送信確認待ち';
  if(status === 'assessing') return '査定中';
  if(meta?.needsResend) return '要再送';
  return '未送信';
}

function buybackStatusBadgeHtml(id){
  const meta = buybackMeta(id);
  const status = meta.status === 'confirming'
    ? 'confirming'
    : (meta.status === 'assessing' ? 'assessing' : (meta.needsResend ? 'resend' : 'unsent'));
  return `<span class="buyback-status-badge ${status}">${buybackStatusLabel(meta.status, meta)}</span>`;
}

function buybackStatusSummary(){
  const list = buybackEntries();
  let unsent = 0;
  let assessing = 0;
  let confirming = 0;
  list.forEach(e => {
    const meta = buybackMeta(e.id);
    if(meta.status === 'assessing') assessing++;
    else if(meta.status === 'confirming') confirming++;
    else unsent++;
  });
  return {total:list.length, unsent, assessing, confirming};
}

function buybackEntriesByStatus(status){
  const wanted = ['assessing','confirming'].includes(status) ? status : 'unsent';
  return buybackEntries().filter(e => buybackMeta(e.id).status === wanted);
}

function buybackUnsentEntries(){
  return buybackEntriesByStatus('unsent');
}

function buybackAssessingEntries(){
  return buybackEntriesByStatus('assessing');
}

function buybackConfirmingEntries(){
  return buybackEntriesByStatus('confirming');
}

function markBuybackEntriesAssessing(entries, options={}){
  const now = String(options.sentAt || nowIso());
  if(!state.buybackMeta) state.buybackMeta = {};
  (entries || []).forEach(e => {
    const id = String(e?.id || '');
    if(!id) return;
    const meta = buybackMeta(id);
    const hadPostSendEdit = meta.needsResend === true;
    state.buybackMeta[id] = {
      ...meta,
      status:hadPostSendEdit ? 'unsent' : 'assessing',
      sentAt:meta.sentAt || now,
      lastSentAt:now,
      lastAttemptAt:now,
      pendingAt:'',
      pendingSubmissionId:'',
      needsResend:hadPostSendEdit,
      editedAfterSentAt:hadPostSendEdit ? (meta.editedAfterSentAt || nowIso()) : ''
    };
  });
  saveBuybackMeta();
}

function markBuybackEntriesConfirming(entries, submissionId){
  const now = nowIso();
  if(!state.buybackMeta) state.buybackMeta = {};
  (entries || []).forEach(e => {
    const id = String(e?.id || '');
    if(!id) return;
    const meta = buybackMeta(id);
    state.buybackMeta[id] = {
      ...meta,
      status:'confirming',
      lastAttemptAt:now,
      pendingAt:now,
      pendingSubmissionId:String(submissionId || '')
    };
  });
  saveBuybackMeta();
}

function resolveBuybackConfirming(id, result){
  id = String(id || '');
  const meta = buybackMeta(id);
  if(meta.status !== 'confirming') return false;
  const entry = (state.entries || []).find(e => String(e.id) === id);
  const label = entry?.title || 'この商品';
  const attemptedAt = meta.pendingAt || meta.lastAttemptAt || nowIso();

  if(result === 'received'){
    const ok = confirm(`「${label}」のメールが藤や玩具店へ届いていることを確認しましたか？\n\n確認済みの場合だけ進めてください。`);
    if(!ok) return false;
    markBuybackEntriesAssessing(entry ? [entry] : [{id}], {sentAt:attemptedAt});
    const next = buybackMeta(id);
    toast(next.status === 'unsent' ? '受信済みとして記録し、編集分を要再送にしました' : '受信済みとして査定中にしました');
  }else{
    const ok = confirm(`「${label}」のメールが届いていないことを確認しましたか？\n\n未送信へ戻すと、もう一度メール送信できるようになります。`);
    if(!ok) return false;
    state.buybackMeta[id] = {
      ...meta,
      status:'unsent',
      pendingAt:'',
      pendingSubmissionId:'',
      needsResend:meta.needsResend === true
    };
    saveBuybackMeta();
    toast(meta.needsResend ? '要再送へ戻しました' : '未送信へ戻しました');
  }
  renderBuybackPanel();
  renderBuybackDetail();
  return true;
}

function buybackSentAtText(id){
  const meta = buybackMeta(id);
  if(meta.status === 'confirming'){
    const attempted = fmt(meta.pendingAt || meta.lastAttemptAt || nowIso());
    return meta.needsResend
      ? `送信確認待ち：${attempted} / 送信後に編集あり`
      : `送信確認待ち：${attempted}`;
  }
  if(!meta.sentAt && !meta.lastSentAt) return '';
  const sent = fmt(meta.lastSentAt || meta.sentAt);
  return meta.needsResend ? `前回送信：${sent} / 編集後は要再送` : `送信日：${sent}`;
}
function normalizeBuybackOperationStatus(value){
  const raw = String(value || '').trim().toLowerCase();
  if(['confirmed','checked','ok','動作確認済み','確認済み'].includes(raw)) return 'confirmed';
  if(['untested','unchecked','unknown','未確認'].includes(raw)) return 'untested';
  if(['faulty','broken','ng','不具合あり','故障'].includes(raw)) return 'faulty';
  if(['na','n/a','not_applicable','対象外'].includes(raw)) return 'na';
  return '';
}

function buybackOperationStatusValue(entry){
  const explicit = normalizeBuybackOperationStatus(entry?.buybackOperationStatus || entry?.buyback_operation_status);
  if(explicit) return explicit;
  return entry?.operationChecked ? 'confirmed' : '';
}

function buybackOperationStatusLabel(entry){
  const value = typeof entry === 'string' ? normalizeBuybackOperationStatus(entry) : buybackOperationStatusValue(entry);
  return ({confirmed:'動作確認済み', untested:'未確認', faulty:'不具合あり', na:'対象外'}[value] || '未設定');
}

function buybackEntryEligibility(entry){
  if(!entry) return {ok:false, reason:'missing', message:'登録データが見つかりません'};
  if(entry.owned === false) return {ok:false, reason:'want', message:'欲しい登録は買取相談へ追加できません'};
  if(normalizeMediaType(entry.mediaType) === 'digital') return {ok:false, reason:'digital', message:'ダウンロード版は買取相談へ追加できません'};
  return {ok:true, reason:'', message:''};
}

function buybackComparableSnapshot(entry){
  const parts = {};
  PARTS.forEach(([key]) => {
    const part = getPart(entry || {}, key);
    parts[key] = {has:!!part.has, condition:String(part.condition || '')};
  });
  return JSON.stringify({
    platform:String(entry?.platform || ''),
    title:String(entry?.title || ''),
    mediaType:normalizeMediaType(entry?.mediaType),
    parts,
    accessoryRequired:!!entry?.accessoryRequired,
    overallCondition:String(entry?.overallCondition || ''),
    buybackOperationStatus:buybackOperationStatusValue(entry),
    purchasePrice:String(entry?.purchasePrice ?? ''),
    purchaseDate:String(entry?.purchaseDate || ''),
    purchaseStore:String(entry?.purchaseStore || ''),
    memo:String(entry?.memo || ''),
    sharedTitleId:String(entry?.sharedTitleId || '')
  });
}

function markBuybackEntryNeedsResend(id){
  id = String(id || '');
  if(!id || !buybackHas(id)) return false;
  const meta = buybackMeta(id);
  if(!['assessing','confirming'].includes(meta.status)) return false;
  state.buybackMeta[id] = {
    ...meta,
    status:meta.status === 'confirming' ? 'confirming' : 'unsent',
    needsResend:true,
    editedAfterSentAt:nowIso()
  };
  saveBuybackMeta();
  return true;
}


function buybackHas(id){
  const entry = (state.entries || []).find(item => String(item.id) === String(id));
  if(!entry || !buybackEntryEligibility(entry).ok) return false;
  return (state.buybackEntryIds || []).includes(String(id));
}

function addBuybackEntry(id){
  const normalizedId = String(id ?? '');
  const entry = (state.entries || []).find(e => String(e.id ?? '') === normalizedId);
  if(!entry){
    toast('買取相談へ追加するデータが見つかりません');
    return false;
  }
  id = String(entry.id);
  const eligibility = buybackEntryEligibility(entry);
  if(!eligibility.ok){
    toast(eligibility.message);
    showMikeTalk(eligibility.reason === 'digital'
      ? 'ダウンロード版は現物がないため、買取相談へ追加できないよ。'
      : '買取相談へ追加できるのは、所持しているパッケージ版のソフトだけだよ。');
    return false;
  }
  if(!state.buybackEntryIds) state.buybackEntryIds = [];
  if(!buybackHas(id)){
    state.buybackEntryIds.push(String(id));
    saveBuyback();
    buybackMeta(id);
    saveBuybackMeta();
    addEventLog('edit', entry, '買取相談リストへ追加');
  }
  return true;
}

function removeBuybackEntry(id, options={}){
  id = String(id || '');
  const entry = (state.entries || []).find(e => String(e.id) === id);
  const meta = buybackMeta(id);
  if(options.skipConfirm !== true){
    const title = entry?.title || 'この商品';
    let message = `「${title}」を買取相談リストから外しますか？`;
    if(meta.status === 'assessing'){
      message += '\n\n査定依頼は送信済みです。ここで外しても、藤や玩具店へ送った依頼は取り消されません。';
    }else if(meta.status === 'confirming'){
      message += '\n\nメールが届いている可能性があります。受信状況を確認する前に外すと、送信状態を追跡できなくなります。';
    }
    if(!confirm(message)) return false;
  }
  state.buybackEntryIds = (state.buybackEntryIds || []).filter(x => x !== id);
  if(state.buybackMeta) delete state.buybackMeta[id];
  saveBuyback();
  saveBuybackMeta();
  renderBuybackPanel();
  refreshCardDetail();
  toast('買取相談リストから外しました');
  return true;
}

function clearBuybackList(){
  const list = buybackEntries();
  if(!list.length){
    toast('買取相談リストは空です');
    return;
  }
  const summary = buybackStatusSummary();
  const warnings = [];
  if(summary.assessing) warnings.push(`査定中 ${summary.assessing}点`);
  if(summary.confirming) warnings.push(`送信確認待ち ${summary.confirming}点`);
  let message = `買取相談リスト${list.length}点をすべて外しますか？`;
  if(warnings.length){
    message += `\n\n${warnings.join(' / ')}が含まれます。藤や玩具店へ送った依頼は取り消されず、送信状態の記録だけが消えます。`;
  }
  message += '\n\nこの操作は所持登録そのものを削除しません。';
  if(!confirm(message)) return;
  state.buybackEntryIds = [];
  state.buybackMeta = {};
  saveBuyback();
  saveBuybackMeta();
  renderBuybackPanel();
  refreshCardDetail();
  toast('買取相談リストを空にしました');
}
function addEntryToBuybackFromDetail(id){
  if(addBuybackEntry(id)){
    renderBuybackPanel();
    refreshCardDetail();
    toast('買取相談リストへ追加しました');
  }
}


let buybackPickerSelectedIds = new Set();
let buybackPickerFilterGroupKeys = new Set();
let buybackPickerSearch = '';
let buybackPickerMode = 'all'; // all | duplicate-titles | duplicate-items
let buybackPickerDuplicateGroupKey = '';
let buybackPickerAfterAddSyncReason = '';
let buybackPickerDuplicateChoiceOpen = false;
let buybackPickerFromQr = false;
let buybackPickerQrPostRegistration = false;
let buybackPickerExplicitIds = new Set();
let qrPostRegistrationBuybackQueue = [];
let qrPostRegistrationBuybackCursor = 0;

function buybackPickerEligibleEntries(){
  return (state.entries || [])
    .filter(entry => buybackEntryEligibility(entry).ok)
    .filter(entry => !buybackHas(entry.id));
}

function buybackPickerEntrySummary(entry){
  const labels = autoLabels(entry).map(item => item.text).filter(Boolean).slice(0, 4);
  const purchase = [
    entry.purchaseDate ? fmtDateOnly(entry.purchaseDate) : '',
    entry.purchaseStore || '',
    entry.purchasePrice ? yen(entry.purchasePrice) : ''
  ].filter(Boolean).join(' / ');
  return {
    labels:labels.join(' / ') || mediaTypeLabel(entry.mediaType),
    purchase:purchase || '購入情報なし',
    condition:buybackEntryConditionText(entry),
    memo:String(entry.memo || '').trim(),
    id:String(entry.id || '')
  };
}

function buybackPickerCandidates(){
  const search = titleKey(buybackPickerSearch || '');
  return buybackPickerEligibleEntries()
    .filter(entry => !buybackPickerFilterGroupKeys.size || buybackPickerFilterGroupKeys.has(titleDisplayGroupKey(entry)))
    .filter(entry => {
      if(!search) return true;
      return titleKey([
        entry.platform,
        entry.title,
        entry.purchaseStore,
        entry.memo,
        buybackEntryConditionText(entry)
      ].join(' ')).includes(search);
    })
    .sort((a,b) => {
      const keyA = `${titleDisplayGroupKey(a)}|${a.purchaseDate || ''}|${a.createdAt || ''}`;
      const keyB = `${titleDisplayGroupKey(b)}|${b.purchaseDate || ''}|${b.createdAt || ''}`;
      return keyA.localeCompare(keyB, 'ja');
    });
}

function buybackPickerGroupedEntries(entries){
  const groups = new Map();
  entries.forEach(entry => {
    const key = titleDisplayGroupKey(entry);
    if(!groups.has(key)) groups.set(key, []);
    groups.get(key).push(entry);
  });
  return [...groups.entries()].map(([key,items]) => ({key,items}));
}

function buybackDuplicateOwnedGroups(){
  return buybackPickerGroupedEntries(buybackPickerEligibleEntries())
    .filter(group => group.items.length >= 2);
}

function buybackDuplicateOwnedGroupKeys(){
  return buybackDuplicateOwnedGroups().map(group => group.key);
}

function openBuybackDuplicatePicker(){
  const groups = buybackDuplicateOwnedGroups();
  if(!groups.length){
    toast('複数所持しているタイトルはありません');
    return;
  }

  buybackPickerMode = 'duplicate-titles';
  buybackPickerDuplicateGroupKey = '';
  buybackPickerFilterGroupKeys.clear();
  buybackPickerSelectedIds.clear();
  buybackPickerSearch = '';
  renderBuybackEntryPicker();
}

function qrPostRegistrationCurrentStep(){
  return qrPostRegistrationBuybackQueue[qrPostRegistrationBuybackCursor] || null;
}

function resetQrPostRegistrationBuybackFlow(){
  qrPostRegistrationBuybackQueue = [];
  qrPostRegistrationBuybackCursor = 0;
}

function openQrPostRegistrationBuybackStep(){
  const step = qrPostRegistrationCurrentStep();
  if(!step){
    resetQrPostRegistrationBuybackFlow();
    return;
  }

  const candidateIdSet = new Set((step.candidateIds || []).map(String));
  const groupEntries = (state.entries || []).filter(entry =>
    candidateIdSet.has(String(entry.id)) &&
    buybackEntryEligibility(entry).ok &&
    !buybackHas(entry.id)
  );
  if(!groupEntries.length){
    qrPostRegistrationBuybackCursor += 1;
    openQrPostRegistrationBuybackStep();
    return;
  }

  const preferredId = groupEntries.some(entry => String(entry.id) === String(step.preferredEntryId))
    ? String(step.preferredEntryId)
    : String(groupEntries[0].id);

  // QR登録後はタイトル一覧や簡易候補画面を挟まず、
  // 既存の「売る個体を選ぶ」画面へ直接入る。
  // 今回登録した個体をNEWとして先頭・選択済みにする。
  openBuybackEntryPicker({
    filterGroupKeys:[step.groupKey],
    fromQr:false,
    qrPostRegistration:true,
    initialDuplicateGroupKey:`qrpost:${preferredId}`,
    preselectIds:[preferredId],
    candidateIds:groupEntries.map(entry => String(entry.id)),
    afterAddSyncReason:'店舗QR買取リスト更新'
  });
}

function startQrPostRegistrationBuybackFlow(steps){
  qrPostRegistrationBuybackQueue = (Array.isArray(steps) ? steps : [])
    .filter(step => step?.groupKey && step?.preferredEntryId && Array.isArray(step.candidateIds) && step.candidateIds.length > 1);
  qrPostRegistrationBuybackCursor = 0;
  if(!qrPostRegistrationBuybackQueue.length) return false;
  openQrPostRegistrationBuybackStep();
  return true;
}

function advanceQrPostRegistrationBuybackFlow(){
  qrPostRegistrationBuybackCursor += 1;
  if(qrPostRegistrationBuybackCursor >= qrPostRegistrationBuybackQueue.length){
    resetQrPostRegistrationBuybackFlow();
    toast('QR登録後の重複確認が完了しました');
    return;
  }
  openQrPostRegistrationBuybackStep();
}

function ensureBuybackEntryPicker(){
  let modal = document.getElementById('buybackEntryPickerModal');
  if(modal) return modal;

  modal = document.createElement('div');
  modal.id = 'buybackEntryPickerModal';
  modal.className = 'buyback-picker-modal';
  modal.hidden = true;
  document.body.appendChild(modal);

  modal.addEventListener('click', event => {
    if(event.target.closest('[data-buyback-picker-close]')){
      closeBuybackEntryPicker();
      return;
    }
    if(event.target.closest('[data-buyback-picker-add]')){
      addBuybackPickerSelection();
      return;
    }
    if(event.target.closest('[data-buyback-picker-clear-filter]')){
      buybackPickerFilterGroupKeys.clear();
      buybackPickerSelectedIds.clear();
      renderBuybackEntryPicker();
      return;
    }

    if(event.target.closest('[data-buyback-picker-other]')){
      if(buybackPickerQrPostRegistration){
        // QR登録後の「別の個体を選ぶ」は専用一覧を作らず、
        // 買取リストで使っている「複数所持から選ぶ」へそのまま遷移する。
        buybackPickerFromQr = false;
        buybackPickerDuplicateChoiceOpen = false;
        buybackPickerMode = 'duplicate-titles';
        buybackPickerDuplicateGroupKey = '';
        buybackPickerSelectedIds.clear();
        buybackPickerSearch = '';
      }else{
        buybackPickerDuplicateChoiceOpen = true;
      }
      renderBuybackEntryPicker();
      return;
    }

    if(event.target.closest('[data-buyback-picker-qr-back]')){
      buybackPickerFromQr = true;
      buybackPickerDuplicateChoiceOpen = false;
      renderBuybackEntryPicker();
      return;
    }

    if(event.target.closest('[data-buyback-picker-choice-back]')){
      buybackPickerDuplicateChoiceOpen = false;
      renderBuybackEntryPicker();
      return;
    }

    if(event.target.closest('[data-buyback-picker-skip]')){
      const continueQrFlow = buybackPickerQrPostRegistration;
      closeBuybackEntryPicker();
      if(continueQrFlow) setTimeout(advanceQrPostRegistrationBuybackFlow,80);
      return;
    }

    const pick = event.target.closest('[data-buyback-picker-pick-id]');
    if(pick){
      const id = String(pick.dataset.buybackPickerPickId || '');
      if(id){
        buybackPickerSelectedIds = new Set([id]);
        buybackPickerDuplicateChoiceOpen = false;
        renderBuybackEntryPicker();
      }
      return;
    }

    const duplicateTitle = event.target.closest('[data-buyback-duplicate-group]');
    if(duplicateTitle){
      buybackPickerMode = 'duplicate-items';
      buybackPickerDuplicateGroupKey = String(duplicateTitle.dataset.buybackDuplicateGroup || '');
      buybackPickerSelectedIds.clear();
      buybackPickerSearch = '';
      renderBuybackEntryPicker();
      return;
    }

    if(event.target.closest('[data-buyback-duplicate-back]')){
      buybackPickerMode = 'duplicate-titles';
      buybackPickerDuplicateGroupKey = '';
      buybackPickerSelectedIds.clear();
      buybackPickerSearch = '';
      renderBuybackEntryPicker();
      return;
    }
  });

  modal.addEventListener('change', event => {
    const checkbox = event.target.closest('[data-buyback-picker-entry]');
    if(!checkbox) return;
    const id = String(checkbox.dataset.buybackPickerEntry || '');
    if(buybackPickerMode === 'duplicate-items'){
      buybackPickerSelectedIds.clear();
      if(checkbox.checked) buybackPickerSelectedIds.add(id);
      modal.querySelectorAll('[data-buyback-picker-entry]').forEach(input => {
        if(input !== checkbox) input.checked = false;
      });
    }else{
      if(checkbox.checked) buybackPickerSelectedIds.add(id);
      else buybackPickerSelectedIds.delete(id);
    }
    updateBuybackPickerSelectionState();
  });

  modal.addEventListener('input', event => {
    const input = event.target.closest('#buybackPickerSearch');
    if(!input) return;
    buybackPickerSearch = input.value || '';
    renderBuybackEntryPicker({keepSearchFocus:true});
  });

  return modal;
}

function buybackPickerEntryHtml(entry,index,groupSize){
  const summary = buybackPickerEntrySummary(entry);
  const checked = buybackPickerSelectedIds.has(String(entry.id));
  const qrPreferredId = buybackPickerQrPostRegistration ? String(qrPostRegistrationCurrentStep()?.preferredEntryId || '') : '';
  const isQrNew = !!qrPreferredId && String(entry.id) === qrPreferredId;
  const copyLabel = isQrNew ? '今回登録' : (groupSize > 1 ? `${index + 1}本目` : '登録個体');

  return `<label class="buyback-picker-entry buyback-picker-entry-flat${checked ? ' is-selected' : ''}${isQrNew ? ' is-qr-new' : ''}">
    <input type="checkbox" data-buyback-picker-entry="${esc(entry.id)}" ${checked ? 'checked' : ''}>
    <span class="buyback-picker-check" aria-hidden="true"></span>
    <span class="buyback-picker-entry-main">
      <span class="buyback-picker-entry-title-row">
        <strong>${esc(entry.platform)} / ${esc(entry.title)}${isQrNew ? '<span class="buyback-picker-new-badge">NEW</span>' : ''}</strong>
        <small>${esc(copyLabel)}・ID ${esc(summary.id.slice(-8) || '—')}</small>
      </span>
      <span class="buyback-picker-entry-meta">
        <span><b>内容</b><em>${esc(summary.labels)}</em></span>
        <span><b>状態</b><em>${esc(summary.condition)}</em></span>
        <span><b>購入</b><em>${esc(summary.purchase)}</em></span>
        ${summary.memo ? `<span class="wide"><b>メモ</b><em>${esc(summary.memo)}</em></span>` : ''}
      </span>
    </span>
  </label>`;
}

function qrPostRegistrationPickerSyntheticGroupKey(){
  const preferredId = buybackPickerQrPostRegistration
    ? String(qrPostRegistrationCurrentStep()?.preferredEntryId || '')
    : '';
  return preferredId ? `qrpost:${preferredId}` : '';
}

function buybackDuplicateTitleGroupsForPicker(){
  const search = titleKey(buybackPickerSearch || '');
  let groups = buybackDuplicateOwnedGroups();

  // QR登録直後は、マスターIDやmediaTypeの確定状態で通常グループキーが分かれても、
  // 登録時に確定した候補IDを1タイトルとして束ね直して最上段へ出す。
  if(buybackPickerQrPostRegistration && buybackPickerExplicitIds.size){
    const qrItems = buybackPickerEligibleEntries()
      .filter(entry => buybackPickerExplicitIds.has(String(entry.id)));
    if(qrItems.length >= 2){
      groups = groups.filter(group =>
        !group.items.some(entry => buybackPickerExplicitIds.has(String(entry.id)))
      );
      groups.unshift({
        key:qrPostRegistrationPickerSyntheticGroupKey(),
        items:qrItems,
        qrSynthetic:true
      });
    }
  }

  return groups
    .filter(group => {
      if(!search) return true;
      const first = group.items[0] || {};
      return titleKey([
        first.platform,
        first.title
      ].join(' ')).includes(search);
    })
    .sort((a,b) => {
      if(!!a.qrSynthetic !== !!b.qrSynthetic) return a.qrSynthetic ? -1 : 1;
      const aa = a.items[0] || {};
      const bb = b.items[0] || {};
      return `${aa.platform || ''}|${aa.title || ''}`.localeCompare(
        `${bb.platform || ''}|${bb.title || ''}`,
        'ja'
      );
    });
}

function buybackDuplicateTitleCardHtml(group){
  const first = group.items[0] || {};
  const count = group.items.length;
  const summaries = group.items.map(buybackPickerEntrySummary);
  const withPurchase = summaries.filter(item => item.purchase && item.purchase !== '購入情報なし').length;
  const conditions = [...new Set(summaries.map(item => item.condition).filter(Boolean))];
  const conditionText = conditions.length === 1
    ? conditions[0]
    : `${conditions.length}種類の状態`;
  return `<button type="button" class="buyback-duplicate-title-card" data-buyback-duplicate-group="${esc(group.key)}">
    <span class="buyback-duplicate-title-main">
      <span class="buyback-duplicate-title-platform">${esc(first.platform || '機種未設定')}</span>
      <span class="buyback-duplicate-title-copy">
        <strong><span>${esc(first.title || 'タイトル未設定')}</span></strong>
        <small>${count}本所持${withPurchase ? ` / 購入情報あり ${withPurchase}本` : ''}</small>
      </span>
    </span>
    <span class="buyback-duplicate-title-side">
      <small>${esc(conditionText)}</small>
      <strong>${count}本</strong>
      <span aria-hidden="true">›</span>
    </span>
  </button>`;
}


function buybackDuplicateQuickEntryHtml(entry,index,total){
  const summary = buybackPickerEntrySummary(entry);
  return `<article class="buyback-picker-quick-entry">
    <div class="buyback-picker-quick-count">候補 ${index + 1} / ${total}</div>
    <div class="buyback-picker-quick-title">
      <strong>${esc(entry.platform)} / ${esc(entry.title)}</strong>
      <small>ID ${esc(summary.id.slice(-8) || '—')}</small>
    </div>
    <div class="buyback-picker-quick-meta">
      <span><b>内容</b><em>${esc(summary.labels)}</em></span>
      <span><b>状態</b><em>${esc(summary.condition)}</em></span>
      <span><b>購入</b><em>${esc(summary.purchase)}</em></span>
      ${summary.memo ? `<span class="wide"><b>メモ</b><em>${esc(summary.memo)}</em></span>` : ''}
    </div>
  </article>`;
}

function renderBuybackDuplicateQuickPicker(modal,group){
  const candidates = group?.items?.slice() || [];
  if(!candidates.length){
    closeBuybackEntryPicker();
    toast('買取相談へ追加できる個体がありません');
    return;
  }

  let selectedId = [...buybackPickerSelectedIds].find(id =>
    candidates.some(entry => String(entry.id) === String(id))
  );
  if(!selectedId){
    selectedId = String(candidates[0].id);
    buybackPickerSelectedIds = new Set([selectedId]);
  }
  const selectedIndex = Math.max(0,candidates.findIndex(entry => String(entry.id) === selectedId));
  const selectedEntry = candidates[selectedIndex] || candidates[0];

  if(buybackPickerDuplicateChoiceOpen){
    modal.innerHTML = `<div class="buyback-picker-backdrop" data-buyback-picker-close></div>
      <section class="buyback-picker-dialog buyback-picker-dialog-quick-choice" role="dialog" aria-modal="true" aria-labelledby="buybackPickerTitle">
        <div class="buyback-picker-bar">
          <div>
            <h2 id="buybackPickerTitle">別の個体を選ぶ</h2>
            <p>${esc(selectedEntry.platform)} / ${esc(selectedEntry.title)}・${candidates.length}本所持</p>
          </div>
          <button type="button" class="buyback-picker-close" data-buyback-picker-close aria-label="閉じる">×</button>
        </div>
        <div class="buyback-picker-choice-list">
          ${candidates.map((entry,index) => {
            const summary = buybackPickerEntrySummary(entry);
            const active = String(entry.id) === selectedId;
            return `<button type="button" class="buyback-picker-choice-row${active ? ' is-current' : ''}" data-buyback-picker-pick-id="${esc(entry.id)}">
              <span class="buyback-picker-choice-no">${index + 1}</span>
              <span class="buyback-picker-choice-main">
                <strong>${esc(summary.purchase)}</strong>
                <small>${esc(summary.labels)} / ${esc(summary.condition)}${summary.memo ? ` / ${esc(summary.memo)}` : ''}</small>
              </span>
              <span class="buyback-picker-choice-mark">${active ? '選択中' : '選ぶ'}</span>
            </button>`;
          }).join('')}
        </div>
        <div class="buyback-picker-actions buyback-picker-actions-quick">
          <button type="button" class="ghost" data-buyback-picker-choice-back>戻る</button>
        </div>
      </section>`;
  }else{
    const qrPost = buybackPickerQrPostRegistration;
    const stepNo = qrPost ? qrPostRegistrationBuybackCursor + 1 : 0;
    const stepTotal = qrPost ? qrPostRegistrationBuybackQueue.length : 0;
    const selectedIsPreferred = qrPost && String(selectedEntry.id) === String(qrPostRegistrationCurrentStep()?.preferredEntryId || '');
    modal.innerHTML = `<div class="buyback-picker-backdrop" data-buyback-picker-close></div>
      <section class="buyback-picker-dialog buyback-picker-dialog-quick" role="dialog" aria-modal="true" aria-labelledby="buybackPickerTitle">
        <div class="buyback-picker-bar">
          <div>
            <h2 id="buybackPickerTitle">${qrPost ? '重複タイトルがあります' : '買取相談に入れる個体'}</h2>
            <p>${qrPost
              ? `${stepTotal > 1 ? `${stepNo}/${stepTotal}件目・` : ''}今回のQR登録で複数所持になりました。買取リストに入れますか？`
              : 'まずこの個体を候補にしています。違う個体なら下から変更できます。'}</p>
          </div>
          <button type="button" class="buyback-picker-close" data-buyback-picker-close aria-label="閉じる">×</button>
        </div>
        <div class="buyback-picker-quick-body">
          ${qrPost && selectedIsPreferred ? '<div class="buyback-picker-qr-new-label">今回登録した個体</div>' : ''}
          ${buybackDuplicateQuickEntryHtml(selectedEntry,selectedIndex,candidates.length)}
        </div>
        <div class="buyback-picker-actions buyback-picker-actions-quick${qrPost ? ' is-qr-post' : ''}">
          ${candidates.length > 1 ? '<button type="button" class="ghost" data-buyback-picker-other>別の個体を選ぶ</button>' : ''}
          <button type="button" class="green buyback-picker-quick-add" data-buyback-picker-add>${qrPost && selectedIsPreferred ? '今回登録した個体を買取リストに入れる' : 'この個体を買取リストに入れる'}</button>
          ${qrPost ? '<button type="button" class="ghost buyback-picker-skip" data-buyback-picker-skip>買取リストには入れない</button>' : ''}
        </div>
      </section>`;
  }

  modal.hidden = false;
  document.body.classList.add('buyback-picker-modal-open');
  refreshRegistrationModalChromeSuppression();
  document.body.style.overflow = 'hidden';
}

function renderBuybackEntryPicker(options={}){
  const modal = ensureBuybackEntryPicker();
  const isDuplicateTitleMode = buybackPickerMode === 'duplicate-titles';
  const isDuplicateItemMode = buybackPickerMode === 'duplicate-items';

  if(isDuplicateTitleMode){
    const groups = buybackDuplicateTitleGroupsForPicker();
    const totalGroups = buybackDuplicateOwnedGroups().length;

    modal.innerHTML = `<div class="buyback-picker-backdrop" data-buyback-picker-close></div>
      <section class="buyback-picker-dialog buyback-picker-dialog-duplicates" role="dialog" aria-modal="true" aria-labelledby="buybackPickerTitle">
        <div class="buyback-picker-bar">
          <div>
            <h2 id="buybackPickerTitle">複数所持から選ぶ</h2>
            <p>${buybackPickerQrPostRegistration
              ? 'タイトルを選んで、その中から売る個体を選択してください。'
              : 'まずタイトルを選んで、その中から売る個体を選択してください。'}</p>
          </div>
          <button type="button" class="buyback-picker-close" data-buyback-picker-close aria-label="閉じる">×</button>
        </div>
        <div class="buyback-picker-tools buyback-picker-tools-title">
          <input type="search" id="buybackPickerSearch" value="${esc(buybackPickerSearch)}" placeholder="複数所持しているタイトルを検索">
        </div>
        <div class="buyback-picker-summary">
          <span>複数所持 ${totalGroups}タイトル</span>
          <strong>${groups.length}タイトル表示</strong>
        </div>
        <div class="buyback-picker-list buyback-duplicate-title-list">
          ${groups.length
            ? groups.map(buybackDuplicateTitleCardHtml).join('')
            : '<div class="buyback-picker-empty">検索条件に合う複数所持タイトルがありません。</div>'}
        </div>
        <div class="buyback-picker-actions buyback-picker-actions-title">
          <button type="button" class="ghost" data-buyback-picker-close>キャンセル</button>
        </div>
      </section>`;

    modal.hidden = false;
    document.body.classList.add('buyback-picker-modal-open');
    refreshRegistrationModalChromeSuppression();
    document.body.style.overflow = 'hidden';

    if(options.keepSearchFocus){
      const input = modal.querySelector('#buybackPickerSearch');
      requestAnimationFrame(() => {
        input?.focus();
        try{ input?.setSelectionRange(input.value.length,input.value.length); }catch(error){}
      });
    }
    return;
  }

  let candidates;
  let groups;

  if(isDuplicateItemMode){
    const qrStep = buybackPickerQrPostRegistration ? qrPostRegistrationCurrentStep() : null;
    const preferredId = String(qrStep?.preferredEntryId || '');
    const syntheticKey = qrPostRegistrationPickerSyntheticGroupKey();
    let duplicateGroup = null;

    if(buybackPickerFromQr && qrStep){
      // 最初の重複確認はQR登録時に確定した候補IDをそのまま使用。
      const items = buybackPickerEligibleEntries()
        .filter(entry => buybackPickerExplicitIds.has(String(entry.id)))
        .sort((a,b) => {
          const aNew = String(a.id) === preferredId ? 1 : 0;
          const bNew = String(b.id) === preferredId ? 1 : 0;
          if(aNew !== bNew) return bNew - aNew;
          return String(b.purchaseDate || b.createdAt || '').localeCompare(String(a.purchaseDate || a.createdAt || ''),'ja');
        });
      duplicateGroup = {key:buybackPickerDuplicateGroupKey,items};
    }else if(qrStep && syntheticKey && String(buybackPickerDuplicateGroupKey) === syntheticKey){
      // 「複数所持から選ぶ」のNEWタイトルを開いた時も、同じ候補IDを束ねて表示。
      const items = buybackPickerEligibleEntries()
        .filter(entry => buybackPickerExplicitIds.has(String(entry.id)))
        .sort((a,b) => {
          const aNew = String(a.id) === preferredId ? 1 : 0;
          const bNew = String(b.id) === preferredId ? 1 : 0;
          if(aNew !== bNew) return bNew - aNew;
          return String(b.purchaseDate || b.createdAt || '').localeCompare(String(a.purchaseDate || a.createdAt || ''),'ja');
        });
      duplicateGroup = {key:syntheticKey,items,qrSynthetic:true};
    }else{
      const normalDuplicateGroup = buybackDuplicateOwnedGroups().find(group => group.key === buybackPickerDuplicateGroupKey);
      duplicateGroup = normalDuplicateGroup
        ? {
            key:normalDuplicateGroup.key,
            items:normalDuplicateGroup.items.slice().sort((a,b) =>
              String(b.purchaseDate || b.createdAt || '').localeCompare(String(a.purchaseDate || a.createdAt || ''),'ja')
            )
          }
        : null;
    }
    if(buybackPickerFromQr){
      renderBuybackDuplicateQuickPicker(modal,duplicateGroup);
      return;
    }
    candidates = duplicateGroup ? duplicateGroup.items.slice() : [];
    groups = duplicateGroup ? [duplicateGroup] : [];
  }else{
    candidates = buybackPickerCandidates();
    groups = buybackPickerGroupedEntries(candidates);
  }

  const totalEligible = buybackPickerEligibleEntries().length;
  const filterActive = buybackPickerFilterGroupKeys.size > 0;
  const duplicateFirst = isDuplicateItemMode ? (groups[0]?.items?.[0] || null) : null;
  const filterSummary = isDuplicateItemMode
    ? `${duplicateFirst?.platform || ''} / ${duplicateFirst?.title || ''}・${candidates.length}本所持`
    : (!filterActive
      ? `追加できる所持個体 ${totalEligible}件`
      : (buybackPickerFilterGroupKeys.size === 1
        ? '同じタイトルの所持個体から選択中'
        : `複数所持 ${buybackPickerFilterGroupKeys.size}タイトルから選択中`));

  modal.innerHTML = `<div class="buyback-picker-backdrop" data-buyback-picker-close></div>
    <section class="buyback-picker-dialog${isDuplicateItemMode ? ' buyback-picker-dialog-duplicate-items' : ''}" role="dialog" aria-modal="true" aria-labelledby="buybackPickerTitle">
      <div class="buyback-picker-bar">
        <div>
          ${isDuplicateItemMode && !buybackPickerQrPostRegistration ? '<button type="button" class="buyback-picker-back" data-buyback-duplicate-back>‹ 複数所持タイトル一覧</button>' : ''}
          <h2 id="buybackPickerTitle">${isDuplicateItemMode ? '売る個体を選ぶ' : '買取相談へ入れる個体を選ぶ'}</h2>
          <p>${isDuplicateItemMode
            ? (buybackPickerQrPostRegistration && candidates.some(entry => String(entry.id) === String(qrPostRegistrationCurrentStep()?.preferredEntryId || ''))
              ? '今回QRで登録した個体はNEWで先頭に表示しています。手元に残す個体と売る個体を見比べて選んでください。'
              : '同じタイトルの中から、手元に残す個体と売る個体を見比べて選んでください。')
            : '購入日・店舗・内容物・状態を見比べて、売る個体だけ選択してください。'}</p>
        </div>
        <button type="button" class="buyback-picker-close" data-buyback-picker-close aria-label="閉じる">×</button>
      </div>
      ${isDuplicateItemMode ? '' : `<div class="buyback-picker-tools">
        <input type="search" id="buybackPickerSearch" value="${esc(buybackPickerSearch)}" placeholder="タイトル・店舗・メモで検索">
        ${filterActive ? '<button type="button" class="ghost" data-buyback-picker-clear-filter>すべてのタイトルを表示</button>' : ''}
      </div>`}
      <div class="buyback-picker-summary">
        <span>${esc(filterSummary)}</span>
        <strong data-buyback-picker-selected-count>${buybackPickerSelectedIds.size}件選択</strong>
      </div>
      <div class="buyback-picker-list">
        ${groups.length ? groups.flatMap(group =>
          group.items.map((entry,index) => buybackPickerEntryHtml(entry,index,group.items.length))
        ).join('') : `<div class="buyback-picker-empty">${totalEligible ? '検索条件に合う個体がありません。' : '買取相談へ追加できる所持個体はありません。'}</div>`}
      </div>
      <div class="buyback-picker-actions${isDuplicateItemMode && buybackPickerQrPostRegistration ? ' is-qr-direct' : ''}">
        ${isDuplicateItemMode && buybackPickerQrPostRegistration
          ? '<button type="button" class="ghost buyback-picker-skip" data-buyback-picker-skip>買取リストには入れない</button>'
          : `<button type="button" class="ghost" ${isDuplicateItemMode ? 'data-buyback-duplicate-back' : 'data-buyback-picker-close'}>${isDuplicateItemMode ? 'タイトル一覧へ戻る' : 'キャンセル'}</button>`}
        <button type="button" class="green" data-buyback-picker-add ${buybackPickerSelectedIds.size ? '' : 'disabled'}>選択した個体を買取相談へ追加</button>
      </div>
    </section>`;

  modal.hidden = false;
  document.body.classList.add('buyback-picker-modal-open');
  refreshRegistrationModalChromeSuppression();
  document.body.style.overflow = 'hidden';

  if(options.keepSearchFocus){
    const input = modal.querySelector('#buybackPickerSearch');
    requestAnimationFrame(() => {
      input?.focus();
      try{ input?.setSelectionRange(input.value.length,input.value.length); }catch(error){}
    });
  }
}

function updateBuybackPickerSelectionState(){
  const modal = document.getElementById('buybackEntryPickerModal');
  if(!modal || modal.hidden) return;
  modal.querySelectorAll('[data-buyback-picker-entry]').forEach(input => {
    input.closest('.buyback-picker-entry')?.classList.toggle('is-selected',input.checked);
  });
  const count = modal.querySelector('[data-buyback-picker-selected-count]');
  if(count) count.textContent = `${buybackPickerSelectedIds.size}件選択`;
  const add = modal.querySelector('[data-buyback-picker-add]');
  if(add) add.disabled = buybackPickerSelectedIds.size === 0;
}

function openBuybackEntryPicker(options={}){
  buybackPickerAfterAddSyncReason = String(options.afterAddSyncReason || '');
  buybackPickerFromQr = !!options.fromQr;
  buybackPickerQrPostRegistration = !!options.qrPostRegistration;
  buybackPickerExplicitIds = new Set((Array.isArray(options.candidateIds) ? options.candidateIds : []).map(String).filter(Boolean));
  buybackPickerDuplicateChoiceOpen = false;
  const initialDuplicateGroupKey = String(options.initialDuplicateGroupKey || '');
  buybackPickerMode = initialDuplicateGroupKey ? 'duplicate-items' : 'all';
  buybackPickerDuplicateGroupKey = initialDuplicateGroupKey;
  buybackPickerSelectedIds = new Set(
    (Array.isArray(options.preselectIds) ? options.preselectIds : [])
      .map(String)
      .filter(id => {
        const entry = (state.entries || []).find(item => String(item.id) === id);
        return entry && buybackEntryEligibility(entry).ok && !buybackHas(id);
      })
  );
  buybackPickerSearch = '';

  const requestedGroupKeys = Array.isArray(options.filterGroupKeys)
    ?options.filterGroupKeys.map(String).filter(Boolean)
    :[];
  const filterEntry = options.filterEntryId
    ?(state.entries || []).find(item => String(item.id) === String(options.filterEntryId))
    :null;
  if(filterEntry) requestedGroupKeys.push(titleDisplayGroupKey(filterEntry));

  buybackPickerFilterGroupKeys = new Set(requestedGroupKeys);
  renderBuybackEntryPicker();
}

function closeBuybackEntryPicker(){
  const modal = document.getElementById('buybackEntryPickerModal');
  if(modal){
    modal.hidden = true;
    modal.innerHTML = '';
  }
  buybackPickerSelectedIds.clear();
  buybackPickerFilterGroupKeys.clear();
  buybackPickerSearch = '';
  buybackPickerMode = 'all';
  buybackPickerDuplicateGroupKey = '';
  buybackPickerAfterAddSyncReason = '';
  buybackPickerDuplicateChoiceOpen = false;
  buybackPickerFromQr = false;
  buybackPickerQrPostRegistration = false;
  buybackPickerExplicitIds.clear();
  document.body.classList.remove('buyback-picker-modal-open');
  refreshRegistrationModalChromeSuppression();
  document.body.style.removeProperty('overflow');
}

function addBuybackPickerSelection(){
  const ids = [...buybackPickerSelectedIds];
  const targets = (state.entries || []).filter(entry =>
    ids.includes(String(entry.id)) &&
    buybackEntryEligibility(entry).ok &&
    !buybackHas(entry.id)
  );
  if(!targets.length){
    toast('買取相談へ追加する個体を選んでください');
    return;
  }

  let added = 0;
  targets.forEach(entry => {
    if(addBuybackEntry(entry.id)) added++;
  });

  renderBuybackPanel();
  refreshCardDetail();
  const syncReason = buybackPickerAfterAddSyncReason;
  const continueQrFlow = buybackPickerQrPostRegistration;
  closeBuybackEntryPicker();
  if(added > 0 && syncReason) scheduleAutoSync(syncReason);
  toast(`${added}件を買取相談リストへ追加しました`);
  if(continueQrFlow) setTimeout(advanceQrPostRegistrationBuybackFlow,80);
}

function buybackEntries(){
  const rawIds = (state.buybackEntryIds || []).map(String).filter(Boolean);
  const entryMap = new Map((state.entries || []).map(entry => [String(entry.id), entry]));
  const validIds = rawIds.filter(id => {
    const entry = entryMap.get(id);
    return entry && buybackEntryEligibility(entry).ok;
  });
  if(validIds.length !== rawIds.length){
    state.buybackEntryIds = validIds;
    const validSet = new Set(validIds);
    const nextMeta = {};
    Object.keys(state.buybackMeta || {}).forEach(id => {
      if(validSet.has(String(id))) nextMeta[id] = state.buybackMeta[id];
    });
    state.buybackMeta = nextMeta;
    saveBuyback();
    saveBuybackMeta();
  }
  const ids = new Set(validIds);
  return (state.entries || []).filter(e => ids.has(String(e.id)));
}

function buybackEntryConditionText(entry){
  const conditionName = value => ({S:'極美品',A:'美品',B:'並品',C:'難あり',J:'ジャンク'}[String(value || '')] || '状態未設定');
  const partText = (key, label, always=false) => {
    const part = getPart(entry || {}, key);
    if(!part.has) return always ? `${label}：なし` : '';
    return `${label}：あり（${conditionName(part.condition)}）`;
  };

  const rom = getPart(entry || {}, 'rom');
  const box = getPart(entry || {}, 'box');
  const manual = getPart(entry || {}, 'manual');
  const accessory = getPart(entry || {}, 'accessory');
  const anyPartSet = [rom, box, manual, accessory].some(part => part.has);
  if(!anyPartSet) return entry?.overallCondition
    ? `内容物未設定 / 総合状態：${conditionName(entry.overallCondition)}`
    : '内容物未設定';

  const rows = [
    partText('rom', 'ROM', true),
    partText('box', '箱・ケース', true),
    partText('manual', '取説', true)
  ];
  if(accessory.has || entry?.accessoryRequired){
    rows.push(accessory.has
      ? partText('accessory', '付属品', true)
      : '付属品：なし（欠品）');
  }
  if(entry?.overallCondition){
    rows.push(`総合状態：${conditionName(entry.overallCondition)}`);
  }
  return rows.filter(Boolean).join(' / ');
}

function buybackRequestText(targetList){
  const list = Array.isArray(targetList) ? targetList : buybackEntries();
  if(!list.length){
    return '藤や玩具店さんへ\n\n買取相談リストはまだ空です。';
  }

  const byPlatform = new Map();
  list.forEach(e => {
    const p = e.platform || 'その他';
    if(!byPlatform.has(p)) byPlatform.set(p, []);
    byPlatform.get(p).push(e);
  });

  const lines = [];
  lines.push('藤や玩具店さんへ');
  lines.push('');
  lines.push('以下のソフトの買取査定をお願いします。');
  lines.push('');
  Array.from(byPlatform.keys()).sort((a,b)=>a.localeCompare(b,'ja')).forEach(platform => {
    lines.push(`【${platform}】`);
    byPlatform.get(platform).forEach(e => {
      lines.push(`・${e.title}`);
      lines.push(`  登録個体ID：${e.id || '—'}`);
      lines.push(`  状態：${buybackEntryConditionText(e)}`);
      lines.push(`  動作確認：${buybackOperationStatusLabel(e)}`);
      if(e.purchasePrice) lines.push(`  参考購入価格：${yen(e.purchasePrice)}`);
      if(e.memo) lines.push(`  メモ：${String(e.memo).replace(/\n/g, ' / ')}`);
      lines.push('');
    });
  });
  lines.push(`点数：${list.length}点`);
  lines.push('希望：まとめて査定相談');
  lines.push('');
  lines.push('よろしくお願いします。');
  return lines.join('\n');
}


function buybackCsvString(targetList){
  const list = Array.isArray(targetList) ? targetList : buybackEntries();
  const header = ['機種','タイトル','状態','動作確認','購入価格','購入日','購入店舗','メモ','共有ID','登録個体ID'];
  const rows = list.map(e => [
    e.platform,
    e.title,
    buybackEntryConditionText(e),
    buybackOperationStatusLabel(e),
    e.purchasePrice || '',
    e.purchaseDate || '',
    e.purchaseStore || '',
    e.memo || '',
    e.sharedTitleId || '',
    e.id || ''
  ]);
  return [header, ...rows].map(row => row.map(csvEsc).join(',')).join('\n');
}

function loadBuybackContact(){
  try{
    const raw = localStorage.getItem(BUYBACK_CONTACT_KEY);
    const data = raw ? JSON.parse(raw) : {};
    if($('buybackSenderName')) $('buybackSenderName').value = data.senderName || '';
    if($('buybackReplyEmail')) $('buybackReplyEmail').value = data.replyEmail || '';
    if($('buybackReplyEmailConfirm')) $('buybackReplyEmailConfirm').value = data.replyEmailConfirm || data.replyEmail || '';
    if($('buybackAltContact')) $('buybackAltContact').value = data.altContact || '';
    if($('buybackContactMemo')) $('buybackContactMemo').value = data.contactMemo || '';
  }catch(e){}
}

function buybackContactPayload(){
  return {
    senderName: String($('buybackSenderName')?.value || '').trim(),
    replyEmail: String($('buybackReplyEmail')?.value || '').trim(),
    replyEmailConfirm: String($('buybackReplyEmailConfirm')?.value || '').trim(),
    altContact: String($('buybackAltContact')?.value || '').trim(),
    contactMemo: String($('buybackContactMemo')?.value || '').trim()
  };
}

function saveBuybackContact(){
  const data = buybackContactPayload();
  localStorage.setItem(BUYBACK_CONTACT_KEY, JSON.stringify(data));
  return data;
}

function validBuybackEmail(email){
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(email || '').trim());
}

function buybackMailPayload(submissionId, targetList){
  const contact = saveBuybackContact();
  const list = Array.isArray(targetList) ? targetList : buybackUnsentEntries();
  return {
    app:'fujiya_collection',
    action:'buyback_mail',
    version:APP_VERSION,
    exportedAt:nowIso(),
    submissionId:String(submissionId || ''),
    senderName:contact.senderName,
    replyEmail:contact.replyEmail,
    contactMemo:contact.contactMemo,
    altContact:contact.altContact,
    itemCount:list.length,
    text:buybackRequestText(list),
    csv:'\ufeff' + buybackCsvString(list)
  };
}


async function testBuybackMailEndpoint(){
  const status = $('buybackStatus');
  if(status) status.textContent = '買取メール疎通テスト中…';

  try{
    const data = await fetchGasByPostFrame('buyback_mail_test_frame', {timeoutMs:16000});
    if(!data || !data.ok){
      throw new Error(data?.message || 'GASからok:falseが返りました');
    }
    if(status) status.textContent = `買取メール疎通OK：${data.version || 'version不明'} / 残り送信枠 ${data.remaining_quota ?? '不明'}`;
    toast('買取メール疎通OK');
    showMikeTalk(`買取メール疎通テストOKだよ！\nversion：${data.version || '不明'}\n残り送信枠：${data.remaining_quota ?? '不明'}\n\nこの状態ならCSVメール送信を試せるよ。`);
  }catch(e){
    const msg = String(e && e.message ? e.message : e);
    if(status) status.textContent = `買取メール疎通NG：${msg}`;
    toast('買取メール疎通NG');
    showMikeTalk(`買取メール疎通テストNGだよ。\n\nエラー内容：${msg}\n\n確認ポイント：\n1. GAS全文が最新版になっているか\n2. authorizeFujiyaBuybackMail を手動実行して権限承認したか\n3. デプロイを管理から新しいバージョンで更新したか\n4. HTML側のGAS URLが新しいWebアプリURLか\n\n公開中デプロイが古いと、このテストはタイムアウトするよ。`);
  }
}

function gasActionUrl(action){
  const base = getGasEndpoint();
  if(!base) return '';
  const sep = base.includes('?') ? '&' : '?';
  return base + sep + 'action=' + encodeURIComponent(action);
}


function fetchBuybackMailStatusJsonp(submissionId, options={}){
  const timeoutMs = Number(options.timeoutMs || 12000);
  const id = String(submissionId || '').trim();
  if(!id) return Promise.reject(new Error('送信確認IDがありません'));
  if(!getGasEndpoint()) return Promise.reject(new Error('共有同期URLが未設定です'));

  return new Promise((resolve, reject) => {
    const callbackName = '__fujiyaBuybackStatus_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2,7);
    const script = document.createElement('script');
    let settled = false;
    const timer = setTimeout(() => {
      cleanup();
      reject(new Error('送信結果確認がタイムアウトしました'));
    }, timeoutMs);

    function cleanup(){
      if(settled) return;
      settled = true;
      clearTimeout(timer);
      window.fujiyaKeepLateJsonpCallback_(callbackName);
      try{ script.remove(); }catch(e){}
    }

    window[callbackName] = data => {
      cleanup();
      resolve(data || {});
    };

    script.onerror = () => {
      cleanup();
      reject(new Error('送信結果をGASから確認できませんでした'));
    };

    script.src = buildGasUrl({
      action:'buyback_mail_status',
      submissionId:id,
      callback:callbackName,
      t:Date.now()
    });
    document.body.appendChild(script);
  });
}

function waitMs(ms){
  return new Promise(resolve => setTimeout(resolve, ms));
}

async function confirmBuybackMailStatus(submissionId, statusEl, timeoutMs=130000){
  let lastError = null;
  let checks = 0;
  const deadline = Date.now() + Math.max(30000, Number(timeoutMs || 130000));
  while(Date.now() < deadline){
    if(checks > 0) await waitMs(1800);
    checks += 1;
    if(statusEl) statusEl.textContent = `メール送信結果を確認中… ${checks}回目`;
    try{
      const data = await fetchBuybackMailStatusJsonp(submissionId, {timeoutMs:10000});
      if(data && (data.ok === true || data.status === 'sent')) return data;
      if(data && data.status === 'failed'){
        throw new Error(data.message || data.error || 'GAS側でメール送信に失敗しました');
      }
      if(statusEl && data && (data.status === 'waiting_lock' || data.status === 'processing')){
        statusEl.textContent = data.message || '別のGAS処理が完了するのを待っています…';
      }
    }catch(e){
      lastError = e;
      const message = String(e?.message || e);
      if(/GAS側でメール送信に失敗|権限|メールアドレス|添付/.test(message)) throw e;
    }
  }
  const suffix = lastError && lastError.message ? `（${lastError.message}）` : '';
  const error = new Error(`メールは送信済みの可能性がありますが、完了確認を取得できませんでした${suffix}。受信状況を確認するまで、この依頼は再送できません。`);
  error.mayHaveSent = true;
  error.submissionId = String(submissionId || '');
  throw error;
}

async function sendBuybackCsvMail(){
  const list = buybackUnsentEntries();
  const contact = saveBuybackContact();

  if(!list.length){
    toast('未送信の買取依頼はありません');
    showMikeTalk('未送信のソフトはないよ。新しく追加したソフトだけ、次のメール送信対象になるよ。');
    return;
  }
  if(!validBuybackEmail(contact.replyEmail)){
    toast('返信先メールを入力してください');
    const status = $('buybackStatus');
    if(status) status.textContent = '返信先メールアドレスを入力してください。';
    return;
  }
  if(contact.replyEmail !== contact.replyEmailConfirm){
    toast('返信先メールが一致しません');
    const status = $('buybackStatus');
    if(status) status.textContent = '返信先メールと確認用メールが一致していません。';
    return;
  }

  if(!getGasEndpoint()){
    toast('GAS URLが未設定です');
    showMikeTalk('CSVメール送信にはGAS WebアプリURLが必要だよ。\n設定タブの共有接続を確認してね。');
    return;
  }

  const submissionId = 'buyback_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2,10);
  const payload = buybackMailPayload(submissionId, list);
  const status = $('buybackStatus');
  const btn = $('buybackSendMailBtn');
  if(status) status.textContent = '買取依頼を送信中…';
  if(btn) btn.disabled = true;

  try{
    // ローカルHTMLでも安定する隠しフォームPOSTで送信し、JSONPで完了を確認する。
    submitGasPostFormNoWait('buyback_mail_frame', {
      payload:JSON.stringify(payload)
    }, submissionId, getGasEndpoint());
    const data = await confirmBuybackMailStatus(submissionId, status, 130000);

    if(!data || !data.ok){
      throw new Error(data?.message || data?.error || 'GASから送信完了を確認できませんでした');
    }

    markBuybackEntriesAssessing(list);
    renderBuybackPanel();
    if(status) status.textContent = `送信完了：${Number(data.item_count || payload.itemCount)}点 / ${data.filename || 'CSV添付'}`;
    toast('買取依頼を送信しました');
  }catch(e){
    const msg = String(e && e.message ? e.message : e);
    if(e?.mayHaveSent){
      markBuybackEntriesConfirming(list, e.submissionId || submissionId);
      renderBuybackPanel();
      if(status) status.textContent = `送信確認待ち：${list.length}点 / メール受信状況を確認してください`;
      toast('送信確認待ちにしました');
    }else{
      if(status) status.textContent = `送信できませんでした：${msg}`;
      toast('買取依頼を送信できませんでした');
    }
  }finally{
    renderBuybackPanel();
  }
}

