function loadBuybackHistory(){
  try{
    const raw = localStorage.getItem(BUYBACK_HISTORY_KEY);
    const list = raw ? JSON.parse(raw) : [];
    state.buybackHistory = Array.isArray(list) ? list.filter(Boolean) : [];
  }catch(e){
    state.buybackHistory = [];
  }
}

function saveBuybackHistory(){
  localStorage.setItem(BUYBACK_HISTORY_KEY, JSON.stringify(state.buybackHistory || []));
}

function buybackHistoryId(){
  return 'buyback_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2,8);
}

function buybackCompletionRecord(entry){
  const contact = typeof buybackContactPayload === 'function' ? buybackContactPayload() : {};
  return {
    historyId: buybackHistoryId(),
    completedAt: nowIso(),
    entry: JSON.parse(JSON.stringify(entry || {})),
    contact: {
      senderName: contact.senderName || '',
      replyEmail: contact.replyEmail || '',
      altContact: contact.altContact || '',
      contactMemo: contact.contactMemo || ''
    },
    buybackMeta: JSON.parse(JSON.stringify(buybackMeta(entry && entry.id)))
  };
}

function addBuybackHistoryRecord(entry){
  if(!entry) return null;
  const record = buybackCompletionRecord(entry);
  if(!state.buybackHistory) state.buybackHistory = [];
  state.buybackHistory.unshift(record);
  saveBuybackHistory();
  return record;
}

function restoreBuybackHistory(historyId){
  createUndoSnapshot('買取成立履歴から所持に戻す前');
  const record = (state.buybackHistory || []).find(h => h.historyId === historyId);
  if(!record || !record.entry){
    toast('戻すための履歴が見つかりません');
    return;
  }

  const exists = state.entries.some(e => e.id === record.entry.id);
  const restored = norm({
    ...record.entry,
    id: exists ? uid() : record.entry.id,
    owned: true,
    updatedAt: nowIso()
  });

  state.entries.unshift(hydrateEntryFromMaster(ensureSharedFields(restored)));
  state.buybackHistory = (state.buybackHistory || []).filter(h => h.historyId !== historyId);
  saveBuybackHistory();
  addEventLog('add', restored, '買取成立履歴から所持に戻しました');
  if(save()){
    render();
    scheduleAutoSync('買取成立取り消しで所持に戻す');
    toast('所持に戻しました');
    showMikeTalk(`「${restored.title}」を買取成立履歴から所持に戻したよ。`);
  }
}

function deleteBuybackHistory(historyId){
  state.buybackHistory = (state.buybackHistory || []).filter(h => h.historyId !== historyId);
  saveBuybackHistory();
  renderBuybackHistoryPanel();
  toast('買取成立履歴を消しました');
}

function clearBuybackHistory(){
  if(!(state.buybackHistory || []).length){
    toast('買取成立履歴は空です');
    return;
  }
  const ok = confirm('買取成立履歴をすべて削除しますか？\n所持に戻すための退避データも消えます。');
  if(!ok) return;
  state.buybackHistory = [];
  saveBuybackHistory();
  renderBuybackHistoryPanel();
  toast('買取成立履歴を全クリアしました');
}

function buybackHistoryCsv(){
  const header = ['成立日','買取状態','送信日','機種','タイトル','状態','動作確認','購入価格','購入日','購入店舗','メモ','共有ID','登録個体ID','返信先','予備連絡先','連絡メモ'];
  const rows = (state.buybackHistory || []).map(h => {
    const e = h.entry || {};
    const c = h.contact || {};
    return [
      h.completedAt || '',
      buybackStatusLabel(h.buybackMeta?.status || 'assessing', h.buybackMeta),
      h.buybackMeta?.lastSentAt || h.buybackMeta?.sentAt || '',
      e.platform || '',
      e.title || '',
      buybackEntryConditionText(e),
      buybackOperationStatusLabel(e),
      e.purchasePrice || '',
      e.purchaseDate || '',
      e.purchaseStore || '',
      e.memo || '',
      e.sharedTitleId || '',
      e.id || '',
      c.replyEmail || '',
      c.altContact || '',
      c.contactMemo || ''
    ];
  });
  return [header, ...rows].map(row => row.map(csvEsc).join(',')).join('\n');
}

function downloadBuybackHistoryCsv(){
  if(!(state.buybackHistory || []).length){
    toast('買取成立履歴は空です');
    return;
  }
  dl(`fujiya_buyback_completed_v${APP_VERSION.replaceAll('.', '_')}_${new Date().toISOString().slice(0,10)}.csv`, '\ufeff' + buybackHistoryCsv(), 'text/csv');
}

function buybackHistoryDateKey(value){
  const raw = String(value || '').trim();
  if(raw && /^\d{4}-\d{2}-\d{2}/.test(raw)) return raw.slice(0, 10);
  const d = value ? new Date(value) : new Date();
  if(isNaN(d.getTime())) return 'unknown';
  return d.toISOString().slice(0, 10);
}

function buybackHistoryDateLabel(dateKey){
  if(!dateKey || dateKey === 'unknown') return '日付不明';
  const d = new Date(dateKey + 'T00:00:00');
  if(isNaN(d.getTime())) return dateKey;
  return `${d.getFullYear()}/${String(d.getMonth()+1).padStart(2,'0')}/${String(d.getDate()).padStart(2,'0')}`;
}

function buybackHistoryGroupsByDate(){
  const map = new Map();
  (state.buybackHistory || []).forEach(h => {
    const key = buybackHistoryDateKey(h.completedAt);
    if(!map.has(key)) map.set(key, []);
    map.get(key).push(h);
  });
  return Array.from(map.entries())
    .sort((a,b) => String(b[0]).localeCompare(String(a[0])))
    .map(([dateKey, items]) => ({
      dateKey,
      items: items.slice().sort((a,b) => String(b.completedAt || '').localeCompare(String(a.completedAt || '')))
    }));
}

function buybackHistoryDateCsv(dateKey){
  const group = buybackHistoryGroupsByDate().find(g => g.dateKey === dateKey);
  if(!group) return '';
  const header = ['成立日','送信日','機種','タイトル','状態','動作確認','購入価格','購入日','購入店舗','メモ','共有ID','登録個体ID','返信先','予備連絡先','連絡メモ'];
  const rows = group.items.map(h => {
    const e = h.entry || {};
    const c = h.contact || {};
    return [
      h.completedAt || '', h.buybackMeta?.lastSentAt || h.buybackMeta?.sentAt || '',
      e.platform || '', e.title || '', buybackEntryConditionText(e), buybackOperationStatusLabel(e),
      e.purchasePrice || '', e.purchaseDate || '', e.purchaseStore || '', e.memo || '', e.sharedTitleId || '', e.id || '',
      c.replyEmail || '', c.altContact || '', c.contactMemo || ''
    ];
  });
  return [header, ...rows].map(row => row.map(csvEsc).join(',')).join('\n');
}

function downloadBuybackHistoryDateCsv(dateKey){
  const csv = buybackHistoryDateCsv(dateKey);
  if(!csv){ toast('指定日の履歴がありません'); return; }
  const version = APP_VERSION_LABEL.replace(/^V/i, '').replaceAll('.', '_');
  dl(`fujiya_buyback_completed_${dateKey}_v${version}.csv`, '\ufeff' + csv, 'text/csv');
}

function renderBuybackHistoryPanel(){
  const status = $('buybackHistoryStatus');
  const listBox = $('buybackHistoryList');
  const detailBox = $('buybackHistoryDetail');
  if(!status || !listBox || !detailBox) return;

  const groups = buybackHistoryGroupsByDate();
  const total = (state.buybackHistory || []).length;
  status.textContent = total ? `買取成立履歴：${total}件 / ${groups.length}日分` : '買取成立履歴は空です。';

  if(!groups.length){
    listBox.innerHTML = '<div class="buyback-empty">買取成立にしたソフトがここに保存されます。</div>';
    detailBox.innerHTML = '';
    return;
  }

  listBox.innerHTML = groups.map(g => {
    const first = g.items[0] || {};
    const last = g.items[g.items.length - 1] || {};
    const sample = g.items.slice(0, 3).map(h => h.entry?.title).filter(Boolean).join(' / ');
    return `
      <div class="buyback-history-date-row">
        <div class="buyback-history-date-main">
          <div class="buyback-history-date-title">${esc(buybackHistoryDateLabel(g.dateKey))}</div>
          <div class="buyback-history-date-meta">
            <span>成立 ${g.items.length}件</span>
            ${sample ? `<span>例：${esc(sample)}</span>` : ''}
            <span>${last.completedAt ? esc(fmt(last.completedAt)) : '—'} ～ ${first.completedAt ? esc(fmt(first.completedAt)) : '—'}</span>
          </div>
        </div>
        <div class="buyback-history-date-actions">
          <button type="button" class="buyback-restore-btn" data-buyback-history-date="${esc(g.dateKey)}">開く</button>
          <button type="button" class="ghost" data-buyback-history-date-csv="${esc(g.dateKey)}">CSV</button>
        </div>
      </div>`;
  }).join('');

  detailBox.innerHTML = '';
}

