function bindBuybackHistoryEvents(){
  const panel = $('buybackHistoryPanel');
  if(!panel) return;

  $('buybackHistoryCsvBtn')?.addEventListener('click', downloadBuybackHistoryCsv);
  $('buybackHistoryClearBtn')?.addEventListener('click', clearBuybackHistory);
  $('buybackHistoryTalkBtn')?.addEventListener('click', () => {
    showMikeTalk('買取成立履歴は、成立で所持から外したソフトの退避場所だよ。\n間違えた時は「所持に戻す」で復元できるよ。');
  });

  panel.addEventListener('click', ev => {
    const dateBtn = ev.target.closest('[data-buyback-history-date]');
    if(dateBtn){ renderBuybackHistoryDateDetail(dateBtn.dataset.buybackHistoryDate); return; }
    const csvBtn = ev.target.closest('[data-buyback-history-date-csv]');
    if(csvBtn){ downloadBuybackHistoryDateCsv(csvBtn.dataset.buybackHistoryDateCsv); return; }
    const closeBtn = ev.target.closest('[data-buyback-history-detail-close]');
    if(closeBtn){ const detailBox = $('buybackHistoryDetail'); if(detailBox) detailBox.innerHTML = ''; return; }
    const restoreBtn = ev.target.closest('[data-buyback-history-restore]');
    if(restoreBtn){
      restoreBuybackHistory(restoreBtn.dataset.buybackHistoryRestore);
      return;
    }
    const deleteBtn = ev.target.closest('[data-buyback-history-delete]');
    if(deleteBtn){
      deleteBuybackHistory(deleteBtn.dataset.buybackHistoryDelete);
    }
  });
}


function completeBuybackEntry(id){
  const entry = state.entries.find(e => e.id === id);
  if(!entry){
    removeBuybackEntry(id, {skipConfirm:true});
    return;
  }
  if(buybackMeta(id).status !== 'assessing'){
    toast('送信前のソフトは買取成立にできません');
    showMikeTalk('先に買取依頼を送信して、査定中になったソフトだけ成立処理できるよ。');
    return;
  }
  const ok = confirm(`買取成立として「${entry.title}」を所持から外しますか？\n\nこの個体はコレクション一覧から削除され、所持数から減ります。`);
  if(!ok) return;

  createUndoSnapshot('買取成立の前');
  addBuybackHistoryRecord(entry);
  state.entries = (state.entries || []).filter(e => e.id !== id);
  state.buybackEntryIds = (state.buybackEntryIds || []).filter(x => x !== String(id));
  if(state.buybackMeta) delete state.buybackMeta[String(id)];
  saveBuyback();
  saveBuybackMeta();
  addEventLog('delete', entry, '買取成立：所持から外しました');
  if(save()){
    render();
    refreshCardDetail();
    scheduleAutoSync('買取成立で所持から外す');
    toast('買取成立として所持から外しました');
    showMikeTalk(`「${entry.title}」を買取成立として所持から外したよ。\n共有DBの保存確認後、共有所持率も自動更新するよ。`);
  }
}

function completeAllBuybackEntries(){
  const list = buybackAssessingEntries();
  if(!list.length){
    toast('成立処理できる査定中の商品はありません');
    showMikeTalk('未送信のソフトは成立処理できないよ。買取依頼を送信して査定中になった商品だけが対象だよ。');
    return;
  }
  const ok = confirm(`査定中の${list.length}点を、まとめて買取成立として所持から外しますか？`);
  if(!ok) return;

  createUndoSnapshot('買取成立まとめ処理の前');
  list.forEach(entry => addBuybackHistoryRecord(entry));
  const ids = new Set(list.map(e => String(e.id)));
  const removedTitles = list.map(e => e.title).join(' / ');
  state.entries = (state.entries || []).filter(e => !ids.has(String(e.id)));
  state.buybackEntryIds = (state.buybackEntryIds || []).filter(id => !ids.has(String(id)));
  if(state.buybackMeta){
    ids.forEach(id => delete state.buybackMeta[String(id)]);
  }
  saveBuyback();
  saveBuybackMeta();
  addEventLog('delete', null, `買取成立：${list.length}点を所持から外しました：${removedTitles}`);
  if(save()){
    render();
    refreshCardDetail();
    scheduleAutoSync('買取成立まとめて所持から外す');
    toast(`${list.length}点を買取成立として所持から外しました`);
    showMikeTalk(`${list.length}点を買取成立として所持から外したよ。\n共有DBの保存確認後、共有所持率も自動更新するよ。`);
  }
}

function renderBuybackPanel(){
  const status = $('buybackStatus');
  const listBox = $('buybackList');
  const detailBox = $('buybackDetail');
  if(!status || !listBox || !detailBox) return;

  const list = buybackEntries();
  const summary = buybackStatusSummary();
  const sendBtn = $('buybackSendMailBtn');
  const completeAllBtn = $('buybackCompleteAllBtn');
  const panel = $('buybackPanel');
  const countBadge = $('buybackItemCountBadge');
  const duplicateBtn = $('buybackChooseDuplicatesBtn');
  const duplicateCount = $('buybackDuplicateTitleCount');
  const duplicateGroups = buybackDuplicateOwnedGroups();

  if(duplicateBtn){
    duplicateBtn.disabled = duplicateGroups.length === 0;
    duplicateBtn.classList.toggle('is-disabled', duplicateGroups.length === 0);
  }
  if(duplicateCount){
    duplicateCount.textContent = `${duplicateGroups.length}タイトル`;
  }

  if(panel){
    panel.classList.toggle('has-buyback-items', list.length > 0);
    panel.classList.toggle('has-buyback-unsent', summary.unsent > 0);
    panel.classList.toggle('has-buyback-assessing', summary.assessing > 0);
  }
  if(countBadge) countBadge.textContent = `${list.length}点`;

  if(sendBtn){
    sendBtn.disabled = summary.unsent === 0;
    sendBtn.textContent = summary.unsent > 0 ? `未送信${summary.unsent}点をメール送信` : '未送信分はありません';
  }
  if(completeAllBtn){
    completeAllBtn.disabled = summary.assessing === 0;
    completeAllBtn.textContent = summary.assessing > 0
      ? `査定中${summary.assessing}点の成立処理`
      : '成立処理できる商品はありません';
  }

  status.textContent = list.length
    ? `買取相談リスト：${list.length}点 / 未送信 ${summary.unsent}点 / 査定中 ${summary.assessing}点 / 送信確認待ち ${summary.confirming}点`
    : '買取相談リストは空です。';
  detailBox.innerHTML = '';

  if(!list.length){
    status.textContent = '';
    listBox.innerHTML = `
      <div class="buyback-empty buyback-empty-clean">
        <strong>買取リストは空です</strong>
        <span>所持しているゲームから、査定に出したいものを追加してください。</span>
      </div>`;
    return;
  }

  const sample = list.slice(0, 3).map(e => e.title).filter(Boolean).join(' / ');
  const platforms = Array.from(new Set(list.map(e => e.platform).filter(Boolean))).slice(0, 6).join(' / ');
  listBox.innerHTML = `
    <div class="buyback-summary-row">
      <div>
        <div class="buyback-summary-title">買取相談リスト</div>
        <div class="buyback-summary-meta">
          相談点数：${list.length}点${platforms ? ` / 機種：${esc(platforms)}` : ''}<br>
          未送信：${summary.unsent}点 / 査定中：${summary.assessing}点 / 送信確認待ち：${summary.confirming}点<br>
          ${sample ? `例：${esc(sample)}` : '明細は開くボタンで確認できます。'}
        </div>
      </div>
      <div class="buyback-summary-actions">
        <button type="button" class="buyback-restore-btn" data-buyback-open-detail>査定依頼明細を開く</button>
      </div>
    </div>
  `;
}

