function buybackReadonlyPartHtml(entry){
  return PARTS.map(([key,label]) => {
    const part = getPart(entry || {}, key);
    const condition = part.has ? (COND_LABELS[part.condition] || '未設定') : 'なし';
    return `
      <div class="buyback-readonly-part${part.has ? '' : ' missing'}">
        <span>${esc(label)}</span>
        <strong>${esc(condition)}</strong>
      </div>`;
  }).join('');
}

