window.closeBuybackReadonlyDetail = closeBuybackReadonlyDetail;

function bindBuybackEvents(){
  const panel = $('buybackPanel');
  if(!panel) return;


  $('buybackChooseEntriesBtn')?.addEventListener('click', () => openBuybackEntryPicker());
  $('buybackChooseDuplicatesBtn')?.addEventListener('click', openBuybackDuplicatePicker);
  $('buybackSendMailBtn')?.addEventListener('click', sendBuybackCsvMail);
  $('buybackMailTestBtn')?.addEventListener('click', testBuybackMailEndpoint);
  $('buybackDownloadCsvBtn')?.addEventListener('click', downloadBuybackCsv);
  $('buybackClearBtn')?.addEventListener('click', clearBuybackList);
  $('buybackCompleteAllBtn')?.addEventListener('click', completeAllBuybackEntries);
  $('buybackTalkBtn')?.addEventListener('click', () => {
    showMikeTalk('売りたいソフトを買取相談リストへ追加して、返信先を確認したら未送信分を送ってね。\n送信済みの商品は査定中になり、買取成立後に所持から外せるよ。送信完了だけ確認できなかった場合は、送信確認待ちとして再送を止めるよ。');
  });
  ['buybackSenderName','buybackReplyEmail','buybackReplyEmailConfirm','buybackAltContact','buybackContactMemo'].forEach(id => {
    const el = $(id);
    if(el) el.addEventListener('input', () => saveBuybackContact());
  });
  panel.addEventListener('click', ev => {
    const openBtn = ev.target.closest('[data-buyback-open-detail]');
    if(openBtn){ renderBuybackDetail(); return; }
    const closeBtn = ev.target.closest('[data-buyback-detail-close]');
    if(closeBtn){ const detailBox = $('buybackDetail'); if(detailBox) detailBox.innerHTML = ''; return; }
    const viewBtn = ev.target.closest('[data-buyback-view-entry]');
    if(viewBtn){
      openBuybackReadonlyDetail(viewBtn.dataset.buybackViewEntry || '');
      return;
    }
    const receivedBtn = ev.target.closest('[data-buyback-confirm-received]');
    if(receivedBtn){ resolveBuybackConfirming(receivedBtn.dataset.buybackConfirmReceived, 'received'); return; }
    const unsentBtn = ev.target.closest('[data-buyback-confirm-unsent]');
    if(unsentBtn){ resolveBuybackConfirming(unsentBtn.dataset.buybackConfirmUnsent, 'unsent'); return; }
    const completeBtn = ev.target.closest('[data-buyback-complete]');
    if(completeBtn){ completeBuybackEntry(completeBtn.dataset.buybackComplete); return; }
    const btn = ev.target.closest('[data-buyback-remove]');
    if(btn) removeBuybackEntry(btn.dataset.buybackRemove);
  });
}


function cloneEntryForAdditionalCopy(source){
  const base = JSON.parse(JSON.stringify(source || {}));
  const clone = norm({
    ...base,
    id: uid(),
    owned: true,
    createdAt: nowIso(),
    updatedAt: nowIso()
  });

  // タイトル・機種など「作品情報」は引き継ぐ
  clone.title = source.title || clone.title;
  clone.platform = source.platform || clone.platform;
  clone.titleKey = source.titleKey || titleKey(source.title || '');
  clone.canonicalTitle = source.canonicalTitle || source.title || clone.title;
  clone.sharedTitleId = source.sharedTitleId || '';
  clone.sharedStatus = source.sharedStatus || (clone.sharedTitleId ? 'confirmed' : 'unconfirmed');
  clone.localSharedId = source.localSharedId || (clone.sharedTitleId ? source.sharedTitleId : localSharedId(clone.platform, clone.titleKey || titleKey(clone.title)));

  // 個体ごとの登録情報は未設定へ戻す
  const blankFields = [
    'purchaseDate','purchasePrice','purchaseStore',
    'playStatus','clearHours',
    'memo','marketMemo','stockLocation',
    'photoData','buybackOperationStatus'
  ];
  blankFields.forEach(key => { clone[key] = ''; });

  const falseFields = [
    'operationChecked','cleaned'
  ];
  falseFields.forEach(key => { clone[key] = false; });

  // 画像の表示調整も初期化
  clone.photoTransform = { zoom:1, x:0, y:0, rotate:0 };

  // 内容物・コンディションはコピーしない
  clone.parts = Object.fromEntries(
    PARTS.map(([key]) => [key, { has:false, condition:'' }])
  );
  clone.overallCondition = '';

  // 個体ごとの評価も未設定に戻す
  clone.rating = 0;

  return hydrateEntryFromMaster(ensureSharedFields(clone));
}

function addOneCopyFromEntry(id){
  createUndoSnapshot('＋1本追加の前');
  const source = state.entries.find(e => e.id === id);
  if(!source){
    toast('追加元のデータが見つかりません');
    return;
  }
  const copy = cloneEntryForAdditionalCopy(source);
  state.entries.unshift(copy);
  if(save()){
    addEventLog('add', copy, '同じソフトを＋1本追加');
    addRareLogIfNeeded(copy, '＋1本追加でレア判定');
    render();
    refreshCardDetail();
    scheduleAutoSync('＋1本追加');
    const info = duplicateCountInfo(copy);
    toast('同じソフトを＋1本追加しました');
    showMikeTalk(`「${copy.title}」をもう1本追加したよ。\n購入日・価格・店舗・メモ・写真は空欄にしたよ。\n現在の所持数：${info.owned}本 / ダブり：${info.duplicateOwned}本`);
  }
}


function renderCardDetailModal(entry){
  const e = hydrateEntryFromMaster({...entry});
  const rare = rareInfoForEntry(e);
  const stat = remoteStatFor(e);
  const shelfLabel = shelfHas(e.id) ? 'ショーケースから外す' : 'ショーケースに追加';
  const ratingText = ratingNumber(e.rating) ? ratingStars(e.rating) : '未評価';
  const buybackEligibility = buybackEntryEligibility(e);
  const buybackButtonLabel = buybackHas(e.id)
    ? '買取リスト済み'
    : (buybackEligibility.ok ? '買取相談へ追加' : (buybackEligibility.reason === 'digital' ? 'DL版は買取対象外' : '欲しい登録は対象外'));
  const buybackButtonDisabled = buybackHas(e.id) || !buybackEligibility.ok;
  const detailImageView = photoViewForEntry(e);
  const cover = e.photoData
    ? `<div class="detail-cover-media">
        <img class="detail-cover-img zoomable" ${detailImageView.set?'data-photo-view="1"':''} style="${detailImageView.set?photoViewInlineStyle(e):''}" src="${e.photoData}" alt="${esc(e.title)}" data-detail-action="zoom">
      </div>`
    : `<div class="detail-cover-placeholder">NO IMAGE</div>`;
  const shared = sharedStateLabel(e);
  const rareBlock = rare && rare.burst
    ? `<div class="detail-rare ${rare.level === 'ultra' ? 'ultra' : ''}">
        <div class="detail-rare-label">${esc(rare.label)}</div>
        <div class="detail-rare-text">${esc(rare.text)}</div>
      </div>`
    : '';
  const purchaseRows = [
    detailInfoRow('購入日', e.purchaseDate ? fmtDateOnly(e.purchaseDate) : ''),
    detailInfoRow('購入価格', e.purchasePrice ? yen(e.purchasePrice) : ''),
    detailInfoRow('購入店舗', e.purchaseStore ? esc(e.purchaseStore) : '')
  ].join('');
  const playRows = [
    detailInfoRow('プレイ状況', e.playStatus ? playStatusLabel(e.playStatus) : ''),
    detailInfoRow('自分のクリア時間', clearTimeShareValue(e) !== null ? formatClearHours(e.clearHours) : '')
  ].join('');
  const overallConditionLabel = e.overallCondition ? ({S:'S：極美品', A:'A：美品', B:'B：並品', C:'C：難あり', J:'J：ジャンク'}[e.overallCondition] || e.overallCondition) : '';
  const managementRows = [
    detailInfoRow('総合状態', overallConditionLabel ? esc(overallConditionLabel) : ''),
    detailInfoRow('動作確認', e.operationChecked ? '済み' : ''),
    detailInfoRow('端子清掃', e.cleaned ? '済み' : ''),
    detailInfoRow('保管場所', e.stockLocation ? esc(e.stockLocation) : '')
  ].join('');
  const masterRows = [
    detailInfoRow('発売日', e.releaseDate ? fmtDateOnly(e.releaseDate) : (e.rawReleaseDate ? esc(e.rawReleaseDate) : '')),
    detailInfoRow('メーカー', e.maker ? esc(e.maker) : ''),
    detailInfoRow('ジャンル', e.genre ? esc(e.genre) : ''),
    detailInfoRow('品番', e.productCode ? esc(e.productCode) : ''),
    detailInfoRow('備考', e.remarks ? esc(e.remarks) : '')
  ].join('');
  const sharedRows = [
    detailInfoRow('共有状態', `<span class="pill shared ${shared.cls}">${esc(shared.text)}</span>`),
    detailInfoRow('共有ID', e.sharedTitleId ? esc(e.sharedTitleId) : '未確定'),
    detailInfoRow('共有所持率', sharedRateDetailValue(stat)),
    detailInfoRow('共有平均レート', stat && stat.rating_count ? `${Number(stat.rating_avg || 0).toFixed(2)} / ${stat.rating_count}件` : '未取得'),
    detailInfoRow('クリア目安', sharedClearTimeText(stat))
  ].join('');
  const sharedPriceBlock = sharedPurchaseReadableBlock(stat);

  return `
    <div class="detail-layout">
      <div class="detail-cover">${cover}</div>
      <div class="detail-main">
        <div class="detail-title-block">
          <div class="detail-platform">${esc(e.platform)} / ${e.owned ? '所持' : '欲しい'} / ${esc(mediaTypeLabel(e.mediaType))}</div>
          <div class="detail-title">${esc(e.title)}</div>
          <div class="detail-rating">${esc(ratingText)} ${isCompleteEntry(e) ? '<span class="pill complete-badge detail-complete-badge">完品</span>' : ''} ${collectionBadgeHtml(e)} ${duplicateCountBadgeHtml(e)}</div>
        </div>
        ${rareBlock}
        <div class="detail-action-grid primary detail-primary-actions">
          <button type="button" class="ghost action-unified" data-detail-action="edit">編集</button>
          <button type="button" class="ghost action-unified add-copy-btn" data-detail-action="addcopy">同じソフトを＋1本</button>
          <button type="button" class="ghost action-unified" data-detail-action="shelf">${esc(shelfLabel)}</button>
        </div>

      </div>
    </div>

    ${renderVideoHashtagPanel(e)}

    ${sameTitleCopiesPanelHtml(e)}

    <div class="detail-section">
      <div class="detail-section-title">管理操作</div>
      <div class="detail-action-grid">
        <button type="button" class="ghost action-unified" data-detail-action="rematch">再照合</button>
        <button type="button" class="buyback-btn action-unified" data-detail-action="buyback" ${buybackButtonDisabled ? 'disabled aria-disabled="true"' : ''}>${esc(buybackButtonLabel)}</button>
        <button type="button" class="danger" data-detail-action="delete">削除</button>
      </div>
    </div>

    <div class="detail-two-col">
      <div class="detail-section">
        <div class="detail-section-title">作品情報</div>
        <div class="detail-info">${masterRows || '<div class="detail-empty">作品情報はまだありません。</div>'}</div>
      </div>
      <div class="detail-section">
        <div class="detail-section-title">共有情報</div>
        <div class="detail-info">${sharedRows}</div>
        ${sharedPriceBlock}
      </div>
    </div>

    ${playRows ? `<div class="detail-section"><div class="detail-section-title">プレイ記録</div><div class="detail-info">${playRows}</div></div>` : ''}
    ${purchaseRows ? `<div class="detail-section"><div class="detail-section-title">購入情報</div><div class="detail-info">${purchaseRows}</div></div>` : ''}
    ${managementRows ? `<div class="detail-section admin-only"><div class="detail-section-title">店長用：管理・整備</div><div class="detail-info">${managementRows}</div></div>` : ''}
    <div class="detail-section">
      <div class="detail-section-title">内容物・コンディション</div>
      <div class="detail-parts">${partsSummary(e) || '<div class="detail-empty">内容物情報はありません。</div>'}</div>
      <div class="detail-complete-note">${completeStatusText(e)}</div>
    </div>
    ${e.marketMemo ? `<div class="detail-section admin-only"><div class="detail-section-title">店長用：価格メモ</div><div class="detail-memo">${esc(e.marketMemo)}</div></div>` : ''}
    <div class="detail-section">
      <div class="detail-section-title">メモ</div>
      <div class="detail-memo">${e.memo ? esc(e.memo) : `更新日：${fmt(e.updatedAt)}`}</div>
    </div>
  `;
}

function openCardDetail(id){
  const entry = state.entries.find(e => e.id === id);
  if(!entry){
    toast('詳細を開くカードが見つかりません');
    return;
  }
  currentDetailEntryId = id;
  $('cardDetailTitle').textContent = entry.title || 'カード詳細';
  $('cardDetailKicker').textContent = `${entry.platform || ''} / カード詳細`;
  $('cardDetailBody').innerHTML = renderCardDetailModal(entry);
  $('cardDetailModal').classList.add('show');
  $('cardDetailModal').setAttribute('aria-hidden', 'false');
}

function closeCardDetail(){
  currentDetailEntryId = null;
  $('cardDetailModal').classList.remove('show');
  $('cardDetailModal').setAttribute('aria-hidden', 'true');
  $('cardDetailBody').innerHTML = '';
}

function refreshCardDetail(){
  if(!currentDetailEntryId) return;
  const entry = state.entries.find(e => e.id === currentDetailEntryId);
  if(!entry){
    closeCardDetail();
    return;
  }
  $('cardDetailTitle').textContent = entry.title || 'カード詳細';
  $('cardDetailKicker').textContent = `${entry.platform || ''} / カード詳細`;
  $('cardDetailBody').innerHTML = renderCardDetailModal(entry);
}

function handleDetailModalAction(ev){
  const target = ev.target.closest('[data-detail-action]');
  if(!target || !currentDetailEntryId) return;
  const action = target.dataset.detailAction;
  const id = currentDetailEntryId;
  ev.preventDefault();
  if(action === 'zoom'){
    const entry = state.entries.find(e => e.id === id);
    if(entry && entry.photoData) openImageModal(entry.photoData, entry.title);
    return;
  }
  if(action === 'video-copy-tags'){
    copyVideoHashtagsForEntry(id);
    return;
  }
  if(action === 'video-copy-guide'){
    copyVideoGuideForEntry(id);
    return;
  }
  if(action === 'edit'){
    closeCardDetail();
    openEditEntry(id);
    return;
  }
  if(action === 'edit-copy'){
    const targetId = target.dataset.copyEntryId || id;
    closeCardDetail();
    openEditEntry(targetId);
    return;
  }
  if(action === 'buyback-copy'){
    const targetId = target.dataset.copyEntryId || id;
    addEntryToBuybackFromDetail(targetId);
    return;
  }
  if(action === 'buyback'){
    addEntryToBuybackFromDetail(id);
    return;
  }
  if(action === 'addcopy'){
    addOneCopyFromEntry(id);
    return;
  }
  if(action === 'shelf'){
    toggleShelfEntry(id);
    refreshCardDetail();
    return;
  }
  if(action === 'talk'){
    talkEntry(id);
    return;
  }
  if(action === 'rematch'){
    closeCardDetail();
    openRematchModal(id);
    return;
  }
  if(action === 'delete'){
    closeCardDetail();
    deleteEntry(id);
  }
}
function nowIso(){ return new Date().toISOString(); }
function uid(){ return 'local_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2,8); }


function generateUserId(){
  if(window.crypto?.randomUUID){
    return 'fujiya_' + crypto.randomUUID();
  }
  return 'fujiya_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2,10);
}

function getUserId(){
  let id = localStorage.getItem(USER_ID_KEY);
  if(!id){
    id = generateUserId();
    localStorage.setItem(USER_ID_KEY, id);
  }
  return id;
}

function setSetupDone(){
  localStorage.setItem(SETUP_KEY, nowIso());
  localStorage.setItem(FIRST_RUN_VERSION_KEY, '1');
}

function setupDone(){
  return !!localStorage.getItem(SETUP_KEY);
}

function shortUserId(id=getUserId()){
  const text = String(id || '');
  return text.length > 18 ? text.slice(0, 14) + '…' + text.slice(-6) : text;
}

function regenerateUserId(silent=false){
  createUndoSnapshot('個人ID再発行の前');
  const oldId = getUserId();
  const id = generateUserId();
  localStorage.setItem(USER_ID_KEY, id);
  setSetupDone();
  addEventLog('edit', null, `個人ID再発行：${shortUserId(oldId)} → ${shortUserId(id)}`);
  save();
  render();
  if(!silent){
    toast('新しい個人IDを発行しました');
    showMikeTalk(`新しい個人IDを発行したよ！\n共有所持率へ送る時は、このIDが新しいユーザーとして使われるよ。`);
  }
  return id;
}

function renderDistributionStatus(){
  const box = $('distributionStatus');
  if(!box) return;
  const id = getUserId();
  box.innerHTML = `この端末の個人ID：<span class="sync-id">${esc(id)}</span><br>短縮表示：${esc(shortUserId(id))}<br>初回案内：${setupDone() ? '完了' : '未完了'}`;
}

async function copyUserId(){
  const id = getUserId();
  try{
    await navigator.clipboard.writeText(id);
    toast('個人IDをコピーしました');
  }catch(e){
    toast('コピーできませんでした');
    showMikeTalk(`個人ID：${id}`);
  }
}

async function confirmRegenerateUserId(){
  const ok = await askDeleteConfirm('新しい個人IDを発行しますか？登録データは消えませんが、共有DB上では別ユーザーとして扱われます。');
  if(!ok) return;
  regenerateUserId(false);
}

let firstRunStep = 1;

function setFirstRunStep(step){
  firstRunStep = Math.max(1, Math.min(3, Number(step) || 1));
  document.querySelectorAll('#firstRunModal [data-first-run-step]').forEach(el => {
    el.classList.toggle('active', Number(el.dataset.firstRunStep) === firstRunStep);
  });
  document.querySelectorAll('#firstRunModal [data-first-run-progress]').forEach(el => {
    const n = Number(el.dataset.firstRunProgress);
    el.classList.toggle('active', n === firstRunStep);
    el.classList.toggle('done', n < firstRunStep);
  });
  const card = document.querySelector('#firstRunModal .onboarding-card');
  if(card) card.scrollTop = 0;
}

function applyFirstRunOptions(){
  const share = $('firstRunShareOptIn') ? !!$('firstRunShareOptIn').checked : true;
  const sharePrice = $('firstRunSharePriceOptIn') ? !!$('firstRunSharePriceOptIn').checked : true;
  const receive = $('firstRunAutoReceive') ? !!$('firstRunAutoReceive').checked : true;

  setShareOptIn(share);
  setSharePurchasePriceOptIn(sharePrice);
  setAutoReceiveEnabled(receive);
}

function openFirstRunModal(options={}){
  firstRunPreviewMode = !!options.preview;
  const input = $('firstRunName');
  const share = $('firstRunShareOptIn');
  const sharePrice = $('firstRunSharePriceOptIn');
  const receive = $('firstRunAutoReceive');
  const modal = $('firstRunModal');

  if(input) input.value = firstRunPreviewMode ? 'プレビュー中' : getStoredUserName();
  if(share) share.checked = getShareOptIn();
  if(sharePrice) sharePrice.checked = getSharePurchasePriceOptIn();
  if(receive) receive.checked = getAutoReceiveEnabled();

  setFirstRunStep(1);
  modal.classList.toggle('preview-mode', firstRunPreviewMode);
  modal.classList.add('show');
  modal.setAttribute('aria-hidden','false');
}

function closeFirstRunModal(){
  firstRunPreviewMode = false;
  $('firstRunModal').classList.remove('show', 'preview-mode');
  $('firstRunModal').setAttribute('aria-hidden','true');
}

function completeFirstRun(goRegister=true){
  if(firstRunPreviewMode){
    closeFirstRunModal();
    toast('初回画面プレビューを閉じました');
    return;
  }

  const name = String($('firstRunName')?.value || '').trim();
  if(name) localStorage.setItem(USER_NAME_KEY, name.slice(0,20));
  else localStorage.removeItem(USER_NAME_KEY);
  getUserId();
  applyFirstRunOptions();
  setSetupDone();
  closeFirstRunModal();
  render();
  if(goRegister) setUiTab('register', {targetId:'entryPanel'});
  toast('準備完了。最初のソフトを登録してみよう');
  window.setTimeout(() => {
    try { window.fujiyaMaybeOpenTutorialAfterAuth?.(); } catch (_) {}
  }, 260);
}

function firstRunRestore(){
  if(firstRunPreviewMode){
    closeFirstRunModal();
    toast('プレビュー中のため復元画面は開きません');
    return;
  }

  const name = String($('firstRunName')?.value || '').trim();
  if(name) localStorage.setItem(USER_NAME_KEY, name.slice(0,20));
  else localStorage.removeItem(USER_NAME_KEY);
  getUserId();
  applyFirstRunOptions();
  setSetupDone();
  closeFirstRunModal();
  openBackupImportBox();
}

function firstRunGuide(){
  if(!firstRunPreviewMode){
    applyFirstRunOptions();
    setSetupDone();
  }
  closeFirstRunModal();
  openTutorialModal();
}

function closeFirstRunPreview(){
  closeFirstRunModal();
  toast('初回画面プレビューを閉じました');
}

function previewFirstRunScreen(){
  openFirstRunModal({preview:true});
}


function tutorialSeen(){
  return localStorage.getItem(TUTORIAL_SEEN_KEY) === '1';
}

function markTutorialSeen(){
  localStorage.setItem(TUTORIAL_SEEN_KEY, '1');
}

function openTutorialModal(){
  const modal = $('tutorialModal');
  if(!modal) return;
  modal.classList.add('show');
  modal.setAttribute('aria-hidden','false');
}

function closeTutorialModal(markSeen=true){
  const modal = $('tutorialModal');
  if(!modal) return;
  modal.classList.remove('show');
  modal.setAttribute('aria-hidden','true');
  if(markSeen) markTutorialSeen();
}

function goTutorialTab(tab, targetId=''){
  closeTutorialModal(true);
  setUiTab(tab, targetId ? {targetId} : {});
}

function maybeOpenTutorialAfterFirstRun(){
  if(tutorialSeen()) return;
  if(window.__FUJIYA_EARLY_ACCESS_UNLOCKED__ !== true) return;
  const firstRun = $('firstRunModal');
  if(firstRun?.classList.contains('show')) return;
  const tutorial = $('tutorialModal');
  if(tutorial?.classList.contains('show')) return;
  setTimeout(() => {
    if(tutorialSeen()) return;
    if(window.__FUJIYA_EARLY_ACCESS_UNLOCKED__ !== true) return;
    if($('firstRunModal')?.classList.contains('show')) return;
    openTutorialModal();
  }, 250);
}
window.fujiyaMaybeOpenTutorialAfterAuth = maybeOpenTutorialAfterFirstRun;


function getStoredUserName(){
  const name = String(localStorage.getItem(USER_NAME_KEY) || '').trim().slice(0,20);
  if(name !== '店長') return name;
  // 旧配布版が自動表示していた「店長」は、プロフィールで明示保存されていなければ未設定として扱う。
  try{
    const profile = JSON.parse(localStorage.getItem('fujiya_collection_profile_v20_1') || '{}') || {};
    if(String(profile.name || '').trim() === '店長') return name;
  }catch(error){}
  return '';
}

function defaultUserDisplayName(){
  return shortUserId(getUserId());
}

function getUserName(){
  return getStoredUserName() || defaultUserDisplayName();
}

function setUserName(name){
  const clean = String(name || '').trim().slice(0, 20);
  if(clean) localStorage.setItem(USER_NAME_KEY, clean);
  else localStorage.removeItem(USER_NAME_KEY);
  renderUserNameSetting();
  render();
}

function renderUserNameSetting(){
  const input = $('userNameInput');
  const note = $('userNameNote');
  if(!input || !note) return;

  input.value = getUserName();
  note.textContent = `現在の表示名：${getUserName()}　※共有用CSV/共有送信には今のところ表示名は入れません。`;
}


function syncableEntries(){
  return state.entries.filter(e => isSharedPlatform(e.platform) && e.sharedStatus === 'confirmed' && e.sharedTitleId);
}

function ratedSyncableEntries(){
  return syncableEntries().filter(e => ratingNumber(e.rating) > 0);
}

function renderSyncStatus(){
  const box = $('syncStatus');
  if(!box) return;

  const userId = getUserId();
  const syncable = syncableEntries().length;
  const rated = ratedSyncableEntries().length;
  const unconfirmed = state.entries.filter(isUnconfirmedEntry).length;
  const localOnly = state.entries.filter(e => !isSharedPlatform(e.platform)).length;

  box.classList.toggle('warn-sync', unconfirmed > 0 || syncable === 0);

  box.innerHTML = `
    共有用データ：${syncable}件 / レート送信対象：${rated}件 / 未確定：${unconfirmed}件 / 共有対象外：${localOnly}件<br>
    匿名ユーザーID：<span class="sync-id">${esc(userId)}</span><br>
    ※共有用CSV/共有送信には画像・店舗・購入日・メモは入れません。購入価格は「購入金額も共有」がONの時だけ送信します。
  `;
}

function syncReminderMessage(){
  const unconfirmed = state.entries.filter(isUnconfirmedEntry).length;
  if(unconfirmed > 0) return `未確定タイトルが${unconfirmed}件あるよ。共有用CSVに出す前に「再照合」しておくと集計に使いやすいよ。`;
  return '';
}

function userFriendlySystemMessage(message){
  const text = String(message || '');
  if(isAdminMode()) return text;
  const technical = /(GAS|POST|JSONP|doGet|doPost|Webアプリ|デプロイ|共有同期URL|エンドポイント|GViz|スプレッドシートURL|payload|ペイロード|HTTP|status code|version：|v3\.|取得URL)/i;
  if(!technical.test(text)) return text;
  if(/(OK|成功|正常|接続でき|保存しました)/.test(text)) return '共有機能は正常に動いています。';
  if(/(未設定|必要)/.test(text)) return '共有機能の準備ができていません。店長へ知らせてください。';
  return '共有機能を更新できませんでした。少し待ってから、もう一度試してください。';
}

function toast(message){
  message = userFriendlySystemMessage(message);
  const el = $('toast');
  el.textContent = message;
  el.classList.add('show');
  clearTimeout(window.__toastTimer);
  window.__toastTimer = setTimeout(() => el.classList.remove('show'), 1800);
}

function warn(message){
  const el = $('saveWarn');
  if(!message){
    el.classList.remove('show');
    el.textContent = '';
    return;
  }
  el.textContent = message;
  el.classList.add('show');
}

function esc(str=''){
  return String(str)
    .replaceAll('&','&amp;')
    .replaceAll('<','&lt;')
    .replaceAll('>','&gt;')
    .replaceAll('"','&quot;')
    .replaceAll("'","&#039;");
}

function fmt(iso){
  const d = new Date(iso);
  if(Number.isNaN(d.getTime())) return '';
  return `${d.getFullYear()}/${String(d.getMonth()+1).padStart(2,'0')}/${String(d.getDate()).padStart(2,'0')}`;
}

function fmtDateOnly(s){
  const m = String(s || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
  return m ? `${m[1]}/${m[2]}/${m[3]}` : fmt(s);
}

function yen(value){
  const n = Number(value || 0);
  if(!Number.isFinite(n) || n <= 0) return '';
  return n.toLocaleString('ja-JP') + '円';
}

function yen0(value){
  const n = Number(value);
  if(!Number.isFinite(n) || n < 0) return '';
  return n.toLocaleString('ja-JP') + '円';
}

function normalizePurchasePriceForShare(value){
  if(value === null || value === undefined || String(value).trim() === '') return null;
  const n = Math.round(Number(value));
  if(!Number.isFinite(n) || n < 0 || n > 99999999) return null;
  return n;
}

function purchaseConditionCategory(entry){
  if(!entry || !entry.owned) return '';
  const p = entry.parts || {};
  const has = key => !!(p[key] && p[key].has);
  const rom = has('rom');
  const box = has('box');
  const manual = has('manual');
  const accessory = has('accessory');

  if(isCompleteEntry(entry)) return 'complete';
  if(rom && !box && !manual && !accessory) return 'rom_only';
  return '';
}

function purchaseConditionLabel(category){
  if(category === 'rom_only') return 'ROMのみ';
  if(category === 'complete') return '完品';
  return '分類外';
}

function purchasePriceShareValue(entry){
  if(!entry || !entry.owned) return null;
  const category = purchaseConditionCategory(entry);
  if(!category) return null;
  const price = normalizePurchasePriceForShare(entry.purchasePrice);
  if(price === null) return null;
  return {price, category};
}

function currentPurchaseShareDraft(){
  const owned = document.querySelector('input[name="owned"]:checked')?.value === 'owned';
  const draft = {
    owned,
    purchasePrice: $('purchasePrice')?.value || '',
    parts: getPartsForm(),
    accessoryRequired: !!$('accessoryRequired')?.checked
  };
  const price = normalizePurchasePriceForShare(draft.purchasePrice);
  const category = purchaseConditionCategory(draft);
  return {owned, price, category};
}

function purchaseShareTargetMessage(){
  const draft = currentPurchaseShareDraft();
  if(!draft.owned){
    return {status:'off', text:'購入額共有対象外：欲しいもの登録'};
  }
  if(draft.price === null){
    return {status:'pending', text:'購入額共有対象：購入価格を入れると判定'};
  }
  if(draft.category){
    return {status:'on', text:`購入額共有対象：${purchaseConditionLabel(draft.category)}`};
  }
  return {status:'off', text:'購入額共有対象外：ROMのみ/完品ではありません'};
}

function updatePurchaseShareTarget(){
  const box = $('purchaseShareTarget');
  if(!box) return;
  const msg = purchaseShareTargetMessage();
  box.textContent = msg.text;
  box.className = `purchase-share-target ${msg.status}`;
}

function clearDexSearch(){
  state.dexSearch = '';
  saveDexSettings();
  renderDexPanel();
}

function ratingNumber(value){
  const n = Number(value || 0);
  return Number.isFinite(n) ? Math.max(0, Math.min(5, Math.round(n))) : 0;
}

function ratingStars(value){
  const n = ratingNumber(value);
  if(!n) return '未評価';
  return '★★★★★'.slice(0, n) + '☆☆☆☆☆'.slice(0, 5 - n);
}

function ratingLabel(value){
  const n = ratingNumber(value);
  return n ? `${ratingStars(n)} ${n}` : '未評価';
}

function renderRatingStarMeter(value, valueLabel){
  const n = Number(value);
  const valid = Number.isFinite(n) && n > 0;
  const clamped = Math.max(0, Math.min(5, valid ? n : 0));
  const label = valueLabel || (valid ? clamped.toFixed(2) : '');

  const stars = Array.from({length:5}, (_,index)=>{
    const fill = Math.max(0, Math.min(1, clamped - index));
    const width = `${fill * 100}%`;
    return `<span class="tcg-star-meter-cell">
      <span class="tcg-star-meter-cell-base"></span>
      <span class="tcg-star-meter-cell-clip" style="width:${width}">
        <span class="tcg-star-meter-cell-fill"></span>
      </span>
    </span>`;
  }).join('');

  return `<div class="tcg-rating-visual${valid ? '' : ' is-empty'}">
    <span class="tcg-star-meter" aria-hidden="true">${stars}</span>
    ${valid ? `<span class="tcg-star-meter-value">${esc(label)}</span>` : ''}
  </div>`;
}

function updateTitleKeyPreview(){
  const el = $('titleKeyPreview');
  if(!el) return;
  const key = titleKey($('title')?.value || '');
  el.textContent = key ? `正規化キー：${key}` : '正規化キー：—';
}


function applyDefaultPlatformTargets(){
  Object.entries(MASTER_TARGETS).forEach(([platform, count]) => {
    if(!state.platformTargets[platform]) state.platformTargets[platform] = count;
  });
}


function backupAgeDays(){
  const raw = localStorage.getItem(BACKUP_KEY);
  if(!raw) return null;
  const t = new Date(raw).getTime();
  if(!Number.isFinite(t)) return null;
  return Math.floor((Date.now() - t) / 86400000);
}

function renderBackupStatus(){
  const box = $('backupStatus');
  if(!box) return;

  const raw = localStorage.getItem(BACKUP_KEY);
  const age = backupAgeDays();

  box.classList.remove('warn-backup','good-backup');

  if(!raw || age === null){
    box.textContent = '最終バックアップ：未作成　※登録が増えたらJSONバックアップ推奨';
    box.classList.add('warn-backup');
    return;
  }

  const fileName = localStorage.getItem(BACKUP_FILE_KEY) || '';
  box.textContent = `最終バックアップ：${fmt(raw)}（${age === 0 ? '今日' : age + '日前'}）${fileName ? ' / ' + fileName : ''}`;
  box.classList.add(age >= 7 ? 'warn-backup' : 'good-backup');
}

function markBackedUp(){
  localStorage.setItem(BACKUP_KEY, nowIso());
  renderBackupStatus();
}

