function hasPartKey(entry, key){
  return !!entry.parts?.[key]?.has;
}

function entryAccessoryRequired(entry){
  return !!entry.accessoryRequired;
}

function isCompleteEntry(entry){
  const rom = getPart(entry, 'rom');
  const box = getPart(entry, 'box');
  const manual = getPart(entry, 'manual');
  const accessory = getPart(entry, 'accessory');
  if(!(rom.has && box.has && manual.has)) return false;
  if(entryAccessoryRequired(entry) && !accessory.has) return false;
  return true;
}

function completeBadgeHtml(entry){
  return isCompleteEntry(entry) ? '<span class="pill complete-badge">完品</span>' : '';
}

function collectionBadgeHtml(entry){
  return entry && shelfHas(entry.id) ? '<span class="pill collection-badge">コレクション</span>' : '';
}

function dexSharedRateHtml(master, entry){
  const sharedTitleId = (entry && entry.sharedTitleId) || (master && master.sharedTitleId) || '';
  const stat = sharedTitleId ? (state.remoteStats[sharedTitleId] || null) : null;

  // RC1.4.403: 図鑑カードは一覧性を優先し、3区分内訳は「詳細」だけで表示する。
  if(stat){
    const users = Number(stat.users_total || 0);
    const owned = Number(stat.owned_count || 0);
    const sub = users ? `${owned}/${users}人` : '';
    return `<div class="dex-shared-rate dex-shared-rate-compact">
      <span>共有所持率${sub ? `<small>${esc(sub)}</small>` : ''}</span>
      <strong>${formatRatePercent(stat.owned_rate)}</strong>
    </div>`;
  }

  if(sharedTitleId && state.remoteStatsFetchedAt){
    const users = remoteUsersSummary().active || remoteUsersSummary().count || 0;
    return `<div class="dex-shared-rate dex-shared-rate-compact zero">
      <span>共有所持率${users ? `<small>0/${esc(users)}人</small>` : ''}</span>
      <strong>0%</strong>
    </div>`;
  }

  if(sharedTitleId) return '<div class="dex-shared-rate dex-shared-rate-compact muted"><span>共有所持率</span><strong>未取得</strong></div>';
  return '<div class="dex-shared-rate dex-shared-rate-compact muted"><span>共有所持率</span><strong>未確定</strong></div>';
}

function completeStatusText(entry){
  const rom = getPart(entry, 'rom');
  const box = getPart(entry, 'box');
  const manual = getPart(entry, 'manual');
  const accessory = getPart(entry, 'accessory');
  if(isCompleteEntry(entry)) return entryAccessoryRequired(entry) ? '完品判定：ROM・箱・取説・付属品あり' : '完品判定：ROM・箱・取説あり';
  if(rom.has && box.has && manual.has && entryAccessoryRequired(entry) && !accessory.has) return '完品判定：付属品ありタイトルですが、付属品が欠品しているため完品バッジは出していません。';
  return '完品判定：ROM・箱・取説が揃うと完品候補になります。';
}

function isBoxManualEntry(entry){
  return hasPartKey(entry, 'rom') && hasPartKey(entry, 'box') && hasPartKey(entry, 'manual');
}

function hasJunkCondition(entry){
  return PARTS.some(([k]) => entry.parts?.[k]?.has && entry.parts?.[k]?.condition === 'J');
}

function levelExpStart(level){
  const lv = Math.max(1, Number(level || 1));
  return Math.floor(90 * Math.pow(lv - 1, 1.55));
}

function levelFromExp(exp){
  const total = Math.max(0, Number(exp || 0));
  let level = 1;
  while(level < 100 && total >= levelExpStart(level + 1)) level++;
  const current = levelExpStart(level);
  const next = level < 100 ? levelExpStart(level + 1) : current;
  const inLevel = total - current;
  const need = Math.max(1, next - current);
  return {
    level,
    exp: total,
    current,
    next,
    inLevel,
    need,
    percent: level >= 100 ? 100 : Math.max(0, Math.min(100, (inLevel / need) * 100))
  };
}

function rewardForTitleId(titleId){
  return RPG_REWARD_DEFS.find(r => r.titleId === titleId) || null;
}

function titleExpBonusForDef(def){
  if(!def) return 0;
  const reward = rewardForTitleId(def.id);
  if(reward && ['weapon','magic','accessory','armor'].includes(reward.type)) return 0;

  const group = String(def.group || '');
  if(group.includes('トロフィー')) return 60;
  if(group.includes('レア')){
    if(String(def.id || '').includes('ultra')) return 220;
    return 120;
  }
  if(group.includes('機種')) return 90;
  if(group.includes('ログ')) return 70;
  return reward ? 40 : 50;
}

function titleExpBonusFromStats(stats){
  return unlockedTitleDefs(stats).reduce((sum, def) => sum + titleExpBonusForDef(def), 0);
}

function bossDamageBonus(levelInfo){
  return Math.floor(Math.max(0, Number(levelInfo?.level || 1)) / 10);
}

function bossUnlockInfo(levelInfo){
  const level = Number(levelInfo?.level || 1);
  const unlocked = BOSS_DEFS.filter(b => level >= b.level);
  const next = BOSS_DEFS.find(b => level < b.level) || null;
  return {level, unlocked, next, current: unlocked[unlocked.length - 1] || null};
}

function bossGateHtml(levelInfo, battle){
  const info = bossUnlockInfo(levelInfo);
  const bonus = bossDamageBonus(levelInfo);
  const unlockedCount = info.unlocked.length;
  const nextText = info.next ? `次のボス解放：Lv.${info.next.level} ${info.next.name}` : '全ボス解放済み';
  const current = info.current;
  return `
    <div class="boss-gate-main ${current ? '' : 'locked'}">
      <div class="boss-gate-icon">${current ? esc(current.icon) : '🔒'}</div>
      <div style="min-width:0">
        <div class="boss-gate-title">${current ? esc(current.name) : 'ボス戦はLv.10で解放'}</div>
        <div class="boss-gate-sub">${current ? esc(current.hint) : 'まずはLv.10を目指すよ。戦闘本体は後日実装予定です。'}</div>
      </div>
      <button type="button" class="boss-gate-btn" disabled>${current ? 'ボス戦へ（後日実装）' : '未解放'}</button>
    </div>
    <div class="boss-gate-stats">
      <div><strong>${unlockedCount}</strong><span>解放ボス</span></div>
      <div><strong>+${bonus}</strong><span>Lvダメージ補正</span></div>
      <div><strong>${battle?.attack || 0}</strong><span>武器攻撃</span></div>
      <div><strong>${battle?.defense || 0}</strong><span>防御</span></div>
      <div><strong>${battle?.hit || 65}%</strong><span>命中</span></div>
    </div>
    <div class="boss-gate-next">${esc(nextText)}</div>
  `;
}

function unlockedRewards(unlocked){
  const ids = new Set((unlocked || []).map(t => t.id));
  return RPG_REWARD_DEFS.filter(r => ids.has(r.titleId));
}

function bestRewardByType(rewards, type){
  return (rewards || [])
    .filter(r => r.type === type)
    .sort((a,b) => Number(b.value || 0) - Number(a.value || 0))[0] || null;
}

function battleStatsFromRewards(stats, rewards, levelInfo=null){
  const weapon = bestRewardByType(rewards, 'weapon');
  const accessory = bestRewardByType(rewards, 'accessory');
  const armor = bestRewardByType(rewards, 'armor');
  const hitBonus = Number(accessory?.value || 0);
  const damageBonus = bossDamageBonus(levelInfo);
  return {
    hp: Number(stats.owned || 0),
    mp: Number(stats.ratedOwned || 0),
    attack: Number(weapon?.value || 0),
    defense: Number(armor?.value || 0),
    hit: Math.min(95, 65 + hitBonus),
    damageBonus,
    weapon,
    accessory,
    armor
  };
}

function rewardTypeLabel(type){
  return {
    weapon:'武器',
    magic:'魔法',
    accessory:'アクセサリー',
    armor:'防具',
    trophy:'トロフィー'
  }[type] || type || '報酬';
}

function rewardLineHtml(def, unlocked){
  const r = rewardForTitleId(def.id);
  if(r) return `<div class="title-reward ${unlocked ? '' : 'locked'}">入手：${esc(rewardTypeLabel(r.type))}「${esc(r.name)}」 / ${esc(r.desc)}</div>`;
  const bonus = titleExpBonusForDef(def);
  if(bonus > 0) return `<div class="title-reward ${unlocked ? '' : 'locked'}">報酬：経験値ボーナス +${bonus}</div>`;
  return '';
}

function rpgRewardCard(reward, fallbackName, fallbackDesc){
  if(!reward){
    return `
      <div class="rpg-equip-card empty">
        <div class="rpg-equip-kind">${esc(fallbackName)}</div>
        <div class="rpg-equip-name">未入手</div>
        <div class="rpg-equip-desc">${esc(fallbackDesc)}</div>
      </div>
    `;
  }
  return `
    <div class="rpg-equip-card ${esc(reward.type)}">
      <div class="rpg-equip-kind">${esc(reward.icon || '🎁')} ${esc(rewardTypeLabel(reward.type))}</div>
      <div class="rpg-equip-name">${esc(reward.name)}</div>
      <div class="rpg-equip-desc">${esc(reward.desc)}</div>
    </div>
  `;
}

function magicListHtml(rewards){
  const spells = (rewards || []).filter(r => r.type === 'magic');
  if(!spells.length){
    return '<div class="rpg-magic-empty">評価系称号を獲得すると、ここに魔法が増えます。</div>';
  }
  return spells.map(spell => `
    <div class="rpg-magic-row">
      <div class="rpg-magic-icon">${esc(spell.icon || '✨')}</div>
      <div style="min-width:0">
        <div class="rpg-magic-name">${esc(spell.name)}</div>
        <div class="rpg-magic-desc">MP ${Number(spell.mp || 0)} / ${esc(spell.desc)}</div>
      </div>
      <div class="rpg-magic-power">${Number(spell.value || 0)}</div>
    </div>
  `).join('');
}

function levelTitle(level){
  return LEVEL_TITLE_DEFS.find(t => level >= t.level)?.name || 'みけパーティー見習い';
}

function hasPurchaseInfoEntry(entry){
  const e = entry || {};
  return !!(
    String(e.purchaseDate || e.purchase_date || '').trim() ||
    String(e.purchasePrice ?? e.purchase_price ?? '').trim() ||
    String(e.purchaseStore || e.purchase_store || '').trim() ||
    String(e.purchaseMemo || e.purchase_memo || '').trim()
  );
}

function hasPhotoEntry(entry){
  const e = entry || {};
  return !!String(e.photoData || e.photo_data || '').trim();
}

function isManagedEntry(entry){
  return hasPhotoEntry(entry) || hasPurchaseInfoEntry(entry);
}

function collectGameStats(){
  const entries = state.entries || [];
  const ownedEntries = entries.filter(e => e.owned);
  const today = new Date().toISOString().slice(0,10);
  const todayEventLogs = (state.eventLogs || []).filter(l => String(l.at || '').slice(0,10) === today);
  const platformMap = {};
  platforms.forEach(p => platformMap[p] = {owned:0, rated:0, confirmed:0, managed:0, complete:0, rare:0, ultra:0, target:Number(state.platformTargets[p] || MASTER_TARGETS[p] || 0) || 0});

  ownedEntries.forEach(e => {
    const p = e.platform || '';
    if(!platformMap[p]) platformMap[p] = {owned:0, rated:0, confirmed:0, managed:0, complete:0, rare:0, ultra:0, target:Number(state.platformTargets[p] || MASTER_TARGETS[p] || 0) || 0};
    platformMap[p].owned += 1;
    if(ratingNumber(e.rating)) platformMap[p].rated += 1;
    if(e.sharedTitleId) platformMap[p].confirmed += 1;
    if(isManagedEntry(e)) platformMap[p].managed += 1;
    if(isCompleteEntry(e)) platformMap[p].complete += 1;

    const info = rareInfoForEntry(e);
    if(info && info.burst){
      platformMap[p].rare += 1;
      if(info.level === 'ultra') platformMap[p].ultra += 1;
    }
  });

  const ratedOwned = ownedEntries.filter(e => ratingNumber(e.rating) > 0).length;
  const ratedAll = entries.filter(e => ratingNumber(e.rating) > 0).length;
  const rareLogs = (state.eventLogs || []).filter(l => l.type === 'rare');
  const rareFromEntries = ownedEntries.filter(e => {
    const info = rareInfoForEntry(e);
    return info && info.burst;
  }).length;
  const ultraFromEntries = ownedEntries.filter(e => rareInfoForEntry(e)?.level === 'ultra').length;

  return {
    entries,
    owned: ownedEntries.length,
    want: entries.filter(e => !e.owned).length,
    rated: ratedAll,
    ratedOwned,
    ratingRate: ownedEntries.length ? ratedOwned / ownedEntries.length : 0,
    confirmed: ownedEntries.filter(e => e.sharedTitleId).length,
    managed: ownedEntries.filter(isManagedEntry).length,
    complete: ownedEntries.filter(isCompleteEntry).length,
    boxManual: ownedEntries.filter(isBoxManualEntry).length,
    junk: ownedEntries.filter(hasJunkCondition).length,
    highRated: ownedEntries.filter(e => ratingNumber(e.rating) >= 4).length,
    fiveStar: ownedEntries.filter(e => ratingNumber(e.rating) >= 5).length,
    rare: Math.max(rareLogs.length, rareFromEntries),
    ultra: Math.max(rareLogs.filter(l => l.rareLevel === 'ultra').length, ultraFromEntries),
    logCount: (state.eventLogs || []).length,
    todayLogs: todayEventLogs.length,
    todayAdds: todayEventLogs.filter(l => String(l.type || '') === 'add').length,
    platforms: platformMap
  };
}

function totalExpFromStats(s){
  let exp = 0;
  exp += s.owned * 12;
  exp += s.want * 2;
  exp += s.confirmed * 5;
  exp += s.managed * 6;
  exp += s.ratedOwned * 7;
  exp += s.highRated * 4;
  exp += s.fiveStar * 6;
  exp += s.complete * 24;
  exp += s.boxManual * 10;
  exp += s.junk * 4;
  exp += s.rare * 80;
  exp += s.ultra * 160;
  exp += titleExpBonusFromStats(s);
  exp += Math.min(s.logCount, 300) * 1;
  platforms.forEach(p => {
    const row = s.platforms[p] || {};
    const target = Number(row.target || 0) || 0;
    const rate = target ? row.owned / target : 0;
    if(row.owned >= 1) exp += 20;
    if(row.owned >= 50) exp += 80;
    if(row.owned >= 100) exp += 150;
    if(rate >= 0.1) exp += 180;
    if(rate >= 0.25) exp += 320;
    if(rate >= 0.5) exp += 650;
  });
  return Math.floor(exp);
}

function platformMasteryExp(row){
  return Math.floor((row.owned || 0) * 14 + (row.rated || 0) * 5 + (row.confirmed || 0) * 4 + (row.managed || 0) * 6 + (row.complete || 0) * 18 + (row.rare || 0) * 75 + (row.ultra || 0) * 120);
}

function platformMasteryTitle(platform, level, owned, rate){
  const p = platform || '';
  if(rate >= 1) return `${p}神`;
  if(rate >= 0.5) return `${p}覇者`;
  if(level >= 20) return `${p}勇者`;
  if(level >= 10) return `${p}冒険者`;
  if(owned > 0) return `${p}見習い`;
  return `${p}未踏`;
}

function unlockedTitleDefs(stats){
  return TITLE_DEFS.filter(def => {
    try{return !!def.check(stats);}
    catch(e){return false;}
  });
}

function currentMainTitle(stats, levelInfo, unlocked){
  const rareTop = [...unlocked].reverse().find(t => String(t.group || '').includes('レア'));
  const ownedTop = [...unlocked].reverse().find(t => String(t.group || '').includes('所持'));
  return rareTop?.name || ownedTop?.name || levelTitle(levelInfo.level);
}

function selectedDisplayTitleDef(unlocked){
  const id = state.displayTitleId || 'auto';
  if(id === 'auto') return null;
  return (unlocked || []).find(t => t.id === id) || null;
}

function displayTitleName(stats, levelInfo, unlocked){
  return selectedDisplayTitleDef(unlocked)?.name || currentMainTitle(stats, levelInfo, unlocked);
}

function setDisplayTitleId(id){
  const stats = collectGameStats();
  const unlocked = unlockedTitleDefs(stats);
  const valid = id === 'auto' || unlocked.some(t => t.id === id);
  state.displayTitleId = valid ? id : 'auto';
  saveGamifyState();
  render();
  toast(state.displayTitleId === 'auto' ? '表示称号を自動にしました' : '表示称号を変更しました');
}

function toggleQuickProfileEditor(force){
  state.quickProfileEditOpen = typeof force === 'boolean' ? force : !state.quickProfileEditOpen;
  renderQuickStatusBar();
}

function loadGamifyState(){
  try{
    const raw = localStorage.getItem(GAMIFY_STATE_KEY);
    if(!raw){
      state.unlockedTitleIds = [];
      state.gamifyKnown = false;
      state.titleFilter = 'all';
      state.displayTitleId = 'auto';
      return;
    }
    const data = JSON.parse(raw);
    state.unlockedTitleIds = Array.isArray(data.unlockedTitleIds) ? data.unlockedTitleIds : [];
    state.titleFilter = ['all','unlocked','locked'].includes(data.titleFilter) ? data.titleFilter : 'all';
    state.displayTitleId = data.displayTitleId || 'auto';
    state.gamifyKnown = true;
  }catch(e){
    state.unlockedTitleIds = [];
    state.gamifyKnown = false;
    state.titleFilter = 'all';
    state.displayTitleId = 'auto';
  }
}

function saveGamifyState(){
  localStorage.setItem(GAMIFY_STATE_KEY, JSON.stringify({
    unlockedTitleIds: state.unlockedTitleIds || [],
    titleFilter: state.titleFilter || 'all',
    displayTitleId: state.displayTitleId || 'auto',
    updatedAt: nowIso()
  }));
  state.gamifyKnown = true;
}

function showAchievementUnlock(def, extraCount=0){
  const pop = $('achievementPop');
  if(!pop || !def) return;
  $('achievementPopTitle').textContent = `${def.icon || '🏆'} ${def.name}`;
  $('achievementPopDesc').textContent = extraCount > 0
    ? `${def.desc} ほか${extraCount}件の称号を獲得したよ！`
    : `${def.desc} を達成したよ！`;
  pop.classList.remove('show');
  void pop.offsetWidth;
  pop.classList.add('show');
}

const LEGACY_TITLE_UNLOCK_NOTICES_ENABLED = false;

function checkNewTitleUnlocks(unlocked){
  const currentIds = unlocked.map(t => String(t.id || '')).filter(Boolean);
  const known = new Set(state.unlockedTitleIds || []);
  const newly = unlocked.filter(t => !known.has(String(t.id || '')));

  // 旧称号は二つ名へ置き換え済み。内部の達成履歴だけ静かに保持する。
  const mergedIds = Array.from(new Set([...known, ...currentIds]));
  const changed =
    !state.gamifyKnown
    || mergedIds.length !== (state.unlockedTitleIds || []).length
    || mergedIds.some((id, index) => id !== String((state.unlockedTitleIds || [])[index] || ''));

  state.unlockedTitleIds = mergedIds;
  if(changed) saveGamifyState();

  if(!LEGACY_TITLE_UNLOCK_NOTICES_ENABLED){
    $('achievementPop')?.classList.remove('show');
    return [];
  }

  if(newly.length){
    const firstUnlock = newly[0];
    const extraUnlockCount = newly.length - 1;
    showAchievementUnlock(firstUnlock, extraUnlockCount);
    forceEventMikeNavi(
      `称号獲得だよ！\n${firstUnlock.icon || '🏆'} ${firstUnlock.name}\n${firstUnlock.desc}${extraUnlockCount > 0 ? `\nほか${extraUnlockCount}件の称号も獲得したよ！` : ''}`,
      buildAchievementXPost(firstUnlock, extraUnlockCount)
    );
    addEventLog('unlock', null, `称号獲得：${newly.map(t => t.name).join(' / ')}`);
  }
  return newly;
}

function setTitleFilter(filter){
  state.titleFilter = 'unlocked';
  saveGamifyState();
  renderGamifyPanel();
}

function renderGamifyPanel(){
  const summary = $('rpgSummary');
  const mastery = $('platformMasteryList');
  const titleList = $('titleList');
  const actions = $('titleFilterActions');
  const bossGate = $('bossBattleGate');
  const loadout = $('rpgLoadout');
  const magicList = $('rpgMagicList');
  if(!summary || !mastery || !titleList) return;

  const stats = collectGameStats();
  const exp = totalExpFromStats(stats);
  const lv = levelFromExp(exp);
  const unlocked = unlockedTitleDefs(stats);
  const currentTitle = displayTitleName(stats, lv, unlocked);
  const rewards = unlockedRewards(unlocked);
  const battle = battleStatsFromRewards(stats, rewards, lv);
  checkNewTitleUnlocks(unlocked);

  const remaining = lv.level >= 100 ? 'MAX' : (lv.need - lv.inLevel).toLocaleString('ja-JP');
  const titleBonusExp = titleExpBonusFromStats(stats);

  summary.innerHTML = `
    <div class="rpg-level-row">
      <div>
        <div class="rpg-level">Lv.${lv.level}</div>
        <div class="rpg-title">称号：${esc(currentTitle)}</div>
      </div>
      <div class="shared-badge">${exp.toLocaleString('ja-JP')} EXP</div>
    </div>
    <div class="exp-bar"><div class="exp-fill" style="width:${lv.percent}%"></div></div>
    <div class="rpg-sub">次のレベルまで：${remaining}${lv.level >= 100 ? '' : ' EXP'} / 評価率：${Math.round(stats.ratingRate * 100)}% / 獲得称号：${unlocked.length} / 称号EXPボーナス：+${titleBonusExp}</div>
    <div class="rpg-mini-grid battle">
      <div class="rpg-mini"><div class="num">${battle.hp}</div><div class="label">HP / 所持数</div></div>
      <div class="rpg-mini"><div class="num">${battle.mp}</div><div class="label">MP / 評価済み</div></div>
      <div class="rpg-mini"><div class="num">${battle.attack}</div><div class="label">攻撃 / 武器</div></div>
      <div class="rpg-mini"><div class="num">${battle.defense}</div><div class="label">防御 / 防具</div></div>
      <div class="rpg-mini"><div class="num">${battle.hit}%</div><div class="label">命中 / アクセ</div></div>
      <div class="rpg-mini"><div class="num">+${battle.damageBonus}</div><div class="label">Lvダメージ補正</div></div>
    </div>
  `;

  if(loadout){
    loadout.innerHTML = [
      rpgRewardCard(battle.weapon, '武器', '所持系称号で入手'),
      rpgRewardCard(battle.armor, '防具', '管理系称号で入手'),
      rpgRewardCard(battle.accessory, 'アクセサリー', '共有ID・照合系称号で入手')
    ].join('');
  }
  if(magicList){
    magicList.innerHTML = magicListHtml(rewards);
  }
  if(bossGate){
    bossGate.innerHTML = bossGateHtml(lv, battle);
  }

  mastery.innerHTML = platforms.map(p => {
    const row = stats.platforms[p] || {owned:0,rated:0,confirmed:0,complete:0,rare:0,ultra:0,target:Number(state.platformTargets[p] || MASTER_TARGETS[p] || 0) || 0};
    const pexp = platformMasteryExp(row);
    const plv = levelFromExp(pexp);
    const target = Number(row.target || 0) || 0;
    const rate = target ? Math.min(1, row.owned / target) : 0;
    const ratePct = Math.round(rate * 1000) / 10;
    const title = platformMasteryTitle(p, plv.level, row.owned, rate);
    return `
      <div class="mastery-row">
        <div class="mastery-platform">${esc(p)}</div>
        <div>
          <div class="mastery-main">${esc(title)}</div>
          <div class="mastery-sub">${row.owned}本 / 評価${row.rated} / 確定${row.confirmed} / コンプ率${target ? ratePct + '%' : '—'}</div>
          <div class="mastery-bar"><div class="mastery-fill" style="width:${plv.percent}%"></div></div>
        </div>
        <div class="mastery-lv">Lv.${plv.level}</div>
      </div>
    `;
  }).join('');

  const unlockedIds = new Set(unlocked.map(t => t.id));
  if(actions){
    actions.innerHTML = '未獲得称号はネタバレ防止で非表示です。新しい称号を獲得すると、ここに追加されます。';
  }

  const visibleTitles = TITLE_DEFS.filter(def => unlockedIds.has(def.id));
  const hiddenCount = Math.max(0, TITLE_DEFS.length - visibleTitles.length);

  titleList.innerHTML = (visibleTitles.map(def => `
      <div class="title-row">
        <div class="title-icon">${def.icon || '🏆'}</div>
        <div style="min-width:0">
          <div class="title-name">${esc(def.name)}</div>
          <div class="title-desc">${esc(def.group)} / ${esc(def.desc)}</div>
          ${rewardLineHtml(def, true)}
        </div>
        <div class="title-badge">獲得済み</div>
      </div>
    `).join('') || '<div class="log-empty">まだ獲得済み称号はありません。まず1本登録すると称号が解放されます。</div>')
    + `
      <div class="title-row spoiler-locked">
        <div class="title-icon">❔</div>
        <div style="min-width:0">
          <div class="title-name">未発見の称号</div>
          <div class="title-desc">ネタバレ防止のため、未獲得称号の名前・条件・報酬は表示しません。</div>
          <div class="title-reward locked">後日実装予定の称号・ボス報酬もここに追加予定</div>
        </div>
        <div class="title-badge">？？？</div>
      </div>
    `;
}

function gamifyAdvice(){
  const s = collectGameStats();
  const exp = totalExpFromStats(s);
  const lv = levelFromExp(exp);
  const rewards = unlockedRewards(unlockedTitleDefs(s));
  const battle = battleStatsFromRewards(s, rewards, lv);
  if(!s.owned) return 'まず1本登録すると「はじめの一本」を獲得して、武器「ひのきの棒」が手に入るよ。';
  if(!s.ratedOwned) return '評価を1本入れると「はじめての星」を獲得して、魔法「スターショット」を覚えるよ。';
  if(!s.managed) return '写真か購入情報を1本入れると「はじめての管理」を獲得して、防具「布の服」が手に入るよ。';
  if(!s.confirmed) return '共有IDを1本確定すると「はじめてのリンク」を獲得して、命中アクセ「見習いのルーペ」が手に入るよ。';
  return `現在Lv.${lv.level} / HP${battle.hp} / MP${battle.mp} / 攻撃${battle.attack} / 防御${battle.defense} / 命中${battle.hit}% / ダメージ補正+${battle.damageBonus}だよ！Lv10刻みでボスも解放されるよ。`;
}


function todayLogCount(type=''){
  const today = new Date().toISOString().slice(0,10);
  return (state.eventLogs || []).filter(l => {
    if(String(l.at || '').slice(0,10) !== today) return false;
    return type ? l.type === type : true;
  }).length;
}

function questDefs(stats){
  const owned = Math.max(0, stats.owned || 0);
  const halfRatingTarget = owned ? Math.ceil(owned * 0.5) : 1;
  const highRatingTarget = owned ? Math.ceil(owned * 0.8) : 1;
  const halfConfirmTarget = owned ? Math.ceil(owned * 0.5) : 1;
  const fullConfirmTarget = owned ? owned : 1;
  const allPlatformOwned = platforms.filter(p => (stats.platforms[p]?.owned || 0) > 0).length;

  return [
    {id:'daily_add', icon:'➕', title:'今日の一本', desc:'今日ソフトを1本登録する', value:todayLogCount('add'), target:1, action:'register', actionLabel:'登録へ', priority: todayLogCount('add') < 1},
    {id:'rate_50', icon:'⭐', title:'星付け修行', desc:'所持ソフトの50％に評価を入れる', value:stats.ratedOwned, target:halfRatingTarget, action:'audit', actionLabel:'整備へ', priority: owned >= 5 && stats.ratingRate < .5},
    {id:'rate_80', icon:'🌟', title:'星屑の賢者への道', desc:'評価率80％を目指す', value:stats.ratedOwned, target:highRatingTarget, action:'audit', actionLabel:'未評価確認', priority: owned >= 10 && stats.ratingRate < .8},
    {id:'confirm_50', icon:'🔗', title:'マスター照合', desc:'所持ソフトの50％を共有ID確定にする', value:stats.confirmed, target:halfConfirmTarget, action:'audit', actionLabel:'未確定確認', priority: owned >= 5 && stats.confirmed < halfConfirmTarget},
    {id:'confirm_all', icon:'📚', title:'コレクションデータ整備', desc:'所持ソフトをすべてマスター確定する', value:stats.confirmed, target:fullConfirmTarget, action:'audit', actionLabel:'整備へ', priority: owned >= 10 && stats.confirmed < owned},
    {id:'all_platforms', icon:'🗺️', title:'五機種の旅人', desc:'FC/FDS/GB/GBA/SFCすべてに1本以上登録する', value:allPlatformOwned, target:platforms.length, action:'register', actionLabel:'登録へ'},
    {id:'boxmanual_10', icon:'📖', title:'箱説ハンター入門', desc:'箱説ありを10本集める', value:stats.boxManual, target:10, action:'list', actionLabel:'一覧へ'},
    {id:'complete_10', icon:'💿', title:'完品コレクター入門', desc:'完品を10本登録する', value:stats.complete, target:10, action:'list', actionLabel:'一覧へ'},
    {id:'rare_first', icon:'💎', title:'レアの気配', desc:'レアソフトを1本発見する', value:stats.rare, target:1, action:'shared', actionLabel:'データへ'},
    {id:'backup_ready', icon:'💾', title:'冒険の書を残す', desc:'完全バックアップ用にログを10件以上残す', value:Math.min(stats.logCount, 10), target:10, action:'manage', actionLabel:'設定へ'},
    {id:'level_10', icon:'⚔️', title:'レトロ冒険者', desc:'店長Lv.10を目指す', value:levelFromExp(totalExpFromStats(stats)).level, target:10, action:'growth', actionLabel:'クエストへ'}
  ];
}

function questProgress(q){
  const target = Math.max(1, Number(q.target || 1));
  const value = Math.max(0, Number(q.value || 0));
  const percent = Math.max(0, Math.min(100, (value / target) * 100));
  return {value, target, percent, clear:value >= target};
}

function renderQuestPanel(){
  const summary = $('questSummary');
  const list = $('questList');
  if(!summary || !list) return;

  const stats = collectGameStats();
  const quests = questDefs(stats);
  const enriched = quests.map(q => ({...q, progress:questProgress(q)}));
  const clearCount = enriched.filter(q => q.progress.clear).length;
  const priority = enriched.filter(q => !q.progress.clear && q.priority).length;
  const next = enriched.find(q => !q.progress.clear && q.priority) || enriched.find(q => !q.progress.clear);

  summary.innerHTML = `
    <div class="quest-card"><div class="num">${clearCount}</div><div class="label">クリア済み</div></div>
    <div class="quest-card"><div class="num">${enriched.length - clearCount}</div><div class="label">進行中</div></div>
    <div class="quest-card"><div class="num">${priority}</div><div class="label">おすすめ</div></div>
    <div class="quest-card"><div class="num">${next ? esc(next.title) : '完了'}</div><div class="label">次の目標</div></div>
  `;

  list.innerHTML = enriched
    .sort((a,b) => Number(a.progress.clear) - Number(b.progress.clear) || Number(b.priority) - Number(a.priority))
    .map(q => {
      const p = q.progress;
      return `
        <div class="quest-row ${p.clear ? 'clear' : ''} ${q.priority && !p.clear ? 'priority' : ''}">
          <div class="quest-icon">${q.icon}</div>
          <div>
            <div class="quest-title">${esc(q.title)}</div>
            <div class="quest-desc">${esc(q.desc)}</div>
            <div class="quest-progress"><div class="quest-fill" style="width:${p.percent}%"></div></div>
            <button type="button" class="quest-action" data-quest-action="${esc(q.action || 'list')}">${esc(q.actionLabel || '移動')}</button>
          </div>
          <div class="quest-badge">${p.clear ? 'CLEAR' : `${p.value}/${p.target}`}</div>
        </div>
      `;
    }).join('');
}

function questAdvice(){
  const stats = collectGameStats();
  const quests = questDefs(stats).map(q => ({...q, progress:questProgress(q)}));
  const next = quests.find(q => !q.progress.clear && q.priority) || quests.find(q => !q.progress.clear);
  if(!next) return '今出ているクエストは全部クリアだよ！称号集めやレア探しに進むよ。';
  const p = next.progress;
  return `次は「${next.title}」がおすすめだよ。\\n${next.desc}\\n進行度：${p.value}/${p.target}`;
}


function eventTypeLabel(type){
  return {
    all:'全部',
    add:'登録',
    edit:'編集',
    delete:'削除',
    rematch:'再照合',
    rare:'レア発見',
    unlock:'称号獲得',
    restore:'復元',
    import:'読み込み'
  }[type] || 'ログ';
}

function eventTypeIcon(type, level=''){
  if(level === 'ultra') return '💥';
  if(type === 'rare') return '💎';
  if(type === 'add') return '➕';
  if(type === 'edit') return '✏️';
  if(type === 'delete') return '🗑️';
  if(type === 'rematch') return '🔗';
  if(type === 'unlock') return '🏆';
  if(type === 'restore' || type === 'import') return '📥';
  return '📜';
}


function cloneUndoData(value){
  return JSON.parse(JSON.stringify(value || null));
}

function captureUndoState(){
  return {
    entries: cloneUndoData(state.entries || []),
    platformTargets: cloneUndoData(state.platformTargets || {}),
    shelfEntryIds: cloneUndoData(state.shelfEntryIds || []),
    buybackEntryIds: cloneUndoData(state.buybackEntryIds || []),
    buybackHistory: cloneUndoData(state.buybackHistory || []),
    buybackMeta: cloneUndoData(state.buybackMeta || {})
  };
}

function undoStateJson(data){
  try{
    return JSON.stringify(data || captureUndoState());
  }catch(e){
    return '';
  }
}

function fastUndoHash(text){
  const raw = String(text || '');
  let hash = 2166136261;
  for(let i=0;i<raw.length;i++){
    hash ^= raw.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return `${(hash >>> 0).toString(36)}:${raw.length}`;
}

function undoOptions(value){
  if(Array.isArray(value)) return {keepPhotoEntryIds:value};
  return value && typeof value === 'object' ? value : {};
}

function compactUndoEntry(entry, keepPhotoIds){
  const e = cloneUndoData(entry || {}) || {};
  const id = String(e.id || '');
  const photo = String(e.photoData || '');
  const keep = !!photo && keepPhotoIds.has(id) && photo.length <= UNDO_KEPT_PHOTO_MAX_CHARS;
  if(photo && !keep){
    e.photoData = '';
    e.undoPhotoOmitted = true;
  }
  return e;
}

function compactUndoHistoryRecord(record){
  const row = cloneUndoData(record || {}) || {};
  if(row.entry && row.entry.photoData){
    row.entry.photoData = '';
    row.entry.undoPhotoOmitted = true;
  }
  return row;
}

function compactUndoData(data, options={}){
  const safe = data || captureUndoState();
  const opts = undoOptions(options);
  const keepPhotoIds = new Set((opts.keepPhotoEntryIds || []).map(String));
  return {
    entries: (Array.isArray(safe.entries) ? safe.entries : []).map(e => compactUndoEntry(e, keepPhotoIds)),
    platformTargets: cloneUndoData(safe.platformTargets || {}),
    shelfEntryIds: cloneUndoData(safe.shelfEntryIds || []),
    buybackEntryIds: cloneUndoData(safe.buybackEntryIds || []),
    buybackHistory: (Array.isArray(safe.buybackHistory) ? safe.buybackHistory : []).map(compactUndoHistoryRecord),
    buybackMeta: cloneUndoData(safe.buybackMeta || {})
  };
}

function undoStateHash(data){
  try{
    return fastUndoHash(JSON.stringify(compactUndoData(data, {keepPhotoEntryIds:[]})));
  }catch(e){
    return '';
  }
}

function normalizeUndoSnapshotForStorage(snapshot, options={}){
  const source = snapshot || {};
  const opts = undoOptions(options);
  const hasExplicitPhotoIds = Object.prototype.hasOwnProperty.call(opts, 'keepPhotoEntryIds');
  const inheritedPhotoIds = source.undoFormat === 2
    ? (source.entries || []).filter(e => e && e.photoData).map(e => String(e.id || ''))
    : [];
  const compact = compactUndoData(source, {
    ...opts,
    keepPhotoEntryIds: hasExplicitPhotoIds ? opts.keepPhotoEntryIds : inheritedPhotoIds
  });
  return {
    id: source.id || ('undo_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2,8)),
    at: source.at || nowIso(),
    label: String(source.label || '操作前'),
    version: source.version || APP_VERSION,
    undoFormat: 2,
    stateHash: source.stateHash || undoStateHash(source),
    ...compact
  };
}

function buildUndoSnapshotFromData(label, data, options={}){
  const safe = data || captureUndoState();
  const compact = compactUndoData(safe, options);
  return {
    id: 'undo_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2,8),
    at: nowIso(),
    label: String(label || '操作前'),
    version: APP_VERSION,
    undoFormat: 2,
    stateHash: undoStateHash(safe),
    ...compact
  };
}

function undoRowsWithinSoftLimit(rows){
  const result = (rows || []).slice(0, UNDO_MAX_COUNT);
  while(result.length > 1 && JSON.stringify(result).length > UNDO_SOFT_LIMIT_BYTES){
    result.pop();
  }
  return result;
}

function persistUndoRows(rows){
  const safeRows = undoRowsWithinSoftLimit(rows);
  // 旧版の巨大な値を先に解放してから、軽量版を書き戻す。
  localStorage.removeItem(UNDO_KEY);
  if(safeRows.length) localStorage.setItem(UNDO_KEY, JSON.stringify(safeRows));
  return safeRows;
}

function saveUndoSnapshots(){
  const source = (state.undoSnapshots || [])
    .filter(x => x && x.id && x.at)
    .slice(0, UNDO_MAX_COUNT)
    .map(x => normalizeUndoSnapshotForStorage(x));

  const candidates = [
    source,
    source.slice(0, 3).map(x => normalizeUndoSnapshotForStorage(x, {keepPhotoEntryIds:[]})),
    source.slice(0, 1).map(x => normalizeUndoSnapshotForStorage(x, {keepPhotoEntryIds:[]})),
    []
  ];

  for(let i=0;i<candidates.length;i++){
    const rows = candidates[i];
    try{
      state.undoSnapshots = persistUndoRows(rows);
      if(i > 0 && source.length && !undoQuotaWarningShown){
        undoQuotaWarningShown = true;
        warn(rows.length
          ? `保存容量を守るため、復元用履歴を直近${rows.length}件へ自動整理しました。登録データ本体は消えていません。`
          : '保存容量を守るため、復元用履歴だけを自動整理しました。登録データ本体は消えていません。');
      }
      return true;
    }catch(e){
      console.warn('undo snapshot save retry', e && e.name ? e.name : e);
    }
  }

  try{ localStorage.removeItem(UNDO_KEY); }catch(e){}
  state.undoSnapshots = [];
  if(!undoQuotaWarningShown){
    undoQuotaWarningShown = true;
    warn('保存容量を守るため、古い復元用履歴を自動整理しました。登録データ本体は消えていません。');
  }
  return false;
}

function loadUndoSnapshots(){
  try{
    const raw = localStorage.getItem(UNDO_KEY);
    const rows = raw ? JSON.parse(raw) : [];
    state.undoSnapshots = Array.isArray(rows)
      ? rows.filter(x => x && x.id && x.at).slice(0, UNDO_MAX_COUNT).map(x => normalizeUndoSnapshotForStorage(x))
      : [];
    // V7.18.90以前の「全画像＋stateJson」入り履歴を起動時に軽量化する。
    saveUndoSnapshots();
  }catch(e){
    console.warn('undo snapshot load failed', e);
    try{ localStorage.removeItem(UNDO_KEY); }catch(ignore){}
    state.undoSnapshots = [];
  }
}

function pushUndoSnapshotFromData(label, data, options={}){
  if(state.undoRestoring) return '';
  const snap = buildUndoSnapshotFromData(label, data, options);
  const latest = latestUndoSnapshot();
  if(latest && latest.stateHash && latest.stateHash === snap.stateHash){
    state.pendingUndoSnapshotId = latest.id;
    return latest.id;
  }
  state.undoSnapshots = [snap, ...(state.undoSnapshots || [])].slice(0, UNDO_MAX_COUNT);
  state.pendingUndoSnapshotId = snap.id;
  saveUndoSnapshots();
  renderUndoPanel();
  return snap.id;
}

function primeUndoBaseline(){
  const data = captureUndoState();
  state.undoBaselineData = cloneUndoData(data);
  state.undoBaselineJson = undoStateJson(data);
  renderHomeUndoStatus();
}

function maybeCreateUndoBeforeSave(label){
  if(state.undoRestoring) return;
  const current = captureUndoState();
  const currentJson = undoStateJson(current);
  if(!state.undoBaselineJson){
    state.undoBaselineData = cloneUndoData(current);
    state.undoBaselineJson = currentJson;
    return;
  }
  if(currentJson === state.undoBaselineJson) return;

  if(state.undoSnapshotCreatedBeforeSave){
    state.undoSnapshotCreatedBeforeSave = false;
    return;
  }

  pushUndoSnapshotFromData(label || '操作前', state.undoBaselineData || current);
}


function createUndoSnapshot(label='操作前', options={}){
  if(state.undoRestoring) return '';
  const id = pushUndoSnapshotFromData(label || '操作前', captureUndoState(), options);
  state.undoSnapshotCreatedBeforeSave = true;
  return id;
}

function findUndoSnapshot(id){
  return (state.undoSnapshots || []).find(s => s.id === id) || null;
}

function latestUndoSnapshot(){
  return (state.undoSnapshots || [])[0] || null;
}


function compactLogSnapshot(snap){
  if(!snap) return null;
  return {
    id: snap.id || '',
    at: snap.at || nowIso(),
    label: snap.label || '操作前',
    version: snap.version || APP_VERSION,
    entries: cloneUndoData(snap.entries || []),
    platformTargets: cloneUndoData(snap.platformTargets || {}),
    shelfEntryIds: cloneUndoData(snap.shelfEntryIds || []),
    buybackEntryIds: cloneUndoData(snap.buybackEntryIds || []),
    buybackHistory: cloneUndoData(snap.buybackHistory || []),
    buybackMeta: cloneUndoData(snap.buybackMeta || {})
  };
}

function snapshotForLog(id){
  const snap = findUndoSnapshot(id);
  return snap ? compactLogSnapshot(snap) : null;
}

function snapshotFromLogRow(row){
  if(row && row.undoSnapshot && row.undoSnapshot.entries){
    return row.undoSnapshot;
  }
  if(row && row.undoSnapshotId){
    return findUndoSnapshot(row.undoSnapshotId);
  }
  return null;
}

function eventLogRestoreLabel(row){
  const raw = `${row?.type || ''} ${row?.detail || ''} ${row?.title || ''}`;
  if(raw.includes('削除')) return '削除を取り消して復元しますか？';
  if(raw.includes('買取成立')) return '買取成立を取り消して復元しますか？';
  if(raw.includes('編集') || raw.includes('更新')) return '編集前の状態に復元しますか？';
  if(raw.includes('登録') || raw.includes('追加')) return '登録前の状態に復元しますか？';
  if(raw.includes('取り込み') || raw.includes('読み込み')) return '取り込み前の状態に復元しますか？';
  if(raw.includes('統合')) return '統合前の状態に復元しますか？';
  return 'このログの操作前に復元しますか？';
}


function undoSnapshotSummary(snap){
  const count = Array.isArray(snap?.entries) ? snap.entries.length : 0;
  const buyback = Array.isArray(snap?.buybackEntryIds) ? snap.buybackEntryIds.length : 0;
  const hist = Array.isArray(snap?.buybackHistory) ? snap.buybackHistory.length : 0;
  return `登録${count}件 / 買取相談${buyback}件 / 買取成立履歴${hist}件`;
}


function renderHomeUndoStatus(){
  // V7.18.37: 上部Undoボタンは廃止。ログ行の復元ボタンに一本化。
}

function applyUndoSnapshotData(snap){
  const currentPhotos = new Map((state.entries || []).map(e => [String(e.id || ''), String(e.photoData || '')]));
  const restoredEntries = (Array.isArray(snap.entries) ? snap.entries : []).map(raw => {
    const e = cloneUndoData(raw || {}) || {};
    if(!e.photoData && e.undoPhotoOmitted){
      e.photoData = currentPhotos.get(String(e.id || '')) || '';
    }
    delete e.undoPhotoOmitted;
    return e;
  });
  state.entries = restoredEntries.map(norm).map(ensureSharedFields).map(hydrateEntryFromMaster);
  state.platformTargets = snap.platformTargets && typeof snap.platformTargets === 'object' ? cloneUndoData(snap.platformTargets) : {};
  applyDefaultPlatformTargets();
  state.shelfEntryIds = Array.isArray(snap.shelfEntryIds) ? snap.shelfEntryIds.map(String).filter(Boolean).slice(0,24) : [];
  state.buybackEntryIds = Array.isArray(snap.buybackEntryIds) ? snap.buybackEntryIds.map(String).filter(Boolean) : [];

  const historyPhotos = new Map((state.buybackHistory || []).map(h => [String(h.historyId || ''), String(h.entry?.photoData || '')]));
  state.buybackHistory = (Array.isArray(snap.buybackHistory) ? snap.buybackHistory : []).map(raw => {
    const h = cloneUndoData(raw || {}) || {};
    if(h.entry && !h.entry.photoData && h.entry.undoPhotoOmitted){
      h.entry.photoData = historyPhotos.get(String(h.historyId || '')) || '';
      delete h.entry.undoPhotoOmitted;
    }
    return h;
  });
  state.buybackMeta = snap.buybackMeta && typeof snap.buybackMeta === 'object' ? cloneUndoData(snap.buybackMeta) : {};
  saveShelf();
  saveBuyback();
  saveBuybackHistory();
  saveBuybackMeta();
}

async function restoreUndoSnapshot(id, reason='ログから復元'){
  const snap = findUndoSnapshot(id);
  if(!snap){
    toast('復元に必要な保存データが見つかりません');
    showMikeTalk('このログは古いか、復元用データが整理済みで見つからないよ。');
    return;
  }
  return restoreFromSnapshotObject(snap, null, reason);
}

function undoLastOperation(){
  toast('元に戻すボタンは廃止しました。設定・バックアップの操作履歴から復元してください。');
}

async function restoreFromSnapshotObject(snap, row=null, reason='ログから復元'){
  if(!snap || !Array.isArray(snap.entries)){
    toast('復元データが見つかりません');
    showMikeTalk('このログには復元用データが残っていないよ。V7.18.37以降のログで試してね。');
    return;
  }

  const ok = await askRestoreConfirm(snap, row);
  if(!ok) return;

  state.undoRestoring = true;

  // 復元前の現在状態も保険として残す
  const current = buildUndoSnapshotFromData('復元前の状態', captureUndoState());
  state.undoSnapshots = [current, ...(state.undoSnapshots || [])].slice(0, UNDO_MAX_COUNT);
  saveUndoSnapshots();

  applyUndoSnapshotData(snap);
  const saved = saveCoreDataOnly();
  state.undoRestoring = false;

  if(saved){
    primeUndoBaseline();
    addEventLog('restore', null, `${reason}：${row?.title || snap.label || '操作前'}`);
    render();
    resetForm();
    toast('復元しました');
    showMikeTalk('ログから復元したよ。');
    scheduleAutoSync('ログから復元');
  }else{
    toast('復元データの保存に失敗しました');
  }
}


async function restoreDeletedEntriesFromLog(row){
  const entries = Array.isArray(row.restoreEntries) ? row.restoreEntries : [];
  if(!entries.length){
    toast('削除を戻すためのデータがありません');
    showMikeTalk('この削除ログには戻すためのソフト情報が残っていないよ。');
    return;
  }

  const snapForConfirm = {
    label: row.detail || '削除の前',
    entries,
    buybackEntryIds: state.buybackEntryIds || [],
    buybackHistory: state.buybackHistory || []
  };

  const ok = await askRestoreConfirm(snapForConfirm, row);
  if(!ok) return;

  const existingIds = new Set((state.entries || []).map(e => String(e.id)));
  const restored = entries
    .map(e => norm(e))
    .map(ensureSharedFields)
    .map(hydrateEntryFromMaster)
    .filter(e => e.id && !existingIds.has(String(e.id)));

  if(!restored.length){
    toast('すでに復元済みです');
    showMikeTalk('このログのソフトは、もうコレクション内に戻っているみたいだよ。');
    return;
  }

  state.entries = [...restored, ...(state.entries || [])];

  const shelfSet = new Set((state.shelfEntryIds || []).map(String));
  (row.restoreShelfEntryIds || []).forEach(id => {
    if(restored.some(e => String(e.id) === String(id))) shelfSet.add(String(id));
  });
  state.shelfEntryIds = Array.from(shelfSet).slice(0, 24);
  saveShelf();

  const saved = saveCoreDataOnly();
  if(saved){
    addEventLog('restore', restored[0] || null, `削除ログから復元：${restored.length}件`, {skipUndoSnapshotId:true});
    render();
    resetForm();
    toast(`${restored.length}件を復元しました`);
    showMikeTalk(`削除したソフトを${restored.length}件戻したよ。`);
    scheduleAutoSync('削除ログから復元');
  }
}


function restoreFromLogRow(logId){
  const row = (state.eventLogs || []).find(x => x.id === logId);
  if(!row){
    toast('ログが見つかりません');
    return;
  }
  if(row.restoreMode === 'deleted_entries'){
    restoreDeletedEntriesFromLog(row);
    return;
  }
  const snap = snapshotFromLogRow(row);
  restoreFromSnapshotObject(snap, row, 'ログから復元');
}


