function loadEventLogs(){
  try{
    const raw = localStorage.getItem(EVENT_LOG_KEY);
    const rows = raw ? JSON.parse(raw) : [];
    state.eventLogs = Array.isArray(rows) ? rows.filter(x => x && x.id && x.at).slice(0, 500) : [];
  }catch(e){
    console.error(e);
    state.eventLogs = [];
  }
}


function saveCoreDataOnly(){
  try{
    localStorage.setItem(STORAGE_KEY, JSON.stringify({
      version: APP_VERSION,
      updatedAt: nowIso(),
      entries: (state.entries||[]).map(entryPhotoStripForStorage),
      shelfEntryIds: state.shelfEntryIds || [],
      recommendPreferredGenres: state.recommendPreferredGenres || [],
      recommendPreferredMakers: state.recommendPreferredMakers || [],
      platformTargets: state.platformTargets,
      userId: getUserId(),
      userName: getUserName()
    }));
    entryPhotoScheduleMaintenance();
    primeUndoBaseline();
    const suppressDeviceAutoSyncForThisSave = typeof deviceAutoSyncSuppressSave !== 'undefined' && deviceAutoSyncSuppressSave > 0;
    if(!suppressDeviceAutoSyncForThisSave && typeof deviceAutoSyncAfterSave === 'function'){
      setTimeout(() => deviceAutoSyncAfterSave('登録データ変更'), 0);
    }
    return true;
  }catch(e){
    console.error(e);
    warn('ブラウザの保存容量がいっぱいの可能性があります。JSON完全バックアップ後に不要な履歴を整理してください。');
    toast('保存に失敗しました');
    return false;
  }
}


function saveEventLogs(){
  const rows = (state.eventLogs || []).slice(0, 500);
  try{
    localStorage.setItem(EVENT_LOG_KEY, JSON.stringify(rows));
  }catch(e){
    console.warn('event log save failed, retry slim logs', e);
    try{
      const slim = rows.slice(0, 300).map(slimEventLogRow);
      state.eventLogs = slim;
      localStorage.setItem(EVENT_LOG_KEY, JSON.stringify(slim));
      warn('ログ保存容量が大きいため、復元ログの画像データを一部軽量化しました。');
    }catch(e2){
      console.warn('event log slim save failed', e2);
      const minimal = rows.slice(0, 120).map(row => ({
        id: row.id,
        type: row.type,
        at: row.at,
        entryId: row.entryId,
        title: row.title,
        platform: row.platform,
        sharedTitleId: row.sharedTitleId,
        rating: row.rating,
        rareLevel: row.rareLevel,
        ownedRate: row.ownedRate,
        detail: row.detail
      }));
      state.eventLogs = minimal;
      try{
        localStorage.setItem(EVENT_LOG_KEY, JSON.stringify(minimal));
      }catch(e3){
        console.warn('event log minimal save failed', e3);
      }
      warn('ログ保存容量が大きいため、古い復元データを整理しました。');
    }
  }
}


function cloneEntryForRestoreLog(entry){
  return JSON.parse(JSON.stringify(entry || {}));
}

function stripHeavyEntryForLog(entry){
  const e = JSON.parse(JSON.stringify(entry || {}));
  if(e.photoData && String(e.photoData).length > 250000){
    e.photoData = '';
    e.photoRestoreNote = '画像データは容量保護のため復元ログから外しました';
  }
  return e;
}

function slimEventLogRow(row){
  const r = {...row};
  r.undoSnapshot = null;
  if(Array.isArray(r.restoreEntries)){
    r.restoreEntries = r.restoreEntries.map(stripHeavyEntryForLog);
  }
  return r;
}


function addEventLog(type, entry=null, detail='', options={}){
  const rare = entry ? rareInfoForEntry(entry) : null;
  const stat = entry ? remoteStatFor(entry) : null;
  const row = {
    id: uid(),
    type,
    at: nowIso(),
    entryId: entry?.id || '',
    title: entry?.title || '',
    platform: entry?.platform || '',
    sharedTitleId: entry?.sharedTitleId || '',
    rating: entry ? ratingNumber(entry.rating) : 0,
    rareLevel: type === 'rare' ? (rare?.level || '') : '',
    ownedRate: stat ? Number(stat.owned_rate || 0) : '',
    detail: detail || '',
    undoSnapshotId: options.skipUndoSnapshotId ? '' : (state.pendingUndoSnapshotId || ''),
    undoSnapshot: options.undoSnapshot || null,
    restoreMode: options.restoreMode || '',
    restoreEntries: Array.isArray(options.restoreEntries) ? options.restoreEntries.map(cloneEntryForRestoreLog) : [],
    restoreShelfEntryIds: Array.isArray(options.restoreShelfEntryIds) ? options.restoreShelfEntryIds.map(String) : []
  };
  if(state.pendingUndoSnapshotId) state.pendingUndoSnapshotId = '';

  state.eventLogs = [row, ...(state.eventLogs || [])].slice(0, 500);
  saveEventLogs();
  renderEventLogPanel();
  renderUndoPanel();
}

function addRareLogIfNeeded(entry, context=''){
  const info = rareInfoForEntry(entry);
  if(!info || !info.burst) return false;

  const exists = (state.eventLogs || []).some(log =>
    log.type === 'rare' &&
    log.entryId === entry.id &&
    log.rareLevel === info.level
  );
  if(exists) return false;

  addEventLog('rare', entry, context || info.text);
  return true;
}

function syncRareLogsFromCurrentEntries(context=''){
  const existing = new Set(
    (state.eventLogs || [])
      .filter(log => log.type === 'rare')
      .map(log => `${String(log.entryId || '')}|${String(log.rareLevel || '')}`)
  );
  const addedRows = [];

  for(const entry of (state.entries || [])){
    const info = rareInfoForEntry(entry);
    if(!info || !info.burst) continue;
    const key = `${String(entry.id || '')}|${String(info.level || '')}`;
    if(existing.has(key)) continue;
    existing.add(key);
    const stat = remoteStatFor(entry);
    addedRows.push({
      id:uid(),
      type:'rare',
      at:nowIso(),
      entryId:entry.id || '',
      title:entry.title || '',
      platform:entry.platform || '',
      sharedTitleId:entry.sharedTitleId || '',
      rating:ratingNumber(entry.rating),
      rareLevel:info.level || '',
      ownedRate:stat ? Number(stat.owned_rate || 0) : '',
      detail:context || '共有データ反映でレア判定',
      undoSnapshotId:'',
      undoSnapshot:null,
      restoreMode:'',
      restoreEntries:[],
      restoreShelfEntryIds:[]
    });
  }

  if(addedRows.length){
    state.eventLogs = [...addedRows, ...(state.eventLogs || [])].slice(0,500);
    saveEventLogs();
    renderEventLogPanel();
    renderUndoPanel();
  }
  return addedRows.length;
}

function seedEventLogsFromEntries(){
  if((state.eventLogs || []).length || !(state.entries || []).length) return;

  const seed = (state.entries || [])
    .slice()
    .sort((a,b) => String(b.createdAt || '').localeCompare(String(a.createdAt || '')))
    .slice(0, 120)
    .map(e => ({
      id: uid(),
      type:'add',
      at: e.createdAt || e.updatedAt || nowIso(),
      entryId: e.id || '',
      title: e.title || '',
      platform: e.platform || '',
      sharedTitleId: e.sharedTitleId || '',
      rating: ratingNumber(e.rating),
      rareLevel:'',
      ownedRate:'',
      detail:'既存データから初回ログ生成'
    }));

  state.eventLogs = seed;
  saveEventLogs();
}

function loadLogFilter(){
  try{
    const f = localStorage.getItem(LOG_FILTER_KEY) || 'all';
    state.logFilter = ['all','add','edit','delete','rematch','rare'].includes(f) ? f : 'all';
  }catch(e){
    state.logFilter = 'all';
  }
}

function setLogFilter(filter){
  state.logFilter = ['all','add','edit','delete','rematch','rare'].includes(filter) ? filter : 'all';
  localStorage.setItem(LOG_FILTER_KEY, state.logFilter);
  renderEventLogPanel();
}

function logRowsFiltered(){
  const f = state.logFilter || 'all';
  const rows = state.eventLogs || [];
  return f === 'all' ? rows : rows.filter(r => r.type === f);
}

function eventLogsSummary(){
  const rows = state.eventLogs || [];
  const today = new Date().toISOString().slice(0,10);
  const month = today.slice(0,7);

  return {
    total: rows.length,
    today: rows.filter(r => String(r.at || '').slice(0,10) === today).length,
    month: rows.filter(r => String(r.at || '').slice(0,7) === month).length,
    rare: rows.filter(r => r.type === 'rare').length,
    add: rows.filter(r => r.type === 'add').length
  };
}

function eventLogAdvice(){
  const s = eventLogsSummary();
  if(!s.total) return 'まだログがないよ。ソフトを登録するとここに履歴が残るよ。';
  if(s.rare) return `レア発見ログが${s.rare}件あるよ。後から見返すと、コレクションが育った感じが出るよ。`;
  if(s.today) return `今日のログは${s.today}件だよ。動きがあった日はログを見返すと楽しいよ。`;
  return `ログは${s.total}件あるよ。登録・編集・再照合の流れが残るから、あとで振り返れるよ。`;
}

function renderEventLogPanel(){
  const summary = $('logSummary');
  const list = $('eventLogList');
  const note = $('logNote');
  const actions = $('logFilterActions');
  if(!summary || !list || !actions) return;

  const s = eventLogsSummary();
  summary.innerHTML = `
    <div class="log-card"><div class="num">${s.total}</div><div class="label">総ログ</div></div>
    <div class="log-card"><div class="num">${s.today}</div><div class="label">今日</div></div>
    <div class="log-card"><div class="num">${s.month}</div><div class="label">今月</div></div>
    <div class="log-card"><div class="num">${s.rare}</div><div class="label">レア発見</div></div>
    <div class="log-card"><div class="num">${s.add}</div><div class="label">登録ログ</div></div>
  `;

  actions.querySelectorAll('[data-log-filter]').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.logFilter === (state.logFilter || 'all'));
  });

  const rows = logRowsFiltered().slice(0, 80);
  if(note) note.textContent = `表示中：${rows.length}件 / フィルター：${eventTypeLabel(state.logFilter || 'all')}`;

  if(!rows.length){
    list.innerHTML = '<div class="log-empty">この条件のログはまだありません。</div>';
    return;
  }

  list.innerHTML = rows.map(row => {
    const rareClass = row.type === 'rare' ? (row.rareLevel === 'ultra' ? ' ultra' : ' rare') : '';
    const badge = row.type === 'rare' && row.ownedRate !== ''
      ? `${eventTypeLabel(row.type)} ${formatRatePercent(row.ownedRate)}`
      : eventTypeLabel(row.type);
    const sub = [
      row.platform || '',
      row.sharedTitleId || '',
      row.rating ? ratingStars(row.rating) : '',
      row.detail || '',
      fmt(row.at)
    ].filter(Boolean).join(' / ');

    const canRestore = row.restoreMode === 'deleted_entries' || !!snapshotFromLogRow(row);
    return `
      <div class="log-row${rareClass}${canRestore ? ' can-log-restore' : ''}">
        <div class="log-icon">${eventTypeIcon(row.type, row.rareLevel)}</div>
        <div style="min-width:0">
          <div class="log-main">${esc(row.title || eventTypeLabel(row.type))}</div>
          <div class="log-sub">${esc(sub)}</div>
        </div>
        <div class="log-actions-inline">
          ${canRestore ? `<button type="button" class="log-restore-btn" data-log-restore="${esc(row.id)}" title="このログの操作前に復元">復元</button>` : ''}
          <div class="log-badge">${esc(badge)}</div>
        </div>
      </div>
    `;
  }).join('');
}

function exportEventLogs(){
  const header = ['at','type','title','platform','shared_title_id','rating','rare_level','owned_rate','detail'];
  const rows = (state.eventLogs || []).map(r => [
    r.at || '',
    eventTypeLabel(r.type),
    r.title || '',
    r.platform || '',
    r.sharedTitleId || '',
    r.rating || '',
    r.rareLevel || '',
    r.ownedRate !== '' && r.ownedRate !== undefined ? formatRatePercent(r.ownedRate) : '',
    r.detail || ''
  ]);
  const csv = '\ufeff' + [header, ...rows].map(r => r.map(csvEsc).join(',')).join('\n');
  const date = new Date().toISOString().slice(0,10).replaceAll('-','');
  dl(`fujiya_collection_log_v${APP_VERSION.replaceAll('.', '_')}_${date}.csv`, csv, 'text/csv;charset=utf-8');
  toast('ログCSVを書き出しました');
}

