const ENTRY_PHOTO_DB_NAME='fujiya_collection_entry_photos_v1';
const ENTRY_PHOTO_DB_STORE='photos';
let entryPhotoDbPromise=null;
const entryPhotoInlineFallbackIds=new Set();
let entryPhotoMaintenanceTimer=0;

function entryPhotoOpenDb(){
  if(entryPhotoDbPromise) return entryPhotoDbPromise;
  entryPhotoDbPromise=new Promise((resolve,reject)=>{
    if(!window.indexedDB){reject(new Error('登録画像の大容量保存に対応していません'));return;}
    let request;
    try{request=indexedDB.open(ENTRY_PHOTO_DB_NAME,1);}catch(error){reject(error);return;}
    request.onupgradeneeded=()=>{
      const db=request.result;
      if(!db.objectStoreNames.contains(ENTRY_PHOTO_DB_STORE)) db.createObjectStore(ENTRY_PHOTO_DB_STORE,{keyPath:'id'});
    };
    request.onsuccess=()=>resolve(request.result);
    request.onerror=()=>reject(request.error||new Error('登録画像の保存領域を開けませんでした'));
    request.onblocked=()=>reject(new Error('別画面でみてコレを閉じてから、もう一度試してください'));
  }).catch(error=>{entryPhotoDbPromise=null;throw error;});
  return entryPhotoDbPromise;
}

async function entryPhotoGetAllRecords(){
  try{
    const db=await entryPhotoOpenDb();
    return await new Promise((resolve,reject)=>{
      const tx=db.transaction(ENTRY_PHOTO_DB_STORE,'readonly');
      const req=tx.objectStore(ENTRY_PHOTO_DB_STORE).getAll();
      req.onsuccess=()=>resolve(Array.isArray(req.result)?req.result:[]);
      req.onerror=()=>reject(req.error||new Error('登録画像を読み込めませんでした'));
    });
  }catch(error){console.warn('entry photo read failed',error);return [];}
}

async function entryPhotoPersistEntry(entry){
  const id=String(entry?.id||'').trim();
  if(!id) return false;
  try{
    const db=await entryPhotoOpenDb();
    const data=String(entry?.photoData||'');
    await new Promise((resolve,reject)=>{
      const tx=db.transaction(ENTRY_PHOTO_DB_STORE,'readwrite');
      const store=tx.objectStore(ENTRY_PHOTO_DB_STORE);
      if(data) store.put({id,data,updatedAt:String(entry?.updatedAt||nowIso())});
      else store.delete(id);
      tx.oncomplete=()=>resolve();
      tx.onerror=()=>reject(tx.error||new Error('登録画像を保存できませんでした'));
      tx.onabort=()=>reject(tx.error||new Error('登録画像の保存が中断されました'));
    });
    entryPhotoInlineFallbackIds.delete(id);
    return true;
  }catch(error){
    entryPhotoInlineFallbackIds.add(id);
    console.warn('entry photo persist failed; inline fallback',error);
    return false;
  }
}

function entryPhotoStripForStorage(entry){
  const copy={...(entry||{})};
  const id=String(copy.id||'');
  if(!entryPhotoInlineFallbackIds.has(id)) copy.photoData='';
  return copy;
}

async function entryPhotoHydrateEntries(entries){
  const rows=Array.isArray(entries)?entries:[];
  const stored=await entryPhotoGetAllRecords();
  const map=new Map(stored.map(row=>[String(row?.id||''),String(row?.data||'')]));
  let hydrated=0;
  for(const entry of rows){
    if(!entry||!entry.id) continue;
    const inline=String(entry.photoData||'');
    if(inline){
      await entryPhotoPersistEntry(entry);
      continue;
    }
    const data=map.get(String(entry.id))||'';
    if(data){entry.photoData=data;hydrated+=1;}
  }
  return hydrated;
}

function entryPhotoScheduleMaintenance(){
  clearTimeout(entryPhotoMaintenanceTimer);
  entryPhotoMaintenanceTimer=setTimeout(async()=>{
    const rows=Array.isArray(state.entries)?state.entries:[];
    for(const entry of rows){
      if(entry?.photoData) await entryPhotoPersistEntry(entry);
    }
    try{
      const valid=new Set(rows.map(entry=>String(entry?.id||'')).filter(Boolean));
      const stored=await entryPhotoGetAllRecords();
      const stale=stored.filter(row=>row?.id&&!valid.has(String(row.id)));
      if(stale.length){
        const db=await entryPhotoOpenDb();
        await new Promise((resolve,reject)=>{
          const tx=db.transaction(ENTRY_PHOTO_DB_STORE,'readwrite');
          const store=tx.objectStore(ENTRY_PHOTO_DB_STORE);
          stale.forEach(row=>store.delete(String(row.id)));
          tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);
        });
      }
    }catch(error){console.warn('entry photo cleanup failed',error);}
  },350);
}

const EXTENDED_BACKUP_LOCAL_KEYS=[
  'fujiya_collection_profile_v20_1','fujiya_collection_profile_v20_1_updated_at','fujiya_collection_profile_v20_1_image_updated_at',
  'fujiya_collection_profile_v20_1_sync_image','fujiya_collection_profile_v20_1_image_removed_at','fujiya_collection_profile_v20_1_metrics','fujiya_collection_profile_v20_1_manual_grants',
  'fujiya_collection_profile_v20_1_activity_days','fujiya_collection_profile_v20_1_seen_unlocks',
  'fujiya_mitemaga_drafts_v1','fujiya_mitemaga_custom_rss_v1','fujiya_mitemaga_custom_rss_initialized_v1',
  'fujiya_mitemaga_custom_rss_updated_v1','fujiya_mitemaga_view_mode_v1','fujiya_mitemaga_home_latest_v1',
  'fujiya_mitereco_v1','fujiya_mitereco_user_id_v1','fujiya_mitereco_identity_user_v2','fujiya_mitereco_profile_signature_v4',
  'fujiya_mitereco_edit_token_v1','fujiya_mitereco_timer_countdown_v1','fujiya_mitereco_timer_sound_v1',
  'fujiya_mitereco_timer_vibration_v1','fujiya_mitereco_top_notifications_v1','fujiya_mike_navi_community_v1'
];

async function extendedIdbGetAll(dbName,storeName){
  if(!window.indexedDB) return [];
  return await new Promise(resolve=>{
    let request;
    try{request=indexedDB.open(dbName);}catch(error){resolve([]);return;}
    request.onerror=()=>resolve([]);
    request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains(storeName))db.createObjectStore(storeName,{keyPath:'id'});};
    request.onsuccess=()=>{
      const db=request.result;
      if(!db.objectStoreNames.contains(storeName)){db.close();resolve([]);return;}
      const tx=db.transaction(storeName,'readonly');
      const req=tx.objectStore(storeName).getAll();
      req.onsuccess=()=>{const rows=Array.isArray(req.result)?req.result:[];db.close();resolve(rows);};
      req.onerror=()=>{db.close();resolve([]);};
    };
  });
}

async function extendedIdbReplaceAll(dbName,storeName,records){
  if(!window.indexedDB) return false;
  const rows=Array.isArray(records)?records:[];
  return await new Promise(resolve=>{
    let request;
    try{request=indexedDB.open(dbName,1);}catch(error){resolve(false);return;}
    request.onupgradeneeded=()=>{
      const db=request.result;
      if(!db.objectStoreNames.contains(storeName)) db.createObjectStore(storeName,{keyPath:'id'});
    };
    request.onerror=()=>resolve(false);
    request.onsuccess=()=>{
      const db=request.result;
      if(!db.objectStoreNames.contains(storeName)){db.close();resolve(false);return;}
      const tx=db.transaction(storeName,'readwrite');
      const store=tx.objectStore(storeName);store.clear();rows.forEach(row=>{if(row&&row.id)store.put(row);});
      tx.oncomplete=()=>{db.close();resolve(true);};
      tx.onerror=()=>{db.close();resolve(false);};
      tx.onabort=()=>{db.close();resolve(false);};
    };
  });
}

async function collectExtendedBackupData(){
  const localStorageData={};
  EXTENDED_BACKUP_LOCAL_KEYS.forEach(key=>{
    try{const value=localStorage.getItem(key);if(value!==null)localStorageData[key]=value;}catch(error){}
  });
  let profileImage='';
  try{if(typeof profileV201ImageDbGet==='function')profileImage=await profileV201ImageDbGet();}catch(error){}
  const miteMagazineDraftCovers=await extendedIdbGetAll('fujiya_mitemaga_drafts_db_v1','draft_covers');
  return {format:2,localStorage:localStorageData,profileImage,miteMagazineDraftCovers};
}

async function restoreExtendedBackupData(data,mode){
  const ext=data?.extended;
  if(!ext||typeof ext!=='object'||mode?.add||!mode?.keepUserId) return false;
  const localData=ext.localStorage&&typeof ext.localStorage==='object'?ext.localStorage:{};
  EXTENDED_BACKUP_LOCAL_KEYS.forEach(key=>{
    try{if(Object.prototype.hasOwnProperty.call(localData,key))localStorage.setItem(key,String(localData[key]));else localStorage.removeItem(key);}catch(error){}
  });
  if(Object.prototype.hasOwnProperty.call(ext,'profileImage')){
    try{
      if(typeof profileV201CommitImage==='function') await profileV201CommitImage(String(ext.profileImage||''),{updatedAt:localData['fujiya_collection_profile_v20_1_image_updated_at']||nowIso()});
    }catch(error){console.warn('profile image restore failed',error);}
  }
  if(Array.isArray(ext.miteMagazineDraftCovers)){
    await extendedIdbReplaceAll('fujiya_mitemaga_drafts_db_v1','draft_covers',ext.miteMagazineDraftCovers);
  }
  return true;
}

async function buildFullBackup(){
  const photoRecords=await entryPhotoGetAllRecords();
  const photoMap=new Map(photoRecords.map(row=>[String(row?.id||''),String(row?.data||'')]));
  const entries=(state.entries||[]).map(entry=>({
    ...entry,
    photoData:String(entry?.photoData||photoMap.get(String(entry?.id||''))||'')
  }));
  return {
    app:'fujiya_collection',
    version: APP_VERSION,
    versionLabel: APP_VERSION_LABEL,
    backupType:'full-v2',
    exportedAt: nowIso(),
    entries,
    platformTargets: state.platformTargets,
    settings:{
      userId: getUserId(),
      userName: getUserName(),
      gasEndpoint: getGasEndpoint(),
      sheetSource: getSheetSourceSettings(),
      shareOptIn: getShareOptIn(),
      sharePurchasePriceOptIn: getSharePurchasePriceOptIn(),
      autoSyncLastAt: localStorage.getItem(AUTO_SYNC_LAST_KEY) || '',
      autoReceiveEnabled: getAutoReceiveEnabled(),
      autoReceiveLastAt: localStorage.getItem(AUTO_RECEIVE_LAST_KEY) || '',
      view: getViewSettings(),
      collapsedPanels: getCollapsedPanelSettings(),
      remoteStatsFetchedAt: state.remoteStatsFetchedAt || '',
      remoteStats: Object.values(state.remoteStats || {}),
      remoteUsersFetchedAt: state.remoteUsersFetchedAt || '',
      remoteUsers: (state.remoteUsers || []).map(u => ({record_count:u.record_count || 0, last_seen_at:u.last_seen_at || ""})),
      mockCrowdActive: state.mockCrowdActive,
      mockCrowdCount: state.mockCrowdCount,
      eventLogs: state.eventLogs || [],
      gamify: {unlockedTitleIds: state.unlockedTitleIds || [], titleFilter: state.titleFilter || 'all', displayTitleId: state.displayTitleId || 'auto'},
      dexSettings: {platform: state.dexPlatform || '', status: state.dexStatus || 'all', sort: state.dexSort || 'master', search: state.dexSearch || '', ranges: sanitizeDexRanges(state.dexRanges || {})},
      shelfEntryIds: state.shelfEntryIds || [],
      recommendPreferredGenres: state.recommendPreferredGenres || [],
      recommendPreferredMakers: state.recommendPreferredMakers || [],
      buybackEntryIds: state.buybackEntryIds || [],
      buybackHistory: state.buybackHistory || [],
      buybackMeta: state.buybackMeta || {},
      buybackContact: (() => { try { return JSON.parse(localStorage.getItem(BUYBACK_CONTACT_KEY) || '{}'); } catch(e) { return {}; } })(),
      lastBackupAt: localStorage.getItem(BACKUP_KEY) || ''
    },
    extended: await collectExtendedBackupData()
  };
}

function backupHealth(){
  const entries = state.entries || [];
  const imageCount = entries.filter(e => e.photoData).length;
  const sharedReady = syncableEntries().length;
  const age = backupAgeDays();
  const gasReady = !!getGasEndpoint();
  const sheetReady = !!getSheetSourceSettings().spreadsheetId;
  const shareOptIn = getShareOptIn();
  const autoReceive = getAutoReceiveEnabled();
  const remote = remoteStatsSummary();
  const users = remoteUsersSummary();
  updateRankControls();
  renderMockCrowdStatus();

  return {
    total: entries.length,
    imageCount,
    sharedReady,
    age,
    gasReady,
    sheetReady,
    shareOptIn,
    autoReceive,
    remoteCount: remote.count || 0,
    remoteUsers: users.count || 0
  };
}

function renderBackupHealth(){
  const box = $('backupHealth');
  if(!box) return;

  const h = backupHealth();
  const ageText = h.age === null ? '未作成' : (h.age === 0 ? '今日' : h.age + '日前');
  const ageClass = h.age === null || h.age >= 7 ? 'warn' : 'good';
  const fileName = localStorage.getItem(BACKUP_FILE_KEY) || '';
  const userName = getUserName();
  const userId = shortUserId();

  box.innerHTML = `
    <div class="backup-health-primary">
      <div class="backup-compact-card">
        <span>登録</span><strong>${h.total}</strong><small>件</small>
      </div>
      <div class="backup-compact-card">
        <span>画像</span><strong>${h.imageCount}</strong><small>件</small>
      </div>
      <div class="backup-compact-card">
        <span>共有ID</span><strong>${h.sharedReady}</strong><small>件</small>
      </div>
      <div class="backup-compact-card ${ageClass}">
        <span>最終BK</span><strong>${esc(ageText)}</strong>
      </div>
    </div>

    <div class="backup-health-status">
      <span class="${h.shareOptIn ? 'good' : 'warn'}">共有 ${h.shareOptIn ? 'ON' : 'OFF'}</span>
      <span class="${h.autoReceive ? 'good' : 'warn'}">自動受信 ${h.autoReceive ? 'ON' : 'OFF'}</span>
      <span class="${h.remoteCount ? 'good' : 'warn'}">共有データ ${h.remoteCount}件</span>
      <span class="${h.remoteUsers ? 'good' : 'warn'}">参加 ${h.remoteUsers}人</span>
    </div>

    <details class="backup-health-details">
      <summary>保存・共有の詳細</summary>
      <div class="backup-health-detail-grid">
        <div title="${esc(fileName)}"><span>バックアップ</span><strong>${fileName ? '保存済' : '未記録'}</strong></div>
        <div><span>共有URL</span><strong>${h.gasReady ? '設定済' : '未設定'}</strong></div>
        <div><span>取得シート</span><strong>${h.sheetReady ? '設定済' : '未設定'}</strong></div>
        <div><span>形式</span><strong>完全JSON</strong></div>
        <div><span>表示名</span><strong>${esc(userName)}</strong></div>
        <div><span>個人ID</span><strong>${esc(userId)}</strong></div>
      </div>
    </details>
  `;
}

function backupAdvice(){
  const h = backupHealth();
  if(!h.total) return 'まだ登録データがないよ。まずは1本登録してからバックアップするといいよ。';
  if(h.age === null) return 'まだ完全バックアップがないよ。まず「完全バックアップ」を保存しておくと安心だよ。';
  if(h.age >= 7) return `前回バックアップから${h.age}日たってるよ。今日の状態で完全バックアップしておくのがおすすめだよ。`;
  if(h.imageCount > 0) return `画像入りデータが${h.imageCount}件あるよ。画像もJSONに入るから、完全バックアップは大事だよ。`;
  return 'バックアップ状態は良さそうだよ。別端末へ移す時は「完全バックアップ」→新端末でJSON復元の順だよ。';
}

async function exportFullBackup(){
  const token=window.fujiyaProcessing?.start({title:'完全バックアップを作成しています',detail:'登録画像・プロフィール・みてマガ下書きもまとめています。',progressText:'バックアップ中'})||'';
  try{
    await window.fujiyaProcessing?.paint?.();
    const backup=await buildFullBackup();
    const date = new Date().toISOString().slice(0,10).replaceAll('-','');
    const fileName = `fujiya_collection_full_backup_v${APP_VERSION.replaceAll('.', '_')}_${date}.json`;
    dl(fileName, JSON.stringify(backup, null, 2), 'application/json');
    localStorage.setItem(BACKUP_FILE_KEY, fileName);
    markBackedUp();
    if(typeof profileV201IncrementMetric==='function')profileV201IncrementMetric('backup_export',1);
    renderBackupHealth();
    toast('JSON完全バックアップを書き出しました');
    showMikeTalk('完全バックアップを保存したよ。登録画像・プロフィール画像・二つ名・自己紹介・外部リンク・みてマガ下書きも含まれているよ。');
  }catch(error){console.error(error);toast('完全バックアップを作成できませんでした');showMikeTalk(String(error?.message||error));}
  finally{window.fujiyaProcessing?.end(token);}
}

