function recommendationSummaryText(){
  const remote = remoteStatsSummary();
  if(!remote.count) return '共有データ未取得です。まず「共有データ取得」を押すと、高評価・人気・評価数・穴場・未所持おすすめをまとめて確認できるよ。';

  const recs = remoteRecommendations(3);
  const top = remoteTopRated(1)[0];
  const popular = remotePopular(1)[0];
  const most = remoteMostRated(1)[0];

  const parts = [];
  if(top) parts.push(`平均レート上位は「${top.title}」`);
  if(popular) parts.push(`所持率上位は「${popular.title}」`);
  if(most) parts.push(`評価数上位は「${most.title}」`);
  if(recs.length) parts.push(`未所持おすすめは「${recs.map(r => r.title).join('」「')}」あたり`);

  return parts.length
    ? parts.join('、') + 'だよ。'
    : '共有データは取得済みだけど、ランキングに使える評価データがまだ少ないよ。参加人数と評価が増えるほど精度が上がるよ。';
}


function seededNumber(key){
  let h = 2166136261;
  const s = String(key || '');
  for(let i = 0; i < s.length; i++){
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  h >>>= 0;
  return h / 4294967295;
}

function clampNumber(n, min, max){
  return Math.max(min, Math.min(max, n));
}

function famousTitleBonus(title){
  const t = String(title || '');
  let bonus = 0;
  if(/マリオ|ゼルダ|ポケモン|カービィ|ドンキー|メトロイド|ファイナルファンタジー|ドラゴン|ドラクエ|クロノ|ロックマン|悪魔城|桃太郎|ぷよぷよ|ストリートファイター|星のカービィ/.test(t)) bonus += 0.24;
  if(/スーパー|DX|コレクション|ベスト|伝説|物語/.test(t)) bonus += 0.06;
  return bonus;
}

function buildMockCrowdRows(count){
  const participants = Math.max(2, Math.min(999, Number(count || 50)));
  const now = nowIso();

  return MASTER_TITLES.map(m => {
    const r1 = seededNumber(m.sharedTitleId + ':owned:' + participants);
    const r2 = seededNumber(m.sharedTitleId + ':rating:' + participants);
    const r3 = seededNumber(m.sharedTitleId + ':count:' + participants);
    const rRare = seededNumber(m.sharedTitleId + ':rare:' + participants);
    const bonus = famousTitleBonus(m.canonicalTitle);

    // 全体の5%前後だけを低所持率にして、レア表示が多すぎないようにする。
    let ownedRate = 0.10 + (r1 * 0.48) + bonus;
    if(m.platform === 'SFC' || m.platform === 'FC') ownedRate += 0.03;
    if(m.platform === 'GBA') ownedRate -= 0.015;
    if(rRare < 0.015) ownedRate = 0.012 + rRare * 0.8; // 超レア候補
    else if(rRare < 0.055) ownedRate = 0.055 + (rRare - 0.015); // レア候補
    ownedRate = clampNumber(ownedRate, 0.01, 0.96);

    const ownedCount = Math.max(1, Math.round(participants * ownedRate));
    const completeOwnedCount = Math.max(0, Math.min(ownedCount, Math.round(ownedCount * (0.22 + seededNumber(m.sharedTitleId + ':completeOwned:' + participants) * 0.58))));
    const wantSeed = seededNumber(m.sharedTitleId + ':want:' + participants);
    const wantRate = clampNumber(0.015 + wantSeed * 0.22 + bonus * 0.20, 0, 0.48);
    const wantCount = Math.max(0, Math.min(participants - ownedCount, Math.round(participants * wantRate)));
    const ratingCount = Math.max(0, Math.min(ownedCount, Math.round(ownedCount * (0.18 + r3 * 0.42))));
    let ratingAvg = 2.6 + (r2 * 1.7) + (bonus * 1.2);
    ratingAvg = clampNumber(ratingAvg, 2.2, 4.95);

    // V7.16.20: 水増しテストでも共有平均購入額を確認できるように疑似価格を作る。
    const rPrice = seededNumber(m.sharedTitleId + ':price:' + participants);
    const rPriceSpread = seededNumber(m.sharedTitleId + ':priceSpread:' + participants);
    const platformBase = m.platform === 'SFC' ? 900 : (m.platform === 'FC' ? 700 : (m.platform === 'GBA' ? 600 : 500));
    const rareBoost = ownedRate <= 0.08 ? 4500 : (ownedRate <= 0.18 ? 1800 : 0);

    const romCount = Math.max(1, Math.min(ownedCount, Math.round(ownedCount * (0.16 + seededNumber(m.sharedTitleId + ':romPriceCount:' + participants) * 0.28))));
    const completeCount = Math.max(1, Math.min(ownedCount, Math.round(ownedCount * (0.10 + seededNumber(m.sharedTitleId + ':completePriceCount:' + participants) * 0.22))));

    const romAvg = platformBase + Math.round(rPrice * 2600) + Math.round(rareBoost * 0.45);
    const completeAvg = Math.round(romAvg * (2.0 + seededNumber(m.sharedTitleId + ':completeRatio:' + participants) * 2.5) + 800 + rareBoost);
    const romSpread = 0.28 + rPriceSpread * 0.22;
    const completeSpread = 0.22 + rPriceSpread * 0.34;
    const clearCount = Math.max(1, Math.min(ownedCount, Math.round(ownedCount * (0.12 + seededNumber(m.sharedTitleId + ':clearCount:' + participants) * 0.34))));
    const genre = String(m.genre || '').toUpperCase();
    const clearBase = genre.includes('RPG') ? 26 : (genre.includes('SLG') ? 18 : (genre.includes('ADV') ? 10 : (genre.includes('ACT') ? 7 : 5)));
    const clearMedian = Math.max(1, Math.round(clearBase * (0.55 + seededNumber(m.sharedTitleId + ':clearTime:' + participants) * 1.2)));

    return {
      shared_title_id: m.sharedTitleId,
      platform: m.platform,
      title: m.canonicalTitle,
      users_total: participants,
      owned_count: ownedCount,
      owned_rate: ownedCount / participants,
      complete_owned_count: completeOwnedCount,
      complete_status_known_owned_count: ownedCount,
      want_count: wantCount,
      rating_count: ratingCount,
      rating_avg: ratingCount ? ratingAvg : 0,
      updated_at: now,
      purchase_rom_only_count: romCount,
      purchase_rom_only_avg: romCount >= 1 ? romAvg : '',
      purchase_rom_only_median: romCount >= 1 ? romAvg : '',
      purchase_rom_only_min: romCount >= 1 ? (romCount === 1 ? romAvg : Math.max(0, Math.round(romAvg * (0.55 - romSpread * 0.25)))) : '',
      purchase_rom_only_max: romCount >= 1 ? (romCount === 1 ? romAvg : Math.round(romAvg * (1.25 + romSpread))) : '',
      purchase_complete_count: completeCount,
      purchase_complete_avg: completeCount >= 1 ? completeAvg : '',
      purchase_complete_median: completeCount >= 1 ? completeAvg : '',
      purchase_complete_min: completeCount >= 1 ? (completeCount === 1 ? completeAvg : Math.max(0, Math.round(completeAvg * (0.62 - completeSpread * 0.22)))) : '',
      purchase_complete_max: completeCount >= 1 ? (completeCount === 1 ? completeAvg : Math.round(completeAvg * (1.22 + completeSpread))) : '',
      clear_time_count: clearCount,
      clear_time_avg: clearMedian,
      clear_time_median: clearMedian,
      clear_time_min: clearCount === 1
        ? clearMedian
        : Math.max(1, Math.round(clearMedian * (clearCount < 5 ? 0.65 : 0.8))),
      clear_time_max: clearCount === 1
        ? clearMedian
        : Math.max(clearMedian, Math.round(clearMedian * (clearCount < 5 ? 1.45 : 1.25)))
    };
  });
}

function buildMockCrowdUsers(count){
  const participants = Math.max(2, Math.min(999, Number(count || 50)));
  const now = nowIso();
  return Array.from({length: participants}, (_, i) => ({
    record_count: Math.max(1, Math.round(MASTER_TITLES.length * (0.08 + seededNumber('user:' + i + ':' + participants) * 0.25))),
    last_seen_at: now
  }));
}

function applyMockCrowd(count){
  const participants = Math.max(2, Math.min(999, Number(count || 50)));

  try{
    const stats = buildMockCrowdRows(participants);
    const users = buildMockCrowdUsers(participants);
    const fetchedAt = nowIso();

    // テスト水増しは大量の疑似集計をlocalStorageへ保存しない。
    // 登録写真やログが多い環境では保存容量を超えてボタンが止まるため、画面上の一時データとして反映する。
    state.remoteStats = normalizeRemoteStatsRows(stats);
    state.remoteStatsFetchedAt = fetchedAt;
    state.remoteUsers = normalizeRemoteUsersRows(users);
    state.remoteUsersFetchedAt = fetchedAt;
    state.mockCrowdActive = true;
    state.mockCrowdCount = participants;

    localStorage.setItem(MOCK_CROWD_KEY, JSON.stringify({
      active:true,
      count:participants,
      appliedAt:fetchedAt
    }));

    const rareLogAdded = syncRareLogsFromCurrentEntries('水増しテストでレア判定');
    render();
    toast('テスト水増しを反映しました');
    showMikeTalk(`テスト水増し完了だよ！\n疑似参加者：${participants}人\n集計タイトル：${stats.length}件\nレアログ追加：${rareLogAdded}件\n\nレアバッジ・機種別ランキング・昇順/降順・成長型レア演出・図鑑の共有平均購入額（中央値）をこの状態で試せるよ。本番GASには送ってないよ。`);
  }catch(e){
    const msg = String(e && e.message ? e.message : e);
    console.error('mock crowd apply failed:', e);
    toast('テスト水増しに失敗しました');
    showMikeTalk(`テスト水増しNGだよ。\n\nエラー内容：${msg}`);
  }
}

function clearMockCrowd(){
  localStorage.removeItem(MOCK_CROWD_KEY);
  state.mockCrowdActive = false;
  state.mockCrowdCount = 0;

  // 水増し前に保存されていた本番共有データへ戻す。
  state.remoteStats = {};
  state.remoteStatsFetchedAt = '';
  state.remoteUsers = [];
  state.remoteUsersFetchedAt = '';
  loadRemoteStats();
  loadRemoteUsers();

  render();
  toast('テスト水増しを解除しました');
  showMikeTalk('テスト水増しを解除して、保存済みの共有データへ戻したよ。');
}

function loadMockCrowd(){
  try{
    const raw = localStorage.getItem(MOCK_CROWD_KEY);
    if(!raw) return;
    const data = JSON.parse(raw);
    if(data && data.active){
      const participants = Math.max(2, Math.min(999, Number(data.count || 50)));
      const fetchedAt = data.appliedAt || nowIso();

      // 再起動時も、小さな設定だけを元に疑似データをメモリ上で再生成する。
      state.remoteStats = normalizeRemoteStatsRows(buildMockCrowdRows(participants));
      state.remoteStatsFetchedAt = fetchedAt;
      state.remoteUsers = normalizeRemoteUsersRows(buildMockCrowdUsers(participants));
      state.remoteUsersFetchedAt = fetchedAt;
      state.mockCrowdActive = true;
      state.mockCrowdCount = participants;
    }
  }catch(e){
    console.error(e);
    localStorage.removeItem(MOCK_CROWD_KEY);
    state.mockCrowdActive = false;
    state.mockCrowdCount = 0;
  }
}

function renderMockCrowdStatus(){
  const box = $('mockCrowdStatus');
  const select = $('mockCrowdCount');
  const banner = $('mockModeBanner');
  const bannerText = $('mockModeText');
  const bannerRare = $('mockModeRare');

  if(select && state.mockCrowdCount){
    select.value = String(state.mockCrowdCount);
  }

  if(banner){
    banner.classList.toggle('hidden', !state.mockCrowdActive);
  }

  if(state.mockCrowdActive){
    const s = remoteStatsSummary();
    const rarity = remoteRaritySummary();
    if(box){
      box.classList.add('active');
      box.innerHTML = `テスト水増し中：疑似参加者 <strong>${state.mockCrowdCount}</strong> 人 / 疑似集計 ${s.count}件 / 激レア${rarity.ultra}<br>疑似価格登録 ${s.priceRows}件（ROMのみ${s.priceRomRows} / 完品${s.priceCompleteRows}）・集計中${s.pricePendingRows}件。本番GASには送信していません。`;
    }
    if(bannerText) bannerText.textContent = `疑似${state.mockCrowdCount}人`;
    if(bannerRare) bannerRare.textContent = `激レア${rarity.ultra} / 本番送信なし`;
  }else{
    if(box){
      box.classList.remove('active');
      box.textContent = 'テスト水増し：未使用。本番データを汚さず、人数が増えた時のレア候補・演出解禁・ランキングの見え方だけ試せます。';
    }
    if(bannerText) bannerText.textContent = '';
    if(bannerRare) bannerRare.textContent = '';
  }
}


function rowHasAnyKey(row, keys){
  if(!row || typeof row !== 'object') return false;
  return keys.some(key => Object.prototype.hasOwnProperty.call(row, key));
}

function truthyField(value){
  const raw = String(value ?? '').trim().toLowerCase();
  return value === true || value === 1 || raw === '1' || raw === 'true' || raw === 'yes';
}

function remotePriceSchemaFromRow(row){
  const conditionKeys = [
    'purchase_rom_only_count',
    'purchase_rom_only_avg',
    'purchase_rom_only_median',
    'purchase_rom_only_min',
    'purchase_rom_only_max',
    'purchase_complete_count',
    'purchase_complete_avg',
    'purchase_complete_median',
    'purchase_complete_min',
    'purchase_complete_max',
    'rom_only_count',
    'rom_only_avg',
    'rom_only_median',
    'complete_count',
    'complete_avg',
    'complete_median'
  ];
  const legacyKeys = [
    'purchase_price_count',
    'purchase_price_avg',
    'purchase_price_min',
    'purchase_price_max',
    'price_count',
    'price_avg',
    'price_min',
    'price_max'
  ];

  if(rowHasAnyKey(row, conditionKeys) || String(row.purchase_price_schema || '').trim() === 'condition') return 'condition';
  if(row.purchase_price_has_field !== undefined && truthyField(row.purchase_price_has_field)) return 'condition';
  if(rowHasAnyKey(row, legacyKeys) || String(row.purchase_price_schema || '').trim() === 'legacy') return 'legacy';
  return 'none';
}

function statHasConditionPriceSchema(stat){
  return !!stat && (stat.purchase_price_schema === 'condition' || !!stat.purchase_price_has_field);
}

function statHasLegacyPriceSchema(stat){
  return !!stat && stat.purchase_price_schema === 'legacy';
}

function noConditionPriceText(stat){
  if(statHasLegacyPriceSchema(stat)) return {main:'旧形式', sub:'ROMのみ/完品分類なし'};
  return {main:'未対応', sub:'更新後に表示'};
}

function pendingPriceText(count=0){
  const n = Math.max(0, Number(count || 0) || 0);
  return n > 0 ? `参考 ${n}件` : '登録なし';
}

function purchaseMedianValue(stat, key){
  if(!stat) return 0;
  return Number(stat[`${key}_median`] || stat[`${key}_avg`] || 0) || 0;
}

function purchasePriceValueReady(stat, key){
  if(!stat) return false;
  const flag = `${key}_value_ready`;
  if(stat[flag] !== undefined) return !!stat[flag];
  return Number(stat[`${key}_count`] || 0) >= 3;
}

function purchasePriceMetaText(stat, key, count){
  const n = Math.max(0, Number(count || 0) || 0);
  if(!n) return '0件';
  const median = yen0(purchaseMedianValue(stat, key)) || '—';
  const min = yen0(stat && stat[`${key}_min`]) || median;
  const max = yen0(stat && stat[`${key}_max`]) || median;
  const price = min === max ? min : `${min}〜${max}`;
  return `${n < 3 ? '参考 ' : ''}${n}件 / ${price}`;
}


function remotePriceRawValueReady(row, category){
  const prefix = category === 'complete' ? 'purchase_complete' : 'purchase_rom_only';
  const legacy = category === 'complete' ? 'complete' : 'rom_only';
  const explicitKey = `${prefix}_value_ready`;
  if(row && row[explicitKey] !== undefined) return truthyField(row[explicitKey]);

  const looksNormalized = row && row.purchase_price_schema !== undefined && row.purchase_price_has_field !== undefined;
  if(looksNormalized){
    // 旧HTMLのキャッシュは1〜2件の値を0へ正規化しているため、そのまま信用しない。
    return Number(row[`${prefix}_count`] || 0) >= 3;
  }

  return [
    row && row[`${prefix}_median`], row && row[`${legacy}_median`],
    row && row[`${prefix}_avg`], row && row[`${legacy}_avg`],
    row && row[`${prefix}_min`], row && row[`${legacy}_min`],
    row && row[`${prefix}_max`], row && row[`${legacy}_max`]
  ].some(value => value !== undefined && value !== null && String(value).trim() !== '');
}

function normalizeRemoteStatRow(row){
  const id = String(row?.shared_title_id || '').trim();
  if(!id) return null;

  const priceSchema = remotePriceSchemaFromRow(row);
  const hasConditionPrice = priceSchema === 'condition';
  const romPriceValueReady = remotePriceRawValueReady(row, 'rom_only');
  const completePriceValueReady = remotePriceRawValueReady(row, 'complete');
  const usersTotal = Number(row.users_total || 0) || 0;
  const ownedCount = Number(row.owned_count || 0) || 0;
  const wantCountHasField = row.want_count !== undefined
    && row.want_count !== null
    && String(row.want_count).trim() !== '';
  const wantCount = Number(row.want_count || 0) || 0;
  const completeOwnedCountHasField = row.complete_owned_count_has_field === true
    || row.complete_owned_count_has_field === 1
    || row.complete_owned_count_has_field === '1'
    || row.complete_owned_count !== undefined
    || row.owned_complete_count !== undefined
    || row.holder_complete_count !== undefined;
  const completeKnownCountHasField = row.complete_status_known_owned_count_has_field === true
    || row.complete_status_known_owned_count_has_field === 1
    || row.complete_status_known_owned_count_has_field === '1'
    || row.complete_status_known_owned_count !== undefined
    || row.complete_known_owned_count !== undefined;
  const completeOwnedCount = Number(row.complete_owned_count ?? row.owned_complete_count ?? row.holder_complete_count ?? 0) || 0;
  const completeKnownOwnedCount = Number(row.complete_status_known_owned_count ?? row.complete_known_owned_count ?? 0) || 0;
  let ownedRate = Number(row.owned_rate || 0) || 0;
  if(ownedRate > 1) ownedRate = ownedRate / 100;

  return [id, {
    shared_title_id: id,
    platform: String(row.platform || ''),
    title: String(row.title || ''),
    users_total: usersTotal,
    // RC1.4.241: GASが機種別コレクター人数を返す場合は保持する。
    // 現行GASが未対応でも、後段で保守的な最低母数を推定して誤判定を防ぐ。
    platform_users_total: Number(row.platform_users_total || row.platform_collector_count || row.platform_users || 0) || 0,
    owned_count: ownedCount,
    owned_rate: ownedRate,
    complete_owned_count: Math.max(0, Math.min(ownedCount, completeOwnedCount)),
    complete_owned_count_has_field: completeOwnedCountHasField,
    complete_status_known_owned_count: Math.max(0, Math.min(ownedCount, completeKnownOwnedCount)),
    complete_status_known_owned_count_has_field: completeKnownCountHasField,
    want_count: wantCount,
    want_count_has_field: wantCountHasField,
    rating_count: Number(row.rating_count || 0) || 0,
    rating_avg: Number(row.rating_avg || 0) || 0,
    updated_at: String(row.updated_at || ''),
    purchase_rom_only_count: Number(row.purchase_rom_only_count || row.rom_only_count || 0) || 0,
    purchase_rom_only_avg: Number(row.purchase_rom_only_avg || row.rom_only_avg || 0) || 0,
    purchase_rom_only_median: Number(row.purchase_rom_only_median || row.rom_only_median || row.purchase_rom_only_avg || row.rom_only_avg || 0) || 0,
    purchase_rom_only_min: Number(row.purchase_rom_only_min || row.rom_only_min || 0) || 0,
    purchase_rom_only_max: Number(row.purchase_rom_only_max || row.rom_only_max || 0) || 0,
    purchase_rom_only_value_ready: romPriceValueReady,
    purchase_complete_count: Number(row.purchase_complete_count || row.complete_count || 0) || 0,
    purchase_complete_avg: Number(row.purchase_complete_avg || row.complete_avg || 0) || 0,
    purchase_complete_median: Number(row.purchase_complete_median || row.complete_median || row.purchase_complete_avg || row.complete_avg || 0) || 0,
    purchase_complete_min: Number(row.purchase_complete_min || row.complete_min || 0) || 0,
    purchase_complete_max: Number(row.purchase_complete_max || row.complete_max || 0) || 0,
    purchase_complete_value_ready: completePriceValueReady,
    purchase_price_has_field: hasConditionPrice,
    purchase_price_schema: priceSchema,
    purchase_price_legacy_field: priceSchema === 'legacy',
    clear_time_count: Number(row.clear_time_count || row.clear_count || 0) || 0,
    clear_time_avg: Number(row.clear_time_avg || row.clear_avg || 0) || 0,
    clear_time_median: Number(row.clear_time_median || row.clear_median || row.clear_time_avg || row.clear_avg || 0) || 0,
    clear_time_min: Number(row.clear_time_min || row.clear_min || 0) || 0,
    clear_time_max: Number(row.clear_time_max || row.clear_max || 0) || 0
  }];
}

function normalizeRemoteStatsRows(rows){
  const map = {};
  (rows || []).forEach(row => {
    const normalized = normalizeRemoteStatRow(row);
    if(normalized) map[normalized[0]] = normalized[1];
  });
  return map;
}

async function normalizeRemoteStatsRowsAsync(rows, processingToken=''){
  const source = Array.isArray(rows) ? rows : [];
  const map = {};
  let sliceStarted = typeof performance !== 'undefined' && performance.now ? performance.now() : Date.now();
  for(let i=0;i<source.length;i++){
    const normalized = normalizeRemoteStatRow(source[i]);
    if(normalized) map[normalized[0]] = normalized[1];
    if((i + 1) % 220 === 0 || fujiyaTimeSliceExpired(sliceStarted)){
      if(processingToken){
        window.fujiyaProcessing?.update(processingToken,{
          title:'共有データを整理しています',
          detail:'共有所持率・評価・購入額・クリア時間を端末用に変換しています。',
          current:i + 1,
          total:source.length
        });
      }
      await fujiyaYieldToBrowser();
      sliceStarted = typeof performance !== 'undefined' && performance.now ? performance.now() : Date.now();
    }
  }
  return map;
}
function openRemoteCacheDb(){
  return new Promise((resolve,reject) => {
    if(!('indexedDB' in window)){
      reject(new Error('共有キャッシュ保存領域を利用できません'));
      return;
    }
    const request = indexedDB.open(REMOTE_CACHE_DB_NAME, 1);
    request.onupgradeneeded = () => {
      const db = request.result;
      if(!db.objectStoreNames.contains(REMOTE_CACHE_DB_STORE)){
        db.createObjectStore(REMOTE_CACHE_DB_STORE);
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error || new Error('共有キャッシュ保存領域を開けませんでした'));
    request.onblocked = () => reject(new Error('共有キャッシュ保存領域が別画面で使用中です'));
  });
}

async function remoteCacheDbSet(key, value){
  const db = await openRemoteCacheDb();
  try{
    await new Promise((resolve,reject) => {
      const tx = db.transaction(REMOTE_CACHE_DB_STORE, 'readwrite');
      tx.objectStore(REMOTE_CACHE_DB_STORE).put(value, key);
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error || new Error('共有キャッシュを保存できませんでした'));
      tx.onabort = () => reject(tx.error || new Error('共有キャッシュ保存が中断されました'));
    });
  }finally{
    db.close();
  }
}

async function remoteCacheDbGet(key){
  const db = await openRemoteCacheDb();
  try{
    return await new Promise((resolve,reject) => {
      const tx = db.transaction(REMOTE_CACHE_DB_STORE, 'readonly');
      const request = tx.objectStore(REMOTE_CACHE_DB_STORE).get(key);
      request.onsuccess = () => resolve(request.result || null);
      request.onerror = () => reject(request.error || new Error('共有キャッシュを読み込めませんでした'));
    });
  }finally{
    db.close();
  }
}

function removeLegacyRemoteCache(key){
  try{ localStorage.removeItem(key); }catch(error){ console.warn('legacy remote cache cleanup failed', error); }
}

function queueRemoteCacheSave(key, value){
  // キャッシュ保存は受信成功判定と切り離す。容量不足でもGAS取得結果は画面へ反映する。
  Promise.resolve()
    .then(() => remoteCacheDbSet(key, value))
    .catch(error => console.warn('remote cache save skipped', error));
}

function remoteParticipantBaseFromUsers(){
  const rows=Array.isArray(state.remoteUsers)?state.remoteUsers:[];
  return rows.filter(row=>Number(row?.record_count||0)>0).length;
}

function enforceSharedParticipantBase(base=remoteParticipantBaseFromUsers()){
  const participants=Math.max(0,Number(base||0)||0);
  if(!participants||!state.remoteStats||typeof state.remoteStats!=='object')return 0;
  Object.values(state.remoteStats).forEach(stat=>{
    if(!stat||typeof stat!=='object')return;
    const owned=Math.max(0,Number(stat.owned_count||0)||0);
    stat.users_total=participants;
    stat.owned_rate=participants?Math.min(1,owned/participants):0;
  });
  return participants;
}

function persistRemoteStatsCache(){
  const payload = {
    fetchedAt: state.remoteStatsFetchedAt || nowIso(),
    stats: Object.values(state.remoteStats || {})
  };
  // 旧LocalStorageキャッシュが容量超過の原因なので、先に必ず解放する。
  removeLegacyRemoteCache(REMOTE_STATS_KEY);
  queueRemoteCacheSave(REMOTE_STATS_DB_RECORD, payload);
}

function saveRemoteStats(rows){
  const fetchedAt = nowIso();
  state.remoteStats = normalizeRemoteStatsRows(rows);
  enforceSharedParticipantBase();
  state.remoteStatsFetchedAt = fetchedAt;
  persistRemoteStatsCache();
  return state.remoteStats;
}

async function saveRemoteStatsAsync(rows, processingToken=''){
  const fetchedAt = nowIso();
  state.remoteStats = await normalizeRemoteStatsRowsAsync(rows, processingToken);
  enforceSharedParticipantBase();
  state.remoteStatsFetchedAt = fetchedAt;
  persistRemoteStatsCache();
  return state.remoteStats;
}

async function applyRemoteStatsCache(data){
  if(!data || !Array.isArray(data.stats) || state.mockCrowdActive) return false;
  const cachedAt = String(data.fetchedAt || '');
  const cachedTime = Date.parse(cachedAt) || 0;
  const currentTime = Date.parse(state.remoteStatsFetchedAt || '') || 0;
  if(Object.keys(state.remoteStats || {}).length && currentTime >= cachedTime) return false;
  state.remoteStats = await normalizeRemoteStatsRowsAsync(data.stats || []);
  enforceSharedParticipantBase();
  state.remoteStatsFetchedAt = cachedAt;
  return true;
}

function loadRemoteStats(){
  // 旧版キャッシュを一度だけ移行し、LocalStorage容量を即座に空ける。
  try{
    const raw = localStorage.getItem(REMOTE_STATS_KEY);
    if(raw){
      const data = JSON.parse(raw);
      removeLegacyRemoteCache(REMOTE_STATS_KEY);
      queueRemoteCacheSave(REMOTE_STATS_DB_RECORD, data);
      setTimeout(async () => {
        if(await applyRemoteStatsCache(data)){
          fujiyaSchedulePassiveRefresh('共有キャッシュ反映',650);
        }
      },0);
    }
  }catch(error){
    console.warn('legacy remote stats cache load failed', error);
    removeLegacyRemoteCache(REMOTE_STATS_KEY);
  }

  remoteCacheDbGet(REMOTE_STATS_DB_RECORD)
    .then(async data => {
      if(await applyRemoteStatsCache(data)){
        fujiyaSchedulePassiveRefresh('共有キャッシュ反映',650);
      }
    })
    .catch(error => console.warn('remote stats cache load skipped', error));
}


function normalizeRemoteUsersRows(rows){
  return (rows || [])
    .map((row, index) => ({
      // GAS v3.1 privacyでは user_id / display_name は返さない。
      // 画面では人数カウントだけに使うため、内部用の匿名IDを付ける。
      user_id: String(row.user_id || `anonymous-${index + 1}`).trim(),
      display_name: '',
      first_seen_at: String(row.first_seen_at || ''),
      last_seen_at: String(row.last_seen_at || ''),
      record_count: Number(row.record_count || 0) || 0
    }))
    .filter(row => row.record_count || row.last_seen_at || row.user_id)
    .sort((a,b) => (b.last_seen_at || '').localeCompare(a.last_seen_at || ''));
}

function persistRemoteUsersCache(){
  const payload = {
    fetchedAt: state.remoteUsersFetchedAt || nowIso(),
    users: state.remoteUsers || []
  };
  removeLegacyRemoteCache(REMOTE_USERS_KEY);
  queueRemoteCacheSave(REMOTE_USERS_DB_RECORD, payload);
}

function saveRemoteUsers(rows){
  const fetchedAt = nowIso();
  state.remoteUsers = normalizeRemoteUsersRows(rows);
  state.remoteUsersFetchedAt = fetchedAt;
  const participants=enforceSharedParticipantBase();
  persistRemoteUsersCache();
  if(participants)persistRemoteStatsCache();
  return state.remoteUsers;
}

function applyRemoteUsersCache(data){
  if(!data || !Array.isArray(data.users) || state.mockCrowdActive) return false;
  const cachedAt = String(data.fetchedAt || '');
  const cachedTime = Date.parse(cachedAt) || 0;
  const currentTime = Date.parse(state.remoteUsersFetchedAt || '') || 0;
  if((state.remoteUsers || []).length && currentTime >= cachedTime) return false;
  state.remoteUsers = normalizeRemoteUsersRows(data.users || []);
  state.remoteUsersFetchedAt = cachedAt;
  enforceSharedParticipantBase();
  return true;
}

function loadRemoteUsers(){
  try{
    const raw = localStorage.getItem(REMOTE_USERS_KEY);
    if(raw){
      const data = JSON.parse(raw);
      applyRemoteUsersCache(data);
      removeLegacyRemoteCache(REMOTE_USERS_KEY);
      queueRemoteCacheSave(REMOTE_USERS_DB_RECORD, data);
    }
  }catch(error){
    console.warn('legacy remote users cache load failed', error);
    removeLegacyRemoteCache(REMOTE_USERS_KEY);
  }

  remoteCacheDbGet(REMOTE_USERS_DB_RECORD)
    .then(data => {
      if(applyRemoteUsersCache(data)){
        fujiyaSchedulePassiveRefresh('共有ユーザーキャッシュ反映',650);
      }
    })
    .catch(error => console.warn('remote users cache load skipped', error));
}

function remoteUsersSummary(){
  const rows = state.remoteUsers || [];
  return {
    count: rows.length,
    active: rows.filter(u => Number(u.record_count || 0) > 0).length,
    fetched: state.remoteUsersFetchedAt ? fmt(state.remoteUsersFetchedAt) : ''
  };
}

function sharedUsersHtml(limit=6){
  const s = remoteUsersSummary();
  if(!s.count){
    return '<div class="shared-empty">共有データ取得後、参加人数だけ表示します。ユーザー名は表示しません。</div>';
  }

  return `
    <div class="privacy-summary">
      参加ユーザー <strong>${s.count}</strong> 人<br>
      データありユーザー ${s.active} 人
      <div class="privacy-note">プライバシー保護のため、表示名・ユーザーID一覧は画面に出しません。</div>
    </div>
  `;
}

function remoteStatFor(entry){
  if(!entry || !entry.sharedTitleId) return null;
  return state.remoteStats[entry.sharedTitleId] || null;
}

function remoteWishlistCountSupported(){
  return Object.values(state.remoteStats || {}).some(stat => stat && stat.want_count_has_field === true);
}

function remoteWishlistDemandInfo(sharedTitleId){
  const id = String(sharedTitleId || '').trim();
  const stat = id ? (state.remoteStats[id] || null) : null;
  if(stat && stat.want_count_has_field === true){
    return {available:true, count:Math.max(0, Number(stat.want_count || 0) || 0)};
  }
  // 新GASの集計を取得済みで、そのタイトル自体に行がない場合は0人。
  if(id && state.remoteStatsFetchedAt && remoteWishlistCountSupported() && !stat){
    return {available:true, count:0};
  }
  return {available:false, count:0};
}

function formatRatePercent(value){
  const n = Number(value || 0);
  if(!Number.isFinite(n)) return '—';
  return Math.round(n * 100) + '%';
}

let remoteRarityRankCache = {statsRef:null, byId:new Map(), platformCounts:{}};

function rarityPlatformForStat(stat){
  const direct = String(stat?.platform || '').trim();
  if(direct) return direct;
  const id = String(stat?.shared_title_id || '').trim();
  const dash = id.indexOf('-');
  return dash > 0 ? id.slice(0, dash) : 'その他';
}

function buildRemoteRarityRankCache(){
  const stats = state.remoteStats || {};
  if(remoteRarityRankCache.statsRef === stats) return remoteRarityRankCache;

  const pools = {};
  Object.values(stats).forEach(stat => {
    const id = String(stat?.shared_title_id || '').trim();
    if(!id) return;
    const platform = rarityPlatformForStat(stat);
    if(!pools[platform]) pools[platform] = [];
    pools[platform].push(stat);
  });

  const byId = new Map();
  const platformCounts = {};
  Object.entries(pools).forEach(([platform, rows]) => {
    rows.sort((a,b) => {
      const ar = Number.isFinite(Number(a.owned_rate)) ? Number(a.owned_rate) : 1;
      const br = Number.isFinite(Number(b.owned_rate)) ? Number(b.owned_rate) : 1;
      const ac = Math.max(0, Number(a.owned_count || 0));
      const bc = Math.max(0, Number(b.owned_count || 0));
      return ar - br || ac - bc || String(a.shared_title_id || '').localeCompare(String(b.shared_title_id || ''), 'ja');
    });

    const total = rows.length;
    const rareCount = Math.floor(total * 0.08);
    const ultraCount = Math.min(rareCount, Math.floor(total * 0.03));
    platformCounts[platform] = {total, rareCount, ultraCount};

    rows.forEach((row, index) => {
      const id = String(row.shared_title_id || '').trim();
      byId.set(id, {
        platform,
        rank:index + 1,
        total,
        rareCount,
        ultraCount,
        percentile:total ? (index + 1) / total : 1
      });
    });
  });

  remoteRarityRankCache = {statsRef:stats, byId, platformCounts};
  return remoteRarityRankCache;
}

function rarityRankForStat(stat){
  const id = String(stat?.shared_title_id || '').trim();
  if(!id) return null;
  return buildRemoteRarityRankCache().byId.get(id) || null;
}

function platformCollectorBaseForStat(stat){
  if(!stat) return 0;
  const reported = Math.max(0, Number(stat.platform_users_total || stat.platform_collector_count || 0) || 0);
  if(reported > 0) return reported;

  // 現行の共有APIは「その機種を1本以上持つ distinct users」を返していない。
  // そこで、同機種で最も所持者が多いタイトルの owned_count を
  // 「機種コレクター人数の最低保証値」として使う。
  // 実際の機種コレクター数はこの値以上なので、この母数で3%未満なら
  // 本当の機種内所持率も必ず3%未満。マイナー機種の誤レア化を避ける保守判定。
  const platform = rarityPlatformForStat(stat);
  let floor = 0;
  Object.values(state.remoteStats || {}).forEach(row => {
    if(rarityPlatformForStat(row) !== platform) return;
    floor = Math.max(floor, Math.max(0, Number(row?.owned_count || 0) || 0));
  });
  return floor;
}

function rareInfoFromStat(stat){
  if(!stat) return null;
  const owned = Math.max(0, Number(stat.owned_count || 0) || 0);
  if(owned < 1) return null;

  const collectors = platformCollectorBaseForStat(stat);
  if(collectors < 50) return null;

  const platformRateUpper = owned / collectors;
  if(!(platformRateUpper < 0.03)) return null;

  const platform = rarityPlatformForStat(stat);
  const pct = Math.max(0, Math.round(platformRateUpper * 1000) / 10);
  return {
    level:'ultra',
    label:'激レア',
    text:`${platform}内所持率${pct}%以下（所持${owned}人 / 機種コレクター${collectors}人以上）`,
    burst:true,
    rank:null,
    platformCollectors:collectors,
    platformRateUpper
  };
}

function remoteRaritySummary(){
  const result = {pending:0, rare:0, ultra:0, total:0};
  Object.values(state.remoteStats || {}).forEach(stat => {
    const info = rareInfoFromStat(stat);
    if(!info) return;
    result.total += 1;
    if(info.level === 'pending') result.pending += 1;
    else if(info.level === 'ultra') result.ultra += 1;
    else result.rare += 1;
  });
  return result;
}

function rareInfoForEntry(entry){
  return rareInfoFromStat(remoteStatFor(entry));
}

function rareInfoForDexMaster(master, entry){
  const sharedTitleId = (entry && entry.sharedTitleId) || (master && master.sharedTitleId) || '';
  const stat = sharedTitleId ? (state.remoteStats[sharedTitleId] || null) : null;
  if(stat) return rareInfoFromStat(stat);

  // 集計行がないタイトルは「未観測」。所持0人と推測せず、レア判定の母数にも入れない。
  return null;
}

function rareBadgeHtmlFromInfo(info){
  if(!info) return '';
  const cls = info.level === 'ultra'
    ? 'rare-badge ultra'
    : (info.level === 'pending' ? 'rare-badge pending' : 'rare-badge');
  return `<span class="pill ${cls}">${esc(info.label)}</span>`;
}

function rareBadgePill(entry){
  const info = rareInfoForEntry(entry);
  if(!info || !info.burst) return '';
  const cls = info.level === 'ultra'
    ? 'rare-badge ultra'
    : (info.level === 'pending' ? 'rare-badge pending' : 'rare-badge');
  const icon = info.level === 'pending' ? '🔎' : '💎';
  return `<span class="pill ${cls}">${icon} ${esc(info.label)}：${esc(info.text)}</span>`;
}

function rareEventLine(entry){
  const info = rareInfoForEntry(entry);
  if(!info) return '';
  const prefix = '激レアタイトル認定！';
  return `${prefix}「${entry.title}」は${info.text}の条件に入っています。`;
}

function rankSettingsLabel(){
  const platform = state.rankPlatform || '全機種';
  const dir = state.rankDirection === 'asc' ? '昇順' : '降順';
  return `${platform} / ${dir}`;
}

function loadRankSettings(){
  try{
    const raw = localStorage.getItem(RANK_SETTINGS_KEY);
    if(!raw) return;
    const data = JSON.parse(raw);
    state.rankPlatform = platforms.includes(data.rankPlatform) ? data.rankPlatform : '';
    state.rankDirection = data.rankDirection === 'asc' ? 'asc' : 'desc';
  }catch(e){}
}

function saveRankSettings(){
  localStorage.setItem(RANK_SETTINGS_KEY, JSON.stringify({
    rankPlatform: state.rankPlatform || '',
    rankDirection: state.rankDirection === 'asc' ? 'asc' : 'desc'
  }));
}

function updateRankControls(){
  const p = $('rankPlatformSelect');
  const d = $('rankDirectionSelect');
  const n = $('rankFilterNote');
  if(p) p.value = state.rankPlatform || '';
  if(d) d.value = state.rankDirection || 'desc';
  if(n) n.textContent = rankSettingsLabel();
}

function setRankPlatform(value){
  state.rankPlatform = platforms.includes(value) ? value : '';
  saveRankSettings();
  render();
}

function setRankDirection(value){
  state.rankDirection = value === 'asc' ? 'asc' : 'desc';
  saveRankSettings();
  render();
}

function applyRankDirection(rows){
  if(state.rankDirection === 'asc') return [...rows].reverse();
  return rows;
}

function filterRankRows(rows){
  const platform = state.rankPlatform || '';
  return platform ? rows.filter(r => r.platform === platform) : rows;
}


function remoteStatsSummary(){
  const rows = Object.values(state.remoteStats || {});
  const fetched = state.remoteStatsFetchedAt ? fmt(state.remoteStatsFetchedAt) : '';
  const ratingRows = rows.filter(r => Number(r.rating_count) > 0);
  const priceRows = rows.filter(r => Number(r.purchase_rom_only_count || 0) >= 1 || Number(r.purchase_complete_count || 0) >= 1);
  const pricePendingRows = rows.filter(r => (
    (Number(r.purchase_rom_only_count || 0) > 0 && Number(r.purchase_rom_only_count || 0) < 3) ||
    (Number(r.purchase_complete_count || 0) > 0 && Number(r.purchase_complete_count || 0) < 3)
  ));
  const priceRomRows = rows.filter(r => Number(r.purchase_rom_only_count || 0) >= 1);
  const priceCompleteRows = rows.filter(r => Number(r.purchase_complete_count || 0) >= 1);
  const priceColumns = rows.some(r => !!r.purchase_price_has_field);
  const avg = ratingRows.length
    ? ratingRows.reduce((sum, r) => sum + Number(r.rating_avg || 0), 0) / ratingRows.length
    : 0;

  return {
    count: rows.length,
    fetched,
    ratingRows: ratingRows.length,
    priceRows: priceRows.length,
    pricePendingRows: pricePendingRows.length,
    priceRomRows: priceRomRows.length,
    priceCompleteRows: priceCompleteRows.length,
    priceColumns,
    avg
  };
}

function renderStatsFetchStatus(){
  const box = $('statsFetchStatus');
  if(!box) return;
  const s = remoteStatsSummary();

  if(!s.count){
    box.textContent = '共有データ：未取得';
    return;
  }

  const priceText = s.priceColumns
    ? `価格登録あり：${s.priceRows}件（ROMのみ${s.priceRomRows} / 完品${s.priceCompleteRows}） / 参考値：${s.pricePendingRows}件`
    : '価格登録：未共有';
  box.textContent = `${state.mockCrowdActive ? 'テスト水増し' : '共有データ'}：${s.count}件取得済み / 平均レートあり：${s.ratingRows}件 / ${priceText} / 参加ユーザー：${remoteUsersSummary().count}人 / 取得日：${s.fetched || '—'}`;
}

function sharedPurchaseCategoryText(stat, category){
  if(!stat) return '登録なし';
  if(!stat.purchase_price_has_field) return noConditionPriceText(stat).main;
  const key = category === 'complete' ? 'purchase_complete' : 'purchase_rom_only';
  const count = Number(stat[`${key}_count`] || 0) || 0;
  if(count < 1) return '登録なし';
  if(!purchasePriceValueReady(stat, key)) return '共有データ再取得';
  const median = yen0(purchaseMedianValue(stat, key)) || '—';
  return `${median} / ${purchasePriceMetaText(stat, key, count)}`;
}

function sharedPurchasePriceText(stat){
  if(!stat) return '登録なし';
  if(!stat.purchase_price_has_field) return noConditionPriceText(stat).main;
  return `ROMのみ：${sharedPurchaseCategoryText(stat, 'rom_only')} / 完品：${sharedPurchaseCategoryText(stat, 'complete')}`;
}

function sharedPurchaseCategoryHtml(stat, category, compact=false){
  if(!stat) return '';
  const label = purchaseConditionLabel(category);
  const key = category === 'complete' ? 'purchase_complete' : 'purchase_rom_only';
  const count = Number(stat[`${key}_count`] || 0) || 0;

  if(!stat.purchase_price_has_field){
    const info = noConditionPriceText(stat);
    return compact ? '' : `<span class="pill remote-pill price warn">${label}：${esc(info.main)}</span>`;
  }
  if(count < 1){
    return compact
      ? `<span class="shared-price pending">${label} 登録なし</span>`
      : `<span class="pill remote-pill price warn">${label}：登録なし</span>`;
  }
  if(!purchasePriceValueReady(stat, key)){
    return compact
      ? `<span class="shared-price pending">${label} 再取得待ち</span>`
      : `<span class="pill remote-pill price warn">${label}：共有データ再取得</span>`;
  }

  const median = yen0(purchaseMedianValue(stat, key)) || '—';
  const meta = purchasePriceMetaText(stat, key, count);
  const cls = count < 3 ? 'reference' : 'strong';
  return compact
    ? `<span class="shared-price ${cls}">${label} ${esc(median)} / ${esc(meta)}</span>`
    : `<span class="pill remote-pill price">${label} ${esc(median)} / ${esc(meta)}</span>`;
}

function sharedPurchasePriceHtml(stat, compact=false){
  if(!stat) return '';
  const rom = sharedPurchaseCategoryHtml(stat, 'rom_only', compact);
  const complete = sharedPurchaseCategoryHtml(stat, 'complete', compact);
  return [rom, complete].filter(Boolean).join(compact ? '' : '');
}

function sharedPurchaseReadableLine(stat, category){
  const label = purchaseConditionLabel(category);
  const key = category === 'complete' ? 'purchase_complete' : 'purchase_rom_only';

  if(!stat){
    return `<div class="shared-price-readable-line pending"><span class="price-label">${label}</span><strong class="price-status">登録なし</strong><small>0件</small></div>`;
  }
  if(!stat.purchase_price_has_field){
    const info = noConditionPriceText(stat);
    return `<div class="shared-price-readable-line muted"><span class="price-label">${label}</span><strong class="price-status">${esc(info.main)}</strong><small>${esc(info.sub)}</small></div>`;
  }

  const count = Number(stat[`${key}_count`] || 0) || 0;
  if(count < 1){
    return `<div class="shared-price-readable-line pending"><span class="price-label">${label}</span><strong class="price-status">登録なし</strong><small>0件</small></div>`;
  }
  if(!purchasePriceValueReady(stat, key)){
    return `<div class="shared-price-readable-line pending"><span class="price-label">${label}</span><strong class="price-status">再取得待ち</strong><small>共有データを再取得してください</small></div>`;
  }

  const median = yen0(purchaseMedianValue(stat, key)) || '—';
  const cls = count < 3 ? 'reference' : 'ready';
  return `<div class="shared-price-readable-line ${cls}"><span class="price-label">${label}</span><strong class="price-status">${esc(median)}</strong><small>${esc(purchasePriceMetaText(stat, key, count))}</small></div>`;
}

function sharedPurchaseReadableBlock(stat, options={}){
  if(!stat && options.hideWhenEmpty) return '';
  if(stat && !stat.purchase_price_has_field && options.hideWhenEmpty) return '';
  return `<div class="shared-price-readable ${options.compact ? 'compact' : ''}">
    <div class="shared-price-readable-title">共有平均購入額（中央値）</div>
    ${sharedPurchaseReadableLine(stat, 'rom_only')}
    ${sharedPurchaseReadableLine(stat, 'complete')}
  </div>`;
}

function sharedPurchaseReadableBlockForEntry(entry, options={}){
  const stat = remoteStatFor(entry);
  if(!stat && options.hideWhenEmpty) return '';
  return sharedPurchaseReadableBlock(stat, options);
}

function dexSharedPurchaseCategoryLine(stat, category){
  const label = purchaseConditionLabel(category);
  const key = category === 'complete' ? 'purchase_complete' : 'purchase_rom_only';
  if(!stat) return `<div class="dex-price-line pending"><span class="price-label">${label}</span><strong class="price-status">登録なし</strong><small>0件</small></div>`;
  if(!stat.purchase_price_has_field){
    const info = noConditionPriceText(stat);
    return `<div class="dex-price-line empty"><span class="price-label">${label}</span><strong class="price-status">${esc(info.main)}</strong><small>${esc(info.sub)}</small></div>`;
  }

  const count = Number(stat[`${key}_count`] || 0) || 0;
  if(count < 1) return `<div class="dex-price-line pending"><span class="price-label">${label}</span><strong class="price-status">登録なし</strong><small>0件</small></div>`;
  if(!purchasePriceValueReady(stat, key)) return `<div class="dex-price-line pending"><span class="price-label">${label}</span><strong class="price-status">再取得待ち</strong><small>共有データを再取得してください</small></div>`;

  const median = yen0(purchaseMedianValue(stat, key)) || '—';
  const cls = count < 3 ? 'reference' : 'ready';
  return `<div class="dex-price-line ${cls}"><span class="price-label">${label}</span><strong class="price-status">${esc(median)}</strong><small>${esc(purchasePriceMetaText(stat, key, count))}</small></div>`;
}

function dexSharedPurchasePriceBlock(master, entry){
  const sharedTitleId = (entry && entry.sharedTitleId) || (master && master.sharedTitleId) || '';
  const stat = sharedTitleId ? (state.remoteStats[sharedTitleId] || null) : null;
  if(!sharedTitleId) return '';
  if(!state.remoteStatsFetchedAt && !stat) return '';

  return `<div class="dex-price-card split">
    <div class="dex-price-label">共有平均購入額（中央値）</div>
    ${dexSharedPurchaseCategoryLine(stat, 'rom_only')}
    ${dexSharedPurchaseCategoryLine(stat, 'complete')}
  </div>`;
}

function remotePills(entry){
  const stat = remoteStatFor(entry);
  if(!entry.sharedTitleId){
    return '<span class="pill remote-pill warn">共有所持率：未確定</span>';
  }
  if(!stat){
    return '<span class="pill remote-pill warn">共有所持率：未取得</span>';
  }

  const parts = [
    rareBadgePill(entry),
    `<span class="pill remote-pill">共有所持率：${formatRatePercent(stat.owned_rate)}</span>`
  ].filter(Boolean);

  if(stat.rating_count){
    parts.push(`<span class="pill remote-pill avg">平均レート：${Number(stat.rating_avg || 0).toFixed(2)} / 評価${stat.rating_count}</span>`);
  }else{
    parts.push('<span class="pill remote-pill warn">平均レート：未評価</span>');
  }

  if(stat.users_total){
    parts.push(`<span class="pill remote-pill">参加${stat.users_total}</span>`);
  }

  return parts.join('');
}


function extractSpreadsheetId(value){
  const raw = String(value || '').trim();
  if(!raw) return '';
  const urlMatch = raw.match(/\/spreadsheets\/d\/([a-zA-Z0-9_-]+)/);
  if(urlMatch) return urlMatch[1];
  const idMatch = raw.match(/^([a-zA-Z0-9_-]{20,})$/);
  return idMatch ? idMatch[1] : '';
}

function getSheetSourceSettings(){
  let saved = {};
  try{
    saved = JSON.parse(localStorage.getItem(SHEET_SOURCE_KEY) || '{}') || {};
  }catch(e){
    saved = {};
  }

  const defaultId = DEFAULT_SHEET_SOURCE_ID || '';
  return {
    spreadsheetId: String(saved.spreadsheetId || defaultId || '').trim(),
    rawInput: String(saved.rawInput || saved.spreadsheetId || defaultId || '').trim(),
    statsSheetName: String(saved.statsSheetName || DEFAULT_STATS_SHEET_NAME).trim() || DEFAULT_STATS_SHEET_NAME,
    usersSheetName: String(saved.usersSheetName || DEFAULT_USERS_SHEET_NAME).trim() || DEFAULT_USERS_SHEET_NAME
  };
}

function saveSheetSourceSettings(settings){
  const clean = {
    spreadsheetId: String(settings.spreadsheetId || '').trim(),
    rawInput: String(settings.rawInput || '').trim(),
    statsSheetName: String(settings.statsSheetName || DEFAULT_STATS_SHEET_NAME).trim() || DEFAULT_STATS_SHEET_NAME,
    usersSheetName: String(settings.usersSheetName || DEFAULT_USERS_SHEET_NAME).trim() || DEFAULT_USERS_SHEET_NAME
  };
  if(clean.spreadsheetId){
    localStorage.setItem(SHEET_SOURCE_KEY, JSON.stringify(clean));
  }else{
    localStorage.removeItem(SHEET_SOURCE_KEY);
  }
  renderSheetDirectStatus();
  renderGasStatus();
  scheduleAutoReceive('共有元設定保存後', 1000, true);
}

function saveSheetSourceFromForm(){
  const raw = $('sheetSourceInput')?.value || '';
  const spreadsheetId = extractSpreadsheetId(raw);
  const statsSheetName = $('statsSheetNameInput')?.value || DEFAULT_STATS_SHEET_NAME;
  const usersSheetName = $('usersSheetNameInput')?.value || DEFAULT_USERS_SHEET_NAME;

  if(!spreadsheetId){
    toast('スプレッドシートURL/IDを確認してください');
    showMikeTalk('スプレッドシートURLかIDをうまく読み取れなかったよ。\n\nURLは docs.google.com/spreadsheets/d/〇〇/edit の形を貼ってね。');
    return;
  }

  saveSheetSourceSettings({spreadsheetId, rawInput: raw, statsSheetName, usersSheetName});
  toast('シート設定を保存しました');
  showMikeTalk(`シート設定を保存したよ！\n所持率シート：${statsSheetName || DEFAULT_STATS_SHEET_NAME}\n参加人数シート：${usersSheetName || DEFAULT_USERS_SHEET_NAME}\n\n次は「共有元読取テスト」か「共有データ受信」を試してね。`);
}


function getAutoReceiveEnabled(){
  // 受信は公開シートを読むだけなので初期値ON。
  return localStorage.getItem(AUTO_RECEIVE_KEY) !== '0';
}

function setAutoReceiveEnabled(value){
  const on = !!value;
  if(on) localStorage.removeItem(AUTO_RECEIVE_KEY);
  else localStorage.setItem(AUTO_RECEIVE_KEY, '0');
  renderAutoReceiveStatus();
  if(on) scheduleAutoReceive('自動受信ON', 800, true);
}

function autoReceiveLastText(){
  const last = localStorage.getItem(AUTO_RECEIVE_LAST_KEY) || '';
  return last ? fmt(last) : '未受信';
}

function renderAutoReceiveStatus(extra=''){
  const toggle = $('autoReceiveToggle');
  const box = $('autoReceiveStatus');
  if(toggle) toggle.checked = getAutoReceiveEnabled();
  if(!box) return;

  const settings = getSheetSourceSettings();
  const s = remoteStatsSummary();
  const on = getAutoReceiveEnabled();
  const base = on
    ? `自動受信：ON / 取得済み：${s.count}件 / 最終受信：${autoReceiveLastText()}`
    : `自動受信：OFF / 取得済み：${s.count}件 / 最終受信：${autoReceiveLastText()}`;
  const source = settings.spreadsheetId ? '' : ' / 共有元未設定';
  box.textContent = extra ? `${base}${source} / ${extra}` : `${base}${source}`;
  box.classList.toggle('ready', on && !!settings.spreadsheetId);
  box.classList.toggle('warn', !on || !settings.spreadsheetId);
}

function saveAutoReceiveFromForm(){
  const on = !!$('autoReceiveToggle')?.checked;
  setAutoReceiveEnabled(on);
  toast(on ? '自動受信をONにしました' : '自動受信をOFFにしました');
  showMikeTalk(on
    ? '共有データの自動受信をONにしたよ！\n\n起動時・送信後・画面を開いている間の定期更新で、共有所持率と平均レートを更新するよ。'
    : '共有データの自動受信をOFFにしたよ。\n\n必要な時は「今すぐ受信更新」か「共有データ受信」を押してね。'
  );
}

function scheduleAutoReceive(reason='自動受信', delayMs=2500, force=false){
  if(!getAutoReceiveEnabled()){
    renderAutoReceiveStatus();
    return;
  }

  if(!getSheetSourceSettings().spreadsheetId){
    renderAutoReceiveStatus('シート設定待ち');
    return;
  }

  clearTimeout(autoReceiveTimer);
  renderAutoReceiveStatus('受信予約中');
  autoReceiveTimer = setTimeout(() => {
    if(window.__fujiyaStartupMaintenanceActive||deviceSharedIdentityPromise||deviceAutoSyncBusy||deviceSyncBusy||window.__fujiyaAutoReceiveBusy||fujiyaUiInteractionBusy()){
      scheduleAutoReceive(reason, 5000, force);
      return;
    }
    autoReceiveSharedData({silent:true, reason, force});
  }, delayMs);
}

async function autoReceiveSharedData(options={}){
  const silent = options.silent !== false;
  const force = !!options.force;
  const reason = String(options.reason || '自動受信');
  const settings = getSheetSourceSettings();

  // テスト水増し中は、バックグラウンド自動受信で表示を上書きしない。
  // 「今すぐ受信更新」など force=true の手動操作では本番データへ切り替える。
  if(state.mockCrowdActive && !force){
    renderAutoReceiveStatus('テスト水増し中');
    return true;
  }

  if(!getAutoReceiveEnabled() && !force){
    renderAutoReceiveStatus();
    return false;
  }

  if(!settings.spreadsheetId){
    renderAutoReceiveStatus('共有元未設定');
    if(!silent){
      toast('シート設定が未設定です');
      showMikeTalk('共有データを受信するには、まず共有取得用スプレッドシートURL/IDを保存してね。');
    }
    return false;
  }

  const last = Date.parse(localStorage.getItem(AUTO_RECEIVE_LAST_KEY) || '');
  const now = Date.now();
  const minIntervalMs = 20 * 60 * 1000;
  if(!force && Number.isFinite(last) && now - last < minIntervalMs){
    renderAutoReceiveStatus('最近更新済み');
    return true;
  }
  if(window.__fujiyaAutoReceiveBusy){
    renderAutoReceiveStatus('ほかの受信処理を待機中');
    return false;
  }
  window.__fujiyaAutoReceiveBusy=true;
  const backgroundQuiet = silent && !force;
  if(backgroundQuiet) window.__fujiyaBackgroundSyncQuiet=(Number(window.__fujiyaBackgroundSyncQuiet)||0)+1;

  const processingToken = !silent
    ? (window.fujiyaProcessing?.start({
        title:'共有データを受信しています',
        detail:'共有所持率・評価・参加ユーザーを更新しています。',
        progressText:'共有DB受信中'
      }) || '')
    : '';
  if(processingToken) await window.fujiyaProcessing?.paint?.();

  renderAutoReceiveStatus('受信中…');
  try{
    const [statsRows,usersRows] = await Promise.all([
      fetchGvizSheet(settings.statsSheetName, {timeoutMs:24000}),
      fetchGvizSheet(settings.usersSheetName, {timeoutMs:24000})
    ]);

    await saveRemoteStatsAsync(statsRows || [], processingToken);
    saveRemoteUsers(usersRows || []);
    localStorage.setItem(AUTO_RECEIVE_LAST_KEY, nowIso());
    localStorage.setItem(AUTO_RECEIVE_LAST_KEY, nowIso());
    localStorage.removeItem(MOCK_CROWD_KEY);
    state.mockCrowdActive = false;
    state.mockCrowdCount = 0;
    const rareLogAdded = syncRareLogsFromCurrentEntries(`${reason}でレア判定`);
    if(silent&&!force)fujiyaSchedulePassiveRefresh(reason,900);else render();
    renderAutoReceiveStatus(`${reason}完了`);

    if(!silent){
      toast('共有データを受信更新しました');
      const s = remoteStatsSummary();
      showMikeTalk(`受信更新OKだよ！\n取得件数：${s.count}件\n平均レートあり：${s.ratingRows}件\n参加ユーザー：${remoteUsersSummary().count}人\nレアログ追加：${rareLogAdded}件`);
    }
    return true;
  }catch(e){
    const msg = String(e && e.message ? e.message : e);
    renderAutoReceiveStatus('受信エラー');
    if(!silent){
      toast('受信更新に失敗しました');
      showMikeTalk(`受信更新NGだよ。\n\nエラー内容：${msg}\n\nシート共有設定・シート名・URL/IDを確認してね。`);
    }else{
      console.warn('auto receive failed:', msg);
    }
    return false;
  }finally{
    window.__fujiyaAutoReceiveBusy=false;
    if(backgroundQuiet) window.__fujiyaBackgroundSyncQuiet=Math.max(0,(Number(window.__fujiyaBackgroundSyncQuiet)||1)-1);
    window.fujiyaProcessing?.end(processingToken);
  }
}

function startAutoReceiveLoop(){
  // 開いている間だけ30分ごとに確認。20分以内の重複取得は自動でスキップ。
  setInterval(() => scheduleAutoReceive('定期受信', 500, false), 30 * 60 * 1000);
}

function renderSheetDirectStatus(){
  const settings = getSheetSourceSettings();
  const sourceInput = $('sheetSourceInput');
  const statsInput = $('statsSheetNameInput');
  const usersInput = $('usersSheetNameInput');
  const box = $('sheetDirectStatus');

  if(sourceInput) sourceInput.value = settings.rawInput || settings.spreadsheetId || '';
  if(statsInput) statsInput.value = settings.statsSheetName;
  if(usersInput) usersInput.value = settings.usersSheetName;
  if(!box) return;

  if(!settings.spreadsheetId){
    box.textContent = '共有データ受信：未設定。共有元スプレッドシートURL/IDを保存してください。';
    box.classList.remove('ready');
    box.classList.add('warn');
    renderAutoReceiveStatus();
    return;
  }

  const s = remoteStatsSummary();
  box.textContent = `共有データ受信：設定済み / title_stats=${settings.statsSheetName} / users=${settings.usersSheetName} / 取得済み=${s.count}件`;
  box.classList.remove('warn');
  box.classList.add('ready');
  renderAutoReceiveStatus();
}

function buildGvizUrl(sheetName, callbackName, query=''){
  const settings = getSheetSourceSettings();
  if(!settings.spreadsheetId) return '';
  const tqx = 'out:json;responseHandler:' + callbackName;
  const params = [
    'headers=1',
    'sheet=' + encodeURIComponent(sheetName),
    'tqx=' + encodeURIComponent(tqx),
    't=' + Date.now()
  ];
  if(query) params.push('tq=' + encodeURIComponent(query));
  return `https://docs.google.com/spreadsheets/d/${encodeURIComponent(settings.spreadsheetId)}/gviz/tq?${params.join('&')}`;
}

function ensureGvizFallbackHandler(resolveIfCurrent){
  window.google = window.google || {};
  window.google.visualization = window.google.visualization || {};
  window.google.visualization.Query = window.google.visualization.Query || {};
  window.__fujiyaCurrentGvizHandler = resolveIfCurrent;
  window.google.visualization.Query.setResponse = response => {
    if(typeof window.__fujiyaCurrentGvizHandler === 'function'){
      window.__fujiyaCurrentGvizHandler(response);
    }
  };
}

function fetchGvizSheet(sheetName, options={}){
  const timeoutMs = Number(options.timeoutMs || 22000);
  const query = options.query || '';
  const settings = getSheetSourceSettings();

  if(!settings.spreadsheetId){
    return Promise.reject(new Error('スプレッドシートURL/IDが未設定です'));
  }

  return new Promise((resolve, reject) => {
    const callbackName = '__fujiyaGviz_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2,7);
    const script = document.createElement('script');
    let settled = false;

    const timer = setTimeout(() => {
      cleanup();
      reject(new Error('シート読み取りがタイムアウトしました。スプレッドシートの共有設定とシート名を確認してください。'));
    }, timeoutMs);

    function cleanup(){
      if(settled) return;
      settled = true;
      clearTimeout(timer);
      window.fujiyaKeepLateJsonpCallback_(callbackName);
      if(window.__fujiyaCurrentGvizHandler === handleResponse) window.__fujiyaCurrentGvizHandler = null;
      script.remove();
    }

    function handleResponse(response){
      cleanup();
      if(!response){
        reject(new Error('Googleシートから空の応答が返りました'));
        return;
      }

      if(response.status && response.status !== 'ok'){
        const errors = (response.errors || []).map(e => e.detailed_message || e.message || e.reason).filter(Boolean).join(' / ');
        reject(new Error(errors || `Googleシート応答ステータス：${response.status}`));
        return;
      }

      try{
        resolve(gvizTableToObjects(response.table || {}));
      }catch(e){
        reject(e);
      }
    }

    window[callbackName] = handleResponse;
    ensureGvizFallbackHandler(handleResponse);

    script.onerror = () => {
      cleanup();
      reject(new Error('シートURLをscriptとして読み込めませんでした。共有設定・URL/ID・シート名を確認してください。'));
    };

    script.src = buildGvizUrl(sheetName, callbackName, query);
    document.body.appendChild(script);
  });
}

function normalizeGvizHeader(value, index){
  let key = String(value || '').trim();
  if(!key) key = 'col' + (index + 1);
  key = key.replace(/[Ａ-Ｚａ-ｚ０-９＿]/g, ch => String.fromCharCode(ch.charCodeAt(0) - 0xFEE0));
  key = key.toLowerCase().replace(/\s+/g, '_');
  return key;
}

function gvizCellValue(cell){
  if(!cell) return '';
  const value = cell.v;
  if(value === null || value === undefined) return cell.f || '';
  if(value instanceof Date) return value.toISOString();
  if(typeof value === 'object' && value !== null){
    if(value.toString && value.toString !== Object.prototype.toString) return String(value);
    return cell.f || JSON.stringify(value);
  }
  return value;
}

function gvizTableToObjects(table){
  const cols = (table.cols || []).map((c, i) => normalizeGvizHeader(c.label || c.id || '', i));
  const rows = (table.rows || []).map(row => {
    const obj = {};
    const cells = row.c || [];
    cols.forEach((key, i) => {
      obj[key] = gvizCellValue(cells[i]);
    });
    return obj;
  });

  // 念のため、headers=1が効かず1行目にヘッダーが混ざった時だけ除外。
  if(rows.length && String(rows[0].shared_title_id || '').trim().toLowerCase() === 'shared_title_id'){
    rows.shift();
  }
  return rows;
}

