function buildGasUrl(params={}){
  const url = getGasEndpoint();
  if(!url) return '';
  const sep = url.includes('?') ? '&' : '?';
  const query = Object.entries(params)
    .filter(([,v]) => v !== undefined && v !== null && v !== '')
    .map(([k,v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`)
    .join('&');
  return query ? `${url}${sep}${query}` : url;
}

function gasStatsDirectUrl(){
  return buildGasUrl({action:'stats', t:Date.now()});
}

function gasTestDirectUrl(){
  return buildGasUrl({action:'test', t:Date.now()});
}

function gasStatsJsonpUrl(callbackName){
  return buildGasUrl({action:'stats', callback:callbackName, t:Date.now()});
}

function gasTestJsonpUrl(callbackName){
  return buildGasUrl({action:'test', callback:callbackName, t:Date.now()});
}

function fetchGasStatsJsonp(options={}){
  const url = String(options.endpoint || getGasEndpoint() || '').trim();
  const timeoutMs = Number(options.timeoutMs || 22000);

  if(!url){
    toast('共有同期URLを設定してください');
    showMikeTalk('共有データを取得するには、まず共有同期URLを保存してね。');
    return Promise.reject(new Error('共有同期URLが未設定です'));
  }

  return new Promise((resolve, reject) => {
    const callbackName = '__fujiyaStatsCallback_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2,6);
    const script = document.createElement('script');
    let settled = false;
    const timer = setTimeout(() => {
      cleanup();
      reject(new Error('共有データ取得がタイムアウトしました。別PCだけで起きる場合は、GASのWebアプリ公開範囲が「全員」になっていない可能性が高いです。'));
    }, timeoutMs);

    function cleanup(){
      if(settled) return;
      settled = true;
      clearTimeout(timer);
      window.fujiyaKeepLateJsonpCallback_(callbackName);
      script.remove();
    }

    window[callbackName] = data => {
      cleanup();
      resolve(data);
    };

    script.onerror = () => {
      cleanup();
      reject(new Error('GASから共有データを取得できませんでした。GASの公開設定を「実行ユーザー：自分」「アクセスできるユーザー：全員」にして、新しいバージョンでデプロイしてください。'));
    };

    script.src = gasStatsJsonpUrl(callbackName);
    document.body.appendChild(script);
  });
}


