function fetchGasByPostFrame(action='stats_frame', options={}){
  const url = getGasEndpoint();
  const timeoutMs = Number(options.timeoutMs || 22000);
  if(!url) return Promise.reject(new Error('共有同期URLが未設定です'));
  if(window.__MITEKORE_LOCAL_PREVIEW__){
    return Promise.reject(new Error('ローカル確認ではPOST iframeを使用しません'));
  }

  return new Promise((resolve, reject) => {
    const requestId = 'fujiya_frame_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2,7);
    const iframeName = 'fujiyaGasFrame_' + requestId;
    let settled = false;

    const iframe = document.createElement('iframe');
    iframe.name = iframeName;
    iframe.style.position = 'fixed';
    iframe.style.left = '-9999px';
    iframe.style.top = '-9999px';
    iframe.style.width = '1px';
    iframe.style.height = '1px';
    iframe.setAttribute('aria-hidden','true');

    const form = document.createElement('form');
    form.method = 'POST';
    form.action = url;
    form.target = iframeName;
    form.style.display = 'none';

    const actionInput = document.createElement('input');
    actionInput.type = 'hidden';
    actionInput.name = 'action';
    actionInput.value = action;

    const requestInput = document.createElement('input');
    requestInput.type = 'hidden';
    requestInput.name = 'requestId';
    requestInput.value = requestId;

    form.appendChild(actionInput);
    form.appendChild(requestInput);

    const extraFields = options.fields && typeof options.fields === 'object' ? options.fields : {};
    Object.keys(extraFields).forEach(name => {
      const input = document.createElement('input');
      input.type = 'hidden';
      input.name = name;
      input.value = String(extraFields[name] ?? '');
      form.appendChild(input);
    });

    const timer = setTimeout(() => {
      cleanup();
      reject(new Error('POST応答がタイムアウトしました。公開中のGASが最新版か、必要な権限承認が完了しているか確認してください。'));
    }, timeoutMs);

    function cleanup(){
      if(settled) return;
      settled = true;
      clearTimeout(timer);
      window.removeEventListener('message', onMessage);
      setTimeout(() => {
        try{ iframe.remove(); }catch(e){}
        try{ form.remove(); }catch(e){}
      }, 0);
    }

    function onMessage(ev){
      const data = ev.data;
      if(!data || data.source !== 'fujiyaGasPostMessage') return;
      if(data.requestId !== requestId) return;
      cleanup();
      resolve(data.payload || {});
    }

    window.addEventListener('message', onMessage);
    document.body.appendChild(iframe);
    document.body.appendChild(form);

    try{
      form.submit();
    }catch(e){
      cleanup();
      reject(e);
    }
  });
}

