function getGasEndpoint(){
  const latest = String(DEFAULT_GAS_ENDPOINT || '').trim();
  try{
    if(latest && normalizeGasEndpoint(localStorage.getItem(GAS_ENDPOINT_KEY) || '') !== normalizeGasEndpoint(latest)){
      localStorage.setItem(GAS_ENDPOINT_KEY, latest);
    }
  }catch(error){}
  return latest;
}

function usingDefaultGasEndpoint(){
  return !!DEFAULT_GAS_ENDPOINT;
}

function setGasEndpoint(url){
  try{
    if(DEFAULT_GAS_ENDPOINT) localStorage.setItem(GAS_ENDPOINT_KEY, DEFAULT_GAS_ENDPOINT);
    else localStorage.removeItem(GAS_ENDPOINT_KEY);
  }catch(error){}
  renderGasStatus();
}

function buildSyncPayload(){
  const userId = getUserId();
  const list = syncableEntries();
  const sharePurchasePrice = getSharePurchasePriceOptIn();

  return {
    app: 'fujiya_collection',
    version: APP_VERSION,
    exportedAt: nowIso(),
    userId,
    purchasePriceShared: sharePurchasePrice ? 1 : 0,
    records: list.map(e => {
      const record = {
        user_id: userId,
        platform: e.platform,
        shared_title_id: e.sharedTitleId,
        title: e.canonicalTitle || e.title,
        owned: e.owned ? 1 : 0,
        // RC1.4.400: 共有所持率の内訳（完品 / 完品以外 / 未所持）を正確に集計する。
        // 購入金額共有とは独立した非金額データとして送る。
        complete_owned: e.owned ? (isCompleteEntry(e) ? 1 : 0) : 0,
        rating: ratingNumber(e.rating),
        play_status: normalizePlayStatus(e.playStatus),
        clear_hours: clearTimeShareValue(e) ?? '',
        updated_at: e.updatedAt || ''
      };
      const priceInfo = purchasePriceShareValue(e);
      if(sharePurchasePrice && priceInfo !== null){
        record.purchase_price = priceInfo.price;
        record.purchase_price_category = priceInfo.category;
      }
      return record;
    })
  };
}

function payloadText(){
  return JSON.stringify(buildSyncPayload(), null, 2);
}


function getShareOptIn(){
  const stored = localStorage.getItem(SHARE_OPT_IN_KEY);
  if(stored === '1') return true;
  if(stored === '0') return false;
  // 設定キーが見つからない時に既存ユーザーを勝手にOFFへ落とさない。
  // 正式なON/OFFは起動後にGASの個人設定から復元する。
  return true;
}

function setShareOptIn(value){
  const on = !!value;
  localStorage.setItem(SHARE_OPT_IN_KEY, on ? '1' : '0');
  renderShareSyncStatus();
  renderGasStatus();
  return on;
}

function getSharePurchasePriceOptIn(){
  const stored = localStorage.getItem(SHARE_PRICE_OPT_IN_KEY);
  if(stored === '1') return true;
  if(stored === '0') return false;
  // 設定キー欠落をOFF扱いにしない。GAS復元までは既定ON。
  return true;
}

