function waitForCollectionSyncPostMessage(requestId, timeoutMs=230000){
  return new Promise((resolve,reject)=>{
    const id=String(requestId||'');
    let settled=false;
    const timer=setTimeout(()=>finish(new Error('共有同期のPOST完了通知がタイムアウトしました')),timeoutMs);
    function finish(error,value){
      if(settled)return;
      settled=true;
      clearTimeout(timer);
      window.removeEventListener('message',onMessage);
      error?reject(error):resolve(value);
    }
    function onMessage(event){
      const message=event.data;
      if(!message||message.source!=='fujiyaGasPostMessage'||String(message.requestId||'')!==id)return;
      const payload=message.payload||{};
      if(payload.action!=='collection_sync_status')return;
      const status=String(payload.status||'').toLowerCase();
      if(status==='completed'&&payload.ok===true){finish(null,payload);return;}
      if(status==='error'||(payload.ok===false&&payload.pending===false))finish(new Error(payload.message||'共有同期に失敗しました'));
    }
    window.addEventListener('message',onMessage);
  });
}
function firstSuccessfulPromise(promises){
  return new Promise((resolve,reject)=>{
    const list=(Array.isArray(promises)?promises:[]).map(value=>Promise.resolve(value));
    if(!list.length){reject(new Error('確認処理がありません'));return;}
    let pending=list.length;
    const errors=[];
    list.forEach((promise,index)=>promise.then(resolve,error=>{
      errors[index]=error;
      pending--;
      if(pending===0)reject(errors.find(Boolean)||new Error('共有同期の完了を確認できませんでした'));
    }));
  });
}

function fetchCollectionSyncStatusJsonpRequest(endpoint, requestId, timeoutMs=20000){
  return new Promise((resolve,reject) => {
    const cleanEndpoint = String(endpoint || '').trim();
    if(!cleanEndpoint){ reject(new Error('共有同期URLが未設定です')); return; }
    const callback = `fujiyaCollectionSyncStatus_${Date.now()}_${Math.random().toString(36).slice(2)}`;
    let settled = false;
    const timer = setTimeout(() => {
      cleanup();
      reject(new Error('共有同期状況の確認がタイムアウトしました'));
    }, timeoutMs);

    function cleanup(){
      if(settled) return;
      settled = true;
      clearTimeout(timer);
      window.fujiyaKeepLateJsonpCallback_(callback);
      document.getElementById(callback)?.remove();
    }

    window[callback] = data => {
      cleanup();
      if(data && data.action === 'collection_sync_status') resolve(data);
      else reject(new Error(data?.message || '共有同期状況の応答形式が正しくありません'));
    };

    const script = document.createElement('script');
    script.id = callback;
    script.onerror = () => {
      cleanup();
      reject(new Error('共有同期状況の確認先へ接続できませんでした'));
    };
    const sep = cleanEndpoint.includes('?') ? '&' : '?';
    const params = new URLSearchParams({
      action:'collection_sync_status',
      requestId,
      callback,
      _:String(Date.now())
    });
    script.src = `${cleanEndpoint}${sep}${params.toString()}`;
    document.body.appendChild(script);
  });
}

async function waitForCollectionSyncStatus(requestId, timeoutMs=240000, endpointOverride=''){
  const endpoint = String(endpointOverride || getGasEndpoint() || DEFAULT_GAS_ENDPOINT || '').trim();
  if(!endpoint) throw new Error('共有同期URLが未設定です');

  const deadline = Date.now() + timeoutMs;
  let lastError = '';
  while(Date.now() < deadline){
    try{
      const data = await fetchCollectionSyncStatusJsonpRequest(endpoint, requestId, 20000);
      const status = String(data?.status || '').toLowerCase();
      if(status === 'waiting_lock'){
        renderShareSyncStatus('別の共有送信が終わるのを待っています…');
      }else if(status === 'processing'){
        renderShareSyncStatus('共有DBへ保存中…');
      }
      if(status === 'completed' && data?.ok === true) return data;
      if(status === 'error' || (data?.ok === false && data?.pending === false)){
        throw new Error(data?.message || '共有同期に失敗しました');
      }
    }catch(e){
      lastError = String(e?.message || e);
      if(/保存確認|userId|records|payload|権限|スプレッドシート|共有同期に失敗/.test(lastError)) throw e;
    }
    await new Promise(resolve => setTimeout(resolve, 1200));
  }
  throw new Error(lastError || '共有同期の完了を確認できませんでした');
}

async function refreshSharedStatsDirectAfterSync(reason='共有同期後更新'){
  let lastError = null;
  for(let attempt=1; attempt<=3; attempt++){
    try{
      const data = await fetchGasStatsJsonp({timeoutMs:30000});
      if(!data || data.ok !== true || data.action !== 'stats'){
        throw new Error(data?.message || '共有集計の応答形式が正しくありません');
      }
      await saveRemoteStatsAsync(data.stats || []);
      saveRemoteUsers(data.users || []);
      localStorage.setItem(AUTO_RECEIVE_LAST_KEY, nowIso());
      localStorage.removeItem(MOCK_CROWD_KEY);
      state.mockCrowdActive = false;
      state.mockCrowdCount = 0;
      syncRareLogsFromCurrentEntries(reason);
      if(/自動|バックグラウンド/.test(reason))fujiyaSchedulePassiveRefresh(reason,900);else render();
      renderAutoReceiveStatus(`${reason}完了`);
      return data;
    }catch(e){
      lastError = e;
      if(attempt < 3) await new Promise(resolve => setTimeout(resolve, 1000 * attempt));
    }
  }
  throw lastError || new Error('共有所持率の再取得に失敗しました');
}

async function sendToGasOnce(options={}){
  if(!options || typeof options !== 'object' || options.target) options = {};
  const silent = !!options.silent;
  const auto = !!options.auto;
  const allowEmpty = options.allowEmpty !== false;
  const reason = String(options.reason || (auto ? '自動送信' : '手動送信'));

  const url = getGasEndpoint();
  const payload = buildSyncPayload();

  if(!url){
    if(!silent){
      toast('共有同期URLを設定してください');
      showMikeTalk('共有同期URLが未設定だよ。GASをWebアプリとして公開したURLを入れてから送信してね。');
    }else{
      renderShareSyncStatus('共有同期URL未設定で自動送信できません');
    }
    return false;
  }

  if(!payload.records.length){
    if(!silent){
      toast('送信対象がありません');
      showMikeTalk('共有IDが確定したデータがまだないよ。再照合してから送信するといいよ。');
    }
    return false;
  }

  const requestId = `fujiya_collection_sync_${Date.now()}_${Math.random().toString(36).slice(2,9)}`;
  const processingToken = (!silent && !auto)
    ? (window.fujiyaProcessing?.start({
        title:'共有DBへ送信しています',
        detail:`${payload.records.length.toLocaleString('ja-JP')}件の共有データを保存しています。`,
        progressText:'共有DB送信中'
      }) || '')
    : '';
  if(processingToken) await window.fujiyaProcessing?.paint?.();

  try{
    renderShareSyncStatus(auto ? '自動送信中…' : '送信中…');

    // file:// から不安定な fetch/no-cors は使わない。
    // フォームPOSTで送信し、JSONPの状態確認でGAS保存完了まで待つ。
    const postMessageStatus=waitForCollectionSyncPostMessage(requestId,230000);
    submitGasPostFormNoWait('collection_sync_frame', {
      payload:JSON.stringify(payload)
    }, requestId, url);

    const result = await firstSuccessfulPromise([
      postMessageStatus,
      waitForCollectionSyncStatus(requestId,240000,url)
    ]);
    window.fujiyaProcessing?.update(processingToken,{
      title:'共有所持率を更新しています',
      detail:'保存完了を確認しました。最新の共有集計を受信しています。',
      progressText:'共有集計更新中'
    });
    await refreshSharedStatsDirectAfterSync(auto ? '自動送信後の所持率更新' : '手動送信後の所持率更新');
    try{
      if(typeof window.fujiyaMiteRecoSyncProfile==='function')await window.fujiyaMiteRecoSyncProfile({force:true});
    }catch(profileError){
      console.warn('共有同期後の公開プロフィール更新に失敗しました',profileError);
    }

    localStorage.setItem(AUTO_SYNC_LAST_KEY, nowIso());
    const savedCount = Number(result.record_count || result.remaining_records || 0);
    renderShareSyncStatus(auto
      ? `自動送信・所持率更新完了 ${savedCount}件`
      : `送信・所持率更新完了 ${savedCount}件`
    );

    if(auto){
      toast('共有所持率を更新しました');
    }else{
      toast('共有データと所持率を更新しました');
      showMikeTalk(`共有DBへの保存確認が取れたよ！
送信対象：${savedCount}件
理由：${reason}

削除や買取成立で減った所持情報も、最新の共有所持率へ更新済みだよ。`);
    }
    return true;
  }catch(e){
    console.error(e);
    const message = String(e?.message || e);
    renderShareSyncStatus(auto ? `自動送信エラー：${message}` : `送信エラー：${message}`);
    if(!silent){
      toast('共有送信に失敗しました');
      showMikeTalk(`共有送信でエラーが出たよ。

${message}

GASの公開設定と最新デプロイを確認してね。`);
    }else{
      toast('共有DBへの自動送信に失敗しました');
    }
    return false;
  }finally{
    window.fujiyaProcessing?.end(processingToken);
  }
}


function mergeCollectionSyncOptions(previous, next){
  const hasPrevious = !!(previous && typeof previous === 'object');
  const a = hasPrevious ? previous : {};
  const b = next && typeof next === 'object' ? next : {};
  if(!hasPrevious){
    return {
      silent: !!b.silent,
      auto: !!b.auto,
      allowEmpty: b.allowEmpty !== false,
      reason: String(b.reason || '変更保存')
    };
  }
  return {
    // どれか1回でも手動送信なら、後続送信も結果を画面に出す。
    silent: !!(a.silent && b.silent),
    auto: !!(a.auto && b.auto),
    allowEmpty: a.allowEmpty !== false || b.allowEmpty !== false,
    reason: String(b.reason || a.reason || '変更保存')
  };
}

/**
 * 共有送信の多重実行防止。
 * 削除・買取成立・画面再描画などが続けて保存を要求しても、GASへ同時送信しない。
 * 送信中に変更が入った場合は、完了後に最新状態を1回だけ再送する。
 */
async function sendToGas(options={}){
  const normalized = options && typeof options === 'object' && !options.target
    ? options
    : {};

  if(collectionSyncInFlightPromise){
    collectionSyncQueuedOptions = mergeCollectionSyncOptions(collectionSyncQueuedOptions, normalized);
    renderShareSyncStatus('前の共有送信完了後に最新状態を再送します');
    return collectionSyncInFlightPromise;
  }

  collectionSyncInFlightPromise = (async () => {
    let currentOptions = normalized;
    let finalResult = false;
    do{
      collectionSyncQueuedOptions = null;
      finalResult = await sendToGasOnce(currentOptions);
      currentOptions = collectionSyncQueuedOptions;
      if(currentOptions){
        renderShareSyncStatus('最新状態を続けて再送中…');
        await new Promise(resolve => setTimeout(resolve, 700));
      }
    }while(currentOptions);
    return finalResult;
  })();

  try{
    return await collectionSyncInFlightPromise;
  }finally{
    collectionSyncInFlightPromise = null;
  }
}

function gasAdvice(){
  const url = getGasEndpoint();
  const payload = buildSyncPayload();
  const unconfirmed = state.entries.filter(isUnconfirmedEntry).length;
  if(!url) return 'まずGAS WebアプリURLを入れて保存してね。匿名共有参加ONでも、URLがないと自動送信できないよ。';
  if(!payload.records.length) return '送信対象がないよ。マスター再照合で共有IDを確定してから送ってね。';
  if(unconfirmed) return `送信はできるけど、未確定が${unconfirmed}件あるよ。先に整備すると共有所持率の精度が上がるよ。`;
  return `送信準備はかなり整ってるよ！対象${payload.records.length}件をGASに送れる状態だよ。匿名共有参加は${getShareOptIn() ? 'ON' : 'OFF'}、購入金額共有は${getSharePurchasePriceOptIn() ? 'ON' : 'OFF'}。送信後は「共有データ受信」で所持率・平均レート・共有平均購入金額をカードに反映できるよ。`;
}

