function partsSummary(e){
  return `<div class="parts-summary">${PARTS.map(([k,l]) => {
    const it = e.parts?.[k] || {has:false,condition:''};
    return `<div class="part-pill ${it.has ? '' : 'missing'}"><span class="part-name">${l}</span><span class="part-rank">${it.has ? (COND_LABELS[it.condition] || '未設定') : 'なし'}</span></div>`;
  }).join('')}</div>`;
}


function entryRatingEventComment(entry, oldRating=0){
  const r = ratingNumber(entry.rating);
  const old = ratingNumber(oldRating);
  if(r >= 5 && old < 5) return `★★★★★！これは${getUserName()}の殿堂入り級だよ！`;
  if(r >= 4 && old < 4) return '高評価きたよ！将来おすすめ機能の大事な材料になるよ。';
  if(r > 0 && old === 0) return '評価をつけたよ。こういう好みデータが後でおすすめ表示に効いてくるよ。';
  return '';
}

function compactEntryLine(entry){
  const bits = [];
  if(entry.platform) bits.push(entry.platform);
  if(entry.genre) bits.push(entry.genre);
  if(entry.maker) bits.push(entry.maker);
  if(entry.releaseDate || entry.rawReleaseDate) bits.push(entry.releaseDate ? fmtDateOnly(entry.releaseDate) : entry.rawReleaseDate);
  return bits.length ? bits.join(' / ') : 'マスター情報未確定';
}

function normalizeXPostText(text){
  const tags = '#藤やコレクション #レトロゲーム';
  let body = String(text || '').trim();
  if(!body) return '';
  if(!body.includes('#藤やコレクション')) body = `${body}\n\n${tags}`;
  if(body.length <= 260) return body;
  const tagIndex = body.lastIndexOf('\n\n#藤やコレクション');
  const tagPart = tagIndex >= 0 ? body.slice(tagIndex) : `\n\n${tags}`;
  const mainPart = tagIndex >= 0 ? body.slice(0, tagIndex) : body;
  const limit = Math.max(40, 260 - tagPart.length - 1);
  return `${mainPart.slice(0, limit).trim()}…${tagPart}`;
}

function xPostUrl(text){
  return `https://twitter.com/intent/tweet?text=${encodeURIComponent(text)}`;
}

let mikeTalkShareImageData = '';
let mikeTalkShareFileName = 'fujiya-share.png';
let mikeTalkShareRenderToken = 0;

function sanitizeShareFileName(name){
  const base = String(name || 'fujiya-share')
    .replace(/\.png$/i, '')
    .replace(/[\\/:*?"<>|]+/g, '_')
    .replace(/\s+/g, '_')
    .replace(/_+/g, '_')
    .replace(/^_+|_+$/g, '')
    .slice(0, 80);
  return (base || 'fujiya-share') + '.png';
}

function shareFileStem(entry){
  return `${String(entry.platform || 'GAME').trim()}_${String(entry.title || 'title').trim()}`
    .replace(/[\\/:*?"<>|]+/g, '_')
    .replace(/\s+/g, '_')
    .replace(/_+/g, '_')
    .replace(/^_+|_+$/g, '')
    .slice(0, 60) || 'fujiya-share';
}

function normalizeMikeTalkPost(post=null){
  if(typeof post === 'string'){
    return { text: normalizeXPostText(post), image:null, fileName:'fujiya-share.png' };
  }
  const data = post && typeof post === 'object' ? post : {};
  return {
    text: normalizeXPostText(data.text || ''),
    image: data.image || null,
    fileName: sanitizeShareFileName(data.fileName || 'fujiya-share')
  };
}

function clearMikeTalkSharePreview(){
  mikeTalkShareImageData = '';
  mikeTalkShareFileName = 'fujiya-share.png';
  const box = $('mikeTalkSharePreview');
  const wrap = $('mikeTalkShareImageWrap');
  const img = $('mikeTalkShareImage');
  if(box) box.classList.add('hidden');
  if(wrap){
    wrap.classList.add('loading');
    wrap.textContent = '画像はありません';
  }
  if(img){
    img.classList.add('hidden');
    img.removeAttribute('src');
  }
}

function applyMikeTalkSharePreview(dataUrl, fileName){
  mikeTalkShareImageData = dataUrl || '';
  mikeTalkShareFileName = sanitizeShareFileName(fileName || 'fujiya-share');
  const box = $('mikeTalkSharePreview');
  const wrap = $('mikeTalkShareImageWrap');
  const img = $('mikeTalkShareImage');
  if(!box || !wrap || !img) return;
  if(!dataUrl){
    clearMikeTalkSharePreview();
    return;
  }
  wrap.classList.remove('loading');
  wrap.textContent = '';
  img.src = dataUrl;
  img.classList.remove('hidden');
  box.classList.remove('hidden');
  if(!wrap.contains(img)) wrap.appendChild(img);
}

function setMikeTalkShareLoading(){
  const box = $('mikeTalkSharePreview');
  const wrap = $('mikeTalkShareImageWrap');
  const img = $('mikeTalkShareImage');
  if(box) box.classList.remove('hidden');
  if(wrap){
    wrap.classList.add('loading');
    wrap.textContent = '画像を準備中…';
  }
  if(img){
    img.classList.add('hidden');
    img.removeAttribute('src');
  }
}

function drawRoundRect(ctx, x, y, w, h, r){
  const radius = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.arcTo(x + w, y, x + w, y + h, radius);
  ctx.arcTo(x + w, y + h, x, y + h, radius);
  ctx.arcTo(x, y + h, x, y, radius);
  ctx.arcTo(x, y, x + w, y, radius);
  ctx.closePath();
}

function fitTextLines(ctx, text, maxWidth, maxLines=3){
  const src = String(text || '').trim();
  if(!src) return [];
  const chars = Array.from(src);
  const lines = [];
  let line = '';
  for(const ch of chars){
    const test = line + ch;
    if(ctx.measureText(test).width <= maxWidth || !line){
      line = test;
      continue;
    }
    lines.push(line);
    line = ch;
    if(lines.length >= maxLines - 1) break;
  }
  const used = lines.join('') + line;
  const remaining = src.slice(used.length);
  if(lines.length < maxLines && line) lines.push(line);
  if(remaining && lines.length){
    let last = lines[lines.length - 1];
    while(last && ctx.measureText(last + '…').width > maxWidth){
      last = last.slice(0, -1);
    }
    lines[lines.length - 1] = last + '…';
  }
  return lines;
}

function fillCoverImage(ctx, img, x, y, w, h){
  const scale = Math.max(w / img.width, h / img.height);
  const dw = img.width * scale;
  const dh = img.height * scale;
  const dx = x + (w - dw) / 2;
  const dy = y + (h - dh) / 2;
  ctx.drawImage(img, dx, dy, dw, dh);
}

function shareCardPhotoView(entry){
  return {
    x: Math.max(-80, Math.min(80, Number(entry?.photoViewX || entry?.photo_view_x || 0) || 0)),
    y: Math.max(-80, Math.min(80, Number(entry?.photoViewY || entry?.photo_view_y || 0) || 0)),
    scale: Math.max(1, Math.min(2.5, Number(entry?.photoViewScale || entry?.photo_view_scale || 1) || 1)),
    rotate: normalizePhotoRotate(entry?.photoViewRotate || entry?.photo_view_rotate || 0),
    set: entry?.photoViewSet === true || entry?.photo_view_set === true || entry?.photoViewSet === '1' || entry?.photo_view_set === '1'
  };
}

function drawShareCardAdjustedImage(ctx, img, x, y, w, h, entry){
  const view = shareCardPhotoView(entry);
  const hasAdjust = !!(view.set || view.rotate || view.scale !== 1 || view.x || view.y);
  if(!hasAdjust){
    fillCoverImage(ctx, img, x, y, w, h);
    return;
  }
  const radians = (view.rotate || 0) * Math.PI / 180;
  const absCos = Math.abs(Math.cos(radians));
  const absSin = Math.abs(Math.sin(radians));
  const rotatedW = img.width * absCos + img.height * absSin;
  const rotatedH = img.width * absSin + img.height * absCos;
  const containScale = Math.min(w / rotatedW, h / rotatedH);
  const finalScale = containScale * view.scale;
  const dw = img.width * finalScale;
  const dh = img.height * finalScale;
  const tx = (view.x / 100) * w;
  const ty = (view.y / 100) * h;
  ctx.save();
  ctx.translate(x + w / 2 + tx, y + h / 2 + ty);
  if(view.rotate) ctx.rotate(radians);
  ctx.drawImage(img, -dw / 2, -dh / 2, dw, dh);
  ctx.restore();
}

function loadImageData(src){
  return new Promise((resolve, reject) => {
    if(!src){ resolve(null); return; }
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error('画像読み込み失敗'));
    img.src = src;
  });
}

function pickShareAccent(level=''){
  if(level === 'ultra') return { main:'#7d3a00', soft:'#fdf1cf', border:'#d8a64d', badge:'#9a3d00' };
  if(level === 'rare') return { main:'#6b2f7d', soft:'#f5eefe', border:'#b792d5', badge:'#6b2f7d' };
  return { main:'#2f3955', soft:'#eef2fb', border:'#b8c4de', badge:'#2f3955' };
}

async function buildMikeTalkShareCard(postInfo){
  const imageInfo = (postInfo && postInfo.image) || {};
  const canvas = document.createElement('canvas');
  canvas.width = 1200;
  canvas.height = 630;
  const ctx = canvas.getContext('2d');
  const accent = pickShareAccent(imageInfo.rareLevel || '');
  const bg1 = '#f3efe7';
  const bg2 = '#ebe4d8';
  const panel = {x:36, y:36, w:1128, h:558};

  const grad = ctx.createLinearGradient(0, 0, 0, canvas.height);
  grad.addColorStop(0, bg1);
  grad.addColorStop(1, bg2);
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = 'rgba(255,255,255,.82)';
  drawRoundRect(ctx, panel.x, panel.y, panel.w, panel.h, 28);
  ctx.fill();
  ctx.lineWidth = 2;
  ctx.strokeStyle = 'rgba(63,48,35,.10)';
  ctx.stroke();

  ctx.fillStyle = accent.main;
  drawRoundRect(ctx, panel.x + 24, panel.y + 24, panel.w - 48, 64, 18);
  ctx.fill();

  ctx.fillStyle = '#fff';
  ctx.font = '900 20px system-ui, sans-serif';
  ctx.fillText('コレクション管理ツール　みてコレ', panel.x + 46, panel.y + 64);
  ctx.font = '700 12px system-ui, sans-serif';
  ctx.globalAlpha = 0.85;
  ctx.fillText('イベントカード', panel.x + panel.w - 120, panel.y + 64);
  ctx.globalAlpha = 1;

  const imageBox = {x: panel.x + 36, y: panel.y + 116, w: 280, h: 360};
  ctx.fillStyle = '#fff';
  drawRoundRect(ctx, imageBox.x, imageBox.y, imageBox.w, imageBox.h, 22);
  ctx.fill();
  ctx.strokeStyle = accent.border;
  ctx.lineWidth = 2;
  ctx.stroke();

  try{
    const coverImg = await loadImageData(imageInfo.photoData || '');
    if(coverImg){
      ctx.save();
      drawRoundRect(ctx, imageBox.x + 12, imageBox.y + 12, imageBox.w - 24, imageBox.h - 24, 16);
      ctx.clip();
      drawShareCardAdjustedImage(ctx, coverImg, imageBox.x + 12, imageBox.y + 12, imageBox.w - 24, imageBox.h - 24, imageInfo);
      ctx.restore();
    }else{
      ctx.fillStyle = '#faf7ff';
      drawRoundRect(ctx, imageBox.x + 12, imageBox.y + 12, imageBox.w - 24, imageBox.h - 24, 16);
      ctx.fill();
      ctx.fillStyle = accent.main;
      ctx.font = '900 72px system-ui, sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('🎮', imageBox.x + imageBox.w / 2, imageBox.y + 175);
      ctx.font = '900 22px system-ui, sans-serif';
      ctx.fillText(imageInfo.platform || 'GAME', imageBox.x + imageBox.w / 2, imageBox.y + 238);
      ctx.font = '700 14px system-ui, sans-serif';
      ctx.fillStyle = '#6e6280';
      ctx.fillText('画像未登録', imageBox.x + imageBox.w / 2, imageBox.y + 270);
      ctx.textAlign = 'left';
    }
  }catch(e){
    ctx.fillStyle = '#faf7ff';
    drawRoundRect(ctx, imageBox.x + 12, imageBox.y + 12, imageBox.w - 24, imageBox.h - 24, 16);
    ctx.fill();
    ctx.fillStyle = '#6e6280';
    ctx.font = '700 18px system-ui, sans-serif';
    ctx.fillText('画像を読み込めませんでした', imageBox.x + 24, imageBox.y + 58);
  }

  const textX = panel.x + 350;
  const textW = 760;
  const badgeText = imageInfo.badge || '';
  if(badgeText){
    ctx.fillStyle = accent.badge;
    drawRoundRect(ctx, textX, panel.y + 118, 150, 34, 17);
    ctx.fill();
    ctx.fillStyle = '#fff';
    ctx.font = '900 16px system-ui, sans-serif';
    ctx.fillText(badgeText, textX + 18, panel.y + 141);
  }

  ctx.fillStyle = '#4e4257';
  ctx.font = '800 18px system-ui, sans-serif';
  ctx.fillText(imageInfo.headline || 'コレクション更新', textX, panel.y + 180);

  ctx.fillStyle = '#20142b';
  ctx.font = '900 36px system-ui, sans-serif';
  const titleLines = fitTextLines(ctx, imageInfo.title || 'タイトル未設定', textW, 2);
  titleLines.forEach((line, idx) => {
    ctx.fillText(line, textX, panel.y + 236 + idx * 46);
  });

  ctx.fillStyle = '#5f5268';
  ctx.font = '800 20px system-ui, sans-serif';
  ctx.fillText(imageInfo.platform ? `機種：${imageInfo.platform}` : '機種：未設定', textX, panel.y + 330);

  const subtext = imageInfo.subline || '';
  if(subtext){
    ctx.fillStyle = '#3a3142';
    ctx.font = '700 18px system-ui, sans-serif';
    const subLines = String(subtext || '').split(/\n/).flatMap(line => fitTextLines(ctx, line, textW, 2)).slice(0, 3);
    subLines.forEach((line, idx) => {
      ctx.fillText(line, textX, panel.y + 374 + idx * 28);
    });
  }

  const chips = Array.isArray(imageInfo.stats) ? imageInfo.stats.filter(Boolean).slice(0, 5) : [];
  let chipX = textX;
  let chipY = panel.y + 460;
  ctx.font = '900 16px system-ui, sans-serif';
  chips.forEach((chip, idx) => {
    const width = Math.min(ctx.measureText(chip).width + 30, 310);
    if(chipX + width > panel.x + panel.w - 42){
      chipX = textX;
      chipY += 42;
    }
    ctx.fillStyle = idx % 2 === 0 ? accent.soft : '#fff';
    drawRoundRect(ctx, chipX, chipY, width, 30, 15);
    ctx.fill();
    ctx.strokeStyle = accent.border;
    ctx.lineWidth = 1.5;
    ctx.stroke();
    ctx.fillStyle = '#2b2233';
    ctx.fillText(chip, chipX + 14, chipY + 20);
    chipX += width + 10;
  });

  const footerY = panel.y + panel.h - 34;
  ctx.strokeStyle = 'rgba(53,35,79,.12)';
  ctx.beginPath();
  ctx.moveTo(panel.x + 36, footerY - 22);
  ctx.lineTo(panel.x + panel.w - 36, footerY - 22);
  ctx.stroke();
  ctx.fillStyle = '#5b5261';
  ctx.font = '700 14px system-ui, sans-serif';
  ctx.fillText(`記録者：${imageInfo.userName || getUserName()}`, panel.x + 40, footerY);
  ctx.fillText(imageInfo.dateLabel || new Date().toLocaleDateString('ja-JP'), panel.x + 380, footerY);
  // footer slogan removed in V7.18.37

  return canvas.toDataURL('image/png');
}

async function renderMikeTalkShareCard(postInfo){
  const imageInfo = postInfo && postInfo.image ? postInfo.image : null;
  if(!imageInfo){
    clearMikeTalkSharePreview();
    return;
  }
  const token = ++mikeTalkShareRenderToken;
  setMikeTalkShareLoading();
  try{
    const dataUrl = await buildMikeTalkShareCard(postInfo);
    if(token !== mikeTalkShareRenderToken) return;
    applyMikeTalkSharePreview(dataUrl, postInfo.fileName || 'fujiya-share.png');
  }catch(e){
    if(token !== mikeTalkShareRenderToken) return;
    clearMikeTalkSharePreview();
    console.warn('share image render failed:', e);
  }
}

function renderMikeTalkPost(post=null){
  const box = $('mikeTalkPostBox');
  const preview = $('mikeTalkPostPreview');
  if(!box || !preview) return;
  const info = normalizeMikeTalkPost(post);
  if(!info.text){
    box.classList.add('hidden');
    box.dataset.postText = '';
    preview.textContent = '';
    clearMikeTalkSharePreview();
    return;
  }
  box.dataset.postText = info.text;
  preview.textContent = info.text;
  box.classList.remove('hidden');
  renderMikeTalkShareCard(info);
}

function wakeMikeTalk(){
  const box = $('mikeTalk');
  if(!box) return;
  box.classList.remove('hidden');
  box.classList.remove('mike-talk-reopen');
  void box.offsetWidth;
  box.classList.add('mike-talk-reopen');
  try{ box.scrollIntoView({behavior:'smooth', block:'nearest'}); }catch(e){}
  clearTimeout(wakeMikeTalk._timer);
  wakeMikeTalk._timer = setTimeout(() => box.classList.remove('mike-talk-reopen'), 700);
}

function showMikeTalk(message, post=null){
  message = userFriendlySystemMessage(message);
  const body = $('mikeTalkBody');
  if(body) body.textContent = message;
  renderMikeTalkPost(post);
  wakeMikeTalk();
}

function showMikeTalkHtml(content, post=null){
  const rawContent = String(content || '');
  // ソフト説明・みけナビは一般ユーザー向け機能なので、
  // 技術メッセージ簡略化の対象にせずHTML表示を維持する。
  const isMikeNaviContent = /title-mike-navi|data-mike-entry-action|みけナビ/.test(rawContent);
  if(!isAdminMode() && !isMikeNaviContent){
    const plain = rawContent.replace(/<[^>]*>/g, ' ');
    const friendly = userFriendlySystemMessage(plain);
    if(friendly !== plain){
      showMikeTalk(friendly, post);
      return;
    }
  }
  const body = $('mikeTalkBody');
  if(body) body.innerHTML = content;
  renderMikeTalkPost(post);
  wakeMikeTalk();
}

function hideMikeTalk(){
  const box = $('mikeTalk');
  if(!box) return;
  box.classList.add('hidden');
  box.classList.remove('mike-talk-reopen');
}

function forceEventMikeNavi(message, post=null){
  const text = String(message || '').trim();
  if(!text) return;
  try{
    showMikeTalk(text, post);
  }catch(e){
    console.warn('showMikeTalk failed:', e);
    const box = $('mikeTalk');
    const body = $('mikeTalkBody');
    if(body) body.textContent = text;
    if(box){
      box.classList.remove('hidden');
      box.style.display = 'block';
      box.style.zIndex = '5600';
    }
  }
  setTimeout(() => {
    try{
      const box = $('mikeTalk');
      const body = $('mikeTalkBody');
      if(body && !body.textContent.trim()) body.textContent = text;
      if(box){
        box.classList.remove('hidden');
        box.style.display = 'block';
        box.style.zIndex = '5600';
        box.classList.remove('mike-talk-reopen');
        void box.offsetWidth;
        box.classList.add('mike-talk-reopen');
      }
    }catch(e){}
  }, 80);
}

