function safeBuildEntryXPost(type, entry, extra={}){
  try{
    return buildEntryXPost(type, entry, extra);
  }catch(e){
    console.warn('event post build failed:', e);
    if(!entry) return {text:''};
    const title = postEntryTitle(entry);
    const text = type === 'showcase'
      ? `【ショーケース更新】\n${title}をショーケースに飾りました！`
      : (type === 'rematch'
        ? `【図鑑照合】\n${title}の共有IDを確定しました！`
        : `【コレクション登録】\n${title}をコレクションに登録しました！`);
    return {text};
  }
}

let lastRareBurstEntryId = '';

function playRareBurstSound(level='rare'){
  try{
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if(!AudioCtx) return;
    const ctx = new AudioCtx();
    const now = ctx.currentTime;
    const master = ctx.createGain();
    master.gain.setValueAtTime(0.0001, now);
    master.gain.exponentialRampToValueAtTime(0.16, now + 0.03);
    master.gain.exponentialRampToValueAtTime(0.0001, now + 0.78);
    master.connect(ctx.destination);

    const notes = level === 'ultra'
      ? [523.25, 659.25, 783.99, 1046.5, 1318.51]
      : [392, 523.25, 659.25, 783.99];

    notes.forEach((freq, i) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = i % 2 ? 'triangle' : 'square';
      osc.frequency.setValueAtTime(freq, now + i * 0.055);
      gain.gain.setValueAtTime(0.0001, now + i * 0.055);
      gain.gain.exponentialRampToValueAtTime(0.12, now + i * 0.055 + 0.018);
      gain.gain.exponentialRampToValueAtTime(0.0001, now + i * 0.055 + 0.22);
      osc.connect(gain);
      gain.connect(master);
      osc.start(now + i * 0.055);
      osc.stop(now + i * 0.055 + 0.24);
    });

    setTimeout(() => ctx.close().catch(()=>{}), 1000);
  }catch(e){
    // 音が鳴らなくても演出は止めない
  }
}

function rareBurstMessage(entry, info){
  if(!info) return '';
  const platform = String(info.rank?.platform || entry?.platform || '同じ機種');
  const rank = Number(info.rank?.rank || 0);
  const total = Number(info.rank?.total || 0);
  const rankText = rank && total ? `（希少順位 ${rank}/${total}）` : '';
  if(info.level === 'ultra'){
    return `参加50人以上の共有データで、${platform}内の所持率下位3％に入りました${rankText}。みてコレ内の「超レアタイトル」として認定されました。`;
  }
  return `参加50人以上の共有データで、${platform}内の所持率下位8％に入りました${rankText}。みてコレ内の「レアタイトル」として認定されました。`;
}

function renderRareParticles(level='rare'){
  const box = $('rareParticles');
  if(!box) return;
  const count = level === 'ultra' ? 42 : 28;
  box.innerHTML = Array.from({length:count}, (_, i) => {
    const angle = (Math.PI * 2 * i / count) + (seededNumber('particle:' + i) * 0.45);
    const radius = (level === 'ultra' ? 250 : 210) + seededNumber('particle:r:' + i) * 120;
    const x = Math.cos(angle) * radius;
    const y = Math.sin(angle) * radius;
    const rot = Math.round(seededNumber('particle:rot:' + i) * 720 - 360);
    const delay = (seededNumber('particle:d:' + i) * 0.18).toFixed(3);
    return `<span class="rare-particle" style="--x:${x.toFixed(0)}px;--y:${y.toFixed(0)}px;--r:${rot}deg;animation-delay:${delay}s"></span>`;
  }).join('');
}

function showRareBurst(entry, info=null, options={}){
  const rare = info || rareInfoForEntry(entry);
  if(!entry || !rare || (!rare.burst && !options.force)) return false;

  lastRareBurstEntryId = entry.id || '';
  const isUltra = rare.level === 'ultra';
  const wrap = $('rareBurst');
  const card = $('rareBurstCard');
  const kicker = $('rareBurstKicker');
  const title = $('rareBurstTitle');
  const soft = $('rareBurstSoft');
  const rate = $('rareBurstRate');
  const message = $('rareBurstMessage');

  card.classList.toggle('ultra', isUltra);
  kicker.classList.toggle('ultra', isUltra);
  title.classList.toggle('ultra', isUltra);
  rate.classList.toggle('ultra', isUltra);

  kicker.textContent = '💥 みてコレ 激レア判定';
  title.textContent = '激レアタイトル認定！';
  soft.textContent = entry.title;
  rate.textContent = rare.text || `共有所持率${formatRatePercent(remoteStatFor(entry)?.owned_rate)}`;
  message.textContent = options.message || rareBurstMessage(entry, rare);

  renderRareParticles(rare.level);
  wrap.classList.add('show');
  wrap.setAttribute('aria-hidden', 'false');
  playRareBurstSound(rare.level);
  return true;
}

function closeRareBurst(){
  const wrap = $('rareBurst');
  if(!wrap) return;
  wrap.classList.remove('show');
  wrap.setAttribute('aria-hidden', 'true');
}

function triggerRareBurstIfNeeded(entry, type='add'){
  const info = rareInfoForEntry(entry);
  if(!info || !info.burst) return;
  // レア演出は登録・再照合だけ。編集ではうるさくしない。
  if(type !== 'add' && type !== 'rematch') return;
  setTimeout(() => showRareBurst(entry, info), 220);
}

function testRareBurst(){
  const rareEntries = (state.entries || [])
    .filter(e => rareInfoForEntry(e))
    .sort((a,b) => Number(remoteStatFor(a)?.owned_rate || 1) - Number(remoteStatFor(b)?.owned_rate || 1));

  if(rareEntries.length){
    showRareBurst(rareEntries[0], rareInfoForEntry(rareEntries[0]), {force:true, message:'テスト演出だよ！ 実際に条件を満たしたレアソフトを追加した時は、このカットインが出るよ。'});
    return;
  }

  const stat = remoteRows()
    .map(r => ({...r, info: rareInfoFromStat(r)}))
    .filter(r => r.info)
    .sort((a,b) => Number(a.owned_rate || 1) - Number(b.owned_rate || 1))[0];

  if(stat){
    showRareBurst({
      id:'test-rare',
      title:stat.title || stat.shared_title_id,
      sharedTitleId:stat.shared_title_id
    }, stat.info, {force:true, message:'テスト演出だよ！ 手持ちに未登録でも、レア判定の見え方を確認できるよ。'});
    return;
  }

  toast('レア演出対象がありません');
  showMikeTalk('レア演出を試すには、先に「疑似参加者で見る」を押してね。機種コレクター50人以上かつ機種内所持率3%未満で、激レア演出を確認できるよ。');
}

function buildEventTalk(type, entry, extra={}){
  const lines = [];
  if(type === 'add'){
    lines.push(`登録完了だよ！「${entry.title}」をコレクションに登録したよ。`);
  }else if(type === 'edit'){
    lines.push(`編集完了だよ！「${entry.title}」の情報を更新したよ。`);
  }else if(type === 'delete'){
    lines.push(`「${entry.title}」を削除したよ。必要ならJSONバックアップから戻せるようにしておくと安心だよ。`);
    return lines.join('\n');
  }else if(type === 'rematch'){
    lines.push(`マスター再照合完了だよ！「${entry.title}」を共有IDつきで確定したよ。`);
  }

  if(type !== 'delete'){
    lines.push(compactEntryLine(entry));

    if(entry.sharedStatus === 'confirmed' && entry.sharedTitleId){
      lines.push(`共有ID：${entry.sharedTitleId}`);
    }else{
      lines.push('まだマスター未確定だよ。カードの「再照合」で候補を探せるよ。');
    }

    if(type === 'add' || type === 'rematch'){
      const rareLine = rareEventLine(entry);
      if(rareLine) lines.push(rareLine);
    }

    const ratingComment = entryRatingEventComment(entry, extra.oldRating || 0);
    if(ratingComment) lines.push(ratingComment);
  }

  return lines.join('\n');
}

function buildResearchQuery(entry){
  return `${entry.title} ${entry.platform || ''} ゲーム`.trim();
}

function getTitleMikeNaviCache(){
  try{
    const obj = JSON.parse(localStorage.getItem(TITLE_MIKE_NAVI_CACHE_KEY) || '{}');
    return obj && typeof obj === 'object' ? obj : {};
  }catch(e){
    return {};
  }
}

function clearLegacyTitleMikeNaviCaches(){
  if(!Array.isArray(TITLE_MIKE_NAVI_LEGACY_CACHE_KEYS)) return;
  TITLE_MIKE_NAVI_LEGACY_CACHE_KEYS.forEach(key => {
    try{ localStorage.removeItem(key); }catch(e){}
  });
}


function normalizeTitleDescriptionCatalogItem(item={}){
  return {
    sharedTitleId:String(item.sharedTitleId||item.shared_title_id||'').trim(),
    platform:normalizePlatformName(item.platform||''),
    title:String(item.title||'').trim(),
    updatedAt:String(item.updatedAt||item.updated_at||'').trim()
  };
}

function readTitleDescriptionCatalogCache(){
  try{
    const raw=JSON.parse(
      localStorage.getItem(TITLE_DESCRIPTION_CATALOG_CACHE_KEY)||'{}'
    )||{};
    const savedAt=Date.parse(String(raw.savedAt||''))||0;
    if(
      !savedAt
      ||Date.now()-savedAt>TITLE_DESCRIPTION_CATALOG_MAX_AGE_MS
      ||!Array.isArray(raw.items)
    ){
      return {
        revision:'',
        items:[],
        savedAt:0,
        loaded:false
      };
    }
    return {
      revision:String(raw.revision||''),
      items:raw.items
        .map(normalizeTitleDescriptionCatalogItem)
        .filter(item=>item.sharedTitleId||item.title),
      savedAt,
      loaded:true
    };
  }catch(error){
    return {
      revision:'',
      items:[],
      savedAt:0,
      loaded:false
    };
  }
}

let titleDescriptionCatalogState=readTitleDescriptionCatalogCache();
let titleDescriptionCatalogPromise=null;
let titleMikeNaviOpenEntryId='';

function writeTitleDescriptionCatalogCache(state){
  try{
    localStorage.setItem(
      TITLE_DESCRIPTION_CATALOG_CACHE_KEY,
      JSON.stringify({
        revision:String(state.revision||''),
        items:Array.isArray(state.items)?state.items:[],
        savedAt:new Date().toISOString()
      })
    );
  }catch(error){}
}

function localTitleDescriptionCatalogRevision(items){
  const rows=(Array.isArray(items)?items:[])
    .map(item=>[
      String(item.sharedTitleId||'').trim().toUpperCase(),
      normalizePlatformName(item.platform||'').toUpperCase(),
      titleKey(item.title||''),
      String(item.updatedAt||'')
    ].join('|'))
    .sort();
  let hash=2166136261;
  const text=rows.join('\n');
  for(let index=0;index<text.length;index++){
    hash^=text.charCodeAt(index);
    hash=Math.imul(hash,16777619);
  }
  return `${rows.length}:${(hash>>>0).toString(16)}`;
}

function titleDescriptionCatalogItem(entry){
  const target=normalizeTitleMikeNaviEntry(entry);
  const items=titleDescriptionCatalogState.items||[];
  const wantedId=String(target.sharedTitleId||'').trim().toUpperCase();
  if(wantedId){
    const exact=items.find(item=>
      String(item.sharedTitleId||'').trim().toUpperCase()===wantedId
    );
    if(exact)return exact;
  }

  const platform=normalizePlatformName(target.platform||'');
  const key=titleKey(target.canonicalTitle||target.title||'');
  if(!key)return null;
  return items.find(item=>
    (!platform||normalizePlatformName(item.platform||'')===platform)
    &&titleKey(item.title||'')===key
  )||null;
}

function titleDescriptionCatalogJsonpRequest(endpoint,knownRevision=''){
  return new Promise((resolve,reject)=>{
    const cleanEndpoint=String(endpoint||'').trim();
    if(!cleanEndpoint){
      reject(new Error('ゲーム説明の更新確認先が未設定です'));
      return;
    }

    const callback=
      `fujiyaTitleDescriptionCatalog_${Date.now()}_${Math.random().toString(36).slice(2)}`;
    let settled=false;
    const timer=setTimeout(()=>{
      cleanup();
      reject(new Error('ゲーム説明の更新確認がタイムアウトしました'));
    },12000);

    function cleanup(){
      if(settled)return;
      settled=true;
      clearTimeout(timer);
      window.fujiyaKeepLateJsonpCallback_(callback);
      document.getElementById(callback)?.remove();
    }

    window[callback]=data=>{
      cleanup();
      if(data?.ok&&data?.action==='title_description_catalog'){
        resolve(data);
      }else{
        reject(titleMikeNaviPayloadError(
          data,
          'ゲーム説明の更新情報を取得できませんでした'
        ));
      }
    };

    const script=document.createElement('script');
    script.id=callback;
    script.onerror=()=>{
      cleanup();
      reject(new Error('ゲーム説明の更新確認先へ接続できませんでした'));
    };

    const params=new URLSearchParams({
      action:'title_description_catalog',
      knownRevision:String(knownRevision||''),
      callback,
      _:String(Date.now())
    });
    const sep=cleanEndpoint.includes('?')?'&':'?';
    script.src=`${cleanEndpoint}${sep}${params.toString()}`;
    document.body.appendChild(script);
  });
}

async function refreshTitleDescriptionCatalog(options={}){
  if(window.__MITEKORE_LOCAL_PREVIEW__){
    return titleDescriptionCatalogState;
  }

  const force=options.force===true;
  const age=titleDescriptionCatalogState.savedAt
    ?Date.now()-titleDescriptionCatalogState.savedAt
    :Infinity;
  if(
    !force
    &&titleDescriptionCatalogState.loaded
    &&age<TITLE_DESCRIPTION_CATALOG_REFRESH_MS
  ){
    return titleDescriptionCatalogState;
  }
  if(titleDescriptionCatalogPromise)return titleDescriptionCatalogPromise;

  titleDescriptionCatalogPromise=(async()=>{
    const endpoints=[...new Set([
      getGasEndpoint(),
      DEFAULT_GAS_ENDPOINT
    ].map(value=>String(value||'').trim()).filter(Boolean))];

    let lastError=null;
    for(const endpoint of endpoints){
      try{
        const data=await titleDescriptionCatalogJsonpRequest(
          endpoint,
          titleDescriptionCatalogState.revision
        );
        const previousRevision=String(titleDescriptionCatalogState.revision||'');

        if(data.notModified===true){
          titleDescriptionCatalogState={
            ...titleDescriptionCatalogState,
            savedAt:Date.now(),
            loaded:true
          };
        }else{
          const items=Array.isArray(data.items)
            ?data.items
              .map(normalizeTitleDescriptionCatalogItem)
              .filter(item=>item.sharedTitleId||item.title)
            :[];
          titleDescriptionCatalogState={
            revision:String(
              data.revision||localTitleDescriptionCatalogRevision(items)
            ),
            items,
            savedAt:Date.now(),
            loaded:true
          };
        }

        writeTitleDescriptionCatalogCache(titleDescriptionCatalogState);

        if(
          previousRevision
          &&previousRevision!==titleDescriptionCatalogState.revision
          &&titleMikeNaviOpenEntryId
        ){
          setTimeout(()=>{
            const entry=state.entries.find(row=>
              String(row.id||'')===String(titleMikeNaviOpenEntryId||'')
            );
            if(entry)refreshOpenTitleMikeNaviIfNeeded(entry).catch(()=>false);
          },100);
        }
        return titleDescriptionCatalogState;
      }catch(error){
        lastError=error;
      }
    }
    if(options.throwOnError)throw lastError||new Error(
      'ゲーム説明の更新情報を取得できませんでした'
    );
    return titleDescriptionCatalogState;
  })().finally(()=>{
    titleDescriptionCatalogPromise=null;
  });

  return titleDescriptionCatalogPromise;
}

let titleDescriptionCatalogRefreshTimer=0;
function scheduleTitleDescriptionCatalogRefresh(delayMs=30000,force=false){
  if(window.__MITEKORE_LOCAL_PREVIEW__)return;
  clearTimeout(titleDescriptionCatalogRefreshTimer);
  const run=()=>{
    if(document.hidden||fujiyaUiInteractionBusy()||deviceAutoSyncBusy||deviceSyncBusy||window.__fujiyaAutoReceiveBusy){
      titleDescriptionCatalogRefreshTimer=setTimeout(run,8000);
      return;
    }
    titleDescriptionCatalogRefreshTimer=0;
    const execute=()=>refreshTitleDescriptionCatalog({force}).catch(()=>false);
    if(typeof requestIdleCallback==='function')requestIdleCallback(execute,{timeout:6000});
    else setTimeout(execute,0);
  };
  titleDescriptionCatalogRefreshTimer=setTimeout(run,Math.max(1000,Number(delayMs)||30000));
}

function titleMikeNaviCacheAge(data){
  const stamp=Date.parse(String(data?.cachedAt||data?.fetchedAt||''))||0;
  return stamp?Math.max(0,Date.now()-stamp):Infinity;
}

function titleMikeNaviContentSignature(data){
  return JSON.stringify({
    sourceType:String(data?.sourceType||''),
    updatedAt:String(data?.updatedAt||data?.updated_at||''),
    extract:String(data?.extract||data?.description||''),
    points:Array.isArray(data?.points)?data.points:[],
    pageUrl:String(data?.pageUrl||'')
  });
}

function titleMikeNaviCachedStatus(entry,cached){
  if(!cached)return {current:false,reason:'missing'};
  const sourceType=String(cached.sourceType||'').toLowerCase();

  if(sourceType==='curated'){
    if(!titleDescriptionCatalogState.loaded){
      return {current:true,needsCatalog:true,reason:'catalog-unchecked'};
    }
    const item=titleDescriptionCatalogItem(entry);
    if(!item){
      return {current:false,reason:'curated-removed'};
    }
    const serverAt=Date.parse(String(item.updatedAt||''))||0;
    const cachedAt=Date.parse(String(cached.updatedAt||cached.updated_at||''))||0;
    return {
      current:serverAt<=cachedAt,
      reason:serverAt<=cachedAt?'curated-current':'curated-updated',
      item
    };
  }

  if(sourceType==='gavas'){
    return {
      current:titleMikeNaviCacheAge(cached)<TITLE_MIKE_NAVI_GAVAS_TTL_MS,
      reason:'gavas-ttl'
    };
  }

  return {
    current:titleMikeNaviCacheAge(cached)<24*60*60*1000,
    reason:'default-ttl'
  };
}

async function refreshOpenTitleMikeNaviIfNeeded(entry){
  const cached=anyTitleMikeNaviCache(entry);
  if(!cached)return false;

  const status=titleMikeNaviCachedStatus(entry,cached);
  if(status.current){
    if(status.needsCatalog)scheduleTitleDescriptionCatalogRefresh(45000,false);
    return true;
  }

  const updated=await prefetchTitleMikeNaviEntry(entry,{
    force:true,
    returnData:true,
    skipCatalog:true
  });
  if(!updated||updated===true)return false;

  if(
    titleMikeNaviContentSignature(updated)!==
    titleMikeNaviContentSignature(cached)
  ){
    const talkTitle=
      document.querySelector('#mikeTalkBody .talk-title')?.textContent||'';
    if(talkTitle.includes(String(entry.title||''))){
      renderTitleMikeNaviSummary(entry,updated,false);
      appendMikeCommunityTeaser(entry,false);
    }
  }
  return true;
}

function setTitleMikeNaviCache(key, data){
  if(!key || !data) return;
  const cache = getTitleMikeNaviCache();
  cache[key] = {...data, cachedAt: nowIso()};
  const sortKeys=()=>Object.keys(cache).sort((a,b)=>String(cache[b]?.cachedAt||'').localeCompare(String(cache[a]?.cachedAt||'')));
  let keys=sortKeys();
  if(keys.length>240)keys.slice(240).forEach(k=>delete cache[k]);
  try{
    localStorage.setItem(TITLE_MIKE_NAVI_CACHE_KEY,JSON.stringify(cache));
  }catch(error){
    // 他の保存領域を巻き込まないよう、説明キャッシュだけ縮小して再保存する。
    keys=sortKeys();
    keys.slice(80).forEach(k=>delete cache[k]);
    try{localStorage.setItem(TITLE_MIKE_NAVI_CACHE_KEY,JSON.stringify(cache));}catch(_error){}
  }
}

function titleMikeNaviMasterFor(entry={}){
  const source = entry && typeof entry === 'object' ? entry : {};
  const sharedTitleId = String(source.sharedTitleId || source.shared_title_id || source.masterTitleId || '').trim();
  if(sharedTitleId){
    const direct = findMasterById(sharedTitleId) || findMasterBySharedTitleId(sharedTitleId);
    if(direct) return direct;
  }

  const platform = normalizePlatformName(source.platform || '');
  const queryKey = titleKey(source.canonicalTitle || source.title || source.gameTitle || '');
  if(!queryKey) return null;

  const index = getMasterSearchIndex();
  const pool = platform ? (index.byPlatform.get(platform) || []) : index.all;
  const exact = pool.filter(row => row.titleKeys.includes(queryKey));
  return exact.length === 1 ? exact[0].master : null;
}

function normalizeTitleMikeNaviEntry(entry={}){
  const source = entry && typeof entry === 'object' ? entry : {};
  const master = titleMikeNaviMasterFor(source);
  if(!master){
    return {
      ...source,
      title:String(source.canonicalTitle || source.title || source.gameTitle || '').trim(),
      canonicalTitle:String(source.canonicalTitle || source.title || source.gameTitle || '').trim(),
      platform:normalizePlatformName(source.platform || ''),
      sharedTitleId:String(source.sharedTitleId || source.shared_title_id || source.masterTitleId || '').trim()
    };
  }

  const canonicalTitle = String(master.canonicalTitle || master.title || source.canonicalTitle || source.title || '').trim();
  return {
    ...source,
    sharedTitleId:String(master.sharedTitleId || source.sharedTitleId || source.shared_title_id || '').trim(),
    canonicalSharedTitleId:String(master.canonicalSharedTitleId || master.sharedTitleId || source.canonicalSharedTitleId || '').trim(),
    title:canonicalTitle,
    canonicalTitle,
    platform:normalizePlatformName(master.platform || source.platform || ''),
    maker:String(master.maker || source.maker || '').trim(),
    productCode:String(master.productCode || source.productCode || '').trim(),
    detailUrl:String(master.detailUrl || source.detailUrl || '').trim(),
    gavasProductId:String(master.gavasProductId || source.gavasProductId || '').trim(),
    aliases:Array.isArray(master.aliases) ? master.aliases.slice() : (Array.isArray(source.aliases) ? source.aliases.slice() : [])
  };
}

function titleMikeNaviCacheKey(entry){
  const target = normalizeTitleMikeNaviEntry(entry);
  const sharedTitleId = String(target.sharedTitleId || '').trim().toLowerCase();
  if(sharedTitleId) return `id:${sharedTitleId}`;
  return `title:${normalizePlatformName(target.platform || '').toLowerCase()}|${titleKey(target.canonicalTitle || target.title || '')}`;
}

function titleMikeNaviCacheKeys(entry){
  const source = entry && typeof entry === 'object' ? entry : {};
  const target = normalizeTitleMikeNaviEntry(source);
  return [...new Set([
    titleMikeNaviCacheKey(target),
    `${target.sharedTitleId || ''}|${target.platform || ''}|${target.title || ''}`.toLowerCase(),
    `${source.sharedTitleId || source.shared_title_id || ''}|${source.platform || ''}|${source.title || source.canonicalTitle || ''}`.toLowerCase()
  ].filter(Boolean))];
}

function findTitleMikeNaviCachedData(entry){
  const cache = getTitleMikeNaviCache();
  for(const key of titleMikeNaviCacheKeys(entry)){
    const cached = cache[key];
    if(cached && (cached.extract || (Array.isArray(cached.points) && cached.points.length))){
      return cached;
    }
  }
  return null;
}

function titleMikeNaviRequestFields(entry){
  const original = entry && typeof entry === 'object' ? entry : {};
  const target = normalizeTitleMikeNaviEntry(original);
  const master = titleMikeNaviMasterFor(target);
  const canonicalTitle = String(target.canonicalTitle || target.title || '').trim();
  const aliases = [...new Set([
    canonicalTitle,
    String(original.title || original.canonicalTitle || '').trim(),
    ...(Array.isArray(target.aliases) ? target.aliases : []),
    ...(Array.isArray(master?.aliases) ? master.aliases : [])
  ].map(value => String(value || '').trim()).filter(Boolean))].slice(0, 12);
  return {
    sharedTitleId:target.sharedTitleId || '',
    title:canonicalTitle,
    canonicalTitle,
    aliases:JSON.stringify(aliases),
    platform:target.platform || '',
    maker:target.maker || master?.maker || '',
    productCode:target.productCode || master?.productCode || '',
    detailUrl:target.detailUrl || master?.detailUrl || '',
    gavasProductId:target.gavasProductId || master?.gavasProductId || ''
  };
}

function titleMikeNaviPayloadError(data, fallback='タイトル要約取得に失敗しました'){
  const err = new Error((data && (data.message || data.error)) || fallback);
  err.code = String(data?.code || '');
  err.reportable = !!data?.reportable;
  err.payload = data || null;
  return err;
}

function titleMikeNaviJsonpRequest(entry, endpoint){
  return new Promise((resolve, reject) => {
    const cleanEndpoint = String(endpoint || '').trim();
    if(!cleanEndpoint){
      reject(new Error('ソフト説明の取得先が未設定です'));
      return;
    }

    const callback = `fujiyaTitleMikeNavi_${Date.now()}_${Math.random().toString(36).slice(2)}`;
    let settled = false;
    const timer = setTimeout(() => {
      cleanup();
      reject(new Error('タイトル要約取得がタイムアウトしました'));
    }, TITLE_MIKE_NAVI_TIMEOUT_MS);

    function cleanup(){
      if(settled) return;
      settled = true;
      clearTimeout(timer);
      window.fujiyaKeepLateJsonpCallback_(callback);
      const script = document.getElementById(callback);
      if(script) script.remove();
    }

    window[callback] = data => {
      cleanup();
      if(data && data.ok){
        resolve(data);
      }else{
        reject(titleMikeNaviPayloadError(data));
      }
    };

    const script = document.createElement('script');
    script.id = callback;
    script.onerror = () => {
      cleanup();
      reject(new Error('ソフト説明の取得先へ接続できませんでした'));
    };

    const sep = cleanEndpoint.includes('?') ? '&' : '?';
    const params = new URLSearchParams({
      action:'title_summary',
      ...titleMikeNaviRequestFields(entry),
      callback,
      _:String(Date.now())
    });
    script.src = `${cleanEndpoint}${sep}${params.toString()}`;
    document.body.appendChild(script);
  });
}

async function titleMikeNaviFrameRequest(entry, endpoint){
  const data = await fetchGasByPostFrame('title_summary_frame', {
    endpoint,
    timeoutMs:14000,
    fields:titleMikeNaviRequestFields(entry)
  });
  if(data && data.ok && data.action === 'title_summary') return data;
  throw titleMikeNaviPayloadError(data, 'ソフト説明を取得できませんでした');
}

function titleMikeNaviCanRetryTransport(error){
  if(error?.reportable || String(error?.code || '') === 'DESCRIPTION_NOT_FOUND') return false;
  const message = String(error?.message || error || '');
  return /タイムアウト|接続でき|取得先|応答|通信|Webアプリ|Unknown action|unknown action|一時的/i.test(message);
}

async function titleMikeNaviJsonp(entry){
  const endpoints = [...new Set([
    getGasEndpoint(),
    DEFAULT_GAS_ENDPOINT
  ].map(v => String(v || '').trim()).filter(Boolean))];

  if(!endpoints.length){
    throw new Error('ソフト説明の取得先が未設定です');
  }

  const errors = [];
  for(const endpoint of endpoints){
    try{
      return await titleMikeNaviJsonpRequest(entry, endpoint);
    }catch(error){
      errors.push(String(error?.message || error || 'JSONP取得失敗'));
      if(!titleMikeNaviCanRetryTransport(error)) throw error;
    }

    if(!window.__MITEKORE_LOCAL_PREVIEW__){
      try{
        return await titleMikeNaviFrameRequest(entry, endpoint);
      }catch(error){
        errors.push(String(error?.message || error || 'POST取得失敗'));
        if(!titleMikeNaviCanRetryTransport(error)) throw error;
      }
    }
  }

  throw new Error(errors.filter(Boolean).join(' / ') || 'タイトル要約取得に失敗しました');
}

function titleMikeNaviLinks(entry){
  const target = normalizeTitleMikeNaviEntry(entry);
  const q = buildResearchQuery(target);
  const google = `https://www.google.com/search?q=${encodeURIComponent(q)}`;
  const wiki = `https://www.google.com/search?q=${encodeURIComponent(target.title + ' ' + (target.platform || '') + ' GAVAS')}`;
  const youtube = `https://www.youtube.com/results?search_query=${encodeURIComponent(target.title + ' ' + (target.platform || '') + ' ゲーム')}`;
  const review = `https://www.google.com/search?q=${encodeURIComponent(target.title + ' ' + (target.platform || '') + ' レビュー 攻略')}`;
  return {q, google, wiki, youtube, review};
}

function descriptionRequestKey(entry){
  const target = normalizeTitleMikeNaviEntry(entry);
  const id = String(target.sharedTitleId || '').trim().toUpperCase();
  if(id) return `id:${id}`;
  const platform = normalizePlatformName(target.platform || '').toUpperCase();
  const title = titleKey(target.canonicalTitle || target.title || '');
  return `title:${platform}|${title}`;
}

function getDescriptionRequestSentMap(){
  try{
    const data = JSON.parse(localStorage.getItem(DESCRIPTION_REQUEST_SENT_KEY) || '{}');
    return data && typeof data === 'object' ? data : {};
  }catch(e){ return {}; }
}

function hasReportedMissingDescription(entry){
  return !!getDescriptionRequestSentMap()[descriptionRequestKey(entry)];
}

function markMissingDescriptionReported(entry){
  const data = getDescriptionRequestSentMap();
  data[descriptionRequestKey(entry)] = new Date().toISOString();
  const keys = Object.keys(data);
  if(keys.length > 1000){
    keys.sort((a,b) => Date.parse(data[a] || 0) - Date.parse(data[b] || 0));
    keys.slice(0, keys.length - 800).forEach(k => delete data[k]);
  }
  localStorage.setItem(DESCRIPTION_REQUEST_SENT_KEY, JSON.stringify(data));
}

function isDescriptionMissingError(error){
  if(error?.reportable || String(error?.code || '') === 'DESCRIPTION_NOT_FOUND') return true;
  const message = String(error?.message || error || '');
  return /該当タイトルが見つかりません|ゲーム概要が見つかりません|概要本文を抽出できません|説明が見つかりません/i.test(message);
}

function setDescriptionReportStatus(message, sent=false){
  const box = document.getElementById('descriptionReportStatus');
  if(!box) return;
  box.textContent = message;
  box.className = 'description-report-note' + (sent ? ' sent' : '');
}

function titleDescriptionRequestJsonp(entry, error, endpoint){
  return new Promise((resolve, reject) => {
    const cleanEndpoint = String(endpoint || '').trim();
    if(!cleanEndpoint){
      reject(new Error('共有同期URLが未設定です'));
      return;
    }

    const callback = `fujiyaDescriptionRequest_${Date.now()}_${Math.random().toString(36).slice(2)}`;
    let settled = false;
    const timer = setTimeout(() => {
      cleanup();
      reject(new Error('説明リクエスト送信がタイムアウトしました'));
    }, 22000);

    function cleanup(){
      if(settled) return;
      settled = true;
      clearTimeout(timer);
      window.fujiyaKeepLateJsonpCallback_(callback);
      document.getElementById(callback)?.remove();
    }

    window[callback] = data => {
      cleanup();
      if(data && data.ok && data.action === 'title_description_request'){
        resolve(data);
      }else{
        const detail = data && (data.message || data.error);
        reject(new Error(detail || '説明リクエスト用GASではありません'));
      }
    };

    const script = document.createElement('script');
    script.id = callback;
    script.onerror = () => {
      cleanup();
      reject(new Error('説明リクエスト送信先へ接続できませんでした'));
    };

    const sep = cleanEndpoint.includes('?') ? '&' : '?';
    const target = normalizeTitleMikeNaviEntry(entry);
    const params = new URLSearchParams({
      action:'title_description_request',
      sharedTitleId:String(target.sharedTitleId || ''),
      platform:String(target.platform || ''),
      title:String(target.canonicalTitle || target.title || ''),
      reporterId:getUserId(),
      reason:String(error?.message || error || '').slice(0,300),
      callback,
      _:String(Date.now())
    });
    script.src = `${cleanEndpoint}${sep}${params.toString()}`;
    document.body.appendChild(script);
  });
}

async function reportMissingDescription(entry, error){
  if(!isDescriptionMissingError(error)) return {reportable:false};
  const key = descriptionRequestKey(entry);
  if(hasReportedMissingDescription(entry)) return {ok:true, duplicate:true, local:true};
  if(DESCRIPTION_REQUEST_INFLIGHT.has(key)) return DESCRIPTION_REQUEST_INFLIGHT.get(key);

  const promise = (async () => {
    try{
      const endpoints = [...new Set([
        getGasEndpoint(),
        DEFAULT_GAS_ENDPOINT
      ].map(v => String(v || '').trim()).filter(Boolean))];
      if(!endpoints.length) throw new Error('共有同期URLが未設定です');

      const errors = [];
      for(const endpoint of endpoints){
        try{
          const data = await titleDescriptionRequestJsonp(entry, error, endpoint);
          markMissingDescriptionReported(entry);
          return data;
        }catch(e){
          errors.push(String(e && e.message ? e.message : e));
        }
      }
      throw new Error(errors.filter(Boolean).join(' / ') || '説明リクエストを送信できませんでした');
    }finally{
      DESCRIPTION_REQUEST_INFLIGHT.delete(key);
    }
  })();
  DESCRIPTION_REQUEST_INFLIGHT.set(key, promise);
  return promise;
}

function scheduleMissingDescriptionReport(entry, error){
  if(!isDescriptionMissingError(error)) return;
  if(hasReportedMissingDescription(entry)){
    setDescriptionReportStatus('このタイトルは店長へ報告済みだよ。', true);
    return;
  }
  setDescriptionReportStatus('説明未登録として店長へ自動報告しているよ…');
  reportMissingDescription(entry, error).then(data => {
    const count = Number(data?.request_count || 0);
    setDescriptionReportStatus(`店長へ報告したよ。${count ? ` 現在${count}件のリクエストがあるよ。` : ''}`, true);
  }).catch(err => {
    console.warn('description request failed', err);
    setDescriptionReportStatus('自動報告を確認できなかったよ。次に開いた時にもう一度試すよ。');
  });
}

