async function showTitleMiteRecoNavi(entry, actionBarHtml, cap='MIKE NAVI × MITERECO'){
  const target = mikeNaviMiteRecoTarget(entry);
  const requestId = ++mikeRecoNaviRequestSeq;
  showMikeTalkHtml(`
    <div class="title-mike-navi points-only mike-mitereco-navi">
      <div class="title-mike-navi-cap">${esc(cap)}</div>
      <div class="talk-title">みてレコ「${esc(target.title || 'タイトル未設定')}」</div>
      ${actionBarHtml}
      <div class="mike-mitereco-loading">紐づいている競技を確認中だよ…</div>
    </div>
  `);
  try{
    const competitions = typeof window.miteRecoGetCompetitionsForTitle === 'function'
      ? await window.miteRecoGetCompetitionsForTitle(target)
      : [];
    if(requestId !== mikeRecoNaviRequestSeq) return;
    showMikeTalkHtml(`
      <div class="title-mike-navi points-only mike-mitereco-navi">
        <div class="title-mike-navi-cap">${esc(cap)}</div>
        <div class="talk-title">みてレコ「${esc(target.title || 'タイトル未設定')}」</div>
        ${actionBarHtml}
        ${competitions.length ? `
          <div class="mike-mitereco-summary"><strong>${competitions.length}件</strong><span>このタイトルに紐づく競技</span></div>
          ${mikeRecoNaviCompetitionCards(competitions)}
          ${mikeRecoNaviCreateButton(target, '新しい競技も作る')}
        ` : `
          <div class="mike-mitereco-empty"><strong>まだ競技がありません</strong><span>最初の競技を作ると、このタイトルのみけナビからすぐ参加できるようになります。</span></div>
          ${mikeRecoNaviCreateButton(target)}
        `}
      </div>
    `);
  }catch(error){
    if(requestId !== mikeRecoNaviRequestSeq) return;
    showMikeTalkHtml(`
      <div class="title-mike-navi points-only mike-mitereco-navi">
        <div class="title-mike-navi-cap">${esc(cap)}</div>
        <div class="talk-title">みてレコ「${esc(target.title || 'タイトル未設定')}」</div>
        ${actionBarHtml}
        <div class="mike-mitereco-empty"><strong>競技を取得できませんでした</strong><span>${esc(String(error?.message || error || '通信状態を確認してください'))}</span></div>
        ${mikeRecoNaviCreateButton(target)}
      </div>
    `);
  }
}
