function renderShoppingRecommendations(){
  const summary = $('recommendSummary');
  const masterBox = $('recommendMasterList');
  const wantBox = $('recommendWantList');
  const nearBox = $('recommendNearCompleteList');
  const genreBox = $('recommendGenreList');
  const cleanupBox = $('recommendCleanupList');
  if(!summary && !masterBox && !wantBox && !nearBox && !genreBox && !cleanupBox) return;

  const profile = favoriteProfile();
  renderRecommendationPreferenceSettings();
  const recs = scoredRecommendationMasters(100);
  const wants = wantEntries(100);
  const near = nearCompleteMissingMasters(100);
  const genre = highRatedGenreMissingMasters(100);
  const cleanup = cleanupRecommendationEntries(100);

  if(summary){
    const bits = [];
    bits.push(profile.effectiveGenres.length ? `好みジャンル：${profile.effectiveGenres.join('・')}` : '好みジャンル：未判定');
    bits.push(profile.effectiveMakers.length ? `好みメーカー：${profile.effectiveMakers.join('・')}` : '好みメーカー：未判定');
    bits.push(`おすすめ候補：${recs.length}`);
    bits.push(`欲しい：${wants.length}`);
    bits.push(`整理候補：${cleanup.length}`);
    summary.innerHTML = bits.map(b => `<span>${esc(b)}</span>`).join('');
  }

  if(masterBox) masterBox.innerHTML = renderRecommendationMasterList(recs.slice(0,3)) + dataRankingMoreButton('personal_recommend',recs.length,'recommend');
  if(wantBox) wantBox.innerHTML = renderEntryMiniList(wants.slice(0,3)) + dataRankingMoreButton('want',wants.length,'recommend');
  if(nearBox) nearBox.innerHTML = renderRecommendationMasterList(near.slice(0,3)) + dataRankingMoreButton('near',near.length,'recommend');
  if(genreBox) genreBox.innerHTML = renderRecommendationMasterList(genre.slice(0,3)) + dataRankingMoreButton('genre',genre.length,'recommend');
  if(cleanupBox) cleanupBox.innerHTML = renderCleanupList(cleanup.slice(0,3)) + dataRankingMoreButton('cleanup',cleanup.length,'recommend');
  bindDataRankingButtons(document.getElementById('recommendPanel')||document);
}

function recommendAdvice(){
  const profile = favoriteProfile();
  const recs = scoredRecommendationMasters(3);
  const near = nearCompleteMissingMasters(3);
  const cleanup = cleanupRecommendationEntries(3);
  const lines = [];
  if(profile.effectiveGenres.length || profile.effectiveMakers.length){
    lines.push(`今の好みは${[profile.effectiveGenres.length && `ジャンル:${profile.effectiveGenres.join('・')}`, profile.effectiveMakers.length && `メーカー:${profile.effectiveMakers.join('・')}`].filter(Boolean).join(' / ')}寄りだよ。`);
  }else{
    lines.push('★4以上の評価が増えると、好みからおすすめを出しやすくなるよ。');
  }
  if(recs.length) lines.push(`おすすめ未所持は「${recs[0].canonicalTitle}」あたりが候補だよ。`);
  if(near.length) lines.push(`コンプ狙いなら「${near[0].platform}」の未所持を埋めるのが近道だよ。`);
  if(cleanup.length) lines.push(`整理候補も${cleanup.length}件あるよ。写真・購入情報・評価を埋めると管理が強くなるよ。`);
  return lines.join('\n');
}

function updateDexControls(){
  const p = $('dexPlatformSelect');
  const s = $('dexStatusSelect');
  const sort = $('dexSortSelect');
  const q = $('dexSearchInput');
  if(p) p.value = state.dexPlatform || '';
  if(s) s.value = state.dexStatus || 'all';
  if(sort) sort.value = state.dexSort || 'master';
  if(q && q.value !== (state.dexSearch || '')) q.value = state.dexSearch || '';

  state.dexRanges = sanitizeDexRanges(state.dexRanges || {});
  const inputMap = {
    clearMin:'dexClearMin', clearMax:'dexClearMax',
    ratingMin:'dexRatingMin', ratingMax:'dexRatingMax',
    ownedMin:'dexOwnedMin', ownedMax:'dexOwnedMax',
    priceMin:'dexPriceMin', priceMax:'dexPriceMax'
  };
  Object.entries(inputMap).forEach(([key,id]) => {
    const input = $(id);
    const value = state.dexRanges[key] || '';
    if(input && input.value !== value) input.value = value;
  });
  const count = activeDexRangeCount();
  const summary = $('dexRangeSummary');
  if(summary){
    summary.textContent = count ? `${count}項目指定中` : '未指定';
    summary.classList.toggle('active', count > 0);
  }
  const details = $('dexRangeFilter');
  if(details && count > 0) details.open = true;

  const compactSummary = $('dexMobileFilterSummaryText');
  if(compactSummary){
    const platformText = p?.selectedOptions?.[0]?.textContent || '全機種';
    const statusText = s?.selectedOptions?.[0]?.textContent || '全部';
    const sortText = sort?.selectedOptions?.[0]?.textContent || '図鑑順';
    const extras = [];
    if((state.dexSearch || '').trim()) extras.push('検索中');
    if(count > 0) extras.push(`範囲${count}`);
    compactSummary.textContent = [
      platformText,
      statusText,
      sortText,
      ...extras
    ].join('｜');
  }
}

function renderDexCard(row, index){
  const m = row.master;
  const e = row.entry;
  const owned = !!(e && e.owned);
  const want = !!(e && !e.owned);
  const rare = row.rare;
  const baseClass = owned ? 'owned' : (want ? 'want' : 'missing');
  const rareClass = rare?.level === 'ultra' ? ' ultra' : (rare ? ' rare' : '');
  const cls = `${baseClass}${rareClass}`;
  const statusPillHtml = owned
    ? '<span class="pill owned">所持</span>'
    : (want ? '<span class="pill want">欲しい</span>' : '');
  const meta = [m.releaseDate ? fmtDateOnly(m.releaseDate) : m.rawReleaseDate, m.maker, m.genre, m.productCode].filter(Boolean).join(' / ');
  const ratingText = e ? (ratingNumber(e.rating) ? ratingStars(e.rating) : '未評価') : '';
  const sharedTitleId = (e && e.sharedTitleId) || m.sharedTitleId || '';
  const sharedStat = sharedTitleId ? (state.remoteStats[sharedTitleId] || null) : null;
  const sharedRatingCount = Number(sharedStat && sharedStat.rating_count || 0);
  const sharedRatingAvg = Number(sharedStat && sharedStat.rating_avg || 0);
  const sharedRatingLabel = sharedRatingCount > 0
    ? `★${sharedRatingAvg.toFixed(1)}（${sharedRatingCount}）`
    : '☆－';
  const sharedRatingClass = sharedRatingCount > 0 ? '' : ' empty';
  const sharedWant = remoteWishlistDemandInfo(sharedTitleId);
  const sharedWantLabel = sharedWant.available
    ? `${sharedWant.count.toLocaleString('ja-JP')}人`
    : '－';
  const sharedWantClass = sharedWant.available ? (sharedWant.count > 0 ? '' : ' zero') : ' empty';
  const sharedWantTitle = sharedWant.available
    ? `匿名共有でこのタイトルを欲しいもの登録している人数：${sharedWant.count}人`
    : '欲しい人数は共有データ更新後に表示されます';
  const sharedClearRange = sharedClearTimeRange(sharedStat);
  const sharedClearAvailable = !!sharedClearRange;
  const sharedClearLabel = sharedClearAvailable ? `⏱${sharedClearRange.estimate}` : '⏱－';
  const sharedClearClass = !sharedClearAvailable ? ' empty' : (sharedClearRange.reference ? ' reference' : '');
  const sharedClearTitle = sharedClearAvailable
    ? `${sharedClearRange.reference ? '参考値' : 'クリア目安'} ${sharedClearRange.estimate} / ${sharedClearRange.count}件`
    : 'クリア目安はまだありません';

  return `
    <div class="dex-card ${cls}" data-dex-shared-id="${esc(m.sharedTitleId || '')}">
      <div class="dex-no-row">
        <div class="dex-no"><span class="dex-id">${esc(m.sharedTitleId || `${m.platform}-${index+1}`)}</span><span class="dex-platform-name">${esc(m.platform || '')}</span></div>
        <span class="dex-clear-time-chip${sharedClearClass}" title="${esc(sharedClearTitle)}" aria-label="${esc(sharedClearTitle)} ${esc(sharedClearLabel)}">${esc(sharedClearLabel)}</span>
      </div>
      <div class="dex-title-row">
        <div class="dex-title">${esc(m.canonicalTitle || '')}</div>
        <div class="dex-title-insights">
          <span class="dex-shared-rating-chip${sharedRatingClass}" title="共有平均レート / 評価件数" aria-label="共有平均レート ${esc(sharedRatingLabel)}">${esc(sharedRatingLabel)}</span>
        </div>
      </div>
      <div class="dex-mobile-metrics">
        <div class="dex-mobile-metric clear${sharedClearClass}" title="${esc(sharedClearTitle)}">
          <span>クリア</span>
          <strong>${esc(sharedClearAvailable ? sharedClearRange.estimate : '－')}</strong>
        </div>
        <div class="dex-mobile-metric rating${sharedRatingClass}" title="共有平均レート / 評価件数">
          <span>評価</span>
          <strong>${esc(sharedRatingLabel)}</strong>
        </div>
      </div>
      <div class="dex-meta">${esc(meta || 'マスター情報なし')}</div>
      ${dexSharedRateHtml(m, e)}
      <div class="dex-shared-demand${sharedWantClass}" title="${esc(sharedWantTitle)}" aria-label="${esc(sharedWantTitle)}">
        <span>欲しい人</span><strong>${esc(sharedWantLabel)}</strong>
      </div>
      ${dexSharedPurchasePriceBlock(m, e)}
      <div class="dex-pills tcg-main-pills">
        ${statusPillHtml}
        ${ratingText ? `<span class="pill rating"><span class="rating-stars">${esc(ratingText)}</span></span>` : ''}
        ${e ? completeBadgeHtml(e) : ''}
        ${e ? collectionBadgeHtml(e) : ''}
        ${rareBadgeHtmlFromInfo(rare)}
      </div>
      <div class="dex-actions dex-unified-actions">
        <button type="button" class="dex-detail-btn" data-dex-detail="${esc(m.sharedTitleId || '')}">詳細</button>
        ${owned ? `<button type="button" class="dex-want-btn done" disabled>所持済み</button>` : (want ? `<button type="button" class="dex-want-btn remove" data-dex-wishlist="${esc(m.sharedTitleId)}">欲しい解除</button>` : `<button type="button" class="dex-want-btn" data-dex-wishlist="${esc(m.sharedTitleId)}">欲しい</button>`)}
        <button type="button" class="dex-mikenavi-btn" data-dex-navi="${esc(m.sharedTitleId || '')}" data-dex-title="${esc(m.canonicalTitle || '')}" data-dex-platform="${esc(m.platform || '')}" onclick="window.fujiyaDexNavi('${dexNaviJs(m.sharedTitleId || '')}','${dexNaviJs(m.canonicalTitle || '')}','${dexNaviJs(m.platform || '')}')">みけナビ</button>
      </div>
    </div>
  `;
}

function renderDexPanel(){
  const summary = $('dexSummary');
  const grid = $('dexGrid');
  const info = $('dexInfo');
  const moreWrap = $('dexLoadMoreWrap');
  const moreBtn = $('dexLoadMoreBtn');
  const resultBar = $('dexResultBar');
  if(!summary || !grid) return;

  updateDexControls();

  const masterReady = Array.isArray(MASTER_TITLES) && MASTER_TITLES.length >= 1000;
  if(!masterReady){
    summary.innerHTML = `
      <div class="dex-stat dex-master-summary-loading">
        <div class="num">準備中</div>
        <div class="label">図鑑データを読み込んでいます</div>
      </div>
    `;
    if(info){
      info.textContent = '初回のみ約17,000件の図鑑データを端末へ保存します。通信状況によって少し時間がかかります。';
    }
    const dexLoadProgress = (()=>{try{return window.fujiyaGetTitleMasterProgress?.()||{};}catch(error){return {};}})();
    const dexLoadTotal = Math.max(0,Number(dexLoadProgress.total)||0);
    const dexLoadReceived = Math.max(0,Number(dexLoadProgress.received)||0);
    const dexLoadPercent = Math.max(0,Math.min(100,Number.isFinite(Number(dexLoadProgress.percent))?Number(dexLoadProgress.percent):(dexLoadTotal?Math.round(dexLoadReceived/dexLoadTotal*100):0)));
    const dexLoadMessage = String(dexLoadProgress.message||'保存済みデータを確認しています…');
    grid.innerHTML = `
      <div class="dex-master-loading" role="status" aria-live="polite">
        <div class="dex-master-loading-icon" aria-hidden="true">▦</div>
        <strong>図鑑を準備しています</strong>
        <span id="dexMasterLoadingDetail">${esc(dexLoadMessage)}</span>
        <div class="dex-master-progress" id="dexMasterProgress" aria-label="図鑑データ準備の進捗">
          <div class="dex-master-progress-track"><div class="dex-master-progress-fill" id="dexMasterProgressFill" style="width:${dexLoadPercent}%"></div></div>
          <div class="dex-master-progress-meta">
            <b id="dexMasterProgressPercent">${dexLoadPercent}%</b>
            <span id="dexMasterProgressCount">${dexLoadTotal?`${dexLoadReceived.toLocaleString('ja-JP')} / ${dexLoadTotal.toLocaleString('ja-JP')}件`:'準備状況を確認中'}</span>
          </div>
        </div>
        <small id="dexMasterLoadingNote">初回は約17,000件を順番に取得・保存します。時間がかかる場合も進捗が動いていればそのままお待ちください。</small>
        <button type="button" id="dexMasterRetryBtn" class="hidden">図鑑データを再取得</button>
      </div>
    `;
    const retryButton=document.getElementById('dexMasterRetryBtn');
    retryButton?.addEventListener('click',()=>{
      retryButton.classList.add('hidden');
      const detail=document.getElementById('dexMasterLoadingDetail');
      if(detail)detail.textContent='図鑑データを再取得しています…';
      try{window.fujiyaClearTitleMasterError?.();}catch(error){}
      window.__fujiyaDexMasterLoadPending=false;
      renderDexPanel();
    },{once:true});
    if(resultBar){
      resultBar.textContent = '';
      resultBar.classList.add('hidden');
    }
    if(moreWrap) moreWrap.classList.add('hidden');
    if(moreBtn) moreBtn.disabled = true;

    if(!window.__fujiyaDexMasterLoadPending){
      window.__fujiyaDexMasterLoadPending = true;
      Promise.resolve(window.fujiyaEnsureTitleMaster?.('dex',{showOverlay:false}))
        .then(ok => {
          if(ok){
            renderDexPanel();
            return;
          }
          const detail = document.getElementById('dexMasterLoadingDetail');
          let reason='';
          try{reason=String(window.fujiyaGetTitleMasterLastError?.()||'').trim();}catch(error){}
          if(detail) detail.textContent = reason
            ? `図鑑データの取得を完了できませんでした：${reason}`
            : '図鑑データを最後まで取得できませんでした。下のボタンから再試行してください。';
          const note=document.getElementById('dexMasterLoadingNote');
          if(note) note.textContent='通信エラーの場合は、原因を上に表示しています。再取得すると成功済みの取得分は同じ画面内で再利用します。';
          document.getElementById('dexMasterRetryBtn')?.classList.remove('hidden');
        })
        .catch(error => {
          const detail = document.getElementById('dexMasterLoadingDetail');
          if(detail) detail.textContent = `図鑑データを取得できませんでした：${String(error?.message || error)}`;
          document.getElementById('dexMasterRetryBtn')?.classList.remove('hidden');
        })
        .finally(() => { window.__fujiyaDexMasterLoadPending = false; });
    }
    return;
  }

  const s = dexSummaryStats();
  const rows = dexMasterRows();
  const limit = Math.max(DEX_PAGE_SIZE, Number(state.dexDisplayLimit || DEX_PAGE_SIZE));
  const shown = rows.slice(0, limit);
  const rate = s.total ? Math.round((s.owned / s.total) * 1000) / 10 : 0;
  summary.innerHTML = `
    <div class="dex-stat"><div class="num">${s.total}</div><div class="label" data-mobile-label="総数">図鑑総数</div></div>
    <div class="dex-stat"><div class="num">${s.owned}</div><div class="label" data-mobile-label="所持">所持済み</div></div>
    <div class="dex-stat"><div class="num">${s.missing}</div><div class="label" data-mobile-label="未所持">未所持</div></div>
    <div class="dex-stat"><div class="num">${s.want}</div><div class="label" data-mobile-label="欲しい">欲しい</div></div>
    <div class="dex-stat"><div class="num">${rate}%</div><div class="label" data-mobile-label="進捗">図鑑進捗</div></div>
    <div class="dex-stat"><div class="num">${s.rare}</div><div class="label" data-mobile-label="激レア">激レア</div></div>
  `;

  if(info){
    const platformText = state.dexPlatform || '全機種';
    const sortText = $('dexSortSelect')?.selectedOptions?.[0]?.textContent || '図鑑順';
    const rangeCount = activeDexRangeCount();
    const rangeText = rangeCount ? ` / 数値範囲${rangeCount}項目` : '';
    info.textContent = `${platformText} / ${rows.length}件一致 / ${shown.length}件表示 / ${sortText}${rangeText}。必要な分だけ追加表示します。`;
  }

  if(resultBar){
    const total = rows.length;
    const visible = shown.length;
    const allCount = Array.isArray(MASTER_TITLES) ? MASTER_TITLES.length : 0;
    resultBar.classList.remove('hidden');
    resultBar.innerHTML = total
      ? `<span><strong>${visible.toLocaleString('ja-JP')}</strong> / ${total.toLocaleString('ja-JP')}件表示</span>${total !== allCount ? `<small>全${allCount.toLocaleString('ja-JP')}件から絞り込み</small>` : '<small>全タイトル</small>'}`
      : '<span><strong>0</strong>件</span><small>条件に一致するタイトルなし</small>';
  }

  grid.innerHTML = shown.length
    ? shown.map(renderDexCard).join('')
    : `<div class="dex-empty-state" style="grid-column:1/-1">
        <div class="dex-empty-icon" aria-hidden="true">⌕</div>
        <strong>この条件では見つかりませんでした</strong>
        <span>検索語や絞り込み条件を変えてみてください。</span>
        <button type="button" id="dexEmptyResetBtn">条件をすべて解除</button>
      </div>`;

  $('dexEmptyResetBtn')?.addEventListener('click', resetDexFilters, {once:true});

  const hasMore = shown.length < rows.length;
  if(moreWrap) moreWrap.classList.toggle('hidden', !hasMore);
  if(moreBtn){
    const remain = Math.max(0, rows.length - shown.length);
    const next = Math.min(DEX_PAGE_SIZE, remain);
    moreBtn.innerHTML = hasMore
      ? `<strong>さらに${next.toLocaleString('ja-JP')}件表示</strong><small>残り ${remain.toLocaleString('ja-JP')}件</small>`
      : 'すべて表示済み';
    moreBtn.disabled = !hasMore;
  }
}

function dexAdvice(){
  const s = dexSummaryStats();
  if(!s.total) return 'この機種のマスター図鑑データがまだ少ないよ。';
  const rate = s.total ? Math.round((s.owned / s.total) * 1000) / 10 : 0;
  if(s.owned === 0) return 'まず所持ソフトを登録すると図鑑が埋まり始めるよ。';
  if(s.rated < s.owned) return `図鑑進捗は${rate}%だよ。評価未入力が${s.owned - s.rated}本あるから、星を付けると成長にもつながるよ。`;
  if(s.missing > 0) return `図鑑進捗は${rate}%だよ。未所持は${s.missing}本、そのうち欲しい登録は${s.want}本だよ。欲しいもの登録しても未所持数は減らないように直してあるよ。`;
  return 'この条件の図鑑はかなり埋まってるよ！次は別機種も見てみてね。';
}

function startRegisterFromMaster(sharedTitleId){
  const m = (MASTER_TITLES || []).find(x => x.sharedTitleId === sharedTitleId);
  if(!m){
    toast('図鑑タイトルが見つかりません');
    return;
  }

  navigateDirectlyToUiPage('register', {
    targetId:'entryPanel',
    focusId:'title',
    behavior:'smooth',
    block:'start'
  });

  resetForm();
  selectMaster(m.sharedTitleId);
  updateTitleKeyPreview();

  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      const panel = $('entryPanel');
      if(panel && panel.scrollIntoView){
        panel.scrollIntoView({behavior:'smooth', block:'start'});
      }
      const titleInput = $('title');
      if(titleInput && titleInput.focus){
        try{ titleInput.focus({preventScroll:true}); }
        catch(error){ titleInput.focus(); }
      }
    });
  });

  toast(`「${m.canonicalTitle}」の登録画面を開きました`);
  showMikeTalk(`図鑑から「${m.canonicalTitle}」の登録画面を開いたよ。所持状態や評価を入れて保存してね。`);
}

function toggleWishlistFromMaster(sharedTitleId){
  const m = (MASTER_TITLES || []).find(x => x.sharedTitleId === sharedTitleId);
  if(!m){
    toast('図鑑タイトルが見つかりません');
    return;
  }

  const existingIndex = (state.entries || []).findIndex(e => e.sharedTitleId === sharedTitleId);
  const existing = existingIndex >= 0 ? state.entries[existingIndex] : null;

  if(existing?.owned){
    toast('すでに所持登録済みです');
    showMikeTalk(`「${existing.title}」はすでに所持登録済みだよ。`);
    return;
  }

  if(existing && !existing.owned){
    createUndoSnapshot('図鑑ほしいもの解除の前');
    const removed = state.entries.splice(existingIndex, 1)[0];
    state.shelfEntryIds = (state.shelfEntryIds || []).filter(id => id !== removed.id);
    if(typeof saveShelf === 'function') saveShelf();
    addEventLog('delete', removed, '図鑑から欲しいものリスト解除');
    if(save()){
      render();
      toast('欲しいものリストから解除しました');
      showMikeTalk(`「${removed.title}」を欲しいものリストから解除したよ。`);
    }
    return;
  }

  const entry = norm({
    id: uid(),
    platform: m.platform || 'SFC',
    title: m.canonicalTitle || '',
    owned: false,
    rating: 0,
    releaseDate: m.releaseDate || '',
    rawReleaseDate: m.rawReleaseDate || '',
    maker: m.maker || '',
    genre: m.genre || '',
    productCode: m.productCode || '',
    remarks: m.remarks || '',
    parts: emptyParts(),
    memo: '',
    createdAt: nowIso(),
    updatedAt: nowIso(),
    titleKey: titleKey(m.canonicalTitle || ''),
    canonicalTitle: m.canonicalTitle || '',
    sharedTitleId: m.sharedTitleId || '',
    sharedStatus: 'confirmed'
  });

  createUndoSnapshot('図鑑ほしいもの登録の前');
  state.entries.unshift(hydrateEntryFromMaster(entry));
  if(save()){
    addEventLog('add', entry, '図鑑から欲しいものリスト登録');
    render();
    toast('欲しいものリストに登録しました');
    showMikeTalk(`「${entry.title}」を欲しいものリストに登録したよ。\nもう一度押すと解除できるよ。`);
  }
}


function wishlistListEntries(){
  return (state.entries || [])
    .filter(entry => entry && entry.owned === false)
    .slice()
    .sort((a,b) => {
      const pa = normalizePlatformName(a.platform || '');
      const pb = normalizePlatformName(b.platform || '');
      return pa.localeCompare(pb, 'ja') ||
        String(a.title || '').localeCompare(String(b.title || ''), 'ja');
    });
}

function renderListChoiceHub(){
  const buybackCount = $('listHubBuybackCount');
  const wishlistCount = $('listHubWishlistCount');
  if(buybackCount) buybackCount.textContent = `${buybackEntries().length}件`;
  if(wishlistCount) wishlistCount.textContent = `${wishlistListEntries().length}件`;
}

function renderWishlistListPanel(){
  const body = $('wishlistListBody');
  const count = $('wishlistListCount');
  if(!body) return;

  const rows = wishlistListEntries();
  if(count) count.textContent = `${rows.length}件`;

  if(!rows.length){
    body.innerHTML = `
      <div class="wishlist-empty">
        <strong>欲しいものはまだありません</strong>
        <span>図鑑で気になるタイトルの「欲しい」を押すと、ここに追加されます。</span>
        <button type="button" class="green" data-wishlist-go-dex>図鑑を開く</button>
      </div>
    `;
    return;
  }

  body.innerHTML = rows.map(entry => {
    const master = entry.sharedTitleId
      ? (findMasterById(entry.sharedTitleId) || findMasterBySharedTitleId(entry.sharedTitleId))
      : null;
    const title = entry.title || master?.canonicalTitle || 'タイトル未設定';
    const platform = normalizePlatformName(entry.platform || master?.platform || '') || '機種未設定';
    const maker = entry.maker || master?.maker || 'メーカー未設定';
    const genre = entry.genre || master?.genre || '';
    const sharedTitleId = entry.sharedTitleId || master?.sharedTitleId || '';
    const meta = [maker, genre].filter(Boolean).join(' / ');

    return `
      <article class="wishlist-row">
        <div class="wishlist-row-main">
          <span class="wishlist-platform">${esc(platform)}</span>
          <div class="wishlist-title-wrap">
            <strong>${esc(title)}</strong>
            <small>${esc(meta)}</small>
          </div>
        </div>
        <div class="wishlist-row-bottom">
          <div class="wishlist-row-actions">
            <button type="button" class="ghost"
              data-wishlist-detail-entry="${esc(entry.id || '')}"
              data-wishlist-detail-shared="${esc(sharedTitleId)}">詳細</button>
            <button type="button" class="ghost" data-wishlist-store="${esc(entry.id || '')}">ストアリンク</button>
            <button type="button" class="wishlist-remove-btn" data-wishlist-remove-entry="${esc(entry.id || '')}">欲しい解除</button>
          </div>
        </div>
      </article>
    `;
  }).join('');
}


function removeWishlistEntryById(entryId){
  const id = String(entryId || '').trim();
  if(!id) return;

  const index = (state.entries || []).findIndex(entry =>
    String(entry?.id || '') === id && entry?.owned === false
  );
  if(index < 0){
    toast('欲しい登録が見つかりません');
    return;
  }

  createUndoSnapshot('欲しいものリスト解除の前');
  const removed = state.entries.splice(index,1)[0];

  state.shelfEntryIds = (state.shelfEntryIds || []).filter(shelfId => shelfId !== removed.id);
  if(typeof saveShelf === 'function') saveShelf();

  addEventLog('delete', removed, '欲しいものリスト解除');

  if(save()){
    // global render() は applyUiTab() 内で listView を hub に戻すため使わない。
    // 欲しいものリストを開いたまま、必要な部分だけ更新する。
    document.body.dataset.listView = 'wishlist';
    renderWishlistListPanel();
    renderListChoiceHub();
    if(typeof renderQuickStatusBar === 'function') renderQuickStatusBar();

    toast('欲しいものリストから解除しました');

    if(typeof scheduleAutoSync === 'function'){
      scheduleAutoSync('欲しいものリスト解除');
    }
  }
}

function openWishlistDetailByEntry(entryId, sharedTitleId=''){
  const id = String(entryId || '').trim();
  const sid = String(sharedTitleId || '').trim();

  /* 現行DBなら図鑑詳細を優先 */
  const currentMaster = sid
    ? (findMasterById(sid) || findMasterBySharedTitleId(sid))
    : null;

  if(currentMaster && typeof openDexDetail === 'function'){
    openDexDetail(currentMaster.sharedTitleId || sid);
    return;
  }

  /* 旧DB・廃止ID・未確定IDはローカルentryの詳細を開く */
  if(id && typeof openCardDetail === 'function'){
    openCardDetail(id);
    return;
  }

  toast('詳細を開けませんでした');
}

function setListSubView(view){
  const next = ['hub','buyback','wishlist'].includes(view) ? view : 'hub';
  document.body.dataset.listView = next;

  const hub = $('listChoiceHub');
  const buyback = $('buybackPanel');
  const history = $('buybackHistoryPanel');
  const wishlist = $('wishlistListPanel');

  [hub, buyback, history, wishlist].forEach(el => {
    if(el) el.style.setProperty('display', 'none', 'important');
  });

  if(next === 'hub'){
    if(hub) hub.style.setProperty('display', 'grid', 'important');
  }else if(next === 'buyback'){
    if(buyback) buyback.style.setProperty('display', 'block', 'important');
    if(history) history.style.setProperty('display', 'block', 'important');
  }else if(next === 'wishlist'){
    if(wishlist) wishlist.style.setProperty('display', 'block', 'important');
  }

  renderListChoiceHub();

  if(next === 'buyback'){
    renderBuybackPanel();
    renderBuybackHistoryPanel();
  }else if(next === 'wishlist'){
    renderWishlistListPanel();
  }

  const target = next === 'hub'
    ? hub
    : (next === 'buyback' ? buyback : wishlist);
  requestAnimationFrame(() => {
    target?.scrollIntoView?.({behavior:'smooth', block:'start'});
  });
}

window.fujiyaSetListSubView = setListSubView;

document.addEventListener('click', ev => {
  if(ev.target.closest('#openBuybackListBtn')){
    setListSubView('buyback');
    return;
  }
  if(ev.target.closest('#openWishlistListBtn')){
    setListSubView('wishlist');
    return;
  }
  if(ev.target.closest('#wishlistBackToHubBtn') || ev.target.closest('[data-buyback-back-hub]')){
    setListSubView('hub');
    return;
  }
  if(ev.target.closest('[data-wishlist-go-dex]')){
    setUiTab('dex');
    return;
  }

  const detail = ev.target.closest('[data-wishlist-detail-entry]');
  if(detail){
    openWishlistDetailByEntry(
      detail.dataset.wishlistDetailEntry || '',
      detail.dataset.wishlistDetailShared || ''
    );
    return;
  }

  const store = ev.target.closest('[data-wishlist-store]');
  if(store){
    const id = store.dataset.wishlistStore || '';
    if(id) showMarketLinks(id);
    return;
  }

  const remove = ev.target.closest('[data-wishlist-remove-entry]');
  if(remove){
    removeWishlistEntryById(remove.dataset.wishlistRemoveEntry || '');
    return;
  }
});


