async function resizeImage(file){
  const data = await new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });

  const img = await new Promise((resolve, reject) => {
    const image = new Image();
    image.onload = () => resolve(image);
    image.onerror = reject;
    image.src = data;
  });

  let {width, height} = img;
  const scale = Math.min(1, MAX_IMAGE_SIDE / Math.max(width, height));
  width = Math.round(width * scale);
  height = Math.round(height * scale);

  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  canvas.getContext('2d').drawImage(img, 0, 0, width, height);
  return canvas.toDataURL('image/jpeg', JPEG_QUALITY);
}

function editEntry(id){
  const e = state.entries.find(x => x.id === id);
  if(!e) return;

  $('editId').value = e.id;
  $('platform').value = normalizePlatformName(e.platform);
  updatePlatformShareNote();
  $('title').value = e.title;
  updateTitleKeyPreview();
  const master = e.sharedTitleId ? findMasterById(e.sharedTitleId) : null;
  if(master) selectMaster(master.sharedTitleId);
  else clearMasterSelection(false);
  $('releaseDate').value = e.releaseDate || master?.releaseDate || '';
  $('maker').value = e.maker || master?.maker || '';
  $('purchaseDate').value = e.purchaseDate || '';
  $('purchasePrice').value = e.purchasePrice || '';
  $('purchaseStore').value = e.purchaseStore || '';
  if($('overallCondition')) $('overallCondition').value = e.overallCondition || '';
  if($('operationChecked')) $('operationChecked').checked = !!e.operationChecked;
  if($('buybackOperationStatus')) $('buybackOperationStatus').value = buybackOperationStatusValue(e);
  if($('cleaned')) $('cleaned').checked = !!e.cleaned;
  if($('stockLocation')) $('stockLocation').value = e.stockLocation || '';
  if($('marketMemo')) $('marketMemo').value = e.marketMemo || '';
  $('memo').value = e.memo || '';
  document.querySelector(`input[name="owned"][value="${e.owned ? 'owned' : 'want'}"]`).checked = true;
  const mediaRadio = document.querySelector(`input[name="mediaType"][value="${normalizeMediaType(e.mediaType)}"]`);
  if(mediaRadio) mediaRadio.checked = true;
  $('rating').value = String(ratingNumber(e.rating));
  if($('playStatus')) $('playStatus').value = normalizePlayStatus(e.playStatus);
  if($('clearHours')) $('clearHours').value = normalizeClearHours(e.clearHours);
  updateClearTimeInputState();
  if($('accessoryRequired')) $('accessoryRequired').checked = !!e.accessoryRequired;
  setPartsForm(e.parts);

  state.photoData = '';
  state.removePhoto = false;
  state.photoViewX = Math.max(-80,Math.min(80,Number(e.photoViewX||0)||0));
  state.photoViewY = Math.max(-80,Math.min(80,Number(e.photoViewY||0)||0));
  state.photoViewScale = Math.max(1,Math.min(2.5,Number(e.photoViewScale||1)||1));
  state.photoViewRotate = normalizePhotoRotate(e.photoViewRotate||e.photo_view_rotate||0);
  state.photoViewSet = e.photoViewSet===true||e.photoViewSet==='1';
  state.photoPreviewShape = 'list';
  $('photo').value = '';

  if(e.photoData){
    $('photoPreview').src = e.photoData;
    $('photoPreview').style.display = 'block';
  }else{
    $('photoPreview').src = '';
    $('photoPreview').style.display = 'none';
  }
  window.fujiyaPhotoAdjustSync?.();

  $('formTitle').textContent = 'ソフト編集';
  $('saveBtn').textContent = '変更内容を保存する';
  $('editActions').classList.remove('hidden');
  updatePurchaseShareTarget();
  updateEntrySaveState();
  const panel = $('entryPanel');
  if(panel && panel.scrollIntoView){
    requestAnimationFrame(() => panel.scrollIntoView({behavior:'smooth', block:'start'}));
  }
}

function openEditEntry(id){
  const entryId = String(id || '');
  if(!entryId) return;

  // 編集は必ず「登録 > かんたん登録 > 詳細入力」の画面へ入る。
  // カード/一覧の委譲クリックは window.fujiyaEdit を経由しないため、
  // openEditEntry 自体で詳細モードを確定させる。
  navigateDirectlyToUiPage('register', {
    targetId:'entryPanel',
    behavior:'smooth',
    block:'start'
  });
  window.fujiyaSetEntryMode?.('detail');

  // タブ切替・スマホ表示切替の描画が終わってから編集値を入れ、
  // editId 設定後にもう一度 detail を適用して「登録内容を編集」表示へ更新する。
  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      editEntry(entryId);
      window.fujiyaSetEntryMode?.('detail');
      updateEntrySaveState();
      const panel = document.getElementById('entryPanel');
      if(panel && panel.scrollIntoView){
        panel.scrollIntoView({behavior:'smooth', block:'start'});
      }
    });
  });
}


function deleteEntriesWithRestore(entries, representative, detail='コレクションから削除'){
  const targets = (entries || []).filter(Boolean);
  if(!targets.length){
    toast('削除対象が見つかりません');
    return false;
  }

  const ids = new Set(targets.map(e => String(e.id)));
  recordDeviceSyncDeletion(targets);
  const restoreEntries = targets.map(cloneEntryForRestoreLog);
  const restoreShelfEntryIds = (state.shelfEntryIds || []).filter(id => ids.has(String(id)));

  state.entries = (state.entries || []).filter(e => !ids.has(String(e.id)));
  state.shelfEntryIds = (state.shelfEntryIds || []).filter(id => !ids.has(String(id)));
  saveShelf();

  addEventLog('delete', representative || targets[0], detail, {
    skipUndoSnapshotId: true,
    restoreMode: 'deleted_entries',
    restoreEntries,
    restoreShelfEntryIds
  });

  const saved = saveCoreDataOnly();
  if(saved){
    if(ids.has(String($('editId')?.value || ''))) resetForm();
    closeCardDetail();
    render();
    toast(`${targets.length}件を削除しました`);
    showMikeTalk(buildEventTalk('delete', representative || targets[0]));
    scheduleAutoSync('削除反映');
    return true;
  }

  // 保存に失敗した場合は画面上だけでも戻して、ズレを防ぐ
  state.entries = [...restoreEntries.map(norm).map(ensureSharedFields).map(hydrateEntryFromMaster), ...(state.entries || [])];
  state.shelfEntryIds = Array.from(new Set([...(state.shelfEntryIds || []), ...restoreShelfEntryIds])).slice(0,24);
  saveShelf();
  render();
  return false;
}

async function deleteCardGroup(id){
  if(window.__fujiyaDeletingEntry) return;
  window.__fujiyaDeletingEntry = true;
  try{
    const entry = state.entries.find(x => String(x.id) === String(id));
    if(!entry){
      toast('削除対象が見つかりません');
      return;
    }

    const group = sameTitleEntries(entry).filter(e => !!e.owned);
    if(group.length <= 1){
      const ok = await askDeleteConfirm(`「${entry.title}」を削除しますか？\n\n削除後もログの「復元」から戻せます。`);
      if(!ok) return;
      deleteEntriesWithRestore([entry], entry, 'コレクションから削除');
      return;
    }

    const ok = await askDeleteConfirm(`このカードは「${entry.title}」の所持${group.length}件分をまとめて表示しています。\n\nカードごと消すため、同タイトルの所持${group.length}件をすべて削除しますか？\n\n削除後もログの「復元」から戻せます。`);
    if(!ok) return;
    deleteEntriesWithRestore(group, entry, `カードごと削除：${group.length}件`);
  }finally{
    window.__fujiyaDeletingEntry = false;
  }
}

async function deleteEntry(id, skipConfirm=false){
  if(window.__fujiyaDeletingEntry) return;
  window.__fujiyaDeletingEntry = true;
  try{
    const entry = state.entries.find(x => String(x.id) === String(id));
    if(!entry){
      toast('削除対象が見つかりません');
      return;
    }

    if(!skipConfirm){
      const ok = await askDeleteConfirm(`「${entry.title}」を削除しますか？\n\n削除後もログの「復元」から戻せます。`);
      if(!ok) return;
    }

    deleteEntriesWithRestore([entry], entry, 'コレクションから削除');
  }finally{
    window.__fujiyaDeletingEntry = false;
  }
}

