function dl(name, text, type='text/plain'){
  const blob = new Blob([text], {type});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = name;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

function csvEsc(v){
  return `"${String(v ?? '').replaceAll('"','""')}"`;
}

function parseCsvLine(line){
  const result = [];
  let current = '';
  let quoted = false;

  for(let i=0; i<line.length; i++){
    const ch = line[i];
    const next = line[i+1];

    if(ch === '"' && quoted && next === '"'){
      current += '"';
      i++;
    }else if(ch === '"'){
      quoted = !quoted;
    }else if(ch === ',' && !quoted){
      result.push(current);
      current = '';
    }else{
      current += ch;
    }
  }
  result.push(current);
  return result;
}

function yes(v){
  return ['1','true','TRUE','所持','あり','有'].includes(String(v || '').trim());
}


function handleCardActionClick(ev){
  const btn = ev.target.closest('#cards button[data-action]');
  if(!btn) return false;
  ev.preventDefault();
  ev.stopPropagation();
  if(typeof ev.stopImmediatePropagation === 'function') ev.stopImmediatePropagation();
  const id = btn.dataset.id;
  const action = btn.dataset.action;
  if(action === 'detail'){ openCardDetail(id); return true; }
  if(action === 'edit'){ openEditEntry(id); return true; }
  if(action === 'shelf'){ toggleShelfEntry(id); return true; }
  if(action === 'rematch'){ openRematchModal(id); return true; }
  if(action === 'talk'){ talkEntry(id); return true; }
  if(action === 'market'){ showMarketLinks(id); return true; }
  if(action === 'addcopy'){ addOneCopyFromEntry(id); return true; }
  if(action === 'delete'){ deleteCardGroup(id); return true; }
  return false;
}


const SHEET_IMPORT_FIELDS = [
  {key:'title',label:'タイトル',required:true,aliases:['タイトル','ゲーム名','ソフト名','name','title']},
  {key:'platform',label:'機種',required:true,aliases:['機種','ハード','platform','hardware']},
  {key:'mediaType',label:'版の種類',aliases:['版の種類','所有形態','メディア','パッケージdl','media_type','format']},
  {key:'owned',label:'所持区分',aliases:['所持区分','所持','owned','status']},
  {key:'rating',label:'評価',aliases:['評価','rating','rate']},
  {key:'playStatus',label:'プレイ状況',aliases:['プレイ状況','play_status']},
  {key:'clearHours',label:'クリア時間',aliases:['クリア時間','clear_hours']},
  {key:'purchaseDate',label:'購入日',aliases:['購入日','purchase_date']},
  {key:'purchasePrice',label:'購入価格',aliases:['購入価格','価格','purchase_price']},
  {key:'purchaseStore',label:'購入店舗',aliases:['購入店舗','店舗','purchase_store']},
  {key:'overallCondition',label:'総合状態',aliases:['総合状態','状態','condition']},
  {key:'releaseDate',label:'発売日',aliases:['発売日','release_date']},
  {key:'maker',label:'メーカー',aliases:['メーカー','maker']},
  {key:'sharedTitleId',label:'共有タイトルID',aliases:['共有タイトルid','shared_title_id']},
  {key:'romHas',label:'ROMあり',aliases:['rom','romあり','rom_has']},
  {key:'romCondition',label:'ROM状態',aliases:['rom状態','rom_condition']},
  {key:'boxHas',label:'箱あり',aliases:['箱','ケース','箱あり','box_has']},
  {key:'boxCondition',label:'箱状態',aliases:['箱状態','box_condition']},
  {key:'manualHas',label:'説明書あり',aliases:['説明書','取説','manual_has']},
  {key:'manualCondition',label:'説明書状態',aliases:['説明書状態','manual_condition']},
  {key:'accessoryHas',label:'付属品あり',aliases:['付属品','accessory_has']},
  {key:'accessoryCondition',label:'付属品状態',aliases:['付属品状態','accessory_condition']},
  {key:'accessoryRequired',label:'付属品必須',aliases:['付属品必須','accessory_required']},
  {key:'memo',label:'メモ',aliases:['メモ','備考','memo','note']}
];

function sheetImportHeaderKey(value){
  return titleKey(String(value || '')).replace(/[＿_]/g,'');
}
function sheetImportAutoMap(headers){
  const normalized = (headers || []).map(sheetImportHeaderKey);
  const mapping = {};
  SHEET_IMPORT_FIELDS.forEach(field => {
    const aliases = [field.label, ...(field.aliases || [])].map(sheetImportHeaderKey);
    const index = normalized.findIndex(header => aliases.includes(header));
    mapping[field.key] = index >= 0 ? String(index) : '';
  });
  return mapping;
}
function sheetImportMappedValue(row, key){
  const index = Number(sheetImportState.mapping?.[key]);
  if(!Number.isInteger(index) || index < 0) return '';
  return String(row?.[index] ?? '').trim();
}
function sheetImportNormalizePlatform(value){
  return normalizePlatformName(String(value || '').trim());
}
function sheetImportOwned(value){
  const raw = String(value || '').trim().toLowerCase();
  if(['欲しい','want','wanted','0','false','no'].includes(raw)) return false;
  return true;
}
function sheetImportRating(value){return ratingNumber(value);}
function sheetImportDate(value){
  const raw=String(value||'').trim();
  if(!raw) return '';
  const normalized=raw.replace(/[./]/g,'-');
  const match=normalized.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if(!match) return '';
  return `${match[1]}-${String(match[2]).padStart(2,'0')}-${String(match[3]).padStart(2,'0')}`;
}
function sheetImportPrice(value){
  const n=String(value||'').replace(/[^0-9-]/g,'');
  return n && Number.isFinite(Number(n)) ? String(Math.max(0,Number(n))) : '';
}
function sheetImportCondition(value){
  const raw=String(value||'').trim().toUpperCase();
  return ['S','A','B','C','J'].includes(raw) ? raw : '';
}
function sheetImportTruthy(value){
  return ['1','true','yes','y','所持','あり','有','○','〇','◯','完品'].includes(String(value||'').trim().toLowerCase());
}
function sheetImportParts(row){
  const part=(hasKey,conditionKey,defaultHas=false)=>({
    has: sheetImportState.mapping?.[hasKey] === '' || sheetImportState.mapping?.[hasKey] == null ? defaultHas : sheetImportTruthy(sheetImportMappedValue(row,hasKey)),
    condition: sheetImportCondition(sheetImportMappedValue(row,conditionKey))
  });
  return {
    rom:part('romHas','romCondition',true),
    box:part('boxHas','boxCondition',false),
    manual:part('manualHas','manualCondition',false),
    accessory:part('accessoryHas','accessoryCondition',false)
  };
}
function sheetImportParseDelimited(text, delimiter){
  const rows=[]; let row=[]; let field=''; let quoted=false;
  const source=String(text||'').replace(/^\uFEFF/,'');
  for(let i=0;i<source.length;i++){
    const ch=source[i], next=source[i+1];
    if(ch==='"' && quoted && next==='"'){field+='"';i++;continue;}
    if(ch==='"'){quoted=!quoted;continue;}
    if(ch===delimiter && !quoted){row.push(field);field='';continue;}
    if((ch==='\n' || ch==='\r') && !quoted){
      if(ch==='\r' && next==='\n') i++;
      row.push(field);field='';
      if(row.some(cell=>String(cell).trim())) rows.push(row);
      row=[];continue;
    }
    field+=ch;
  }
  row.push(field);
  if(row.some(cell=>String(cell).trim())) rows.push(row);
  return rows;
}
function sheetImportDetectHeaderRow(all){
  const rows=Array.isArray(all)?all:[];
  const aliasKeys=new Set();
  SHEET_IMPORT_FIELDS.forEach(field=>{
    [field.label,...(field.aliases||[])].forEach(value=>{
      const key=sheetImportHeaderKey(value);
      if(key)aliasKeys.add(key);
    });
  });
  let bestIndex=-1;
  let bestScore=0;
  const limit=Math.min(rows.length,20);
  for(let i=0;i<limit;i++){
    const cells=(rows[i]||[]).map(value=>String(value||'').trim());
    const nonEmpty=cells.filter(Boolean).length;
    if(nonEmpty<2)continue;
    let matches=0;
    let requiredLike=0;
    cells.forEach(cell=>{
      const key=sheetImportHeaderKey(cell);
      if(aliasKeys.has(key))matches++;
      if(['機種','platform','ハード','タイトル','title','ゲーム名','ソフト名'].map(sheetImportHeaderKey).includes(key))requiredLike++;
    });
    const score=matches*10+requiredLike*8+Math.min(nonEmpty,6);
    if(matches>=2 && requiredLike>=1 && score>bestScore){bestScore=score;bestIndex=i;}
  }
  return bestIndex;
}
function sheetImportReadRows(){
  const text=String($('sheetImportText')?.value||'');
  const firstLine=(text.split(/\r?\n/,1)[0]||'');
  const delimiter=(firstLine.split('\t').length>firstLine.split(',').length)?'\t':',';
  const all=sheetImportParseDelimited(text,delimiter);
  const useHeader=!!$('sheetImportHasHeader')?.checked;
  const maxCols=Math.max(0,...all.map(row=>row.length));
  const detectedHeaderIndex=useHeader?sheetImportDetectHeaderRow(all):-1;
  const headers=detectedHeaderIndex>=0
    ? Array.from({length:maxCols},(_,index)=>String(all[detectedHeaderIndex]?.[index]||'').trim()||`列${index+1}`)
    : Array.from({length:maxCols},(_,index)=>`列${index+1}`);
  const sourceRows=detectedHeaderIndex>=0?all.slice(detectedHeaderIndex+1):all;
  const rows=sourceRows.map(row=>Array.from({length:maxCols},(_,index)=>String(row[index]??'')));
  return {headers,rows,delimiter,headerRowIndex:detectedHeaderIndex};
}

const sheetImportState = {
  headers: [],
  rows: [],
  mapping: {},
  preview: [],
  delimiter: ',',
  analyzing: false,
  analysisToken: 0,
  processingToken: ''
};

let sheetImportMasterLookup = null;
let sheetImportMasterLookupPromise = null;
const sheetImportFastCandidateCache = new Map();

function sheetImportBucketKey(value){
  const key = titleKey(value);
  if(!key) return '';
  return key.slice(0, Math.min(3,key.length));
}

function sheetImportLookupAdd(map,key,row){
  if(!key) return;
  if(!map.has(key)) map.set(key,[]);
  const rows = map.get(key);
  if(!rows.includes(row)) rows.push(row);
}

async function ensureSheetImportMasterLookup(processingToken=''){
  if(sheetImportMasterLookup) return sheetImportMasterLookup;
  if(sheetImportMasterLookupPromise) return sheetImportMasterLookupPromise;

  sheetImportMasterLookupPromise = (async () => {
    const exactByPlatform = new Map();
    const exactAny = new Map();
    const bucketByPlatform = new Map();
    const bucketAny = new Map();
    const source = MASTER_TITLES || [];
    let sliceStarted = typeof performance !== 'undefined' && performance.now ? performance.now() : Date.now();

    for(let i=0;i<source.length;i++){
      const master = source[i];
      const platform = normalizePlatformName(master?.platform || '');
      const titleKeys = Array.from(new Set(
        [master?.canonicalTitle || '', ...((master?.aliases || []))]
          .map(titleKey)
          .filter(Boolean)
      ));
      const row = {master,platform,titleKeys};
      const buckets = new Set();
      titleKeys.forEach(key => {
        sheetImportLookupAdd(exactAny,key,row);
        sheetImportLookupAdd(exactByPlatform,`${platform}|${key}`,row);
        const bucket = sheetImportBucketKey(key);
        if(bucket) buckets.add(bucket);
      });
      buckets.forEach(bucket => {
        sheetImportLookupAdd(bucketAny,bucket,row);
        sheetImportLookupAdd(bucketByPlatform,`${platform}|${bucket}`,row);
      });

      if((i + 1) % 160 === 0 || fujiyaTimeSliceExpired(sliceStarted)){
        if(processingToken){
          window.fujiyaProcessing?.update(processingToken,{
            title:'CSV用タイトル索引を準備しています',
            detail:'完全一致と近い候補を高速に探せるよう準備しています。',
            current:i + 1,
            total:source.length
          });
        }
        await fujiyaYieldToBrowser();
        sliceStarted = typeof performance !== 'undefined' && performance.now ? performance.now() : Date.now();
      }
    }

    sheetImportMasterLookup = {exactByPlatform,exactAny,bucketByPlatform,bucketAny};
    return sheetImportMasterLookup;
  })();

  try{return await sheetImportMasterLookupPromise;}
  finally{sheetImportMasterLookupPromise = null;}
}

function sheetImportYield(){
  return fujiyaYieldToBrowser();
}

function sheetImportFastCandidate(title, platform){
  const qKey = titleKey(title);
  const normalizedPlatform = normalizePlatformName(platform || '');
  if(!qKey || !sheetImportMasterLookup) return null;

  const cacheKey = `${normalizedPlatform || '*'}|${qKey}`;
  if(sheetImportFastCandidateCache.has(cacheKey)) return sheetImportFastCandidateCache.get(cacheKey);

  const bucket = sheetImportBucketKey(qKey);
  let pool = normalizedPlatform
    ? (sheetImportMasterLookup.bucketByPlatform.get(`${normalizedPlatform}|${bucket}`) || [])
    : (sheetImportMasterLookup.bucketAny.get(bucket) || []);
  if(pool.length > 800) pool = pool.slice(0,800);

  let best = null;
  let bestScore = 0;
  for(const row of pool){
    let score = 0;
    for(const key of row.titleKeys){
      if(key === qKey){score=400;break;}
      if(qKey.length >= 2 && key.includes(qKey)) score=Math.max(score,230+Math.min(45,qKey.length*3));
      else if(key.length >= 3 && qKey.includes(key)) score=Math.max(score,170+Math.min(35,key.length*2));
    }
    if(score > bestScore){bestScore=score;best=row.master;if(score>=400)break;}
  }

  const result = bestScore >= 170 ? best : null;
  sheetImportFastCandidateCache.set(cacheKey,result);
  if(sheetImportFastCandidateCache.size > 500){
    const first = sheetImportFastCandidateCache.keys().next().value;
    sheetImportFastCandidateCache.delete(first);
  }
  return result;
}

function sheetImportFastCandidates(title, platform, limit=12){
  const qKey = titleKey(title);
  const normalizedPlatform = normalizePlatformName(platform || '');
  if(!qKey || !sheetImportMasterLookup) return [];
  const bucket = sheetImportBucketKey(qKey);
  let pool = normalizedPlatform
    ? (sheetImportMasterLookup.bucketByPlatform.get(`${normalizedPlatform}|${bucket}`) || [])
    : (sheetImportMasterLookup.bucketAny.get(bucket) || []);
  if(pool.length > 900) pool = pool.slice(0,900);

  return pool.map(row => {
    let score = 0;
    for(const key of row.titleKeys){
      if(key === qKey){score=400;break;}
      if(qKey.length >= 2 && key.includes(qKey)) score=Math.max(score,230+Math.min(45,qKey.length*3));
      else if(key.length >= 3 && qKey.includes(key)) score=Math.max(score,170+Math.min(35,key.length*2));
      else{
        const commonPrefix = [...qKey].findIndex((ch,index) => key[index] !== ch);
        const prefixLength = commonPrefix < 0 ? Math.min(qKey.length,key.length) : commonPrefix;
        if(prefixLength >= 3) score=Math.max(score,90+prefixLength*6);
      }
    }
    if(normalizedPlatform && row.platform === normalizedPlatform) score += 25;
    return {...row.master,_candidateScore:score};
  }).filter(master => master._candidateScore >= 90)
    .sort((a,b) => b._candidateScore-a._candidateScore || String(a.canonicalTitle||'').localeCompare(String(b.canonicalTitle||''),'ja'))
    .slice(0,Math.max(1,Number(limit)||12));
}

function sheetImportExactMaster(title, platform, sharedTitleId=''){
  const sid = String(sharedTitleId || '').trim();
  if(sid){
    const byId = findMasterById(sid);
    if(byId) return {status:'confirmed', master:byId, note:'共有タイトルIDで確定'};
  }

  const key = titleKey(title);
  if(!key) return {status:'error', note:'タイトルが空です'};
  if(!sheetImportMasterLookup) return {status:'unconfirmed', note:'タイトル索引を準備中です'};

  const normalizedPlatform = normalizePlatformName(platform || '');
  const platformRows = normalizedPlatform
    ? (sheetImportMasterLookup.exactByPlatform.get(`${normalizedPlatform}|${key}`) || [])
    : [];
  const anyRows = sheetImportMasterLookup.exactAny.get(key) || [];

  if(platformRows.length === 1) return {status:'confirmed', master:platformRows[0].master, note:'タイトルと機種で確定'};
  if(!normalizedPlatform && anyRows.length === 1) return {status:'confirmed', master:anyRows[0].master, note:'タイトル一致で確定'};

  const candidate = sheetImportFastCandidate(title, normalizedPlatform);
  if(candidate) return {status:'candidate', candidate, note:'近い候補あり。未確定として取り込み'};
  return {status:'unconfirmed', note:'図鑑候補なし。ローカル保存'};
}
function sheetImportBuildEntry(row){
  const title = sheetImportMappedValue(row, 'title');
  const rawPlatform = sheetImportMappedValue(row, 'platform');
  let platform = sheetImportNormalizePlatform(rawPlatform);
  const sharedTitleId = sheetImportMappedValue(row, 'sharedTitleId');
  let match = sheetImportExactMaster(title, platform, sharedTitleId);
  if(!platform){
    const titleOnlyMatch=sheetImportExactMaster(title,'',sharedTitleId);
    if(titleOnlyMatch.status==='confirmed' && titleOnlyMatch.master){
      platform=titleOnlyMatch.master.platform;
      match={...titleOnlyMatch,note:'タイトルから機種も確定'};
    }else{
      return {entry:null, match:{status:'error', note:'機種列が空です。', candidate:titleOnlyMatch.candidate||null}};
    }
  }
  const parts = sheetImportParts(row);

  let entry = norm({
    id: uid(),
    platform,
    title,
    owned: sheetImportOwned(sheetImportMappedValue(row, 'owned')),
    mediaType: normalizeMediaType(sheetImportMappedValue(row, 'mediaType') || 'package'),
    rating: sheetImportRating(sheetImportMappedValue(row, 'rating')),
    playStatus: normalizePlayStatus(sheetImportMappedValue(row, 'playStatus')),
    clearHours: normalizeClearHours(sheetImportMappedValue(row, 'clearHours')),
    purchaseDate: sheetImportDate(sheetImportMappedValue(row, 'purchaseDate')),
    purchasePrice: sheetImportPrice(sheetImportMappedValue(row, 'purchasePrice')),
    purchaseStore: sheetImportMappedValue(row, 'purchaseStore'),
    overallCondition: sheetImportCondition(sheetImportMappedValue(row, 'overallCondition')),
    releaseDate: sheetImportDate(sheetImportMappedValue(row, 'releaseDate')),
    maker: sheetImportMappedValue(row, 'maker'),
    memo: sheetImportMappedValue(row, 'memo'),
    parts,
    photoData:'',
    createdAt: nowIso(),
    updatedAt: nowIso(),
    sharedTitleId:'',
    titleKey:titleKey(title),
    canonicalTitle:title,
    sharedStatus:'unconfirmed',
    localSharedId:''
  });

  if(match.status === 'confirmed' && match.master){
    const m = match.master;
    entry.title = m.canonicalTitle;
    entry.platform = m.platform;
    entry.titleKey = titleKey(m.canonicalTitle);
    entry.canonicalTitle = m.canonicalTitle;
    entry.sharedTitleId = m.sharedTitleId;
    entry.sharedStatus = 'confirmed';
    entry.localSharedId = '';
    entry.releaseDate = entry.releaseDate || m.releaseDate || '';
    entry.rawReleaseDate = m.rawReleaseDate || '';
    entry.maker = entry.maker || m.maker || '';
    entry.genre = m.genre || '';
    entry.productCode = m.productCode || '';
    entry.remarks = m.remarks || '';
  }

  entry = hydrateEntryFromMaster(ensureSharedFields(entry));

  return {entry, match};
}

async function sheetImportBuildPreview(){
  const token = ++sheetImportState.analysisToken;
  const preview = [];
  const skipDupes = !!$('sheetImportSkipDupes')?.checked;
  const seen = new Set();
  const existingKeys = new Set(
    (state.entries || []).map(entry =>
      `${normalizePlatformName(entry.platform || '')}::${entry.titleKey || titleKey(entry.title || '')}::${normalizeMediaType(entry.mediaType)}`
    )
  );
  const total = sheetImportState.rows.length;
  const statusBox = $('sheetImportStatus');
  const processingToken = sheetImportState.processingToken;

  sheetImportState.analyzing = true;
  await ensureSheetImportMasterLookup(processingToken);
  if(token !== sheetImportState.analysisToken) return null;
  if(processingToken){
    window.fujiyaProcessing?.update(processingToken,{
      title:'CSVを解析しています',
      detail:`タイトル・機種・重複・図鑑候補を確認しています。`,
      current:0,
      total
    });
  }

  for(let i=0; i<total; i++){
    if(token !== sheetImportState.analysisToken) return null;

    const row = sheetImportState.rows[i];
    const rawTitle = sheetImportMappedValue(row, 'title');
    const rawPlatform = sheetImportMappedValue(row, 'platform');
    if(!rawTitle && row.every(c => !String(c || '').trim())) continue;

    if(!rawTitle){
      preview.push({index:i+1, status:'error', title:'', platform:'', note:'タイトル列が空です', entry:null});
    }else{
      const built = sheetImportBuildEntry(row);
      const e = built.entry;
      if(!e){
        preview.push({index:i+1,status:'error',title:rawTitle,rawTitle,rawPlatform,platform:rawPlatform,candidateMaster:built.match?.candidate || null,candidate:built.match?.candidate ? `${built.match.candidate.platform} / ${built.match.candidate.canonicalTitle}` : '',note:built.match?.note || '機種を確認してください',entry:null});
      }else{
        const dupeKey = `${normalizePlatformName(e.platform || '')}::${e.titleKey || titleKey(e.title)}::${normalizeMediaType(e.mediaType)}`;
        const existing = existingKeys.has(dupeKey);
        const batchDupe = seen.has(dupeKey);
        seen.add(dupeKey);

        let rowStatus = built.match.status;
        let note = built.match.note || '';
        if((existing || batchDupe) && skipDupes){
          rowStatus = 'duplicate';
          note = existing ? '既存登録と重複するためスキップ' : '取り込みデータ内で重複するためスキップ';
        }

        preview.push({
          index:i+1,
          status:rowStatus,
          title:e.title,
          rawTitle,
          platform:e.platform,
          sharedTitleId:e.sharedTitleId || '',
          candidateMaster: built.match.candidate || null,
          candidate: built.match.candidate ? `${built.match.candidate.platform} / ${built.match.candidate.canonicalTitle}` : '',
          note,
          entry:e
        });
      }
    }

    if((i + 1) % 20 === 0){
      if(statusBox){
        statusBox.textContent = `解析中… ${i + 1}/${total}件`;
        statusBox.classList.add('is-loading');
      }
      if(processingToken){
        window.fujiyaProcessing?.update(processingToken,{
          detail:`タイトル・機種・重複・図鑑候補を確認しています。`,
          current:i + 1,
          total
        });
      }
      await sheetImportYield();
    }
  }

  if(token !== sheetImportState.analysisToken) return null;
  sheetImportState.preview = preview;
  sheetImportState.analyzing = false;
  statusBox?.classList.remove('is-loading');
  if(processingToken){
    window.fujiyaProcessing?.update(processingToken,{
      detail:'解析結果を画面へ反映しています。',
      current:total,
      total
    });
  }
  return preview;
}

function renderSheetImportMapping(){
  const box = $('sheetImportMapping');
  if(!box) return;
  const headers = sheetImportState.headers || [];
  if(!headers.length){
    box.innerHTML = '';
    return;
  }

  const optionLabel=(header,index)=>`${index + 1}列目：${String(header || '').trim() || '（項目名なし）'}`;
  box.innerHTML = `
    <div class="sheet-import-map-guide">
      <strong>各項目が元CSVの何列目にあるか指定</strong>
      <span>例：タイトル → 2列目「タイトル」 / 機種 → 3列目「機種」。自動判定できた項目は選択済みです。</span>
    </div>
    <div class="sheet-import-map-grid">
      ${SHEET_IMPORT_FIELDS.map(field => `
        <div class="sheet-import-map-item ${field.required ? 'required' : ''}">
          <label><span>${esc(field.label)}${field.required ? ' *' : ''}</span><small>← 元CSVの列</small></label>
          <select data-sheet-import-field="${esc(field.key)}" aria-label="${esc(field.label)}に対応する元CSVの列">
            <option value="">使わない</option>
            ${headers.map((h, i) => `<option value="${i}" ${String(sheetImportState.mapping[field.key] ?? '') === String(i) ? 'selected' : ''}>${esc(optionLabel(h,i))}</option>`).join('')}
          </select>
        </div>
      `).join('')}
    </div>
  `;
}


function sheetImportPreviewFindRow(rowIndex){
  return (sheetImportState.preview || []).find(row => Number(row.index) === Number(rowIndex)) || null;
}

function sheetImportPreviewBuildEntryWithMaster(previewRow, master){
  if(!previewRow || !master) return null;
  let entry = previewRow.entry ? {...previewRow.entry, parts: JSON.parse(JSON.stringify(previewRow.entry.parts || {}))} : null;
  if(!entry){
    const sourceRow = (sheetImportState.rows || [])[Math.max(0, Number(previewRow.index || 1) - 1)] || [];
    const parts = sheetImportParts(sourceRow);
    const rawTitle = sheetImportMappedValue(sourceRow, 'title') || previewRow.rawTitle || master.canonicalTitle;
    entry = norm({
      id: uid(),
      platform: master.platform,
      title: rawTitle,
      owned: sheetImportOwned(sheetImportMappedValue(sourceRow, 'owned')),
      mediaType: normalizeMediaType(sheetImportMappedValue(sourceRow, 'mediaType') || 'package'),
      rating: sheetImportRating(sheetImportMappedValue(sourceRow, 'rating')),
      playStatus: normalizePlayStatus(sheetImportMappedValue(sourceRow, 'playStatus')),
      clearHours: normalizeClearHours(sheetImportMappedValue(sourceRow, 'clearHours')),
      purchaseDate: sheetImportDate(sheetImportMappedValue(sourceRow, 'purchaseDate')),
      purchasePrice: sheetImportPrice(sheetImportMappedValue(sourceRow, 'purchasePrice')),
      purchaseStore: sheetImportMappedValue(sourceRow, 'purchaseStore'),
      overallCondition: sheetImportCondition(sheetImportMappedValue(sourceRow, 'overallCondition')),
      releaseDate: sheetImportDate(sheetImportMappedValue(sourceRow, 'releaseDate')),
      maker: sheetImportMappedValue(sourceRow, 'maker'),
      memo: sheetImportMappedValue(sourceRow, 'memo'),
      parts,
      photoData:'',
      createdAt: nowIso(),
      updatedAt: nowIso(),
      sharedTitleId:'',
      titleKey:titleKey(rawTitle),
      canonicalTitle:rawTitle,
      sharedStatus:'unconfirmed',
      localSharedId:''
    });
  }
  bulkRematchApplyMasterToEntry(entry, master);
  return hydrateEntryFromMaster(ensureSharedFields(entry));
}

function sheetImportPreviewApplyMaster(rowIndex, master){
  const row = sheetImportPreviewFindRow(rowIndex);
  if(!row || !master){
    toast('確定するDB候補が見つかりません');
    return false;
  }
  const entry = sheetImportPreviewBuildEntryWithMaster(row, master);
  if(!entry){
    toast('候補を反映できませんでした');
    return false;
  }
  row.entry = entry;
  row.status = 'confirmed';
  row.title = entry.title;
  row.rawTitle = row.rawTitle || entry.title;
  row.platform = entry.platform;
  row.rawPlatform = row.rawPlatform || '';
  row.sharedTitleId = entry.sharedTitleId || '';
  row.candidateMaster = null;
  row.candidate = '';
  row.note = '取込前にDB照合して確定';
  renderSheetImportPreview();
  toast(`「${entry.title}」で確定しました`);
  return true;
}

function sheetImportPreviewCandidateOption(master, selected=false){
  if(!master) return '';
  const sub = [master.platform, master.canonicalTitle, master.maker || '', master.releaseDate || master.rawReleaseDate || ''].filter(Boolean).join(' / ');
  return `<option value="${esc(master.sharedTitleId)}" ${selected ? 'selected' : ''}>${esc(sub)}</option>`;
}


let sheetImportManualSearchIndexRC1446 = null;
const sheetImportManualSearchCacheRC1446 = new Map();
function sheetImportManualCandidatesRC1446(query, platform='', limit=20){
  const raw=String(query||'').trim();
  const qKey=candidateTitleKey(raw);
  if(!qKey) return [];
  const normalizedPlatform=normalizePlatformName(platform||'');
  const cacheKey=`${normalizedPlatform||'*'}|${qKey}|${limit}`;
  if(sheetImportManualSearchCacheRC1446.has(cacheKey)) return sheetImportManualSearchCacheRC1446.get(cacheKey).slice();
  if(!sheetImportManualSearchIndexRC1446){
    sheetImportManualSearchIndexRC1446=(MASTER_TITLES||[]).map(master=>({
      master,
      platform:normalizePlatformName(master?.platform||''),
      keys:Array.from(new Set([master?.canonicalTitle||'',...((master?.aliases||[]))].map(candidateTitleKey).filter(Boolean)))
    }));
  }
  const scored=[];
  for(const row of sheetImportManualSearchIndexRC1446){
    let score=0;
    for(const key of row.keys){
      if(key===qKey){score=Math.max(score,1200);break;}
      if(key.startsWith(qKey)) score=Math.max(score,1000 + Math.min(120,qKey.length*5));
      else if(qKey.length>=2 && key.includes(qKey)) score=Math.max(score,900 + Math.min(100,qKey.length*4));
      else if(key.length>=2 && qKey.includes(key)) score=Math.max(score,650 + Math.min(80,key.length*3));
    }
    if(score>0){
      if(normalizedPlatform && row.platform===normalizedPlatform) score+=130;
      else if(normalizedPlatform && row.platform!==normalizedPlatform) score-=20;
      scored.push({master:row.master,score});
    }
  }
  scored.sort((a,b)=>b.score-a.score || String(a.master?.platform||'').localeCompare(String(b.master?.platform||''),'ja') || String(a.master?.canonicalTitle||'').localeCompare(String(b.master?.canonicalTitle||''),'ja'));
  const out=[];
  const seen=new Set();
  for(const item of scored){
    const id=String(item.master?.sharedTitleId||'');
    if(!id || seen.has(id)) continue;
    seen.add(id);
    out.push(item.master);
    if(out.length>=limit) break;
  }
  if(out.length<Math.min(limit,8)){
    const fuzzy=findMasterCandidatesLoose(raw,normalizedPlatform,Math.max(limit,15));
    for(const master of fuzzy){
      const id=String(master?.sharedTitleId||'');
      if(!id || seen.has(id)) continue;
      seen.add(id);
      out.push(master);
      if(out.length>=limit) break;
    }
  }
  sheetImportManualSearchCacheRC1446.set(cacheKey,out.slice());
  if(sheetImportManualSearchCacheRC1446.size>300){
    const first=sheetImportManualSearchCacheRC1446.keys().next().value;
    sheetImportManualSearchCacheRC1446.delete(first);
  }
  return out;
}

function sheetImportPreviewFillSuggestions(rowIndex, query){
  const row = sheetImportPreviewFindRow(rowIndex);
  const select = document.querySelector(`[data-sheet-import-precheck-select="${CSS.escape(String(rowIndex))}"]`);
  const note = document.querySelector(`[data-sheet-import-precheck-note="${CSS.escape(String(rowIndex))}"]`);
  if(!row || !select) return;
  const q = String(query || '').trim();
  row.manualQuery = q;
  if(!q){
    row.manualCandidates=[];
    select.innerHTML = '<option value="">タイトルを入力するとDB候補を表示</option>';
    if(note) note.textContent = 'タイトルの一部だけでも検索できます。';
    return;
  }
  const platform = normalizePlatformName(row.platform || row.rawPlatform || '');
  let candidates = sheetImportManualCandidatesRC1446(q, platform, 20);
  if(row.candidateMaster){
    const sid=String(row.candidateMaster.sharedTitleId||'');
    candidates=[row.candidateMaster,...candidates.filter(m=>String(m.sharedTitleId||'')!==sid)];
  }
  row.manualCandidates = candidates;
  select.innerHTML = candidates.length
    ? '<option value="">候補を選択</option>' + candidates.map((m,i)=>sheetImportPreviewCandidateOption(m,i===0)).join('')
    : '<option value="">候補なし</option>';
  if(candidates.length) select.value = candidates[0].sharedTitleId;
  if(note) note.textContent = candidates.length ? `部分一致を含む候補 ${candidates.length}件` : '候補が見つかりません。タイトルの一部だけでも検索できます。';
}

function sheetImportPreviewReconcileHtml(row){
  if(!row || row.status === 'confirmed' || row.status === 'duplicate') return '<span class="sheet-import-precheck-done">—</span>';
  const suggested = row.candidateMaster;
  const rawQuery = String(row.manualQuery || row.rawTitle || row.title || '').trim();
  let candidates = rawQuery ? sheetImportManualCandidatesRC1446(rawQuery, row.platform || row.rawPlatform || '', 14) : [];
  if(suggested){
    const sid=String(suggested.sharedTitleId||'');
    candidates=[suggested,...candidates.filter(m=>String(m.sharedTitleId||'')!==sid)];
  }
  row.manualCandidates=candidates;
  const query = esc(rawQuery);
  return `
    <div class="sheet-import-precheck" data-sheet-import-precheck="${row.index}">
      ${suggested ? `<button type="button" class="sheet-import-precheck-suggested" data-sheet-import-confirm-suggested="${row.index}">この候補で確定：${esc(suggested.platform)} / ${esc(suggested.canonicalTitle)}</button>` : ''}
      <div class="sheet-import-precheck-search">
        <input type="text" data-sheet-import-precheck-query="${row.index}" value="${query}" placeholder="タイトルの一部を入力してDB検索">
        <select data-sheet-import-precheck-select="${row.index}">
          ${candidates.length ? '<option value="">候補を選択</option>' + candidates.map((m,i)=>sheetImportPreviewCandidateOption(m,i===0)).join('') : '<option value="">候補なし</option>'}
        </select>
        <button type="button" class="ghost" data-sheet-import-confirm-selected="${row.index}">選択候補で確定</button>
      </div>
      <small data-sheet-import-precheck-note="${row.index}">${candidates.length ? `タイトルの一部を含む候補を${candidates.length}件表示しています。` : 'タイトルの一部だけでも検索できます。'}</small>
    </div>`;
}

function renderSheetImportPreview(){
  const box = $('sheetImportPreview');
  const status = $('sheetImportStatus');
  const runBtn = $('sheetImportRunBtn');
  if(!box || !status) return;

  const preview = sheetImportState.preview || [];
  if(!preview.length){
    box.innerHTML = '';
    status.textContent = '解析結果がありません。';
    if(runBtn) runBtn.disabled = true;
    return;
  }

  const counts = preview.reduce((acc, r) => {
    acc.total++;
    acc[r.status] = (acc[r.status] || 0) + 1;
    return acc;
  }, {total:0, confirmed:0, candidate:0, unconfirmed:0, duplicate:0, error:0});

  const importable = preview.filter(r => r.entry && r.status !== 'error' && r.status !== 'duplicate').length;
  if(runBtn) runBtn.disabled = importable <= 0;
  status.textContent = `解析済み：${counts.total}件 / 取り込み可能 ${importable}件 / 確定 ${counts.confirmed || 0}件 / 候補 ${counts.candidate || 0}件 / 未確定 ${counts.unconfirmed || 0}件 / 重複 ${counts.duplicate || 0}件 / エラー ${counts.error || 0}件`;

  const rows = preview.slice(0, 120);
  box.innerHTML = `
    <div class="sheet-import-precheck-guide"><strong>取込前に照合できます</strong><span>候補ありはその候補で確定できます。未確定・エラーも、タイトルの一部を入力するとDB候補を予測表示します。</span></div>
    <div class="sheet-import-summary-grid">
      <div class="sheet-import-summary-card"><strong>${counts.total}</strong><span>解析件数</span></div>
      <div class="sheet-import-summary-card"><strong>${counts.confirmed || 0}</strong><span>図鑑確定</span></div>
      <div class="sheet-import-summary-card"><strong>${counts.candidate || 0}</strong><span>候補あり</span></div>
      <div class="sheet-import-summary-card"><strong>${counts.unconfirmed || 0}</strong><span>未確定</span></div>
      <div class="sheet-import-summary-card"><strong>${counts.duplicate || 0}</strong><span>重複スキップ</span></div>
    </div>
    <div class="sheet-import-table-wrap">
      <table class="sheet-import-table sheet-import-table-precheck">
        <thead><tr><th>No.</th><th>状態</th><th>機種</th><th>タイトル</th><th>共有ID/候補</th><th>メモ</th></tr></thead>
        <tbody>
          ${rows.map(r => {
            const needs = r.status !== 'confirmed' && r.status !== 'duplicate';
            return `
              <tr class="sheet-import-main-row">
                <td>${r.index}</td>
                <td><span class="sheet-import-chip ${esc(r.status)}">${esc(sheetImportStatusLabel(r.status))}</span></td>
                <td>${esc(r.platform || r.rawPlatform || '')}</td>
                <td>${esc(r.title || r.rawTitle || '')}</td>
                <td>${esc(r.sharedTitleId || r.candidate || '—')}</td>
                <td><div class="sheet-import-row-note">${esc(r.note || '')}</div></td>
              </tr>
              ${needs ? `<tr class="sheet-import-precheck-row"><td colspan="6">${sheetImportPreviewReconcileHtml(r)}</td></tr>` : ''}`;
          }).join('')}
        </tbody>
      </table>
    </div>
    ${preview.length > rows.length ? `<div class="sheet-import-status">表示は先頭${rows.length}件までです。取り込み対象は全${preview.length}件です。</div>` : ''}
  `;
}

function sheetImportStatusLabel(status){
  return {
    confirmed:'確定',
    candidate:'候補',
    unconfirmed:'未確定',
    duplicate:'重複',
    error:'エラー'
  }[status] || status;
}

async function sheetImportRefreshPreview(){
  const ownProcessing = !sheetImportState.processingToken;
  const processingToken = ownProcessing
    ? window.fujiyaProcessing?.start({
        title:'CSVを再解析しています',
        detail:'列の対応や取り込み条件の変更を反映しています。',
        total:sheetImportState.rows.length
      })
    : sheetImportState.processingToken;

  if(ownProcessing){
    sheetImportState.processingToken = processingToken || '';
    await window.fujiyaProcessing?.paint?.();
  }

  try{
    const mapping = {};
    document.querySelectorAll('[data-sheet-import-field]').forEach(sel => {
      mapping[sel.dataset.sheetImportField] = sel.value;
    });
    sheetImportState.mapping = mapping;

    const preview = await sheetImportBuildPreview();
    if(preview === null) return false;
    renderSheetImportPreview();
    return true;
  }finally{
    if(ownProcessing){
      window.fujiyaProcessing?.end(processingToken);
      if(sheetImportState.processingToken === processingToken) sheetImportState.processingToken = '';
    }
  }
}

async function parseSheetImportInput(){
  const parseBtn = $('sheetImportParseBtn');
  const runBtn = $('sheetImportRunBtn');
  const statusBox = $('sheetImportStatus');
  const processingToken = window.fujiyaProcessing?.start({
    title:'CSVを読み込んでいます',
    detail:'行と列を確認しています。',
    progressText:'準備中'
  }) || '';
  sheetImportState.processingToken = processingToken;
  await window.fujiyaProcessing?.paint?.();

  if(sheetImportState.analyzing){
    sheetImportState.analysisToken += 1;
    await sheetImportYield();
  }

  if(parseBtn){
    parseBtn.disabled = true;
    parseBtn.textContent = '解析中…';
  }
  if(runBtn) runBtn.disabled = true;
  if(statusBox){
    statusBox.textContent = 'CSV / TSVを読み込んでいます…';
    statusBox.classList.add('is-loading');
  }

  try{
    window.fujiyaProcessing?.update(processingToken,{
      title:'CSVを読み込んでいます',
      detail:'CSV / TSVの行と列を解析しています。',
      progressText:'ファイル解析中'
    });
    const read = sheetImportReadRows();
    sheetImportState.headers = read.headers;
    sheetImportState.rows = read.rows;
    sheetImportState.delimiter = read.delimiter;
    sheetImportState.mapping = sheetImportAutoMap(read.headers);
    sheetImportState.preview = [];

    renderSheetImportMapping();
    await sheetImportYield();
    const completed = await sheetImportRefreshPreview();
    if(!completed) return;

    if(!read.rows.length){
      toast('取り込みデータが見つかりません');
    }else{
      toast(`取り込み候補 ${read.rows.length}件を解析しました`);
    }
  }finally{
    sheetImportState.analyzing = false;
    statusBox?.classList.remove('is-loading');
    if(parseBtn){
      parseBtn.disabled = false;
      parseBtn.textContent = '解析する';
    }
    window.fujiyaProcessing?.end(processingToken);
    if(sheetImportState.processingToken === processingToken) sheetImportState.processingToken = '';
  }
}

async function runSheetImport(){
  if(sheetImportState.analyzing){
    toast('解析が終わるまでお待ちください');
    return;
  }

  const processingToken = window.fujiyaProcessing?.start({
    title:'CSVデータを取り込んでいます',
    detail:'登録可能な行と重複を確認しています。',
    total:(sheetImportState.preview || []).length || sheetImportState.rows.length
  }) || '';
  sheetImportState.processingToken = processingToken;
  await window.fujiyaProcessing?.paint?.();

  try{
  createUndoSnapshot('スプレッドシート取り込みの前');
  if(!sheetImportState.preview.length){
    const completed = await sheetImportRefreshPreview();
    if(!completed) return;
  }

  const allowUnconfirmed = !!$('sheetImportAllowUnconfirmed')?.checked;
  const imported = [];
  let skipped = 0;
  const existingKeys = new Set(
    (state.entries || []).map(entry =>
      `${normalizePlatformName(entry.platform || '')}::${entry.titleKey || titleKey(entry.title || '')}::${normalizeMediaType(entry.mediaType)}`
    )
  );

  const previewRows = sheetImportState.preview || [];
  for(let rowIndex=0; rowIndex<previewRows.length; rowIndex++){
    const row = previewRows[rowIndex];
    if(!row.entry || row.status === 'error' || row.status === 'duplicate'){
      skipped++;
      continue;
    }
    if(!allowUnconfirmed && (row.status === 'candidate' || row.status === 'unconfirmed')){
      skipped++;
      continue;
    }

    const key = `${normalizePlatformName(row.entry.platform || '')}::${row.entry.titleKey || titleKey(row.entry.title || '')}::${normalizeMediaType(row.entry.mediaType)}`;
    if(existingKeys.has(key)){
      skipped++;
      continue;
    }
    existingKeys.add(key);
    imported.push(row.entry);

    if((rowIndex + 1) % 120 === 0){
      window.fujiyaProcessing?.update(processingToken,{
        detail:'登録可能な行と重複を確認しています。',
        current:rowIndex + 1,
        total:previewRows.length
      });
      await sheetImportYield();
    }
  }

  window.fujiyaProcessing?.update(processingToken,{
    title:'コレクションへ保存しています',
    detail:`${imported.length.toLocaleString('ja-JP')}件の登録データを保存しています。`,
    current:previewRows.length,
    total:previewRows.length
  });
  await window.fujiyaProcessing?.paint?.();

  if(!imported.length){
    toast('取り込みできる行がありません');
    return;
  }

  state.entries = imported.concat(state.entries || []);

  if(save()){
    addEventLog('add', imported[0], `スプレッドシート取り込み：${imported.length}件`);
    imported.slice(0, 50).forEach(e => addRareLogIfNeeded(e, 'スプレッドシート取り込みでレア判定'));
    render();
    scheduleAutoSync('スプレッドシート取り込み');
    toast(`${imported.length}件を取り込みました`);
    showMikeTalk(`スプレッドシートから${imported.length}件取り込んだよ。\nスキップ：${skipped}件\n未確定のものは、あとから編集・再照合で共有IDに紐づけできるよ。`);
    setUiTab('list', {scroll:true});
  }
  }finally{
    window.fujiyaProcessing?.end(processingToken);
    if(sheetImportState.processingToken === processingToken) sheetImportState.processingToken = '';
  }
}

function bindSheetImportEvents(){
  const parseBtn = $('sheetImportParseBtn');
  if(!parseBtn) return;

  parseBtn.addEventListener('click', parseSheetImportInput);
  $('sheetImportRunBtn')?.addEventListener('click', runSheetImport);
  $('sheetImportClearBtn')?.addEventListener('click', () => {
    sheetImportState.analysisToken += 1;
    sheetImportState.analyzing = false;
    if(sheetImportState.processingToken){
      window.fujiyaProcessing?.end(sheetImportState.processingToken);
      sheetImportState.processingToken = '';
    }
    $('sheetImportText').value = '';
    $('sheetImportFile').value = '';
    sheetImportState.headers = [];
    sheetImportState.rows = [];
    sheetImportState.mapping = {};
    sheetImportState.preview = [];
    $('sheetImportStatus').textContent = '未解析です。';
    $('sheetImportMapping').innerHTML = '';
    $('sheetImportPreview').innerHTML = '';
    $('sheetImportRunBtn').disabled = true;
    toast('取り込み欄をクリアしました');
  });
  $('sheetImportSampleBtn')?.addEventListener('click', () => {
    $('sheetImportText').value = [
      '機種\tタイトル\t箱\t説明書\t状態\t購入価格\t購入店舗\tメモ',
      'SFC\tクロノ・トリガー\tあり\tあり\tA\t3800\t藤や玩具店\tサンプル',
      'FC\tスーパーマリオブラザーズ\tなし\tなし\tB\t1200\tメルカリ\t',
      'GB\tポケットモンスター 赤\tあり\tあり\t完品\t2500\t駿河屋\t'
    ].join('\n');
    parseSheetImportInput();
  });
  $('sheetImportTalkBtn')?.addEventListener('click', () => {
    showMikeTalk('スプレッドシートの範囲をコピーして貼り付けるか、CSVファイルを読み込むよ。\n解析後に「タイトル」「機種」などの対応を確認してから取り込みを実行してね。\n共有IDが確定できないものはローカル保存できるよ。');
  });
  $('sheetImportFile')?.addEventListener('change', ev => {
    const file = ev.target.files?.[0];
    if(!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      $('sheetImportText').value = String(reader.result || '');
      parseSheetImportInput();
    };
    reader.onerror = () => toast('CSVファイルの読み込みに失敗しました');
    reader.readAsText(file, 'UTF-8');
  });
  $('sheetImportMapping')?.addEventListener('change', ev => {
    if(ev.target && ev.target.matches('[data-sheet-import-field]')){
      sheetImportRefreshPreview();
    }
  });
  let sheetImportSuggestTimer = null;
  $('sheetImportPreview')?.addEventListener('input', ev => {
    const input = ev.target?.closest?.('[data-sheet-import-precheck-query]');
    if(!input) return;
    clearTimeout(sheetImportSuggestTimer);
    const rowIndex = Number(input.dataset.sheetImportPrecheckQuery || 0);
    const value = input.value;
    sheetImportSuggestTimer = setTimeout(() => sheetImportPreviewFillSuggestions(rowIndex, value), 140);
  });
  $('sheetImportPreview')?.addEventListener('keydown', ev => {
    const input = ev.target?.closest?.('[data-sheet-import-precheck-query]');
    if(!input || ev.key !== 'Enter') return;
    ev.preventDefault();
    sheetImportPreviewFillSuggestions(Number(input.dataset.sheetImportPrecheckQuery || 0), input.value);
  });
  $('sheetImportPreview')?.addEventListener('click', ev => {
    const suggestedBtn = ev.target?.closest?.('[data-sheet-import-confirm-suggested]');
    if(suggestedBtn){
      const rowIndex=Number(suggestedBtn.dataset.sheetImportConfirmSuggested || 0);
      const row=sheetImportPreviewFindRow(rowIndex);
      const master=row?.candidateMaster || row?.manualCandidates?.[0] || null;
      sheetImportPreviewApplyMaster(rowIndex, master);
      return;
    }
    const confirmBtn = ev.target?.closest?.('[data-sheet-import-confirm-selected]');
    if(confirmBtn){
      const rowIndex = Number(confirmBtn.dataset.sheetImportConfirmSelected || 0);
      const select = document.querySelector(`[data-sheet-import-precheck-select="${CSS.escape(String(rowIndex))}"]`);
      const selectedId=String(select?.value || '');
      const row=sheetImportPreviewFindRow(rowIndex);
      const master=(row?.manualCandidates || []).find(m=>String(m?.sharedTitleId||'')===selectedId) || (selectedId ? findMasterById(selectedId) : null);
      if(!master){ toast('DB候補を選択してください'); return; }
      sheetImportPreviewApplyMaster(rowIndex, master);
    }
  });
  ['sheetImportSkipDupes','sheetImportAllowUnconfirmed'].forEach(id => {
    $(id)?.addEventListener('change', () => {
      if(sheetImportState.rows.length) sheetImportRefreshPreview();
    });
  });
}


function isIntentionallyUnconfirmed(entry){
  return entry && entry.sharedStatus === 'manual_unconfirmed';
}

function bulkRematchTargets(){
  return (state.entries || [])
    .filter(e => e && String(e.title || '').trim())
    .filter(e => isSharedPlatform(e.platform))
    .filter(e => !isIntentionallyUnconfirmed(e))
    .filter(e => !e.sharedTitleId || e.sharedStatus !== 'confirmed');
}

function bulkRematchMasterKeys(master){
  return [master?.canonicalTitle || '', ...((master?.aliases || []))].map(titleKey).filter(Boolean);
}

function bulkRematchExactMaster(entry, candidates){
  const key = titleKey(entry?.title || '');
  if(!key) return null;
  const list = Array.isArray(candidates) ? candidates : findMasterCandidatesForEntry(entry);
  return list.find(m => m.platform === entry.platform && bulkRematchMasterKeys(m).includes(key))
    || list.find(m => bulkRematchMasterKeys(m).includes(key))
    || null;
}

function bulkRematchRowInfo(entry){
  const candidates = findMasterCandidatesForEntryWithScore(entry, 12).slice(0, 12);
  const exact = bulkRematchExactMaster(entry, candidates);
  return {
    entry,
    candidates,
    exact,
    status: exact ? 'exact' : (candidates.length ? 'candidate' : 'none')
  };
}

function bulkRematchApplyMasterToEntry(entry, master){
  if(!entry || !master) return false;

  entry.title = master.canonicalTitle;
  entry.platform = master.platform;
  entry.titleKey = titleKey(master.canonicalTitle);
  entry.canonicalTitle = master.canonicalTitle;
  entry.sharedTitleId = master.sharedTitleId;
  entry.sharedStatus = 'confirmed';
  entry.localSharedId = '';
  entry.releaseDate = master.releaseDate || entry.releaseDate || '';
  entry.rawReleaseDate = master.rawReleaseDate || '';
  entry.maker = master.maker || entry.maker || '';
  entry.genre = master.genre || '';
  entry.productCode = master.productCode || '';
  entry.remarks = master.remarks || '';
  entry.updatedAt = nowIso();

  return true;
}

function bulkRematchStatusLabel(status){
  return {
    exact:'完全一致',
    candidate:'候補あり',
    none:'候補なし',
    local:'未確定'
  }[status] || status;
}

function bulkRematchCandidateOptionHtml(master, selectedId='', exactId=''){
  const isExact = exactId && master.sharedTitleId === exactId;
  const score = master._candidateScore ? ` / score:${master._candidateScore}` : '';
  return `<option value="${esc(master.sharedTitleId)}" ${master.sharedTitleId === selectedId ? 'selected' : ''}>${isExact ? '◎ ' : ''}${esc(master.platform)} / ${esc(master.canonicalTitle)} / ${esc(master.releaseDate || master.rawReleaseDate || '発売日未設定')} / ${esc(master.maker || 'メーカー未設定')} / ${esc(master.sharedTitleId)}${esc(score)}</option>`;
}

function bulkRematchFillSelect(entryId, candidates, selectedId=''){
  let select = document.querySelector(`[data-bulk-rematch-select="${CSS.escape(entryId)}"]`);
  const entry = state.entries.find(e => e.id === entryId);

  if(!select){
    const row = document.querySelector(`[data-bulk-rematch-row="${CSS.escape(entryId)}"] td:nth-child(3)`);
    if(!row || !entry) return;
    row.insertAdjacentHTML('afterbegin', `<select class="bulk-rematch-select" data-bulk-rematch-select="${esc(entryId)}" data-entry-title="${esc(entry.title)}" data-entry-platform="${esc(entry.platform)}"><option value="">選択しない</option></select>`);
    select = document.querySelector(`[data-bulk-rematch-select="${CSS.escape(entryId)}"]`);
  }

  const exact = bulkRematchExactMaster({title:select.dataset.entryTitle || entry?.title || '', platform:select.dataset.entryPlatform || entry?.platform || ''}, candidates);
  const exactId = exact?.sharedTitleId || '';
  select.innerHTML = `<option value="">${(candidates || []).length ? '選択しない' : '候補なし'}</option>` + (candidates || []).map(m => bulkRematchCandidateOptionHtml(m, selectedId, exactId)).join('');
  if(selectedId) select.value = selectedId;
  updateBulkRematchSelectedCount();
}

function bulkRematchManualSearch(entryId){
  const input = document.querySelector(`[data-bulk-rematch-query="${CSS.escape(entryId)}"]`);
  const entry = state.entries.find(e => e.id === entryId);
  if(!input || !entry) return;
  const query = String(input.value || '').trim() || entry.title || '';
  const candidates = findMasterCandidatesManualWithScore(query, entry.platform, 15);
  bulkRematchFillSelect(entryId, candidates, candidates[0]?.sharedTitleId || '');
  const note = document.querySelector(`[data-bulk-rematch-note="${CSS.escape(entryId)}"]`);
  if(note){
    note.textContent = candidates.length
      ? `「${query}」で${candidates.length}件見つかりました。必要なら候補を選び直してください。`
      : `「${query}」では候補が見つかりませんでした。別の一部タイトルや略称で検索してください。`;
  }
  toast(candidates.length ? '候補を再検索しました' : '候補が見つかりませんでした');
}

function renderBulkRematchPlaceholder(){
  const listBox = $('bulkRematchList');
  const summaryBox = $('bulkRematchSummary');
  const statusBox = $('bulkRematchStatus');
  if(!listBox || !summaryBox || !statusBox || listBox.dataset.analysisReady === '1') return;
  summaryBox.innerHTML = '';
  statusBox.textContent = '未確定タイトルの解析は自動実行しません。「候補を再表示」を押すと開始します。';
  listBox.innerHTML = '<div class="bulk-rematch-empty">設定画面を軽くするため、一括照合は必要な時だけ解析します。</div>';
}

function renderBulkRematchPanel(){
  const listBox = $('bulkRematchList');
  const summaryBox = $('bulkRematchSummary');
  const statusBox = $('bulkRematchStatus');
  if(!listBox || !summaryBox || !statusBox) return;
  listBox.dataset.analysisReady = '1';

  const rows = bulkRematchTargets().map(bulkRematchRowInfo);
  const counts = rows.reduce((acc, row) => {
    acc.total += 1;
    acc[row.status] = (acc[row.status] || 0) + 1;
    return acc;
  }, {total:0, exact:0, candidate:0, none:0});

  const selectedCount = rows.filter(row => row.exact).length;

  summaryBox.innerHTML = `
    <div class="bulk-rematch-card"><strong>${counts.total}</strong><span>未確定</span></div>
    <div class="bulk-rematch-card"><strong>${counts.exact || 0}</strong><span>完全一致</span></div>
    <div class="bulk-rematch-card"><strong>${counts.candidate || 0}</strong><span>候補あり</span></div>
    <div class="bulk-rematch-card"><strong>${counts.none || 0}</strong><span>候補なし</span></div>
    <div class="bulk-rematch-card"><strong id="bulkRematchSelectedCount">${selectedCount}</strong><span>選択中</span></div>
  `;

  if(!rows.length){
    statusBox.textContent = '未確定データはありません。取り込みデータはすべて共有ID確定済みです。';
    listBox.innerHTML = '<div class="bulk-rematch-empty">未確定・候補ありデータはありません。</div>';
    return;
  }

  statusBox.textContent = `未確定 ${counts.total}件 / 完全一致 ${counts.exact || 0}件 / 候補あり ${counts.candidate || 0}件 / 候補なし ${counts.none || 0}件`;

  listBox.innerHTML = `
    <div class="bulk-rematch-table-wrap">
      <table class="bulk-rematch-table">
        <thead>
          <tr>
            <th>登録データ</th>
            <th>状態</th>
            <th>候補選択</th>
            <th>現在の共有状態</th>
          </tr>
        </thead>
        <tbody>
          ${rows.map(row => {
            const e = row.entry;
            const selectedId = row.exact ? row.exact.sharedTitleId : '';
            return `
              <tr data-bulk-rematch-row="${esc(e.id)}">
                <td>
                  <div class="bulk-rematch-title">${esc(e.platform)} / ${esc(e.title)}</div>
                  <div class="bulk-rematch-sub">
                    ${esc(e.maker || 'メーカー未設定')} / ${e.purchasePrice ? '購入価格 ' + esc(e.purchasePrice) + '円 / ' : ''}${esc(e.memo || '')}
                  </div>
                </td>
                <td><span class="bulk-rematch-chip ${esc(row.status)}">${esc(bulkRematchStatusLabel(row.status))}</span></td>
                <td>
                  <select class="bulk-rematch-select" data-bulk-rematch-select="${esc(e.id)}" data-entry-title="${esc(e.title)}" data-entry-platform="${esc(e.platform)}">
                    <option value="">${row.candidates.length ? '選択しない' : '候補検索後にここへ表示'}</option>
                    ${row.candidates.map(m => bulkRematchCandidateOptionHtml(m, selectedId, row.exact?.sharedTitleId || '')).join('')}
                  </select>
                  ${row.candidates.length
                    ? `<div class="bulk-rematch-sub">${row.exact ? '完全一致候補を自動選択済み' : '候補から正しいものを選択してください'}</div>`
                    : '<span class="bulk-rematch-chip none">候補なし</span><div class="bulk-rematch-sub">タイトルの一部や略称で下から検索してください</div>'
                  }
                  <div class="bulk-rematch-manual">
                    <input type="text" data-bulk-rematch-query="${esc(e.id)}" value="${esc(e.title)}" placeholder="例：マリオ / クロノ / FF6">
                    <button type="button" class="ghost" data-bulk-rematch-search="${esc(e.id)}">候補検索</button>
                  </div>
                  <div class="bulk-rematch-search-note" data-bulk-rematch-note="${esc(e.id)}">誤字・表記ゆれ・一部タイトルでも検索できます。</div>
                  <div class="bulk-rematch-row-actions"><button type="button" class="ghost" data-bulk-rematch-save-unconfirmed="${esc(e.id)}">未確定のまま保存</button></div>
                </td>
                <td>
                  <div class="bulk-rematch-sub">
                    sharedStatus: ${esc(e.sharedStatus || 'unconfirmed')}<br>
                    sharedTitleId: ${esc(e.sharedTitleId || '—')}<br>
                    titleKey: ${esc(e.titleKey || titleKey(e.title))}
                  </div>
                </td>
              </tr>
            `;
          }).join('')}
        </tbody>
      </table>
    </div>
  `;

  updateBulkRematchSelectedCount();
}

function updateBulkRematchSelectedCount(){
  const count = Array.from(document.querySelectorAll('[data-bulk-rematch-select]')).filter(sel => String(sel.value || '').trim()).length;
  const el = $('bulkRematchSelectedCount');
  if(el) el.textContent = String(count);
}

async function bulkRematchSetSelections(mode){
  const processingToken = window.fujiyaProcessing?.start({
    title:'一括照合候補を選んでいます',
    detail:mode === 'exact' ? '完全一致した候補だけを選択しています。' : '各データの先頭候補を選択しています。',
    progressText:'候補判定中'
  }) || '';
  await window.fujiyaProcessing?.paint?.();

  try{
    await ensureSheetImportMasterLookup(processingToken);
    const targets = bulkRematchTargets();
    const rows = [];
    for(let i=0;i<targets.length;i++){
      rows.push(bulkRematchRowInfo(targets[i]));
      if((i + 1) % 30 === 0){
        window.fujiyaProcessing?.update(processingToken,{
          current:i + 1,
          total:targets.length,
          detail:'未確定データの候補を確認しています。'
        });
        await sheetImportYield();
      }
    }

    rows.forEach(row => {
      const select = document.querySelector(`[data-bulk-rematch-select="${CSS.escape(row.entry.id)}"]`);
      if(!select) return;

      if(mode === 'exact'){
        select.value = row.exact ? row.exact.sharedTitleId : '';
      }else if(mode === 'first'){
        select.value = row.candidates[0]?.sharedTitleId || '';
      }
    });
    updateBulkRematchSelectedCount();
    toast(mode === 'exact' ? '完全一致候補だけ選択しました' : '先頭候補を選択しました');
  }finally{
    window.fujiyaProcessing?.end(processingToken);
  }
}


function saveEntryAsManualUnconfirmed(entryId){
  createUndoSnapshot('未確定保存の前');
  const entry = state.entries.find(e => e.id === entryId);
  if(!entry){ toast('未確定保存するデータが見つかりません'); return; }
  entry.sharedTitleId = '';
  entry.sharedStatus = 'manual_unconfirmed';
  entry.localSharedId = entry.localSharedId || makeLocalSharedId(entry.platform, entry.titleKey || titleKey(entry.title));
  entry.canonicalTitle = entry.canonicalTitle || entry.title;
  entry.titleKey = entry.titleKey || titleKey(entry.title);
  entry.updatedAt = nowIso();
  if(save()){
    addEventLog('rematch', entry, '未確定のままローカル保存');
    render();
    toast('未確定のまま保存しました');
    showMikeTalk(`「${entry.title}」は未確定のまま保存したよ。\n共有IDには紐づけず、ローカルの所持データとして残すよ。`);
  }
}

function saveAllNoCandidateAsManualUnconfirmed(){
  createUndoSnapshot('候補なし一括未確定保存の前');
  const rows = bulkRematchTargets().map(bulkRematchRowInfo).filter(row => row.status === 'none');
  if(!rows.length){ toast('候補なしの未確定データはありません'); return; }
  rows.forEach(row => {
    const entry = row.entry;
    entry.sharedTitleId = '';
    entry.sharedStatus = 'manual_unconfirmed';
    entry.localSharedId = entry.localSharedId || makeLocalSharedId(entry.platform, entry.titleKey || titleKey(entry.title));
    entry.canonicalTitle = entry.canonicalTitle || entry.title;
    entry.titleKey = entry.titleKey || titleKey(entry.title);
    entry.updatedAt = nowIso();
  });
  if(save()){
    addEventLog('rematch', rows[0].entry, `候補なし${rows.length}件を未確定のまま保存`);
    render();
    toast(`${rows.length}件を未確定のまま保存しました`);
    showMikeTalk(`候補なしの${rows.length}件を未確定のまま保存したよ。\n共有IDには紐づけず、ローカル保存として扱うよ。`);
  }
}

function applyBulkRematchSelections(){
  createUndoSnapshot('一括照合の前');
  const selects = Array.from(document.querySelectorAll('[data-bulk-rematch-select]')).filter(sel => String(sel.value || '').trim());
  if(!selects.length){
    toast('確定する候補が選択されていません');
    return;
  }

  let changed = 0;
  const changedEntries = [];

  selects.forEach(sel => {
    const entry = state.entries.find(e => e.id === sel.dataset.bulkRematchSelect);
    const master = findMasterById(sel.value);
    if(entry && master && bulkRematchApplyMasterToEntry(entry, master)){
      changed += 1;
      changedEntries.push(entry);
    }
  });

  if(!changed){
    toast('反映できる候補がありませんでした');
    return;
  }

  if(save()){
    changedEntries.slice(0, 50).forEach(entry => {
      addEventLog('rematch', entry, '一括照合でマスター情報を反映');
      addRareLogIfNeeded(entry, '一括照合でレア判定');
    });
    render();
    scheduleAutoSync('一括照合');
    toast(`${changed}件を共有IDへ確定しました`);
    showMikeTalk(`${changed}件を図鑑マスターに一括照合したよ。\n共有IDが確定したので、共有所持率やランキングにも反映されるよ。`);
  }
}

function bindBulkRematchEvents(){
  const panel = $('bulkRematchPanel');
  if(!panel) return;

  $('bulkRematchRefreshBtn')?.addEventListener('click', async () => {
    const processingToken = window.fujiyaProcessing?.start({
      title:'一括照合候補を作成しています',
      detail:'未確定データとタイトルマスターを照合しています。',
      progressText:'候補作成中'
    }) || '';
    await window.fujiyaProcessing?.paint?.();
    try{
      await ensureSheetImportMasterLookup(processingToken);
      renderBulkRematchPanel();
      toast('一括照合候補を再表示しました');
    }finally{
      window.fujiyaProcessing?.end(processingToken);
    }
  });
  $('bulkRematchSelectExactBtn')?.addEventListener('click', () => bulkRematchSetSelections('exact'));
  $('bulkRematchSelectFirstBtn')?.addEventListener('click', () => bulkRematchSetSelections('first'));
  $('bulkRematchApplyBtn')?.addEventListener('click', applyBulkRematchSelections);
  $('bulkRematchSaveNoCandidateBtn')?.addEventListener('click', saveAllNoCandidateAsManualUnconfirmed);
  $('bulkRematchTalkBtn')?.addEventListener('click', () => {
    showMikeTalk('未確定データをまとめて図鑑マスターに紐づける画面だよ。\n「完全一致だけ自動選択」は安全寄り、「先頭候補をまとめて選択」は速いけど確認してから確定してね。');
  });
  panel.addEventListener('click', ev => {
    const searchBtn = ev.target.closest('[data-bulk-rematch-search]');
    if(searchBtn){
      bulkRematchManualSearch(searchBtn.dataset.bulkRematchSearch);
      return;
    }
    const saveBtn = ev.target.closest('[data-bulk-rematch-save-unconfirmed]');
    if(saveBtn){
      saveEntryAsManualUnconfirmed(saveBtn.dataset.bulkRematchSaveUnconfirmed);
      return;
    }
  });
  panel.addEventListener('keydown', ev => {
    if(ev.key === 'Enter' && ev.target && ev.target.matches('[data-bulk-rematch-query]')){
      ev.preventDefault();
      bulkRematchManualSearch(ev.target.dataset.bulkRematchQuery);
    }
  });
  panel.addEventListener('change', ev => {
    if(ev.target && ev.target.matches('[data-bulk-rematch-select]')){
      updateBulkRematchSelectedCount();
    }
  });
}


function duplicateMergePartScore(entry){
  const p = entry.parts || {};
  return ['rom','box','manual','accessory'].reduce((sum,k) => sum + (p[k]?.has ? 1 : 0), 0);
}
function duplicateMergeCompletenessLabel(entry){
  const labels = autoLabels(entry).map(x => x.text);
  return labels.slice(0,3).join(' / ') || '内容物未設定';
}
function duplicateMergeScore(entry){
  let score = 0;
  if(entry.sharedTitleId) score += 1000;
  if(entry.owned) score += 100;
  score += duplicateMergePartScore(entry) * 20;
  score += ratingNumber(entry.rating) * 5;
  if(entry.purchasePrice) score += 3;
  if(entry.memo) score += 2;
  if(entry.photoData) score += 2;
  return score;
}
function duplicateMergeReasonForGroup(reason){
  if(reason === 'shared') return '同じ共有ID';
  if(reason === 'key') return '同じ機種＋正規化タイトル';
  if(reason === 'fuzzy') return '同じ機種＋似たタイトル';
  return '重複候補';
}
function duplicateMergeGroups(){
  const entries = (state.entries || []).filter(e => e && String(e.title || '').trim());
  const groups = [];
  const seen = new Set();
  const addGroup = (list, reason, similarity=0) => {
    const uniq = Array.from(new Map(list.map(e => [e.id, e])).values());
    if(uniq.length < 2) return;
    const ids = uniq.map(e => e.id).sort().join('|');
    if(seen.has(ids)) return;
    seen.add(ids);
    groups.push({id:`g${groups.length+1}`, reason, similarity, entries:uniq.sort((a,b)=>duplicateMergeScore(b)-duplicateMergeScore(a))});
  };

  const byShared = new Map();
  const byKey = new Map();
  entries.forEach(e => {
    if(e.sharedTitleId){
      const k = e.sharedTitleId;
      if(!byShared.has(k)) byShared.set(k, []);
      byShared.get(k).push(e);
    }
    const key = `${e.platform}::${e.titleKey || titleKey(e.title)}`;
    if(!byKey.has(key)) byKey.set(key, []);
    byKey.get(key).push(e);
  });
  byShared.forEach(list => addGroup(list, 'shared'));
  byKey.forEach(list => addGroup(list, 'key'));

  // 以前は同一機種内を全組み合わせで比較していた。
  // 先頭3文字の近いタイトルだけを比較し、件数増加時の二乗処理を避ける。
  const fuzzyBuckets = new Map();
  entries.forEach(e => {
    const key = titleKey(e.title || '');
    if(key.length < 3) return;
    const bucket = `${e.platform}::${key.slice(0,3)}`;
    if(!fuzzyBuckets.has(bucket)) fuzzyBuckets.set(bucket, []);
    fuzzyBuckets.get(bucket).push(e);
  });
  fuzzyBuckets.forEach(list => {
    const limited = list.slice(0,140);
    for(let i=0; i<limited.length && groups.length<80; i++){
      for(let j=i+1; j<limited.length && groups.length<80; j++){
        const a=limited[i], b=limited[j];
        if(a.sharedTitleId && b.sharedTitleId && a.sharedTitleId !== b.sharedTitleId) continue;
        const sim=fuzzyTitleSimilarity(a.title,b.title);
        if(sim>=0.82) addGroup([a,b],'fuzzy',sim);
      }
    }
  });
  return groups.slice(0,80);
}
function duplicateMergeMergedEntry(entries, keepId){
  const keep = entries.find(e => e.id === keepId) || entries[0];
  const merged = norm({...keep});
  const bestShared = entries.find(e => e.sharedTitleId && e.sharedStatus === 'confirmed') || entries.find(e => e.sharedTitleId);
  if(bestShared){
    merged.sharedTitleId = bestShared.sharedTitleId;
    merged.sharedStatus = bestShared.sharedStatus === 'confirmed' ? 'confirmed' : bestShared.sharedStatus;
    merged.localSharedId = '';
    const master = findMasterById(bestShared.sharedTitleId);
    if(master){
      merged.title = master.canonicalTitle;
      merged.platform = master.platform;
      merged.canonicalTitle = master.canonicalTitle;
      merged.titleKey = titleKey(master.canonicalTitle);
      merged.releaseDate = merged.releaseDate || master.releaseDate || '';
      merged.rawReleaseDate = master.rawReleaseDate || merged.rawReleaseDate || '';
      merged.maker = merged.maker || master.maker || '';
      merged.genre = master.genre || merged.genre || '';
      merged.productCode = master.productCode || merged.productCode || '';
      merged.remarks = master.remarks || merged.remarks || '';
    }
  }
  merged.owned = entries.some(e => !!e.owned);
  merged.rating = Math.max(...entries.map(e => ratingNumber(e.rating)));
  merged.purchasePrice = merged.purchasePrice || entries.find(e => e.purchasePrice)?.purchasePrice || '';
  merged.purchaseDate = merged.purchaseDate || entries.find(e => e.purchaseDate)?.purchaseDate || '';
  merged.purchaseStore = merged.purchaseStore || entries.find(e => e.purchaseStore)?.purchaseStore || '';
  merged.maker = merged.maker || entries.find(e => e.maker)?.maker || '';
  merged.releaseDate = merged.releaseDate || entries.find(e => e.releaseDate)?.releaseDate || '';
  const p = emptyParts();
  ['rom','box','manual','accessory'].forEach(k => {
    const partEntries = entries.map(e => e.parts?.[k]).filter(Boolean);
    p[k].has = partEntries.some(x => x.has);
    p[k].condition = partEntries.find(x => x.has && x.condition)?.condition || '';
  });
  merged.parts = p;
  const memos = entries.map(e => String(e.memo || '').trim()).filter(Boolean);
  merged.memo = Array.from(new Set(memos)).join('\n--- 統合メモ ---\n');
  merged.updatedAt = nowIso();
  return hydrateEntryFromMaster(ensureSharedFields(merged));
}
function applyDuplicateMerge(groupId){
  createUndoSnapshot('重複統合の前');
  const groupEl = document.querySelector(`[data-duplicate-group="${CSS.escape(groupId)}"]`);
  if(!groupEl) return;
  const keepSelect = groupEl.querySelector('[data-duplicate-keep]');
  const ids = String(groupEl.dataset.entryIds || '').split(',').filter(Boolean);
  const entries = ids.map(id => state.entries.find(e => e.id === id)).filter(Boolean);
  if(entries.length < 2){ toast('統合対象が見つかりません'); return; }
  const keepId = keepSelect?.value || entries[0].id;
  const merged = duplicateMergeMergedEntry(entries, keepId);
  const removeIds = new Set(entries.map(e => e.id).filter(id => id !== keepId));
  state.entries = (state.entries || []).map(e => e.id === keepId ? merged : e).filter(e => !removeIds.has(e.id));
  if(save()){
    addEventLog('edit', merged, `重複・表記ゆれ統合：${entries.length}件を1件へ統合`);
    render();
    scheduleAutoSync('重複統合');
    toast(`${entries.length}件を1件へ統合しました`);
    showMikeTalk(`「${merged.title}」の重複候補${entries.length}件を1件に統合したよ。\nメモや内容物はできるだけ残してまとめたよ。`);
  }
}
