function fetchCollectionResetStatusJsonpRequest(endpoint, requestId, timeoutMs=12000){
  return new Promise((resolve,reject) => {
    const cleanEndpoint = String(endpoint || '').trim();
    if(!cleanEndpoint){ reject(new Error('共有同期URLが未設定です')); return; }
    const callback = `fujiyaCollectionResetStatus_${Date.now()}_${Math.random().toString(36).slice(2)}`;
    let settled = false;
    const timer = setTimeout(() => { cleanup(); reject(new Error('初期化状況の確認がタイムアウトしました')); }, timeoutMs);
    function cleanup(){
      if(settled) return;
      settled = true;
      clearTimeout(timer);
      window.fujiyaKeepLateJsonpCallback_(callback);
      document.getElementById(callback)?.remove();
    }
    window[callback] = data => {
      cleanup();
      if(data && data.action === 'reset_user_collection_status') resolve(data);
      else reject(new Error(data?.message || '初期化状況の応答形式が正しくありません'));
    };
    const script = document.createElement('script');
    script.id = callback;
    script.onerror = () => { cleanup(); reject(new Error('初期化状況の確認先へ接続できませんでした')); };
    const sep = cleanEndpoint.includes('?') ? '&' : '?';
    const params = new URLSearchParams({
      action:'reset_user_collection_status',
      requestId,
      callback,
      _:String(Date.now())
    });
    script.src = `${cleanEndpoint}${sep}${params.toString()}`;
    document.body.appendChild(script);
  });
}

async function waitForCollectionResetStatus(requestId, timeoutMs=130000, endpointOverride=''){
  const endpoint = String(endpointOverride || getGasEndpoint() || DEFAULT_GAS_ENDPOINT || '').trim();
  if(!endpoint) throw new Error('共有同期URLが未設定です');
  const deadline = Date.now() + timeoutMs;
  let lastError = '';
  while(Date.now() < deadline){
    try{
      const data = await fetchCollectionResetStatusJsonpRequest(endpoint, requestId, 10000);
      const status = String(data?.status || '').toLowerCase();
      if(status === 'completed' && data?.ok === true){
        if(Number(data.remaining_records || 0) !== 0) throw new Error(`共有DBに${Number(data.remaining_records || 0)}件残っています`);
        return data;
      }
      if(status === 'error' || (data?.ok === false && data?.pending === false)){
        throw new Error(data?.message || '共有DBの初期化に失敗しました');
      }
    }catch(e){
      lastError = String(e?.message || e);
      if(/共有DBに|userId|初期化に失敗|権限|スプレッドシート/.test(lastError)) throw e;
    }
    await new Promise(resolve => setTimeout(resolve, 1200));
  }
  throw new Error(lastError || '共有DBの初期化結果を確認できませんでした');
}

