async function restartCollectionFromScratch(){
  const buttons = [
    $('restartCollectionBtn'),
    $('manageRestartCollectionBtn')
  ].filter(Boolean);
  const localCount = Number(state.entries?.length || 0);
  const logCount = Number(state.eventLogs?.length || 0);
  const buybackCount = Number(state.buybackEntryIds?.length || 0);
  const historyCount = Number(state.buybackHistory?.length || 0);
  const endpoint = String(getGasEndpoint() || DEFAULT_GAS_ENDPOINT || '').trim();
  if(!endpoint){
    setCollectionResetStatus('初期化できません：共有同期URLが未設定です', 'warn');
    toast('共有同期URLが未設定です');
    return;
  }

  const first = confirm(`コレクションを0件からやり直しますか？\n\n削除対象：登録${localCount}件 / ログ${logCount}件 / 買取相談${buybackCount}件 / 買取成立履歴${historyCount}件\n共有DBの所持・評価・購入価格・クリア時間も0件にします。\n\nプロフィール、個人ID、みてレコ、みてマガ、表示設定は残ります。\n実行前にJSON完全バックアップを自動保存します。`);
  if(!first) return;
  const second = confirm('最終確認です。共有DBの削除確認後、この端末のコレクション関連データを初期化します。続けますか？');
  if(!second) return;

  buttons.forEach(button => { button.disabled = true; });
  const processingToken = window.fujiyaProcessing?.start({
    title:'コレクションを初期化しています',
    detail:'最初にJSON完全バックアップを作成しています。',
    progressText:'バックアップ中'
  }) || '';
  setCollectionResetStatus('JSON完全バックアップを作成しています…', 'loading');
  await window.fujiyaProcessing?.paint?.();
  try{
    const backupFile = await exportBeforeRestartBackup();
    window.fujiyaProcessing?.update(processingToken,{
      title:'共有DBを初期化しています',
      detail:`バックアップ「${backupFile}」を保存しました。共有DBの削除完了を確認しています。`,
      progressText:'共有DB処理中'
    });
    setCollectionResetStatus(`バックアップ「${backupFile}」を保存しました。共有DBを初期化中です。このままお待ちください…`, 'loading');
    toast('バックアップを保存しました');

    const requestId = `fujiya_collection_reset_${Date.now()}_${Math.random().toString(36).slice(2,9)}`;
    submitGasPostFormNoWait('reset_user_collection_frame', {
      userId:getUserId(),
      confirm:'RESET_COLLECTION'
    }, requestId, endpoint);

    const result = await waitForCollectionResetStatus(requestId, 130000, endpoint);
    window.fujiyaProcessing?.update(processingToken,{
      title:'端末内を初期化しています',
      detail:`共有DBから${Number(result.deleted_records || 0).toLocaleString('ja-JP')}件を削除しました。端末内のコレクションを整理しています。`,
      progressText:'端末内処理中'
    });
    setCollectionResetStatus(`共有DBの削除確認完了：${Number(result.deleted_records || 0)}件。端末内のコレクションを初期化中…`, 'loading');
    await window.fujiyaProcessing?.paint?.();

    clearPersonalCollectionLocalData();
    render();
    setUiTab('register', {targetId:'entryPanel'});
    setCollectionResetStatus(`最初からやり直す準備が完了しました。共有DB削除 ${Number(result.deleted_records || 0)}件 / 現在0件`, 'ready');
    toast('コレクションを0件にしました');
    showMikeTalk('最初からやり直す準備ができたよ！\nバックアップは保存済み。共有DBもこの端末も0件になったから、1本目から登録を楽しめるよ。');
    if(getAutoReceiveEnabled()) scheduleAutoReceive('コレクション初期化後', 1200, true);
  }catch(e){
    const message = String(e?.message || e);
    setCollectionResetStatus(`初期化中止：${message}\n端末内の登録データは消していません。`, 'warn');
    toast('初期化を中止しました');
    showMikeTalk(`共有DBの削除確認が取れなかったため、端末内のデータは消していないよ。\n\n${message}`);
  }finally{
    buttons.forEach(button => { button.disabled = false; });
    window.fujiyaProcessing?.end(processingToken);
  }
}

