function verifyTitleDescriptionsJsonpRequest(endpoint, items, offset=0){
  return new Promise((resolve,reject) => {
    const cleanEndpoint = String(endpoint || '').trim();
    if(!cleanEndpoint){ reject(new Error('共有同期URLが未設定です')); return; }
    const callback = `fujiyaDescriptionVerify_${Date.now()}_${Math.random().toString(36).slice(2)}`;
    let settled = false;
    const timer = setTimeout(() => { cleanup(); reject(new Error('説明の保存確認がタイムアウトしました')); }, 30000);
    function cleanup(){
      if(settled) return;
      settled = true;
      clearTimeout(timer);
      window.fujiyaKeepLateJsonpCallback_(callback);
      document.getElementById(callback)?.remove();
    }
    window[callback] = data => {
      cleanup();
      if(data?.ok && data.action === 'title_descriptions_verify') resolve(data);
      else reject(new Error(data?.message || '説明の保存確認に失敗しました'));
    };
    const checks = (items || []).map((item,i) => {
      const sharedTitleId = String(item.sharedTitleId || '').trim().toUpperCase();
      return {
        index:offset + i,
        sharedTitleId,
        platform:sharedTitleId ? '' : String(item.platform || '').trim().toUpperCase(),
        title:sharedTitleId ? '' : String(item.title || '').trim()
      };
    });
    const script = document.createElement('script');
    script.id = callback;
    script.onerror = () => { cleanup(); reject(new Error('説明の保存確認先へ接続できませんでした')); };
    const sep = cleanEndpoint.includes('?') ? '&' : '?';
    const params = new URLSearchParams({
      action:'title_descriptions_verify',
      checks:JSON.stringify(checks),
      callback,
      _:String(Date.now())
    });
    script.src = `${cleanEndpoint}${sep}${params.toString()}`;
    document.body.appendChild(script);
  });
}

async function verifyImportedDescriptions(items, endpointOverride=''){
  const endpoint = String(endpointOverride || getGasEndpoint() || DEFAULT_GAS_ENDPOINT || '').trim();
  if(!endpoint) throw new Error('共有同期URLが未設定です');
  const expected = new Map((items || []).map((item,index) => [index, String(item.descriptionHash || '')]));
  const found = new Map();
  let offset = 0;
  while(offset < items.length){
    const startsWithId = !!String(items[offset]?.sharedTitleId || '').trim();
    let end = offset + 1;
    if(startsWithId){
      while(end < items.length && end - offset < 40 && String(items[end]?.sharedTitleId || '').trim()) end += 1;
    }
    // IDなし行はタイトルが長い場合でもURL上限を超えないよう、1件ずつ確認する。
    const batchItems = items.slice(offset, end);
    const batch = await verifyTitleDescriptionsJsonpRequest(endpoint, batchItems, offset);
    (batch.items || []).forEach(item => {
      const index = Number(item.checkIndex);
      if(Number.isInteger(index)) found.set(index, String(item.descriptionHash || ''));
    });
    offset = end;
  }
  let matched = 0;
  expected.forEach((hash,index) => { if(found.get(index) === hash) matched += 1; });
  return {matched, total:expected.size, found};
}

async function importTitleDescriptionsFile(ev){
  const file = ev?.target?.files?.[0];
  if(!file) return;
  try{
    const token = String($('descriptionAdminToken')?.value || '').trim();
    if(!token) throw new Error('説明CSV取込用トークンを入力してください');
    const csv = await file.text();
    const inspected = inspectDescriptionImportCsv(csv, file.name);
    const importItems = inspected.items;
    const skippedNote = inspected.skippedRows ? ` / 空欄 ${inspected.skippedRows}件は除外` : '';
    setDescriptionImportResult(`選択したCSV：${file.name} / 説明入り ${importItems.length}/${inspected.totalRows}件${skippedNote}`, 'ready');
    setDescriptionManagerStatus(`選択したCSV：${file.name} / 説明入り ${importItems.length}/${inspected.totalRows}件${skippedNote}`, 'ready');
    if(!confirm(`${file.name} の説明 ${importItems.length}/${inspected.totalRows}件を専用説明シートへ取り込みますか？${inspected.skippedRows ? `\n空欄 ${inspected.skippedRows}件は取り込みません。` : ''}`)) return;

    const requestId = `fujiya_desc_import_${Date.now()}_${Math.random().toString(36).slice(2,9)}`;
    const importEndpoint = String(getGasEndpoint() || DEFAULT_GAS_ENDPOINT || '').trim();
    if(!importEndpoint) throw new Error('共有同期URLが未設定です');
    setDescriptionImportResult(`説明CSV ${importItems.length}件を送信中…`);
    setDescriptionManagerStatus(`説明CSV ${importItems.length}件を送信中…`);

    submitGasPostFormNoWait('title_descriptions_import_frame', {
      adminToken:token,
      csv
    }, requestId, importEndpoint);

    setDescriptionImportResult('GASで取り込み中…保存結果を確認しています');
    setDescriptionManagerStatus('GASで取り込み中…保存結果を確認しています');

    let data = null;
    let statusError = null;
    try{
      data = await waitForDescriptionImportStatus(requestId, 130000, importEndpoint);
    }catch(e){
      statusError = e;
      setDescriptionImportResult('受付結果を取得できなかったため、説明本文を直接確認中…');
      setDescriptionManagerStatus('受付結果を取得できなかったため、説明本文を直接確認中…');
    }

    const verification = await verifyImportedDescriptions(importItems, importEndpoint);
    if(verification.matched !== verification.total){
      const detail = statusError ? ` / 受付確認：${String(statusError?.message || statusError)}` : '';
      throw new Error(`保存確認 ${verification.matched}/${verification.total}件。説明シートへ反映されていません${detail}`);
    }

    localStorage.removeItem(TITLE_MIKE_NAVI_CACHE_KEY);
    localStorage.removeItem(TITLE_DESCRIPTION_CATALOG_CACHE_KEY);
    clearLegacyTitleMikeNaviCaches();
    const successMessage = data
      ? `取り込み・保存確認完了：${verification.matched}/${verification.total}件 / 新規 ${Number(data.inserted || 0)}件 / 更新 ${Number(data.updated || 0)}件 / リクエスト解決 ${Number(data.resolvedRequests || 0)}件`
      : `取り込み・保存確認完了：${verification.matched}/${verification.total}件（受付通知のみ取得不可）`;
    setDescriptionImportResult(successMessage, 'ready');
    setDescriptionManagerStatus(successMessage, 'ready');
    toast(`説明CSVの保存確認 ${verification.matched}/${verification.total}件 完了`);
    descriptionRequestItemsCache = [];
    setTimeout(() => refreshDescriptionRequests({silent:true}).catch(() => {}), 500);
  }catch(e){
    const raw = String(e?.message || e);
    const friendly = raw === 'Failed to fetch'
      ? 'ブラウザの直接通信が遮断されました。最新版ではフォーム送信方式を使うため、ページを開き直して再試行してください'
      : raw;
    const errorMessage = `取り込み失敗：${friendly}`;
    setDescriptionImportResult(errorMessage, 'warn');
    setDescriptionManagerStatus(errorMessage, 'warn');
  }finally{
    if(ev?.target) ev.target.value = '';
  }
}

function clearTitleDescriptionCache(){
  localStorage.removeItem(TITLE_MIKE_NAVI_CACHE_KEY);
    localStorage.removeItem(TITLE_DESCRIPTION_CATALOG_CACHE_KEY);
  clearLegacyTitleMikeNaviCaches();
  setDescriptionManagerStatus('この端末のゲーム説明キャッシュを消去しました。次に説明を開くとGASから再取得します。', 'ready');
  toast('説明キャッシュを消去しました');
}

let qrScannerStream = null;
let qrScannerFrameId = 0;
let qrScannerBusy = false;
let qrScannerLastValue = '';
let qrScannerLastAt = 0;
let qrLibraryPromise = null;

function setQrScannerStatus(message, type=''){
  const box = $('qrScannerStatus');
  if(!box) return;
  box.textContent = String(message || '');
  box.className = `qr-scanner-status${type ? ' ' + type : ''}`;
}

function loadQrLibrary(){
  if(typeof window.jsQR === 'function') return Promise.resolve(window.jsQR);
  if(qrLibraryPromise) return qrLibraryPromise;

  qrLibraryPromise = new Promise((resolve, reject) => {
    const existing = document.querySelector('script[data-fujiya-jsqr]');
    if(existing){
      existing.addEventListener('load', () => resolve(window.jsQR), {once:true});
      existing.addEventListener('error', () => reject(new Error('QR読取ライブラリを読み込めませんでした')), {once:true});
      return;
    }

    const script = document.createElement('script');
    script.src = 'https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.min.js';
    script.async = true;
    script.dataset.fujiyaJsqr = '1';
    script.onload = () => {
      if(typeof window.jsQR === 'function') resolve(window.jsQR);
      else reject(new Error('QR読取ライブラリを開始できませんでした'));
    };
    script.onerror = () => reject(new Error('QR読取ライブラリを読み込めませんでした'));
    document.head.appendChild(script);
  });

  return qrLibraryPromise;
}

function stopQrCamera(){
  if(qrScannerFrameId){
    cancelAnimationFrame(qrScannerFrameId);
    qrScannerFrameId = 0;
  }

  if(qrScannerStream){
    qrScannerStream.getTracks().forEach(track => {
      try{ track.stop(); }catch(error){}
    });
    qrScannerStream = null;
  }

  const video = $('qrScannerVideo');
  if(video){
    try{ video.pause(); }catch(error){}
    video.srcObject = null;
  }

  $('qrCameraFrame')?.classList.remove('ready');
}


function setRegistrationModalChromeSuppressed(active){
  const nav = document.getElementById('mobileBottomNav');
  if(nav){
    if(active){
      if(nav.dataset.qrModalSuppressed !== '1'){
        nav.dataset.qrModalSuppressed = '1';
        nav.dataset.qrModalInlineDisplay = nav.style.getPropertyValue('display') || '';
        nav.dataset.qrModalInlineDisplayPriority = nav.style.getPropertyPriority('display') || '';
        nav.dataset.qrModalInlineVisibility = nav.style.getPropertyValue('visibility') || '';
        nav.dataset.qrModalInlinePointer = nav.style.getPropertyValue('pointer-events') || '';
      }
      nav.style.setProperty('display','none','important');
      nav.style.setProperty('visibility','hidden','important');
      nav.style.setProperty('pointer-events','none','important');
      nav.setAttribute('aria-hidden','true');
    }else if(nav.dataset.qrModalSuppressed === '1'){
      const display = nav.dataset.qrModalInlineDisplay || '';
      const priority = nav.dataset.qrModalInlineDisplayPriority || '';
      const visibility = nav.dataset.qrModalInlineVisibility || '';
      const pointer = nav.dataset.qrModalInlinePointer || '';
      if(display) nav.style.setProperty('display',display,priority); else nav.style.removeProperty('display');
      if(visibility) nav.style.setProperty('visibility',visibility); else nav.style.removeProperty('visibility');
      if(pointer) nav.style.setProperty('pointer-events',pointer); else nav.style.removeProperty('pointer-events');
      nav.removeAttribute('aria-hidden');
      delete nav.dataset.qrModalSuppressed;
      delete nav.dataset.qrModalInlineDisplay;
      delete nav.dataset.qrModalInlineDisplayPriority;
      delete nav.dataset.qrModalInlineVisibility;
      delete nav.dataset.qrModalInlinePointer;
    }
  }
  if(active){
    try{ document.getElementById('mobileMoreSheet')?.setAttribute('hidden',''); }catch(error){}
  }
  try{
    const themeMeta = document.querySelector('meta[name="theme-color"]');
    if(themeMeta) themeMeta.setAttribute('content','#0b1117');
  }catch(error){}
}

function refreshRegistrationModalChromeSuppression(){
  const active = !!document.body && (
    document.body.classList.contains('qr-registration-modal-open') ||
    document.body.classList.contains('buyback-picker-modal-open') ||
    document.getElementById('qrScannerModal')?.classList.contains('show') ||
    document.getElementById('qrBatchReviewModal')?.classList.contains('show') ||
    (() => { const picker = document.getElementById('buybackEntryPickerModal'); return !!picker && !picker.hidden; })()
  );
  setRegistrationModalChromeSuppressed(active);
}

function setQrRegistrationModalOpen(open){
  document.body?.classList.toggle('qr-registration-modal-open',!!open);
  refreshRegistrationModalChromeSuppression();
}

function closeQrScanner(keepFlow=false){
  stopQrCamera();
  qrScannerBusy = false;
  const modal = $('qrScannerModal');
  if(modal){
    modal.classList.remove('show');
    modal.setAttribute('aria-hidden', 'true');
  }
  if(!keepFlow) setQrRegistrationModalOpen(false);
}

function openQrScanner(){
  const modal = $('qrScannerModal');
  if(!modal) return;

  setQrRegistrationModalOpen(true);
  modal.classList.add('show');
  modal.setAttribute('aria-hidden', 'false');
  qrScannerLastValue = '';
  qrScannerLastAt = 0;
  setQrScannerStatus('QRコードを枠の中へ映してください。');
  setTimeout(startQrCamera, 80);
}

async function startQrCamera(){
  stopQrCamera();

  if(!window.isSecureContext){
    setQrScannerStatus('カメラはHTTPSで公開したページから利用できます。画像からの読み取りを使ってください。', 'warn');
    return;
  }

  if(!navigator.mediaDevices?.getUserMedia){
    setQrScannerStatus('このブラウザはカメラ読み取りに対応していません。画像から読み取ってください。', 'warn');
    return;
  }

  setQrScannerStatus('カメラの使用を許可してください。');

  try{
    await loadQrLibrary();
    qrScannerStream = await navigator.mediaDevices.getUserMedia({
      audio:false,
      video:{
        facingMode:{ideal:'environment'},
        width:{ideal:1280},
        height:{ideal:720}
      }
    });

    const video = $('qrScannerVideo');
    video.srcObject = qrScannerStream;
    await video.play();
    $('qrCameraFrame')?.classList.add('ready');
    setQrScannerStatus('QRコードを枠の中へ映してください。');
    qrScannerFrameId = requestAnimationFrame(scanQrCameraFrame);
  }catch(error){
    console.error(error);
    const message = String(error?.name || '') === 'NotAllowedError'
      ? 'カメラの使用が許可されていません。ブラウザ設定から許可するか、画像から読み取ってください。'
      : `カメラを開始できませんでした：${String(error?.message || error)}`;
    setQrScannerStatus(message, 'bad');
  }
}

function scanQrCameraFrame(){
  const video = $('qrScannerVideo');
  const canvas = $('qrScannerCanvas');

  if(!video || !canvas || !qrScannerStream){
    qrScannerFrameId = 0;
    return;
  }

  if(video.readyState >= 2 && video.videoWidth && video.videoHeight){
    const maxWidth = 840;
    const scale = Math.min(1, maxWidth / video.videoWidth);
    canvas.width = Math.max(1, Math.round(video.videoWidth * scale));
    canvas.height = Math.max(1, Math.round(video.videoHeight * scale));

    const context = canvas.getContext('2d', {willReadFrequently:true});
    context.drawImage(video, 0, 0, canvas.width, canvas.height);
    const imageData = context.getImageData(0, 0, canvas.width, canvas.height);
    const code = window.jsQR?.(
      imageData.data,
      imageData.width,
      imageData.height,
      {inversionAttempts:'attemptBoth'}
    );

    if(code?.data){
      const now = Date.now();
      const value = String(code.data || '').trim();
      if(value && (value !== qrScannerLastValue || now - qrScannerLastAt > 2500)){
        qrScannerLastValue = value;
        qrScannerLastAt = now;
        handleQrRegistrationText(value);
      }
    }
  }

  qrScannerFrameId = requestAnimationFrame(scanQrCameraFrame);
}

function normalizeQrBoolean(value){
  const raw = String(value ?? '').trim().toLowerCase();
  if(['false','0','want','wanted','欲しい','未所持'].includes(raw)) return false;
  if(['true','1','owned','have','所持','持っている'].includes(raw)) return true;
  return null;
}

function qrFirstValue(source, keys){
  for(const key of keys){
    if(source && source[key] !== undefined && source[key] !== null && String(source[key]).trim() !== ''){
      return source[key];
    }
  }
  return '';
}

function normalizeQrObject(source){
  if(!source || typeof source !== 'object') return null;
  const nested = source.data && typeof source.data === 'object' ? source.data : source;

  const payload = {
    platform: String(qrFirstValue(nested, ['platform','console','system','machine','機種']) || '').trim(),
    title: String(qrFirstValue(nested, ['title','game','name','software','タイトル']) || '').trim(),
    sharedTitleId: String(qrFirstValue(nested, ['sharedTitleId','shared_title_id','masterId','master_id','id','共有ID']) || '').trim(),
    maker: String(qrFirstValue(nested, ['maker','publisher','manufacturer','メーカー']) || '').trim(),
    releaseDate: String(qrFirstValue(nested, ['releaseDate','release_date','発売日']) || '').trim(),
    purchaseDate: String(qrFirstValue(nested, ['purchaseDate','purchase_date','購入日']) || '').trim(),
    purchasePrice: String(qrFirstValue(nested, ['purchasePrice','purchase_price','price','購入価格']) || '').trim(),
    purchaseStore: String(qrFirstValue(nested, ['purchaseStore','purchase_store','store','購入店舗']) || '').trim(),
    memo: String(qrFirstValue(nested, ['memo','note','メモ']) || '').trim(),
    rating: String(qrFirstValue(nested, ['rating','score','評価']) || '').trim(),
    owned: normalizeQrBoolean(qrFirstValue(nested, ['owned','status','ownership','所持区分'])),
    parts: nested.parts || nested.contents || ''
  };

  return payload.title || payload.sharedTitleId ? payload : null;
}

function parseQrKeyValueLines(raw){
  const result = {};
  String(raw || '').split(/\r?\n/).forEach(line => {
    const match = line.match(/^\s*([^:：=]+)\s*[:：=]\s*(.*?)\s*$/);
    if(!match) return;
    result[match[1].trim()] = match[2].trim();
  });
  return normalizeQrObject(result);
}

const QR_STORE_BATCH_SESSION_KEY = 'fujiya_mitekore_store_qr_parts_v4';
const QR_STORE_BATCH_EXPIRE_MS = 12 * 60 * 60 * 1000;
let qrBatchReviewItems = [];
let qrBatchReviewMeta = {};

function compactQrDateToIso(value){
  const raw = String(value || '').replace(/\D/g,'');
  if(raw.length !== 6) return '';
  const iso = `20${raw.slice(0,2)}-${raw.slice(2,4)}-${raw.slice(4,6)}`;
  const date = new Date(`${iso}T00:00:00`);
  if(Number.isNaN(date.getTime())) return '';
  return iso;
}

function compactQrStoreName(value){
  const raw = String(value || '').trim();
  if(raw === 'f' || !raw) return '藤や玩具店';
  return raw.slice(0,120);
}

function parseCompactQrRow(row, common){
  if(!Array.isArray(row) || !row.length){
    throw new Error('QR内の商品情報が不正です');
  }

  const sharedTitleId = String(row[0] || '').trim();
  if(sharedTitleId){
    const master = findMasterById(sharedTitleId);
    const localEntry = !master ? (state.entries || []).find(entry =>
      entry?.owned !== false && String(entry?.sharedTitleId || '').trim() === sharedTitleId
    ) : null;
    const price = Number(row[1] || 0);
    const resolved = master || localEntry;
    return {
      sharedTitleId,
      platform: master?.platform || localEntry?.platform || '',
      title: master?.canonicalTitle || localEntry?.canonicalTitle || localEntry?.title || sharedTitleId,
      maker: master?.maker || localEntry?.maker || '',
      releaseDate: master?.releaseDate || localEntry?.releaseDate || '',
      rawReleaseDate: master?.rawReleaseDate || localEntry?.rawReleaseDate || '',
      genre: master?.genre || localEntry?.genre || '',
      productCode: master?.productCode || localEntry?.productCode || '',
      remarks: master?.remarks || localEntry?.remarks || '',
      purchasePrice: Number.isFinite(price) && price > 0 ? String(Math.round(price)) : '',
      purchaseDate: common.purchaseDate,
      purchaseStore: common.purchaseStore,
      valid: !!resolved,
      invalidReason: resolved ? '' : '図鑑マスターの準備後にもう一度読み取ってください'
    };
  }

  const platform = normalizePlatformName(row[1] || '');
  const title = String(row[2] || '').trim();
  const price = Number(row[3] || 0);
  return {
    sharedTitleId:'',
    platform,
    title,
    maker:'',
    releaseDate:'',
    rawReleaseDate:'',
    genre:'',
    productCode:'',
    remarks:'',
    purchasePrice: Number.isFinite(price) && price > 0 ? String(Math.round(price)) : '',
    purchaseDate: common.purchaseDate,
    purchaseStore: common.purchaseStore,
    valid: !!platform && !!title,
    invalidReason: platform && title ? '' : '機種またはタイトルが不足しています'
  };
}

function parseMitekoreCompactV4(source){
  if(!source || typeof source !== 'object' || Array.isArray(source)) return null;
  if(String(source.a || '') !== 'm' || Number(source.v || 0) !== 4 || !Array.isArray(source.i)){
    return null;
  }

  const part = Math.max(1, Number(source.p || 1) || 1);
  const total = Math.max(1, Number(source.n || 1) || 1);
  if(part > total || total > 99) throw new Error('分割QRの番号が不正です');

  const common = {
    purchaseDate: compactQrDateToIso(source.d),
    purchaseStore: compactQrStoreName(source.s)
  };

  const stickerIds = (() => {
    const raw = source.k;
    const rows = Array.isArray(raw) ? raw : (raw ? [raw] : []);
    return [...new Set(rows.map(value => String(value || '').trim()).filter(Boolean))].slice(0,8);
  })();

  return {
    kind:'mitekore_store_v4',
    batchId:String(source.b || '').trim(),
    part,
    total,
    purchaseDate:common.purchaseDate,
    purchaseStore:common.purchaseStore,
    stickerIds,
    items:source.i.map(row => parseCompactQrRow(row, common))
  };
}

function loadQrPartSessions(){
  try{
    const parsed = JSON.parse(localStorage.getItem(QR_STORE_BATCH_SESSION_KEY) || '{}');
    const now = Date.now();
    const clean = {};
    Object.entries(parsed || {}).forEach(([key,value]) => {
      if(!value || now - Number(value.updatedAt || 0) > QR_STORE_BATCH_EXPIRE_MS) return;
      clean[key] = value;
    });
    localStorage.setItem(QR_STORE_BATCH_SESSION_KEY, JSON.stringify(clean));
    return clean;
  }catch(error){
    return {};
  }
}

function saveQrPartSessions(sessions){
  try{
    localStorage.setItem(QR_STORE_BATCH_SESSION_KEY, JSON.stringify(sessions || {}));
  }catch(error){}
}

function clearQrPartSession(batchId){
  if(!batchId) return;
  const sessions = loadQrPartSessions();
  delete sessions[batchId];
  saveQrPartSessions(sessions);
}

function receiveCompactQrPart(payload){
  if(payload.total <= 1){
    return {complete:true, payload};
  }
  if(!payload.batchId){
    throw new Error('分割QRをまとめる識別情報がありません');
  }

  const sessions = loadQrPartSessions();
  const bundle = sessions[payload.batchId] || {
    total:payload.total,
    parts:{},
    updatedAt:Date.now()
  };

  if(Number(bundle.total) !== Number(payload.total)){
    delete sessions[payload.batchId];
    saveQrPartSessions(sessions);
    throw new Error('同じ組のQR枚数が一致しません。最初から読み直してください');
  }

  const alreadyRead = !!bundle.parts[String(payload.part)];
  bundle.parts[String(payload.part)] = payload;
  bundle.updatedAt = Date.now();
  sessions[payload.batchId] = bundle;
  saveQrPartSessions(sessions);

  const received = Object.keys(bundle.parts).length;
  if(received < payload.total){
    return {
      complete:false,
      alreadyRead,
      received,
      total:payload.total
    };
  }

  const ordered = [];
  for(let part=1; part<=payload.total; part += 1){
    const piece = bundle.parts[String(part)];
    if(!piece){
      return {complete:false,alreadyRead:false,received,total:payload.total};
    }
    ordered.push(piece);
  }

  clearQrPartSession(payload.batchId);

  return {
    complete:true,
    payload:{
      kind:'mitekore_store_v4',
      batchId:payload.batchId,
      part:1,
      total:payload.total,
      purchaseDate:ordered.find(piece => piece.purchaseDate)?.purchaseDate || '',
      purchaseStore:ordered.find(piece => piece.purchaseStore)?.purchaseStore || '藤や玩具店',
      stickerIds:[...new Set(ordered.flatMap(piece => Array.isArray(piece.stickerIds) ? piece.stickerIds : []))],
      items:ordered.flatMap(piece => piece.items || [])
    }
  };
}

function parseQrRegistrationPayload(raw){
  const text = String(raw || '').trim();
  if(!text) throw new Error('QRコードの内容が空です');

  try{
    const parsed = JSON.parse(text);
    const compactPayload = parseMitekoreCompactV4(parsed);
    if(compactPayload) return compactPayload;
    const payload = normalizeQrObject(parsed);
    if(payload) return payload;
  }catch(error){
    if(String(error?.message || '').includes('QR')) throw error;
  }

  try{
    const url = new URL(text);
    const params = Object.fromEntries(url.searchParams.entries());
    const payload = normalizeQrObject(params);
    if(payload) return payload;
    throw new Error('URL内にタイトル情報がありません');
  }catch(error){
    if(/^https?:\/\//i.test(text)) throw error;
  }

  const linePayload = parseQrKeyValueLines(text);
  if(linePayload) return linePayload;

  const parts = text.split('|').map(value => value.trim());
  if(parts.length >= 3 && /^MITEKORE$/i.test(parts[0])){
    return {
      platform: parts[1] || '',
      title: parts[2] || '',
      sharedTitleId: parts[3] || '',
      maker: parts[4] || '',
      releaseDate: '',
      purchaseDate: '',
      purchasePrice: '',
      purchaseStore: '',
      memo: '',
      rating: '',
      owned: null,
      parts: ''
    };
  }

  if(text.length <= 240 && !/[\r\n]/.test(text)){
    return {
      platform:'',
      title:text,
      sharedTitleId:'',
      maker:'',
      releaseDate:'',
      purchaseDate:'',
      purchasePrice:'',
      purchaseStore:'',
      memo:'',
      rating:'',
      owned:null,
      parts:''
    };
  }

  throw new Error('対応している登録用QRコードではありません');
}

function applyQrParts(parts){
  if(!parts) return;
  const enabled = new Set();

  if(Array.isArray(parts)){
    parts.forEach(value => enabled.add(String(value || '').trim().toLowerCase()));
  }else if(typeof parts === 'string'){
    parts.split(/[,、\s]+/).forEach(value => enabled.add(String(value || '').trim().toLowerCase()));
  }else if(typeof parts === 'object'){
    Object.keys(parts).forEach(key => {
      const item = parts[key];
      if(item === true || item?.has === true) enabled.add(String(key).toLowerCase());
    });
  }

  if(!enabled.size) return;

  const aliases = {
    rom:['rom','cassette','cartridge','disc','disk','ソフト','カセット'],
    box:['box','case','箱','ケース'],
    manual:['manual','instruction','説明書','取説'],
    accessory:['accessory','accessories','付属品']
  };

  PARTS.forEach(([key]) => {
    const checked = aliases[key].some(alias => enabled.has(alias.toLowerCase()));
    const checkbox = $(`part_${key}`);
    const condition = $(`cond_${key}`);
    checkbox.checked = checked;
    condition.disabled = !checked;
    if(!checked) condition.value = '';
  });
}

function findExactQrMaster(platform, title){
  const platformName = normalizePlatformName(platform);
  const key = titleKey(title);
  if(!platformName || !key) return null;

  return (MASTER_TITLES || []).find(master =>
    normalizePlatformName(master.platform) === platformName &&
    titleKey(master.canonicalTitle) === key
  ) || null;
}

function applyQrRegistrationPayload(payload){
  const hasInput = Boolean(
    $('editId').value ||
    $('platform').value.trim() ||
    $('title').value.trim()
  );

  if(hasInput){
    const overwrite = window.confirm('入力中の内容を消して、QRコードの内容を読み込みますか？');
    if(!overwrite) return false;
  }

  resetForm();

  if(typeof setUiTab === 'function') setUiTab('register');
  else window.fujiyaMobileTabSwitch?.('register');

  const platform = normalizePlatformName(payload.platform || '');
  $('platform').value = platform;
  $('title').value = String(payload.title || '').trim();

  const directMaster = payload.sharedTitleId
    ? findMasterById(payload.sharedTitleId)
    : null;
  const exactMaster = directMaster || findExactQrMaster(platform, payload.title);

  if(exactMaster){
    selectMaster(exactMaster.sharedTitleId);
  }else{
    clearMasterSelection(false);
    if(payload.maker) $('maker').value = payload.maker;
    if(/^\d{4}-\d{2}-\d{2}$/.test(payload.releaseDate || '')){
      $('releaseDate').value = payload.releaseDate;
    }
    renderMasterCandidates();
  }

  if(payload.owned !== null){
    const radio = document.querySelector(
      `input[name="owned"][value="${payload.owned ? 'owned' : 'want'}"]`
    );
    if(radio) radio.checked = true;
  }

  if(/^[0-5]$/.test(payload.rating || '')){
    $('rating').value = payload.rating;
  }
  if(/^\d{4}-\d{2}-\d{2}$/.test(payload.purchaseDate || '')){
    $('purchaseDate').value = payload.purchaseDate;
  }
  if(/^\d{1,8}$/.test(payload.purchasePrice || '')){
    $('purchasePrice').value = payload.purchasePrice;
  }
  if(payload.purchaseStore) $('purchaseStore').value = payload.purchaseStore.slice(0, 120);
  if(payload.memo) $('memo').value = payload.memo.slice(0, 2000);

  applyQrParts(payload.parts);
  updatePlatformShareNote();
  updateTitleKeyPreview();
  updatePurchaseShareTarget();
  updateClearTimeInputState();
  updateEntrySaveState();

  setTimeout(() => {
    $('entryPanel')?.scrollIntoView({behavior:'smooth', block:'start'});
    $('title')?.focus();
  }, 80);

  return true;
}

function qrBatchItemIdentity(item){
  const directMaster = item.sharedTitleId ? findMasterById(item.sharedTitleId) : null;
  const exactMaster = !directMaster && item.platform && item.title
    ? findExactQrMaster(item.platform,item.title)
    : null;
  const master = directMaster || exactMaster || null;
  const platform = normalizePlatformName(
    master?.platform || item.platform || ''
  );
  const title = String(
    master?.canonicalTitle || item.title || ''
  ).trim();
  const sharedTitleId = String(
    master?.sharedTitleId || item.sharedTitleId || ''
  ).trim();
  const mediaType = normalizeMediaType(
    item.mediaType || item.media_type || 'package'
  );
  const groupKey = titleDisplayGroupKey({
    id:`qr_${item.qrIndex ?? ''}`,
    platform,
    title,
    titleKey:titleKey(title),
    sharedTitleId,
    mediaType
  });
  return {master,platform,title,sharedTitleId,mediaType,groupKey};
}

function qrEntryMatchesIdentity(entry,identity){
  if(!entry || entry.owned === false) return false;
  const entryMedia = normalizeMediaType(entry.mediaType || 'package');
  if(entryMedia !== identity.mediaType) return false;

  const entryShared = String(entry.sharedTitleId || '').trim();
  if(entryShared && identity.sharedTitleId && entryShared === identity.sharedTitleId) return true;

  const entryPlatform = normalizePlatformName(entry.platform || '');
  const entryTitleKey = titleKey(entry.canonicalTitle || entry.title || '');
  const qrTitleKey = titleKey(identity.title || '');
  return !!entryPlatform && !!entryTitleKey && !!qrTitleKey &&
    entryPlatform === identity.platform && entryTitleKey === qrTitleKey;
}

function qrExistingEntriesForItem(item){
  const identity = qrBatchItemIdentity(item);
  return (state.entries || []).filter(entry => qrEntryMatchesIdentity(entry,identity));
}

function qrExistingEntryForItem(item){
  return qrExistingEntriesForItem(item)[0] || null;
}

function prepareQrBatchItems(payload){
  const prepared = (payload.items || []).map((raw,index) => {
    const item = {...raw,qrIndex:index};
    const identity = qrBatchItemIdentity(item);
    const existingEntries = item.valid
      ?qrExistingEntriesForItem(item)
      :[];
    const existingBuybackTargets = existingEntries.filter(entry =>
      buybackEntryEligibility(entry).ok && !buybackHas(entry.id)
    );
    const displayMasterId = String(
      identity.sharedTitleId ||
      existingEntries.find(entry => String(entry.sharedTitleId || '').trim())?.sharedTitleId ||
      ''
    ).trim();
    const buybackGroupKey = existingEntries.length
      ? titleDisplayGroupKey(existingEntries[0])
      : identity.groupKey;
    return {
      ...item,
      ...identity,
      displayMasterId,
      buybackGroupKey,
      existingCount:existingEntries.length,
      existingTitle:existingEntries[0]?.title || '',
      existingBuybackAvailableCount:existingBuybackTargets.length,
      existingBuybackAlreadyCount:existingEntries.filter(entry => buybackHas(entry.id)).length
    };
  });

  const qrGroupCounts = new Map();
  prepared
    .filter(item => item.valid && item.groupKey)
    .forEach(item => {
      qrGroupCounts.set(
        item.groupKey,
        Number(qrGroupCounts.get(item.groupKey) || 0) + 1
      );
    });

  const qrGroupPositions = new Map();
  return prepared.map(item => {
    const qrGroupCount = Number(qrGroupCounts.get(item.groupKey) || 0);
    const position = Number(qrGroupPositions.get(item.groupKey) || 0) + 1;
    qrGroupPositions.set(item.groupKey,position);

    const duplicateExisting = item.existingCount > 0;
    const duplicateInQr = qrGroupCount > 1;
    return {
      ...item,
      qrGroupCount,
      qrGroupPosition:position,
      duplicateExisting,
      duplicateInQr,
      duplicate:duplicateExisting || duplicateInQr,
      // QRを読む行為は購入個体の登録。既登録かどうかに関係なく、登録可能な行は全件を初期選択する。
      // 重複タイトルの買取判断は登録完了後の別ステップで行う。
      selected:!!item.valid
    };
  });
}

function updateQrBatchSelectedCount(){
  const checks = Array.from(
    document.querySelectorAll('#qrBatchList [data-qr-batch-index]')
  );
  const selectable = checks.filter(check => !check.disabled).length;
  const selected = checks.filter(check => check.checked && !check.disabled).length;
  const selectedItems = checks
    .filter(check => check.checked && !check.disabled)
    .map(check => qrBatchReviewItems[Number(check.dataset.qrBatchIndex)])
    .filter(Boolean);

  const selectedByGroup = new Map();
  selectedItems.forEach(item => {
    selectedByGroup.set(
      item.groupKey,
      Number(selectedByGroup.get(item.groupKey) || 0) + 1
    );
  });
  const duplicateGroups = new Set();
  selectedItems.forEach(item => {
    const projectedCount =
      Number(item.existingCount || 0) +
      Number(selectedByGroup.get(item.groupKey) || 0);
    if(projectedCount > 1) duplicateGroups.add(item.groupKey);
  });

  const count = $('qrBatchSelectedCount');
  const button = $('qrBatchRegisterBtn');
  if(count){
    if(!selected){
      count.textContent = '登録するタイトルを選択してください';
    }else{
      count.textContent = `${selected}件を登録予定${duplicateGroups.size ? `・登録後に重複${duplicateGroups.size}タイトルを確認` : ''}`;
    }
  }
  if(button){
    button.disabled = selected < 1;
    button.textContent = selected === selectable && selected > 0
      ? 'この内容で登録'
      : (selected > 0 ? `選択した${selected}件を登録` : 'この内容で登録');
  }
}

function renderQrBatchReview(){
  const list = $('qrBatchList');
  if(!list) return;

  list.innerHTML = qrBatchReviewItems.map((item,index) => {
    const stateClass = !item.valid
      ?'invalid'
      :(item.duplicateExisting
        ?'duplicate'
        :(item.duplicateInQr ?'qr-repeat':''));
    let stateText = '未登録';

    if(!item.valid){
      stateText = item.invalidReason;
    }else if(item.duplicateExisting){
      stateText = `登録済み${item.existingCount}本あり・登録後に重複確認`;
    }else if(item.duplicateInQr){
      // 通常運用では発生しない想定。QR生成ミスへの保険表示。
      stateText = '同じタイトルがQR内に複数あります';
    }

    const priceText = item.purchasePrice
      ?`${Number(item.purchasePrice).toLocaleString('ja-JP')}円`
      :'価格なし';

    return `
      <div class="qr-batch-item ${stateClass}">
        <input
          class="qr-batch-check"
          type="checkbox"
          data-qr-batch-index="${index}"
          aria-label="${esc(item.title || 'このタイトル')}を新しく登録"
          ${item.selected ? 'checked' : ''}
          ${item.valid ? '' : 'disabled'}
        >
        <span class="qr-batch-platform">${esc(item.platform || '不明')}</span>
        <span>
          <span class="qr-batch-title">${esc(item.title || item.sharedTitleId || 'タイトル不明')}</span>
          <span class="qr-batch-sub">
            ${item.displayMasterId ? esc(item.displayMasterId) : 'マスター未登録'}
            ${(item.master?.maker || item.maker) ? ` / ${esc(item.master?.maker || item.maker)}` : ''}
          </span>
          <span class="qr-batch-state ${stateClass}">${esc(stateText)}</span>
        </span>
        <span class="qr-batch-price">${priceText}</span>
      </div>`;
  }).join('');

  updateQrBatchSelectedCount();
}

function openQrBatchReview(payload){
  qrBatchReviewMeta = {
    purchaseDate:payload.purchaseDate || '',
    purchaseStore:payload.purchaseStore || '藤や玩具店',
    totalQrParts:payload.total || 1,
    stickerIds:Array.isArray(payload.stickerIds) ? [...new Set(payload.stickerIds.map(value => String(value || '').trim()).filter(Boolean))] : []
  };
  qrBatchReviewItems = prepareQrBatchItems(payload);

  const validCount = qrBatchReviewItems.filter(item => item.valid).length;
  const existingDuplicateGroupCount = new Set(
    qrBatchReviewItems
      .filter(item => item.valid && item.duplicateExisting)
      .map(item => item.groupKey)
  ).size;
  const totalPrice = qrBatchReviewItems.reduce(
    (sum,item) => sum + Number(item.purchasePrice || 0),
    0
  );

  $('qrBatchSummary').innerHTML = `
    <div><strong>${esc(qrBatchReviewMeta.purchaseStore)}</strong><span>購入店舗</span></div>
    <div><strong>${qrBatchReviewMeta.purchaseDate ? fmtDateOnly(qrBatchReviewMeta.purchaseDate) : '未設定'}</strong><span>購入日</span></div>
    <div><strong>${validCount}本 / ${totalPrice.toLocaleString('ja-JP')}円</strong><span>${existingDuplicateGroupCount ? `登録済み ${existingDuplicateGroupCount}タイトル` : 'すべて未登録'}</span></div>
    ${qrBatchReviewMeta.stickerIds.length ? `<div><strong>シール ${qrBatchReviewMeta.stickerIds.length}枚付き</strong><span>登録完了後に獲得</span></div>` : ''}
  `;

  renderQrBatchReview();
  const modal = $('qrBatchReviewModal');
  setQrRegistrationModalOpen(true);
  modal.classList.add('show');
  modal.setAttribute('aria-hidden','false');
}

function closeQrBatchReview(keepFlow=false){
  const modal = $('qrBatchReviewModal');
  if(modal){
    modal.classList.remove('show');
    modal.setAttribute('aria-hidden','true');
  }
  qrBatchReviewItems = [];
  qrBatchReviewMeta = {};
  if(!keepFlow) setQrRegistrationModalOpen(false);
}

function setQrBatchSelection(mode){
  document.querySelectorAll('#qrBatchList [data-qr-batch-index]').forEach(check => {
    if(check.disabled) return;
    const item = qrBatchReviewItems[Number(check.dataset.qrBatchIndex)];
    if(mode === 'none') check.checked = false;
    else if(mode === 'all') check.checked = true;
    else check.checked = !!item?.valid;
  });
  updateQrBatchSelectedCount();
}

function createEntryFromStoreQr(item){
  const identity = qrBatchItemIdentity(item);
  const master = identity.master;
  const platform = identity.platform;
  const title = identity.title;

  const entry = norm({
    id:uid(),
    platform,
    title,
    owned:true,
    mediaType:identity.mediaType,
    rating:0,
    purchaseDate:item.purchaseDate || qrBatchReviewMeta.purchaseDate || '',
    purchasePrice:item.purchasePrice || '',
    purchaseStore:item.purchaseStore || qrBatchReviewMeta.purchaseStore || '藤や玩具店',
    releaseDate:master?.releaseDate || item.releaseDate || '',
    rawReleaseDate:master?.rawReleaseDate || item.rawReleaseDate || '',
    maker:master?.maker || item.maker || '',
    genre:master?.genre || item.genre || '',
    productCode:master?.productCode || item.productCode || '',
    remarks:master?.remarks || item.remarks || '',
    memo:'',
    createdAt:nowIso(),
    updatedAt:nowIso(),
    titleKey:titleKey(master?.canonicalTitle || title),
    canonicalTitle:master?.canonicalTitle || title,
    sharedTitleId:master?.sharedTitleId || '',
    sharedStatus:master ? 'confirmed' : 'unconfirmed',
    localSharedId:''
  });

  if(master){
    entry.title = master.canonicalTitle;
    entry.platform = master.platform;
    entry.titleKey = titleKey(master.canonicalTitle);
    entry.canonicalTitle = master.canonicalTitle;
    entry.sharedTitleId = master.sharedTitleId;
    entry.sharedStatus = 'confirmed';
  }

  ensureSharedFields(entry);
  return entry;
}

function registerSelectedQrBatch(){
  const selected = Array.from(
    document.querySelectorAll('#qrBatchList [data-qr-batch-index]:checked')
  ).map(check => qrBatchReviewItems[Number(check.dataset.qrBatchIndex)])
   .filter(item => item?.valid);

  if(!selected.length){
    toast('登録するタイトルを選択してください');
    return;
  }

  const registeredPairs = selected.map(item => ({
    item,
    entry:createEntryFromStoreQr(item)
  }));
  const newEntries = registeredPairs.map(pair => pair.entry);
  const stickerIdsToAcquire = Array.isArray(qrBatchReviewMeta.stickerIds)
    ? [...qrBatchReviewMeta.stickerIds]
    : [];

  createUndoSnapshot('QR一括登録の前');
  state.entries = [...newEntries, ...(state.entries || [])];

  if(!save()){
    state.entries = state.entries.slice(newEntries.length);
    toast('QR登録データを保存できませんでした');
    return;
  }

  addEventLog(
    'add',
    newEntries[0] || null,
    `藤や玩具店QRから一括登録：${newEntries.length}件`
  );
  newEntries.forEach(entry =>
    addRareLogIfNeeded(entry,'QR購入登録時にレア判定')
  );

  // 登録完了後に初めて重複を確認する。QR登録そのものは重複の有無で止めない。
  // 同じタイトルが複数行あるQRでも、タイトルごとに1回だけ案内し、今回登録した個体を既定候補にする。
  const duplicateStepByGroup = new Map();
  registeredPairs.forEach(({item,entry}) => {
    const matches = qrExistingEntriesForItem(item);
    if(matches.length <= 1) return;
    const groupKey = titleDisplayGroupKey(entry);
    if(!duplicateStepByGroup.has(groupKey)){
      duplicateStepByGroup.set(groupKey,{
        groupKey,
        preferredEntryId:String(entry.id),
        candidateIds:matches.map(match => String(match.id)),
        platform:entry.platform || '',
        title:entry.title || ''
      });
    }
  });
  const duplicateSteps = [...duplicateStepByGroup.values()];

  closeQrBatchReview();
  resetForm();
  render();
  renderBuybackPanel();

  if(typeof setUiTab === 'function') setUiTab('list');
  else window.fujiyaMobileTabSwitch?.('list');

  scheduleAutoSync('店舗QR登録');

  stickerIdsToAcquire.forEach(stickerId => {
    try{
      const already = !!window.fujiyaStickerAlbum?.has?.(stickerId);
      if(!already && typeof window.fujiyaAcquireSticker === 'function'){
        window.fujiyaAcquireSticker(stickerId,'store-qr');
      }
    }catch(error){
      console.warn('店舗QRのシール付与を後回しにしました',stickerId,error);
    }
  });

  if(duplicateSteps.length){
    toast(`${newEntries.length}本を登録しました。重複タイトルを確認します`);
    setTimeout(() => startQrPostRegistrationBuybackFlow(duplicateSteps),120);
  }else{
    toast(`${newEntries.length}本を登録しました`);
    showMikeTalk(`${newEntries.length}本を登録したよ。`);
  }
}

async function handleQrRegistrationText(raw){
  if(qrScannerBusy) return;
  qrScannerBusy = true;

  try{
    const rawText = String(raw || '').trim();
    let looksLikeStoreV4 = false;
    try{
      const probe = JSON.parse(rawText);
      looksLikeStoreV4 = !!probe && String(probe.a || '') === 'm' && Number(probe.v || 0) === 4;
    }catch(error){}

    if(looksLikeStoreV4 && typeof window.fujiyaEnsureTitleMaster === 'function'){
      setQrScannerStatus('図鑑マスターと所持データを照合しています…');
      try{
        await window.fujiyaEnsureTitleMaster('qr',{showOverlay:false});
      }catch(error){
        console.warn('QR読取前の図鑑マスター準備を完了できませんでした',error);
      }
    }

    const payload = parseQrRegistrationPayload(rawText);

    if(payload?.kind === 'mitekore_store_v4'){
      const result = receiveCompactQrPart(payload);

      if(!result.complete){
        const prefix = result.alreadyRead ? 'このQRは読み取り済みです。' : `${payload.part}/${payload.total}枚目を読み取りました。`;
        setQrScannerStatus(
          `${prefix} 現在${result.received}/${result.total}枚です。次のQRを映してください。`,
          result.alreadyRead ? 'warn' : 'good'
        );
        toast(`分割QR ${result.received}/${result.total}枚を読み取り済み`);
        return;
      }

      stopQrCamera();
      setQrScannerStatus(
        `${result.payload.items.length}タイトルを読み取りました。登録内容を確認します。`,
        'good'
      );
      setTimeout(() => {
        closeQrScanner(true);
        openQrBatchReview(result.payload);
      }, 300);
      return;
    }

    const applied = applyQrRegistrationPayload(payload);
    if(!applied){
      setQrScannerStatus('読み取り内容の反映をキャンセルしました。', 'warn');
      return;
    }

    stopQrCamera();
    setQrScannerStatus(
      `${payload.platform ? payload.platform + ' / ' : ''}${payload.title || 'タイトル'}を読み取りました。`,
      'good'
    );
    setTimeout(closeQrScanner, 450);
    toast('QRコードの内容を登録フォームへ入力しました');
    window.dispatchEvent(new CustomEvent('fujiya-entry-qr-applied'));
  }catch(error){
    console.error(error);
    setQrScannerStatus(
      `読み取れませんでした：${String(error?.message || error)}`,
      'bad'
    );
  }finally{
    setTimeout(() => { qrScannerBusy = false; }, 500);
  }
}

async function readQrFromImageFile(file){
  if(!file) return;

  try{
    setQrScannerStatus('画像を解析しています…');
    await loadQrLibrary();

    const bitmap = await createImageBitmap(file);
    const canvas = $('qrScannerCanvas');
    const maxSize = 1400;
    const scale = Math.min(1, maxSize / Math.max(bitmap.width, bitmap.height));
    canvas.width = Math.max(1, Math.round(bitmap.width * scale));
    canvas.height = Math.max(1, Math.round(bitmap.height * scale));

    const context = canvas.getContext('2d', {willReadFrequently:true});
    context.drawImage(bitmap, 0, 0, canvas.width, canvas.height);
    bitmap.close?.();

    const imageData = context.getImageData(0, 0, canvas.width, canvas.height);
    const code = window.jsQR(
      imageData.data,
      imageData.width,
      imageData.height,
      {inversionAttempts:'attemptBoth'}
    );

    if(!code?.data) throw new Error('画像内にQRコードが見つかりません');
    await handleQrRegistrationText(code.data);
  }catch(error){
    console.error(error);
    setQrScannerStatus(
      `画像を読み取れませんでした：${String(error?.message || error)}`,
      'bad'
    );
  }finally{
    $('qrImageInput').value = '';
  }
}

function bindQrRegistration(){
  if(!window.__MITEKORE_QR_MODAL_CHROME_GUARD__ && document.body && typeof MutationObserver === 'function'){
    window.__MITEKORE_QR_MODAL_CHROME_GUARD__ = new MutationObserver(() => refreshRegistrationModalChromeSuppression());
    window.__MITEKORE_QR_MODAL_CHROME_GUARD__.observe(document.body,{attributes:true,attributeFilter:['class']});
  }
  refreshRegistrationModalChromeSuppression();
  $('qrRegisterBtn')?.addEventListener('click', openQrScanner);
  $('qrScannerCloseBtn')?.addEventListener('click', () => closeQrScanner(false));
  $('qrScannerCancelBtn')?.addEventListener('click', () => closeQrScanner(false));
  $('qrStartCameraBtn')?.addEventListener('click', startQrCamera);
  $('qrImageInput')?.addEventListener('change', event => {
    readQrFromImageFile(event.target.files?.[0]);
  });
  $('qrScannerModal')?.addEventListener('click', event => {
    if(event.target === $('qrScannerModal')) closeQrScanner();
  });
  $('qrBatchCloseBtn')?.addEventListener('click', () => closeQrBatchReview(false));
  $('qrBatchCancelBtn')?.addEventListener('click', () => closeQrBatchReview(false));
  $('qrBatchRegisterBtn')?.addEventListener('click', registerSelectedQrBatch);
  $('qrBatchSelectNewBtn')?.addEventListener('click', () => setQrBatchSelection('new'));
  $('qrBatchSelectAllBtn')?.addEventListener('click', () => setQrBatchSelection('all'));
  $('qrBatchSelectNoneBtn')?.addEventListener('click', () => setQrBatchSelection('none'));
  $('qrBatchList')?.addEventListener('change', updateQrBatchSelectedCount);
  $('qrBatchReviewModal')?.addEventListener('click', event => {
    if(event.target === $('qrBatchReviewModal')) closeQrBatchReview();
  });
  document.addEventListener('visibilitychange', () => {
    if(document.hidden) stopQrCamera();
  });
}

