  $('variantSeparateBtn').addEventListener('click', () => answerVariantDecision('unifySeparate'));
  $('variantUnconfirmedBtn').addEventListener('click', () => answerVariantDecision('unconfirmed'));
  $('variantCancelBtn').addEventListener('click', () => answerVariantDecision('cancel'));
  $('variantModal').addEventListener('click', ev => {
    if(ev.target === $('variantModal')) answerVariantDecision('cancel');
  });

  $('imageModalCloseBtn').addEventListener('click', closeImageModal);
  $('imageModal').addEventListener('click', ev => {
    if(ev.target === $('imageModal')) closeImageModal();
  });
  $('cardDetailCloseBtn').addEventListener('click', closeCardDetail);
  $('cardDetailModal').addEventListener('click', ev => {
    if(ev.target === $('cardDetailModal')) closeCardDetail();
  });
  $('cardDetailBody').addEventListener('click', handleDetailModalAction);

  $('rematchCloseBtn').addEventListener('click', closeRematchModal);
  $('rematchModal').addEventListener('click', ev => {
    if(ev.target === $('rematchModal')) closeRematchModal();
  });
  $('rematchList').addEventListener('click', ev => {
    const btn = ev.target.closest('[data-rematch-master-id]');
    if(!btn || !rematchEntryId) return;
    applyMasterToEntry(rematchEntryId, btn.dataset.rematchMasterId);
  });

  document.addEventListener('keydown', ev => {
    if(ev.key === 'Escape' && $('confirmModal').classList.contains('show')) answerDeleteConfirm(false);
    if(ev.key === 'Escape' && $('imageModal').classList.contains('show')) closeImageModal();
    if(ev.key === 'Escape' && $('duplicateModal').classList.contains('show')) answerDuplicateDecision('cancel');
    if(ev.key === 'Escape' && $('variantModal').classList.contains('show')) answerVariantDecision('cancel');
    if(ev.key === 'Escape' && $('rematchModal').classList.contains('show')) closeRematchModal();
    if(ev.key === 'Escape' && $('importModeModal').classList.contains('show')) answerImportMode(null);
    if(ev.key === 'Escape' && $('tutorialModal')?.classList.contains('show')) closeTutorialModal(false);
    if(ev.key === 'Escape' && $('firstRunModal')?.classList.contains('show')) closeFirstRunModal();
    if(ev.key === 'Escape' && $('qrScannerModal')?.classList.contains('show')) closeQrScanner();
    if(ev.key === 'Escape' && $('qrBatchReviewModal')?.classList.contains('show')) closeQrBatchReview();
  });

  bindParts();
  updateClearTimeInputState();

  document.querySelectorAll('[data-collapse-toggle]').forEach(btn => {
    btn.addEventListener('click', () => toggleCollapsePanel(btn.dataset.collapseToggle));
  });

  $('photo').addEventListener('change', async ev => {
    const file = ev.target.files?.[0];
    if(!file) return;

    try{
      const data = await resizeImage(file);
      state.photoData = data;
      state.removePhoto = false;
      state.photoViewX = 0;
      state.photoViewY = 0;
      state.photoViewScale = 1;
      state.photoViewRotate = 0;
      state.photoViewSet = true;
      state.photoPreviewShape = 'list';
      $('photoPreview').src = data;
      $('photoPreview').style.display = 'block';
      window.fujiyaPhotoAdjustSync?.();
      toast('画像を読み込みました。表示枠で位置を調整できます');
    }catch(e){
      console.error(e);
      toast('画像の読み込みに失敗しました');
    }
  });

  $('clearPhotoBtn').addEventListener('click', () => {
    state.photoData = '';
    state.removePhoto = true;
    state.photoViewX = 0;
    state.photoViewY = 0;
    state.photoViewScale = 1;
    state.photoViewRotate = 0;
    state.photoViewSet = false;
    state.photoPreviewShape = 'list';
    $('photo').value = '';
    $('photoPreview').style.display = 'none';
    $('photoPreview').src = '';
    window.fujiyaPhotoAdjustSync?.();
    toast('画像を外しました');
  });

  $('entryForm').addEventListener('keydown', ev => {
    if(ev.key !== 'Enter') return;
    const target = ev.target;
    if(!target) return;
    if(target.matches('textarea, select, button, input[type="button"], input[type="submit"], input[type="file"]')) return;
    ev.preventDefault();
    ev.stopPropagation();
    flashEntryEnterGuard();
  });

  $('entryForm').addEventListener('submit', async ev => {
    ev.preventDefault();

    // ローカルHTMLや一部ブラウザでは SubmitEvent.submitter が取得できない場合がある。
    // Enterキーによる誤登録は keydown 側で防いでいるため、ここでは保存ボタンの有効状態だけ確認する。
    const saveButton = $('saveBtn');
    if(!saveButton || saveButton.disabled){
      updateEntrySaveState();
      return;
    }

    const id = $('editId').value;
    const old = id ? state.entries.find(e => e.id === id) : null;
    const oldRating = old ? ratingNumber(old.rating) : 0;
    const title = $('title').value.trim();
    const platform = normalizePlatformName($('platform').value);
    const mediaType = normalizeMediaType(document.querySelector('input[name="mediaType"]:checked')?.value || 'package');

    if(!platform){
      toast('機種名を入れてください');
      $('platform').focus();
      return;
    }
    $('platform').value = platform;
    updatePlatformShareNote();

    if(!title){
      toast('タイトルを入れてください');
      return;
    }

    const selectedMaster = isSharedPlatform(platform) ? (state.selectedMaster || findMasterById($('selectedMasterId').value)) : null;
    const duplicate = !old ? findDuplicateEntry(platform, title, '', mediaType) : null;
    let sharedDecision = selectedMaster ? 'master' : null;
    let sharedExisting = null;
    let duplicateBuybackPickerRequested = false;

    if(duplicate){
      const sameVisibleTitle = String(duplicate.title || '').trim() === title;
      if(selectedMaster || sameVisibleTitle){
        const decision = await askDuplicateDecision(duplicate, title);
        if(decision === 'edit'){
          editEntry(duplicate.id);
          toast('既存データを編集モードで開きました');
          return;
        }
        if(decision === 'buyback'){
          duplicateBuybackPickerRequested = true;
        }else if(decision !== 'separate'){
          toast('登録をキャンセルしました');
          return;
        }
        if(!selectedMaster){
          sharedDecision = 'link';
          sharedExisting = duplicate;
        }
      }else{
        sharedDecision = await askVariantDecision(duplicate, title);
        sharedExisting = duplicate;
        if(sharedDecision === 'edit'){
          editEntry(duplicate.id);
          toast('既存データを編集モードで開きました');
          return;
        }
        if(sharedDecision === 'cancel'){
          toast('登録をキャンセルしました');
          return;
        }
      }
    }

    const entry = norm({
      id: id || uid(),
      platform,
      title,
      owned: document.querySelector('input[name="owned"]:checked').value === 'owned',
      mediaType,
      rating: ratingNumber($('rating').value),
      playStatus: document.querySelector('input[name="owned"]:checked').value === 'owned' ? normalizePlayStatus($('playStatus')?.value) : '',
      clearHours: document.querySelector('input[name="owned"]:checked').value === 'owned' && normalizePlayStatus($('playStatus')?.value) === 'cleared' ? normalizeClearHours($('clearHours')?.value) : '',
      purchaseDate: $('purchaseDate').value,
      purchasePrice: $('purchasePrice').value,
      purchaseStore: $('purchaseStore').value.trim(),
      overallCondition: $('overallCondition') ? $('overallCondition').value : (old?.overallCondition || ''),
      operationChecked: $('operationChecked') ? $('operationChecked').checked : !!old?.operationChecked,
      buybackOperationStatus: $('buybackOperationStatus') ? normalizeBuybackOperationStatus($('buybackOperationStatus').value) : buybackOperationStatusValue(old),
      cleaned: $('cleaned') ? $('cleaned').checked : !!old?.cleaned,
      stockLocation: $('stockLocation') ? $('stockLocation').value.trim() : (old?.stockLocation || ''),
      marketMemo: $('marketMemo') ? $('marketMemo').value.trim() : (old?.marketMemo || ''),
      releaseDate: $('releaseDate').value,
      maker: $('maker').value.trim(),
      parts: getPartsForm(),
    accessoryRequired: !!$('accessoryRequired')?.checked,
      memo: $('memo').value.trim(),
      photoData: state.photoData || (old && !state.removePhoto ? old.photoData : ''),
      photoViewX: Math.max(-80,Math.min(80,Number(state.photoViewX)||0)),
      photoViewY: Math.max(-80,Math.min(80,Number(state.photoViewY)||0)),
      photoViewScale: Math.max(1,Math.min(2.5,Number(state.photoViewScale)||1)),
      photoViewRotate: normalizePhotoRotate(state.photoViewRotate),
      photoViewSet: !!state.photoViewSet,
      createdAt: old?.createdAt || nowIso(),
      updatedAt: nowIso(),
      sharedTitleId: old?.sharedTitleId || '',
      titleKey: old?.titleKey || titleKey(title),
      canonicalTitle: old?.canonicalTitle || title,
      sharedStatus: old?.sharedStatus || 'unconfirmed',
      localSharedId: old?.localSharedId || ''
    });

    if(sharedDecision === 'master' && selectedMaster){
      entry.title = selectedMaster.canonicalTitle;
      entry.platform = selectedMaster.platform;
      entry.titleKey = titleKey(selectedMaster.canonicalTitle);
      entry.canonicalTitle = selectedMaster.canonicalTitle;
      entry.sharedTitleId = selectedMaster.sharedTitleId;
      entry.sharedStatus = 'confirmed';
      entry.localSharedId = '';
      entry.releaseDate = selectedMaster.releaseDate || entry.releaseDate || '';
      entry.rawReleaseDate = selectedMaster.rawReleaseDate || '';
      entry.maker = selectedMaster.maker || entry.maker || '';
      entry.genre = selectedMaster.genre || '';
      entry.productCode = selectedMaster.productCode || '';
      entry.remarks = selectedMaster.remarks || '';
    }else if((sharedDecision === 'link' || sharedDecision === 'unifySeparate') && sharedExisting){
      const unifiedTitle = sharedExisting.canonicalTitle || sharedExisting.title;
      entry.title = sharedDecision === 'unifySeparate' ? unifiedTitle : entry.title;
      entry.titleKey = sharedExisting.titleKey || titleKey(sharedExisting.title);
      entry.canonicalTitle = unifiedTitle;
      entry.sharedTitleId = sharedExisting.sharedTitleId || '';
      entry.sharedStatus = sharedExisting.sharedTitleId ? 'confirmed' : 'local';
      entry.localSharedId = sharedExisting.localSharedId || makeLocalSharedId(entry.platform, entry.titleKey);
    }else if(sharedDecision === 'separate'){
      entry.titleKey = titleKey(title);
      entry.canonicalTitle = title;
      entry.sharedStatus = 'unconfirmed';
      entry.localSharedId = '';
    }else if(sharedDecision === 'unconfirmed'){
      entry.titleKey = titleKey(title);
      entry.canonicalTitle = title;
      entry.sharedStatus = 'unconfirmed';
      entry.localSharedId = '';
    }

    ensureSharedFields(entry);
    try{deviceSyncMarkExplicitEntryEdit?.(entry.id,entry.updatedAt);}catch(error){}

    await entryPhotoPersistEntry(entry);
    // RC1.4.541: 「画像なし」と「ユーザーが画像を外した」を区別する。
    // 削除だけ明示stateとして同期し、別端末に画像が無いだけでは写真を消さない。
    try{
      if(state.removePhoto)window.deviceSyncMarkEntryPhotoDeleted?.(id,entry.updatedAt);
      else if(entry.photoData)window.deviceSyncMarkEntryPhotoActive?.(id);
      window.deviceSyncEntryPhotoCommitted?.(id,String(entry.photoData||''),entry.updatedAt,!!state.removePhoto);
    }catch(error){}

    const buybackDataChanged = !!(old && buybackHas(id) && buybackComparableSnapshot(old) !== buybackComparableSnapshot(entry));
    const profileV201WasWanted=!!(old&&old.owned===false&&entry.owned!==false);
    createUndoSnapshot(old ? '編集の前' : '登録の前', old ? {keepPhotoEntryIds:[old.id]} : {});
    if(old){
      state.entries = state.entries.map(e => e.id === id ? entry : e);
    }else{
      state.entries.unshift(entry);
    }

    // RC1.4.543: 登録画像を保存した編集は、localStorage保存→自動同期より先に
    // IndexedDB画像キャッシュを確定させる。これで「ソフト更新だけ届いて画像が落ちる」競合を防ぐ。
    const photoSyncChanged = state.removePhoto || String(entry.photoData||'') !== String(old?.photoData||'');
    if(photoSyncChanged && typeof window.deviceSyncPrepareAllUserData==='function'){
      try{await window.deviceSyncPrepareAllUserData();}catch(error){console.warn('登録画像の同期準備を完了できませんでした',error);}
    }

    if(save()){
      let buybackNeedsResend = false;
      if(old && buybackDataChanged && buybackEntryEligibility(entry).ok){
        buybackNeedsResend = markBuybackEntryNeedsResend(entry.id);
      }
      if(profileV201WasWanted&&typeof profileV201IncrementMetric==='function'){
        profileV201IncrementMetric('wanted_acquired',1);
        if(!(state.entries||[]).some(item=>item&&item.owned===false))profileV201IncrementMetric('wanted_cleared_all',1);
      }
      const eventType = old ? 'edit' : 'add';
      addEventLog(eventType, entry, old ? '情報を更新' : 'コレクション追加');
      if(!old) addRareLogIfNeeded(entry, '登録時にレア判定');
      const talkMessage = buildEventTalk(eventType, entry, {oldRating});
      resetForm();
      render();

      // RC1_4_148:
      // 登録編集で画像位置・拡大率を変更しても、これまでは
      // ショーケース本体だけrender()で更新され、プロフィール側へ変更通知されていなかった。
      // 展示中entryならショーケース変更イベントを出し、
      // 1) 開いている自分プロフィールを即再描画
      // 2) みてレコのprofilePayloadを再生成
      // 3) 他ユーザー向け公開プロフィールへ新しいX/Y/Scaleを同期
      // まで既存のイベント経路で行う。
      if((state.shelfEntryIds || []).some(shelfId => String(shelfId) === String(entry.id))){
        window.dispatchEvent(new Event('fujiya-showcase-changed'));
      }

      toast(
        old
          ?(buybackNeedsResend
            ?'編集を保存しました。買取依頼は要再送です'
            :'編集を保存しました')
          :(duplicateBuybackPickerRequested
            ?'別個体として登録しました。買取へ出す個体を選んでください'
            :'登録しました')
      );
      const reminder = backupReminderMessage();
      const eventPost = !old ? safeBuildEntryXPost('add', entry) : '';
      const buybackTalk = duplicateBuybackPickerRequested
        ?'\n\n同じタイトルの所持個体を表示します。買取相談へ入れる個体を選んでください。'
        :'';
      const eventTalkBase = talkMessage + buybackTalk;
      const eventTalkText = reminder
        ?eventTalkBase + '\n\n' + reminder
        :eventTalkBase;
      forceEventMikeNavi(eventTalkText, eventPost);
      triggerRareBurstIfNeeded(entry, old ? 'edit' : 'add');
      scheduleAutoSync(old ? '編集保存' : '新規登録');
      if(!old && duplicateBuybackPickerRequested){
        setTimeout(() => openBuybackEntryPicker({
          filterEntryId:entry.id
        }), 80);
      }
    }
  });

  $('cancelEditBtn').addEventListener('click', resetForm);

  $('deleteFromFormBtn').addEventListener('click', () => {
    const id = $('editId').value;
    if(id) deleteEntry(id);
  });

  $('title').addEventListener('input', () => {
    if(state.selectedMaster && $('title').value !== state.selectedMaster.canonicalTitle){
      clearMasterSelection(false);
    }
    updateTitleKeyPreview();
    updateEntrySaveState();
    clearTimeout(titleCandidateTimer);
    titleCandidateTimer = setTimeout(renderMasterCandidates, 220);
  });

