      const data = JSON.parse(jsonText);
      const imported = Array.isArray(data.entries) ? data.entries.map(norm) : [];
      createUndoSnapshot('JSON復元の前');
      const importedTargets = data.platformTargets && typeof data.platformTargets === 'object' ? data.platformTargets : {};
      const importedUserName = String(data.userName || '').trim();
      if(!imported.length){
        toast('読み込めるデータがありません');
        return;
      }
      window.fujiyaProcessing?.end(readProcessingToken);
      readProcessingToken = '';
      const mode = await askImportMode(imported.length);
      if(mode === null){
        toast('JSON復元をキャンセルしました');
        return;
      }
      restoreProcessingToken = window.fujiyaProcessing?.start({
        title:'JSONバックアップを復元しています',
        detail:`${imported.length.toLocaleString('ja-JP')}件の登録データと設定を反映しています。`,
        total:imported.length
      }) || '';
