      state.entries = add ? [...imported, ...state.entries] : imported;
      state.platformTargets = add ? {...importedTargets, ...state.platformTargets} : importedTargets;
      restoreSettingsFromBackup(data, mode);
      await entryPhotoHydrateEntries(imported);
      const restoredExtended = await restoreExtendedBackupData(data, mode);
      addEventLog('restore', null, add ? `JSON追加復元：${imported.length}件` : (mode.keepUserId ? `JSON置き換え復元・ID引き継ぎ：${imported.length}件` : `JSON置き換え復元・新ID：${imported.length}件`));
