          rawReleaseDate:o.raw_release_date || '',
          maker:o.maker || '',
          genre:o.genre || '',
          productCode:o.product_code || '',
          remarks:o.remarks || '',
          purchasePrice:o.purchase_price || '',
          purchaseStore:o.purchase_store || '',
          overallCondition:o.overall_condition || '',
          operationChecked:yes(o.operation_checked),
          cleaned:yes(o.cleaned),
          stockLocation:o.stock_location || '',
          marketMemo:o.market_memo || '',
