function devicePairBase64UrlEncode(text){
  const bytes = new TextEncoder().encode(String(text || ''));
  let binary = '';
  bytes.forEach(value => binary += String.fromCharCode(value));
  return btoa(binary).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
}

function devicePairCompactEndpointToken(endpoint){
  const normalized = devicePairNormalizeEndpoint(endpoint || getGasEndpoint());
  try{
    if(normalized === devicePairNormalizeEndpoint(DEFAULT_GAS_ENDPOINT)) return 'd';
  }catch(error){}
  const match = normalized.match(/^https:\/\/script\.google\.com\/macros\/s\/([A-Za-z0-9_-]+)\/exec$/);
  return match ? `x${match[1]}` : '';
}

function devicePairEndpointFromCompactToken(token){
  const value = String(token || '');
  if(value === 'd') return devicePairNormalizeEndpoint(DEFAULT_GAS_ENDPOINT);
  if(/^x[A-Za-z0-9_-]+$/.test(value)){
    return devicePairNormalizeEndpoint(`https://script.google.com/macros/s/${value.slice(1)}/exec`);
  }
  throw new Error('接続QRの同期サーバー情報が正しくありません');
}

function devicePairBuildUrl(key,minRevision=0,endpoint='',prepRequestId=''){
  const startedAt = Date.now();
  const expiresAt = startedAt + DEVICE_PAIR_TTL_MS;
  const relayEndpoint = devicePairNormalizeEndpoint(endpoint || getGasEndpoint());
  const ownerUserId = deviceIdentityPrepareAuthorityOnPairSource();
  const requestId = String(prepRequestId || '').trim().slice(0,120);

  // RC1.4.536: 通常の同期QRは短いv6形式にしてQR密度を下げる。
  // 既定GASは1文字「d」、時刻は秒単位base36、不要なPC名・長いJSON/base64を入れない。
  const endpointToken = devicePairCompactEndpointToken(relayEndpoint);
  if(MITEKORE_PAIR_PROTOCOL_VERSION >= 6 && endpointToken && requestId){
    const parts = [
      key,
      Math.floor(startedAt / 1000).toString(36),
      endpointToken,
      ownerUserId,
      requestId
    ].map(value => encodeURIComponent(String(value || '')));
    return {
      url:`${MITEKORE_PUBLIC_APP_URL}#p6=${parts.join('~')}`,
      expiresAt,
      startedAt,
      minRevision:0,
      endpoint:relayEndpoint,
      prepRequestId:requestId
    };
  }

  // ローカル検証等でGAS URLを短縮できない場合だけ従来形式へフォールバック。
  const payload = {
    v:MITEKORE_PAIR_PROTOCOL_VERSION,
    k:key,
    e:expiresAt,
    s:startedAt,
    r:Math.max(0,Math.floor(Number(minRevision || 0))),
    u:relayEndpoint,
    n:String($('deviceSyncDeviceNameInput')?.value || deviceSyncDefaultName()).slice(0,30),
    o:ownerUserId,
    q:requestId
  };
  return {
    url:`${MITEKORE_PUBLIC_APP_URL}?v=${encodeURIComponent(APP_VERSION)}#pair=${devicePairBase64UrlEncode(JSON.stringify(payload))}`,
    expiresAt,
    startedAt,
    minRevision:payload.r,
    endpoint:relayEndpoint,
    prepRequestId:payload.q
  };
}

function devicePairClose(){
  const modal = $('devicePairModal');
  if(modal){modal.classList.remove('show');modal.setAttribute('aria-hidden','true');}
  const qr = $('devicePairQr');
  if(qr) qr.innerHTML = '';
}

function devicePairSetReadyState(message,type='waiting'){
  const box = $('devicePairReadyState');
  if(!box) return;
  box.textContent = String(message || '');
  box.className = `device-pair-ready ${type || 'waiting'}`;
}

function devicePairRenderQr(url,expiresAt){
  const qr = $('devicePairQr');
  if(!qr) throw new Error('QR表示欄が見つかりません');
  qr.innerHTML = '';
  let rendered = false;
  try{
    // RC1.4.536: 内蔵QRエンジンのSVGを直接生成する。通信・外部ライブラリ読込に依存しない。
    if(window.FujiyaQr && typeof window.FujiyaQr.toSvg === 'function'){
      qr.innerHTML = window.FujiyaQr.toSvg(url,318);
      rendered = !!qr.querySelector('svg');
    }
    if(!rendered && window.FujiyaQr && typeof window.FujiyaQr.render === 'function'){
      rendered = window.FujiyaQr.render(qr,url,318) === true && !!qr.querySelector('svg,canvas,img');
    }
    if(!rendered && typeof QRCode === 'function'){
      qr.innerHTML = '';
      new QRCode(qr,{text:url,width:318,height:318,correctLevel:QRCode.CorrectLevel.L});
      rendered = !!qr.querySelector('svg,canvas,img');
    }
  }catch(error){
    console.error('QR render failed',error);
  }
  if(!rendered){
    qr.innerHTML = '<div style="font-size:inherit;font-weight:900;line-height:1.6">QRの描画に失敗しました。<br>下の「接続URLをコピー」を使用してください。</div>';
  }else{
    qr.dataset.rendered = '1';
  }
  const link = $('devicePairUrl');
  if(link){link.href=url;link.dataset.url=url;}
  const exp = $('devicePairExpire');
  if(exp) exp.textContent = `有効期限：${new Date(expiresAt).toLocaleTimeString('ja-JP',{hour:'2-digit',minute:'2-digit'})}まで`;
  const modal = $('devicePairModal');
  if(modal){modal.classList.add('show');modal.setAttribute('aria-hidden','false');}
  return rendered;
}

function devicePairWaitUntilIdle(timeoutMs=15000){
  const startedAt = Date.now();
  return new Promise(resolve => {
    const check = () => {
      if(!deviceSyncBusy && !deviceAutoSyncBusy){ resolve(true); return; }
      if(Date.now() - startedAt >= timeoutMs){ resolve(false); return; }
      setTimeout(check,250);
    };
    check();
  });
}

let devicePairPreparationPromise = null;
let devicePairPreparationKey = '';
let devicePairPreparationRequestId = '';
let devicePairLastPreparedRevision = 0;
let devicePairLastPreparedAt = 0;

function devicePairPrepRequestId(){
  return `p${Date.now().toString(36)}${Math.random().toString(36).slice(2,6)}`;
}

async function devicePairProbePublicInBackground(){
  let lastError = null;
  for(let attempt=0;attempt<3;attempt++){
    try{return await devicePairLoadPublicVersionScript(7000 + attempt * 3000);}
    catch(error){lastError=error; if(attempt<2) await new Promise(resolve=>setTimeout(resolve,500*(attempt+1)));}
  }
  console.warn('公開先確認は後回しにしました',lastError);
  return null;
}

async function devicePairPrepareRemote(key,endpoint,prepRequestId){
  const normalizedKey = String(key || '');
  if(devicePairPreparationPromise && devicePairPreparationKey === normalizedKey) return devicePairPreparationPromise;
  const promise = (async () => {
    // 公開先確認はQR表示を止めない。Netlify/GASの一時遅延でQR自体が出なくなるのを防ぐ。
    void devicePairProbePublicInBackground();

    if(deviceSyncBusy || deviceAutoSyncBusy){
      devicePairSetReadyState('QRは表示済みです。現在の同期処理が終わり次第、PCデータを準備します…','waiting');
      const idle = await devicePairWaitUntilIdle(180000);
      if(!idle) throw new Error('同期処理が長引いています。QRは表示済みですが、PCデータの準備を再試行してください');
    }

    deviceSyncBusy = true;
    try{
      // RC1.4.537: QRは即表示のまま、クラウドへ送る直前にはIndexedDB画像まで準備完了を待つ。
      if(typeof window.deviceSyncPrepareAllUserData === 'function'){
        devicePairSetReadyState('QRは読み取りできます。ショーケース画像など全データを準備中…','waiting');
        await window.deviceSyncPrepareAllUserData();
      }
      const sourceRecords = deviceSyncCaptureLocalRecords();
      let lastError = null;
      for(let attempt=0;attempt<3;attempt++){
        try{
          devicePairSetReadyState(attempt ? `接続データを再準備中… ${attempt+1}/3` : 'QRは読み取りできます。同じアカウントの最新状態を準備中…','waiting');
          deviceSyncRenderStatus('端末追加用の同期状態を準備中…','warn');
          let remote = await deviceSyncPull(normalizedKey);
          // RC1.4.538: QRを出した端末の内容だけでクラウドを上書きしない。
          // 既に同じ同期キーに別端末の変更があれば、ここでも双方向に統合してからQR接続へ渡す。
          const plan=deviceSyncBuildPlan(sourceRecords,remote.records,remote.revision);
          const preparedRecords=plan.rows.length?deviceSyncMergedRecords(plan):remote.records;
          let result={revision:Number(remote.revision||0)};
          try{
            if(deviceAutoSyncRecordSetSignature(preparedRecords)!==deviceAutoSyncRecordSetSignature(remote.records)){
              result = await deviceSyncPush(normalizedKey,remote.revision,preparedRecords,{requestId:prepRequestId});
            }
          }catch(error){
            if(!String(error?.message || error).includes('REVISION_CONFLICT')) throw error;
            remote = await deviceSyncPull(normalizedKey);
            const retryPlan=deviceSyncBuildPlan(sourceRecords,remote.records,remote.revision);
            const retryRecords=retryPlan.rows.length?deviceSyncMergedRecords(retryPlan):remote.records;
            result = deviceAutoSyncRecordSetSignature(retryRecords)===deviceAutoSyncRecordSetSignature(remote.records)
              ? {revision:Number(remote.revision||0)}
              : await deviceSyncPush(normalizedKey,remote.revision,retryRecords,{requestId:prepRequestId});
            preparedRecords.splice(0,preparedRecords.length,...retryRecords);
          }
          const revision = Number(result?.revision ?? remote.revision);
          deviceSyncSaveBaseline(revision,preparedRecords);
          localStorage.setItem(DEVICE_SYNC_LAST_STORAGE,nowIso());
          localStorage.removeItem(DEVICE_AUTO_SYNC_ENABLED_STORAGE);
          localStorage.removeItem(DEVICE_AUTO_SYNC_PENDING_STORAGE);
          deviceAutoSyncRememberFingerprint();
          deviceAutoSyncRenderStatus('この端末の自動同期を有効にしました。','ready');
          devicePairLastPreparedRevision = revision;
          devicePairLastPreparedAt = Date.now();
          devicePairSetReadyState('準備完了　表示中のQRをスマホで読み取ってください','ready');
          deviceSyncRenderStatus(
            `接続準備完了：同期データ${preparedRecords.filter(r=>!r.deletedAt).length}件 / クラウド版数${revision}\n同期サーバー：${devicePairEndpointFingerprint(endpoint)}`,
            'ready'
          );
          // スマホ側が統合結果を書き戻したら、QRを出した側も早めに同じ状態へ追従する。
          setTimeout(()=>{try{deviceAutoSyncSchedule('新しい端末の接続確認',0,false);}catch(error){}},12000);
          setTimeout(()=>{try{deviceAutoSyncSchedule('新しい端末の接続再確認',0,false);}catch(error){}},45000);
          return {revision,localRecords:preparedRecords};
        }catch(error){
          lastError = error;
          const message = String(error?.message || error);
          const retryable = deviceSyncTemporaryError(error) || /保留|時間|混み合|DEVICE_SYNC_BUSY|REVISION_CONFLICT/i.test(message);
          if(!retryable || attempt>=2) throw error;
          await new Promise(resolve=>setTimeout(resolve,900*(attempt+1)));
        }
      }
      throw lastError || new Error('PCデータの準備に失敗しました');
    }finally{
      deviceSyncBusy = false;
    }
  })().catch(error => {
    console.error('device pair prepare failed',error);
    const message = String(error?.message || error);
    devicePairSetReadyState(`QRは表示済みですが、PCデータ準備に失敗しました：${message}`,'error');
    deviceSyncRenderStatus(message,'bad');
    toast('接続QRのデータ準備を再試行できます');
    throw error;
  }).finally(() => {
    if(devicePairPreparationPromise === promise){
      devicePairPreparationPromise = null;
      devicePairPreparationKey = '';
      devicePairPreparationRequestId = '';
    }
  });
  devicePairPreparationKey = normalizedKey;
  devicePairPreparationRequestId = String(prepRequestId || '');
  devicePairPreparationPromise = promise;
  return promise;
}

let devicePairButtonLaunching = false;
function devicePairShowQrFromButton(event){
  try{ event?.preventDefault?.(); event?.stopPropagation?.(); }catch(error){}
  if(devicePairButtonLaunching) return false;
  devicePairButtonLaunching = true;
  Promise.resolve(devicePairShowQr()).finally(() => { devicePairButtonLaunching = false; });
  return false;
}

async function devicePairShowQr(){
  const button = $('devicePairShowQrBtn');
  try{
    if(button) button.disabled = true;
    // RC1.4.536: QR表示をネットワーク処理から分離。押した時点でまずQRを描く。
    devicePairShowPreparing('同期QRを作成しています…');

    const endpoint = devicePairNormalizeEndpoint(getGasEndpoint());
    let key = deviceSyncGetKey();
    if(!key){
      key = deviceSyncGenerateKey();
      if($('deviceSyncKeyInput')) $('deviceSyncKeyInput').value = key;
      deviceSyncSaveConfig();
      localStorage.removeItem(DEVICE_SYNC_BASELINE_STORAGE);
      localStorage.removeItem(DEVICE_SYNC_TOMBSTONES_STORAGE);
      localStorage.removeItem(DEVICE_SYNC_LAST_STORAGE);
    }
    key = deviceSyncNormalizeKey(key);

    // 共有所持率などの本人IDだけは2台で共通化する。データ内容の優先権には使わない。
    deviceIdentityPrepareAuthorityOnPairSource();

    const prepRequestId = (devicePairPreparationPromise && devicePairPreparationKey === key && devicePairPreparationRequestId)
      ? devicePairPreparationRequestId
      : devicePairPrepRequestId();
    const pair = devicePairBuildUrl(key,0,endpoint,prepRequestId);
    const rendered = devicePairRenderQr(pair.url,pair.expiresAt);
    if(!rendered) throw new Error('同期QRを描画できませんでした');

    devicePairSetReadyState('QRを表示しました。今すぐ読み取れます。PCデータは裏で準備しています…','waiting');
    deviceSyncRenderStatus(`同期QR表示済み / PCデータ準備中… ${devicePairEndpointFingerprint(endpoint)}`,'warn');
    toast('スマホ接続QRを表示しました');

    // 表示後に通信を行う。スマホ側はprepRequestIdの完了を待つため、先に読んでも古いデータを受け取らない。
    void devicePairPrepareRemote(key,endpoint,prepRequestId).catch(()=>{});
  }catch(error){
    console.error(error);
    const message = String(error?.message || error);
    const qr = $('devicePairQr');
    if(qr && !qr.dataset.rendered) qr.innerHTML = '<div class="device-pair-error-icon">!</div>';
    devicePairSetReadyState(message,'error');
    deviceSyncRenderStatus(message,'bad');
    toast('接続QRの表示に失敗しました');
  }finally{
    if(button) button.disabled = false;
  }
}

async function devicePairCopyUrl(){
  const url = String($('devicePairUrl')?.dataset?.url || '');
  if(!url) return;
  try{await navigator.clipboard.writeText(url);toast('接続URLをコピーしました');}
  catch(error){window.prompt('このURLをスマホで開いてください',url);}
}

function devicePairTokenFromUrl(){
  const hash = String(location.hash || '');
  // RC1.4.543: v6の短縮QR(#p6=...)も接続URLとして認識する。
  // 542ではQR生成側が#p6を使う一方、受信開始判定が#pairしか見ておらず、
  // 読み取り後にacceptDevicePairFromUrl()へ到達しない不整合があった。
  const compactMatch = hash.match(/^#p6=(.+)$/);
  if(compactMatch) return `p6:${compactMatch[1]}`;
  const hashMatch = hash.match(/^#pair=([A-Za-z0-9_-]+)$/);
  if(hashMatch) return hashMatch[1];
  try{
    const queryToken = new URLSearchParams(location.search || '').get('pair');
    return /^[A-Za-z0-9_-]+$/.test(String(queryToken || '')) ? String(queryToken) : '';
  }catch(error){
    return '';
  }
}

function decodeDevicePairPayloadFromUrl(){
  const hash = String(location.hash || '');
  const compact = hash.match(/^#p6=(.+)$/);
  if(compact){
    const fields = String(compact[1] || '').split('~').map(value => decodeURIComponent(value));
    if(fields.length !== 5) throw new Error('接続QRの形式が正しくありません');
    const [rawKey,startedText,endpointToken,ownerUserIdRaw,prepRequestIdRaw] = fields;
    const key = deviceSyncNormalizeKey(rawKey);
    const startedSeconds = parseInt(String(startedText || ''),36);
    if(!Number.isFinite(startedSeconds) || startedSeconds <= 0) throw new Error('接続QRの時刻情報が正しくありません');
    const startedAt = startedSeconds * 1000;
    const expiresAt = startedAt + DEVICE_PAIR_TTL_MS;
    if(Date.now() > expiresAt + DEVICE_PAIR_TTL_GRACE_MS) throw new Error('この接続QRは期限切れです。PCで新しいQRを表示してください');
    const endpoint = devicePairEndpointFromCompactToken(endpointToken);
    const ownerUserId = String(ownerUserIdRaw || '').trim();
    if(!deviceIdentityValidUserId(ownerUserId)) throw new Error('接続QRの本人IDが正しくありません');
    const prepRequestId = String(prepRequestIdRaw || '').trim().replace(/[^A-Za-z0-9_-]/g,'').slice(0,120);
    if(!prepRequestId) throw new Error('接続QRの準備IDが正しくありません');
    return {version:6,key,expiresAt,startedAt,minRevision:0,endpoint,pcName:'PC',ownerUserId,prepRequestId};
  }

  const token = devicePairTokenFromUrl();
  if(!token) return null;
  const raw = token.replace(/-/g,'+').replace(/_/g,'/');
  const padded = raw + '='.repeat((4 - raw.length % 4) % 4);
  const binary = atob(padded);
  const bytes = Uint8Array.from(binary,char => char.charCodeAt(0));
  const payload = JSON.parse(new TextDecoder().decode(bytes));
  const version = Number(payload?.v || 0);
  if(![1,2,3,4,5,6].includes(version)) throw new Error('接続QRの形式が正しくありません');
  const key = deviceSyncNormalizeKey(String(payload?.k || ''));
  const expiresAt = Number(payload?.e || 0);
  const startedAt = Number(payload?.s || 0);
  const minRevision = Math.max(0,Math.floor(Number(payload?.r || 0)));
  const endpoint = version >= 4
    ? devicePairNormalizeEndpoint(String(payload?.u || ''))
    : devicePairNormalizeEndpoint(getGasEndpoint());
  if(!expiresAt || Date.now() > expiresAt + DEVICE_PAIR_TTL_GRACE_MS) throw new Error('この接続QRは期限切れです。PCで新しいQRを表示してください');
  const ownerUserId = version >= 5 ? String(payload?.o || '').trim() : '';
  if(version >= 5 && !deviceIdentityValidUserId(ownerUserId)) throw new Error('接続QRの本人IDが正しくありません');
  const prepRequestId = version >= 6 ? String(payload?.q || '').trim().replace(/[^A-Za-z0-9_-]/g,'').slice(0,120) : '';
  if(version >= 6 && !prepRequestId) throw new Error('接続QRの準備IDが正しくありません');
  return {version,key,expiresAt,startedAt,minRevision,endpoint,pcName:String(payload?.n || 'PC').slice(0,30),ownerUserId,prepRequestId};
}

async function devicePairWaitForPreparation(requestId,timeoutMs=300000){
  const id = String(requestId || '').trim();
  if(!id) return null;
  const deadline = Date.now() + timeoutMs;
  let lastMessage = '';
  while(Date.now() < deadline){
    try{
      const data = await deviceSyncJsonp('device_sync_status',{requestId:id},8000);
      const status = String(data?.status || '');
      if(status === 'completed' && data?.ok === true){
        return {revision:Number(data.revision || 0),recordCount:Number(data.record_count || 0)};
      }
      // PC側は同じrequestIdで最大3回再試行する。途中のerrorは即失敗にせず待つ。
      if(data?.message) lastMessage = String(data.message);
      deviceSyncRenderStatus(status === 'processing' ? 'PCの最新データを保存中…' : 'PCの接続準備を待っています…','warn');
    }catch(error){
      lastMessage = String(error?.message || error);
      deviceSyncRenderStatus('PCの接続準備を確認中…','warn');
    }
    await new Promise(resolve=>setTimeout(resolve,650));
  }
  throw new Error(lastMessage || 'PC側の接続準備を確認できませんでした。PCのQR画面を確認してください');
}

async function devicePairWaitForRemote(key,startedAt,minRevision=0,timeoutMs=120000){
  const deadline = Date.now() + timeoutMs;
  let lastError = '';
  const requiredRevision = Math.max(0,Math.floor(Number(minRevision || 0)));

  while(Date.now() < deadline){
    try{
      const remote = await deviceSyncPull(key);
      const revision = Math.max(0,Math.floor(Number(remote.revision || 0)));

      if(requiredRevision > 0){
        if(revision >= requiredRevision) return remote;
        deviceSyncRenderStatus(`PCデータを準備中… クラウド版数 ${revision}/${requiredRevision}`,'warn');
      }else{
        // V15以前のQRだけ、更新時刻を後方互換の判定に使う。
        const remoteTime = Date.parse(String(remote.updatedAt || ''));
        const freshEnough = !startedAt || (Number.isFinite(remoteTime) && remoteTime >= startedAt - 5000);
        if((revision > 0 || remote.records.length > 0) && freshEnough) return remote;
        deviceSyncRenderStatus('PCデータの準備完了を待っています…','warn');
      }
    }catch(error){
      lastError = String(error?.message || error);
      deviceSyncRenderStatus('同期サーバーへ接続中…','warn');
    }
    await new Promise(resolve => setTimeout(resolve,500));
  }

  throw new Error(
    lastError ||
    (requiredRevision > 0
      ? `クラウド版数${requiredRevision}のデータを確認できませんでした。PCでQRを作り直してください`
      : 'PCデータの準備を確認できませんでした。PC画面を確認してください')
  );
}


function showDevicePairIncomingProgress(pcName='PC'){
  try{
    if(typeof closeFirstRunModal === 'function') closeFirstRunModal();
  }catch(error){}
  const modal = $('directQrArrival');
  if(!modal){
    deviceSyncRenderStatus(`${pcName}と接続しています…`,'warn');
    return;
  }
  $('directQrArrivalTitle').textContent = `${pcName}と接続しています`;
  $('directQrArrivalMessage').textContent = 'PCのデータを受信しています。\nこの画面を閉じずに、そのままお待ちください。';
  const button = $('directQrArrivalCloseBtn');
  if(button){
    button.disabled = true;
    button.textContent = '接続中…';
    button.onclick = null;
  }
  modal.classList.add('show');
  modal.setAttribute('aria-hidden','false');
}

function finishDevicePairIncomingMessage(title,message,onClose=null){
  const button = $('directQrArrivalCloseBtn');
  if(button){
    button.disabled = false;
    button.textContent = '確認';
  }
  showDirectQrArrival(title,message,onClose);
}

function devicePairScheduleSharedIdentityFinalize(){
  const run = () => {
    Promise.resolve(
      deviceSharedIdentityMigrate('QR接続後の共有ID統合')
    ).catch(error => console.warn('QR接続後の共有ID整理を後回しにしました',error));
  };
  const start = () => {
    if(typeof window.requestIdleCallback === 'function'){
      window.requestIdleCallback(run,{timeout:30000});
    }else{
      window.setTimeout(run,0);
    }
  };
  // 接続完了直後のrenderや画面操作と競合させない。
  window.setTimeout(start,12000);
}

async function acceptDevicePairFromUrl(pair){
  showDevicePairIncomingProgress(pair.pcName || 'PC');
  try{
    if(typeof closeFirstRunModal === 'function') closeFirstRunModal();
    // QRは「PCからスマホへコピー」ではなく、この端末を同じ同期アカウントへ追加する入口。
    const pairEndpoint = devicePairNormalizeEndpoint(pair.endpoint || getGasEndpoint());
    localStorage.setItem(GAS_ENDPOINT_KEY,pairEndpoint);
    localStorage.setItem(GAS_ENDPOINT_MIGRATION_KEY,'1');
    localStorage.setItem(DEVICE_SYNC_KEY_STORAGE,pair.key);

    // 共有所持率などで使う本人IDは1つに統一するが、データ内容の優先権には使わない。
    // 旧スマホIDはaliasとして残し、あとで共有DB側を統合する。
    const ownerMigration = pair.ownerUserId
      ? deviceSharedSetCanonicalUserId(pair.ownerUserId)
      : {previous:getUserId(),canonical:getUserId(),changed:false};
    if(ownerMigration.changed){
      deviceAutoSyncSuppressSave += 1;
      try{ saveCoreDataOnly(); }
      finally{ deviceAutoSyncSuppressSave = Math.max(0,deviceAutoSyncSuppressSave - 1); }
    }
    await deviceSharedIdentityMigrate('QR接続時の共有ID統合',{localOnly:true});
    if(!localStorage.getItem(DEVICE_SYNC_DEVICE_NAME_STORAGE)) localStorage.setItem(DEVICE_SYNC_DEVICE_NAME_STORAGE,'スマホ');
    if($('deviceSyncKeyInput')) $('deviceSyncKeyInput').value = pair.key;
    if($('deviceSyncDeviceNameInput')) $('deviceSyncDeviceNameInput').value = localStorage.getItem(DEVICE_SYNC_DEVICE_NAME_STORAGE) || 'スマホ';

    setUiTab('sync',{targetId:'deviceSyncPanel'});
    deviceSyncRenderStatus('同じアカウントへ接続しています…','warn');

    const prepared = pair.prepRequestId
      ? await devicePairWaitForPreparation(pair.prepRequestId,300000)
      : null;
    const requiredRevision = Math.max(Number(pair.minRevision || 0),Number(prepared?.revision || 0));
    let remote = await devicePairWaitForRemote(pair.key,pair.startedAt,requiredRevision,pair.prepRequestId ? 120000 : 300000);

    // スマホから使い始めた場合も、端末内画像を含めて先に読み出してから統合する。
    if(typeof window.deviceSyncPrepareAllUserData === 'function'){
      deviceSyncRenderStatus('この端末のデータも確認しています…','warn');
      await window.deviceSyncPrepareAllUserData();
    }

    let merged=[];
    let revision=Number(remote.revision||0);
    for(let attempt=0;attempt<2;attempt++){
      const localRecords=deviceSyncCaptureLocalRecords();
      merged=typeof window.deviceSyncMergeInitialPairRecords==='function'
        ? window.deviceSyncMergeInitialPairRecords(localRecords,remote.records)
        : deviceSyncMergedRecords(deviceSyncBuildPlan(localRecords,remote.records,remote.revision));

      const remoteSig=deviceAutoSyncRecordSetSignature(remote.records);
      const mergedSig=deviceAutoSyncRecordSetSignature(merged);
      if(mergedSig===remoteSig){revision=Number(remote.revision||0);break;}
      try{
        deviceSyncRenderStatus('2台のデータを統合して保存しています…','warn');
        const result=await deviceSyncPush(pair.key,remote.revision,merged);
        revision=Number(result?.revision||remote.revision+1);
        break;
      }catch(error){
        if(attempt===0&&String(error?.message||error).includes('REVISION_CONFLICT')){
          remote=await deviceSyncPull(pair.key);
          revision=Number(remote.revision||0);
          continue;
        }
        throw error;
      }
    }

    deviceAutoSyncSuppressSave += 1;
    try{
      createUndoSnapshot('同じアカウントへの端末追加前');
      await deviceSyncApplyRecordsLocally(merged);
      if(!save()) throw new Error('統合したデータをこの端末へ保存できませんでした');
    }finally{
      deviceAutoSyncSuppressSave = Math.max(0,deviceAutoSyncSuppressSave - 1);
    }

    deviceSyncSaveBaseline(revision,merged);
    localStorage.setItem(DEVICE_SYNC_LAST_STORAGE,nowIso());
    localStorage.removeItem(DEVICE_AUTO_SYNC_ENABLED_STORAGE);
    localStorage.removeItem(DEVICE_AUTO_SYNC_PENDING_STORAGE);
    localStorage.removeItem(DEVICE_AUTO_SYNC_LAST_ERROR_STORAGE);
    deviceAutoSyncRememberFingerprint();
    deviceAutoSyncRenderStatus('同じアカウントとして接続しました。以後は自動同期します。','ready');
    try{
      if(typeof setSetupDone === 'function') setSetupDone();
      if(typeof markTutorialSeen === 'function') markTutorialSeen();
    }catch(error){}
    clearDirectQrFromAddress();
    render();
    deviceSyncRenderStatus(`接続完了：登録${state.entries.length}件 / PC・スマホ同一状態`,'ready');
    finishDevicePairIncomingMessage(
      '端末の接続が完了しました',
      `この端末を同じアカウントに追加しました。\n登録${state.entries.length}件を含むデータを統合済みです。\nこれからはPC・スマホのどちらで追加・編集・削除しても自動で反映します。`
    );
    devicePairScheduleSharedIdentityFinalize();
    // QRを表示したPC側にも、統合後のクラウド状態を早めに取り込ませる。
    setTimeout(()=>{try{deviceAutoSyncSchedule('端末追加後の同一状態確認',1200,false);}catch(error){}},800);
  }catch(error){
    console.error(error);
    deviceSyncRenderStatus(String(error?.message || error),'bad');
    finishDevicePairIncomingMessage(
      '端末を接続できませんでした',
      `${String(error?.message || error)}\n\n同期サーバー：${devicePairEndpointFingerprint(pair?.endpoint || getGasEndpoint())}\nQRの有効期限内なら、この画面を再読み込みするともう一度接続します。`
    );
  }finally{
    devicePairIncomingBusy = false;
  }
}

function handleDevicePairFromUrl(){
  const token = devicePairTokenFromUrl();
  if(!token) return false;
  if(devicePairIncomingBusy && devicePairIncomingToken === token) return true;

  let pair;
  try{
    pair = decodeDevicePairPayloadFromUrl();
  }catch(error){
    clearDirectQrFromAddress();
    finishDevicePairIncomingMessage('接続QRを読み込めませんでした',String(error?.message || error));
    return true;
  }
  if(!pair) return false;

  devicePairIncomingBusy = true;
  devicePairIncomingToken = token;
  showDevicePairIncomingProgress(pair.pcName || 'PC');
  Promise.resolve().then(() => acceptDevicePairFromUrl(pair));
  return true;
}

function bindDevicePairUrlListeners(){
  if(devicePairUrlListenersBound) return;
  devicePairUrlListenersBound = true;

  const check = () => {
    if(devicePairTokenFromUrl()) handleDevicePairFromUrl();
  };

  window.addEventListener('hashchange',check);
  window.addEventListener('pageshow',() => setTimeout(check,0));
  window.addEventListener('popstate',() => setTimeout(check,0));
  document.addEventListener('visibilitychange',() => {
    if(!document.hidden) setTimeout(check,0);
  });
}

function decodeDirectQrBase64Url(value){
  const raw = String(value || '').trim().replace(/-/g,'+').replace(/_/g,'/');
  if(!raw) throw new Error('QR登録データがありません');
  const padded = raw + '='.repeat((4 - raw.length % 4) % 4);
  const binary = atob(padded);
  const bytes = Uint8Array.from(binary, char => char.charCodeAt(0));
  return new TextDecoder().decode(bytes);
}

function readDirectQrPayloadFromUrl(){
  const hash = String(location.hash || '');
  const match = hash.match(/^#mk=([A-Za-z0-9_-]+)$/);
  if(!match) return null;

  const jsonText = decodeDirectQrBase64Url(match[1]);
  const source = JSON.parse(jsonText);
  const payload = parseMitekoreCompactV4(source);
  if(!payload){
    throw new Error('藤や玩具店の登録QR形式ではありません');
  }
  return payload;
}

function clearDirectQrFromAddress(){
  try{
    history.replaceState(
      null,
      document.title,
      `${location.pathname}${location.search}`
    );
  }catch(error){
    location.hash = '';
  }
}

function showDirectQrArrival(title,message,onClose=null){
  const modal = $('directQrArrival');
  if(!modal){
    window.alert(`${title}\n\n${message}`);
    onClose?.();
    return;
  }

  $('directQrArrivalTitle').textContent = title;
  $('directQrArrivalMessage').textContent = message;
  modal.classList.add('show');
  modal.setAttribute('aria-hidden','false');

  const button = $('directQrArrivalCloseBtn');
  button.disabled = false;
  button.textContent = '確認';
  button.onclick = () => {
    modal.classList.remove('show');
    modal.setAttribute('aria-hidden','true');
    button.onclick = null;
    onClose?.();
  };
}

function handleDirectPurchaseQrFromUrl(){
  let payload;
  try{
    payload = readDirectQrPayloadFromUrl();
  }catch(error){
    clearDirectQrFromAddress();
    showDirectQrArrival(
      'QRを読み込めませんでした',
      String(error?.message || error)
    );
    return;
  }

  if(!payload) return;
  clearDirectQrFromAddress();

  try{
    if(typeof closeFirstRunModal === 'function') closeFirstRunModal();

    const result = receiveCompactQrPart(payload);
    if(!result.complete){
      const already = result.alreadyRead ? 'このQRはすでに読み取り済みです。' : '';
      showDirectQrArrival(
        `購入QR ${result.received}/${result.total}枚`,
        `${already}残り${result.total - result.received}枚です。標準カメラへ戻って次のQRを読み取ってください。`
      );
      return;
    }

    showDirectQrArrival(
      '購入QRを読み取りました',
      `${result.payload.items.length}タイトルの登録内容を確認します。`,
      () => openQrBatchReview(result.payload)
    );
  }catch(error){
    showDirectQrArrival(
      'QR登録の準備に失敗しました',
      String(error?.message || error)
    );
  }
}

