function fetchUserAliasStatusJsonpRequest(endpoint,requestId,timeoutMs=12000){
  return new Promise((resolve,reject) => {
    const cleanEndpoint = String(endpoint || '').trim();
    if(!cleanEndpoint){
      reject(new Error('共有同期URLが未設定です'));
      return;
    }

    const callback = `fujiyaUserAliasStatus_${Date.now()}_${Math.random().toString(36).slice(2)}`;
    let settled = false;
    const timer = setTimeout(() => {
      cleanup();
      reject(new Error('共有利用者IDの統合確認がタイムアウトしました'));
    },timeoutMs);

    function cleanup(){
      if(settled) return;
      settled = true;
      clearTimeout(timer);
      window.fujiyaKeepLateJsonpCallback_(callback);
      document.getElementById(callback)?.remove();
    }

    window[callback] = data => {
      cleanup();
      if(data && data.action === 'user_alias_status') resolve(data);
      else reject(new Error(data?.message || '共有利用者IDの統合応答が正しくありません'));
    };

    const script = document.createElement('script');
    script.id = callback;
    script.onerror = () => {
      cleanup();
      reject(new Error('共有利用者IDの統合状況へ接続できませんでした'));
    };

    const separator = cleanEndpoint.includes('?') ? '&' : '?';
    const params = new URLSearchParams({
      action:'user_alias_status',
      requestId,
      callback,
      _:String(Date.now())
    });
    script.src = `${cleanEndpoint}${separator}${params.toString()}`;
    document.body.appendChild(script);
  });
}

async function waitForUserAliasStatus(requestId,timeoutMs=130000,endpointOverride=''){
  const endpoint = String(
    endpointOverride || getGasEndpoint() || DEFAULT_GAS_ENDPOINT || ''
  ).trim();
  if(!endpoint) throw new Error('共有同期URLが未設定です');

  const deadline = Date.now() + timeoutMs;
  let lastError = '';

  while(Date.now() < deadline){
    try{
      const data = await fetchUserAliasStatusJsonpRequest(
        endpoint,
        requestId,
        10000
      );
      const status = String(data?.status || '').toLowerCase();

      if(status === 'completed' && data?.ok === true) return data;
      if(status === 'error' || (data?.ok === false && data?.pending === false)){
        throw new Error(data?.message || '共有利用者IDの統合に失敗しました');
      }
    }catch(error){
      lastError = String(error?.message || error);
      if(/形式|権限|スプレッドシート|統合に失敗/.test(lastError)) throw error;
    }
    await new Promise(resolve => setTimeout(resolve,1200));
  }

  throw new Error(lastError || '共有利用者IDの統合結果を確認できませんでした');
}

async function deviceSharedRegisterAliases(canonicalId,aliases,endpoint){
  const canonical = String(canonicalId || '').trim();
  const cleanAliases = Array.from(new Set(
    (aliases || [])
      .map(value => String(value || '').trim())
      .filter(value => value && value !== canonical)
  )).slice(0,50);

  if(!cleanAliases.length){
    return {
      ok:true,
      aliases_registered:0,
      canonical_user_id:canonical
    };
  }

  const requestId = `fujiya_user_alias_${Date.now()}_${Math.random().toString(36).slice(2,9)}`;
  submitGasPostFormNoWait('user_alias_register_frame',{
    canonicalUserId:canonical,
    aliases:JSON.stringify(cleanAliases),
    source:'mitekore_v19_device_identity'
  },requestId,endpoint);

  return await waitForUserAliasStatus(requestId,120000,endpoint);
}


/* RC1.4.535: 端末同期キーと本人IDを分離する。 */
function deviceIdentityValidUserId(value){
  const id=String(value||'').trim();
  return /^fujiya_[A-Za-z0-9._:-]{6,190}$/.test(id);
}
function deviceIdentityIsGeneratedSyncId(value){
  return /^fujiya_sync_[a-f0-9]{32}$/.test(String(value||'').trim());
}
function deviceIdentityStoredOwnerUserId(){
  const id=String(localStorage.getItem(DEVICE_IDENTITY_OWNER_USER_STORAGE)||'').trim();
  return deviceIdentityValidUserId(id)?id:'';
}
function deviceIdentityRecoverableSourceOwnerUserId(){
  const stored=deviceIdentityStoredOwnerUserId();
  if(stored && !deviceIdentityIsGeneratedSyncId(stored)) return stored;
  const current=String(getUserId()||'').trim();
  if(deviceIdentityValidUserId(current) && !deviceIdentityIsGeneratedSyncId(current)) return current;
  // 旧版で本人IDをfujiya_sync_*へ置換していた場合、QRを作るPCに残る旧IDを復元候補にする。
  const oldIds=deviceSharedReadOldUserIds().filter(id=>deviceIdentityValidUserId(id)&&!deviceIdentityIsGeneratedSyncId(id));
  if(oldIds.length) return oldIds[oldIds.length-1];
  return deviceIdentityValidUserId(current)?current:'';
}
function deviceIdentitySetOwnerUserId(ownerId,{rememberPrevious=true}={}){
  const owner=String(ownerId||'').trim();
  if(!deviceIdentityValidUserId(owner)) throw new Error('本人IDの形式が正しくありません');
  const previous=String(getUserId()||'').trim();
  if(previous!==owner){
    if(rememberPrevious) deviceSharedRememberOldUserId(previous,owner);
    localStorage.setItem(USER_ID_KEY,owner);
  }
  // みてレコも同じ本人IDへ統一する。トークンは端末固有のまま維持する。
  try{localStorage.setItem('fujiya_mitereco_identity_user_v2',owner);}catch(error){}
  localStorage.setItem(DEVICE_IDENTITY_OWNER_USER_STORAGE,owner);
  localStorage.setItem(DEVICE_SHARED_CANONICAL_USER_STORAGE,owner);
  return {previous,canonical:owner,changed:previous!==owner};
}
function deviceIdentityPrepareAuthorityOnPairSource(){
  const owner=deviceIdentityRecoverableSourceOwnerUserId();
  if(!owner) throw new Error('PCの本人IDを確認できません');
  const migration=deviceIdentitySetOwnerUserId(owner,{rememberPrevious:true});
  if(migration.changed){
    deviceAutoSyncSuppressSave += 1;
    try{saveCoreDataOnly();}
    finally{deviceAutoSyncSuppressSave=Math.max(0,deviceAutoSyncSuppressSave-1);}
    try{renderDistributionStatus();}catch(error){}
  }
  return owner;
}

