let profileV201LegacyPreservedCache=null;
function profileV201LegacyPreservedIds(){
  if(profileV201LegacyPreservedCache)return profileV201LegacyPreservedCache;
  const kept=new Set();
  try{
    const stored=JSON.parse(localStorage.getItem(PROFILE_V201_LEGACY_PRESERVED_KEY)||'[]');
    if(Array.isArray(stored))stored.map(String).forEach(id=>{if(PROFILE_V201_LEGACY_PART_IDS.has(id))kept.add(id);});
  }catch(error){}
  try{
    const raw=localStorage.getItem(PROFILE_V201_UNLOCK_SEEN_KEY);
    if(raw!==null){
      const seen=JSON.parse(raw||'[]');
      if(Array.isArray(seen))seen.map(String).forEach(id=>{if(PROFILE_V201_LEGACY_PART_IDS.has(id))kept.add(id);});
    }
  }catch(error){}
  try{
    const profile=typeof profileV201Read==='function'?profileV201Read():null;
    [profile?.upperId,profile?.lowerId].map(String).forEach(id=>{if(PROFILE_V201_LEGACY_PART_IDS.has(id))kept.add(id);});
  }catch(error){}
  try{localStorage.setItem(PROFILE_V201_LEGACY_PRESERVED_KEY,JSON.stringify(Array.from(kept)));}catch(error){}
  profileV201LegacyPreservedCache=kept;
  return kept;
}
function profileV201LegacyPartUnlocked(def){
  const id=String(def?.id||String(def?.condition||'').replace(/^legacy:/,'')).trim();
  return !!id&&profileV201LegacyPreservedIds().has(id);
}

function profileV201Unlocked(def){
  const condition=String(def?.condition||'basic');
  if(condition==='basic')return true;
  if(condition.startsWith('legacy:'))return profileV201LegacyPartUnlocked(def);
  const parts=condition.split(':');
  const kind=parts.shift()||condition;
  const raw=parts.join(':');
  const stats=profileV201ActiveStats||profileV201BuildStats();
  const n=index=>Math.max(0,Number(parts[index]||0)||0);
  if(kind==='title'){
    const needles=String(raw||'').split('|').map(profileV201Norm).filter(Boolean);
    return Array.from(stats.titleCounts.keys()).some(title=>needles.some(needle=>title.includes(needle)));
  }
  if(kind==='platform')return (stats.platformCounts.get(profileV201PlatformCode(raw))||0)>=1;
  if(kind==='platform_owned')return (stats.platformCounts.get(profileV201PlatformCode(parts[0]))||0)>=n(1);
  if(kind==='owned')return stats.owned.length>=n(0);
  if(kind==='wanted')return stats.wanted.length>=n(0);
  if(kind==='same_title_owned')return stats.maxSameTitle>=n(0);
  if(kind==='today_adds')return stats.todayAdds>=n(0);
  if(kind==='streak')return stats.activityStreak>=n(0);
  if(kind==='wanted_acquired')return stats.wantedAcquired>=n(0);
  if(kind==='wanted_cleared_all')return stats.wantedClearedAll;
  if(kind==='platform_count')return Array.from(stats.platformCounts.values()).filter(value=>value>0).length>=n(0);
  if(kind==='confirmed')return stats.confirmedCount>=n(0);
  if(kind==='platform_completion')return stats.platformCompletionValues.some(row=>row.percent>=n(0));
  if(kind==='multi_platform_completion')return stats.platformCompletionValues.filter(row=>row.percent>=n(1)).length>=n(0);
  if(kind==='all_platforms_owned'){
    const targets=['FC','FDS','SFC','N64','GC','WII','WIIU','GB','GBA','DS','3DS','VB','MARK3','SG','MD','SS','DC','PCE','PCFX','PS','PS2','PS3','PSP','3DO','NG','NCD','WS','XBOX','X360'];
    return targets.every(code=>(stats.platformCounts.get(code)||0)>0);
  }
  if(kind==='content')return (stats.content[String(parts[0]||'')]||0)>=n(1);
  if(kind==='condition'){
    const key=String(parts[0]||'');
    const value=key==='new'?stats.conditionNew:key==='good'?stats.conditionGood:key==='junk'?stats.conditionJunk:0;
    return value>=n(1);
  }
  if(kind==='cleaned')return stats.cleanedCount>=n(0);
  if(kind==='rated')return stats.ratedCount>=n(0);
  if(kind==='rated_all_owned')return stats.owned.length>=10&&stats.ratedCount===stats.owned.length;
  if(kind==='rating5')return (stats.ratingCounts.get(5)||0)>=n(0);
  if(kind==='rating1')return (stats.ratingCounts.get(1)||0)>=n(0);
  if(kind==='average_rating'){
    const minimum=Number(parts[0]||0);
    const minCount=Math.max(0,Number(String(parts[1]||'').replace(/\D/g,''))||0);
    return stats.ratedCount>=minCount&&stats.ratingSum/Math.max(1,stats.ratedCount)>=minimum;
  }
  if(kind==='all_rating_values')return [1,2,3,4,5].every(value=>(stats.ratingCounts.get(value)||0)>0);
  if(kind==='photo')return stats.photoCount>=n(0);
  if(kind==='shelf')return stats.shelfCount>=n(0);
  if(kind==='profile')return !!stats.profile[String(parts[0]||'')];
  if(kind==='purchase_price_count')return stats.purchasePriceCount>=n(0);
  if(kind==='total_spend')return stats.totalSpend>=n(0);
  if(kind==='free_acquisition')return stats.freeAcquisition>=n(0);
  if(kind==='bargain_under500')return stats.bargainUnder500>=n(0);
  if(kind==='single_purchase')return stats.maxSinglePurchase>=n(0);
  if(kind==='store_count')return stats.storeCounts.size>=n(0);
  if(kind==='same_store')return stats.maxSameStore>=n(0);
  if(kind==='release_year_span')return new Set(stats.releaseYears).size>=n(0);
  if(kind==='release_year_gap')return stats.releaseYears.length>1&&(Math.max(...stats.releaseYears)-Math.min(...stats.releaseYears))>=n(0);
  if(kind==='era'){
    const decade=Number(String(parts[0]||'').replace(/\D/g,''))||0;
    return (stats.eraCounts.get(decade)||0)>=n(1);
  }
  if(kind==='genre_count')return stats.genreCounts.size>=n(0);
  if(kind==='genre')return profileV201MapCount(stats.genreCounts,parts[0])>=n(1);
  if(kind==='maker_count')return stats.makerCounts.size>=n(0);
  if(kind==='maker')return profileV201MapCount(stats.makerCounts,parts[0])>=n(1);
  if(kind==='rare')return stats.rareCount>=n(0);
  if(kind==='super_rare')return stats.superRareCount>=n(0);
  if(kind==='clear_time_count')return stats.clearTimeCount>=n(0);
  if(kind==='cleared')return stats.clearedCount>=n(0);
  if(kind==='clear_over100h')return stats.clearOver100h>=n(0);
  if(kind==='clear_under1h')return stats.clearUnder1h>=n(0);
  if(kind==='total_clear_time')return stats.totalClearTime>=Math.max(0,Number(String(parts[0]||'').replace(/[^\d.]/g,''))||0);
  if(kind==='community_review')return (stats.communityReviewCount+stats.communityDescriptionCount)>=n(0);
  if(kind==='community'){
    const action=String(parts[0]||'');
    if(action==='description')return stats.communityDescriptionCount>=n(1);
    if(action==='review')return stats.communityReviewCount>=n(1);
    if(action==='featured')return stats.communityFeatured;
    return false;
  }
  if(kind==='magazine')return String(parts[0]||'')==='post'&&stats.magazinePostCount>=n(1);
  if(kind==='mitereco'){
    const action=String(parts[0]||'');
    const value=stats.mitereco[action]||0;
    return value>=(parts.length>1?n(1):1);
  }
  if(kind==='buyback'){
    const action=String(parts[0]||'');
    if(action==='large_cleanup')return stats.buyback.large_cleanup>0;
    return (stats.buyback[action]||0)>=(parts.length>1?n(1):1);
  }
  if(kind==='backup'){
    const action=String(parts[0]||'');
    return (stats.backup[action]||0)>=(parts.length>1?n(1):1);
  }
  if(kind==='sync'){
    const action=String(parts[0]||'');
    return (stats.sync[action]||0)>=(parts.length>1?n(1):1);
  }
  if(kind==='manual')return stats.manualGrants.has(raw)||stats.manualGrants.has(condition);
  if(kind==='combo'){
    const combo=String(parts[0]||'');
    if(combo==='owned100_wanted50')return stats.owned.length>=100&&stats.wanted.length>=50;
    if(combo==='owned100_ratedall')return stats.owned.length>=100&&stats.ratedCount===stats.owned.length;
    if(combo==='5platforms_each10')return Array.from(stats.platformCounts.values()).filter(value=>value>=10).length>=5;
    if(combo==='rare10_sr3')return stats.rareCount>=10&&stats.superRareCount>=3;
    if(combo==='complete50_photo50')return stats.content.complete>=50&&stats.photoCount>=50;
    if(combo==='mitereco1_magazine10')return stats.mitereco.rank1>=1&&stats.magazinePostCount>=10;
    if(combo==='owned500_backup10')return stats.owned.length>=500&&stats.backup.export>=10;
    if(combo==='allplatform_complete1'){
      const targets=['FC','FDS','SFC','N64','GC','Wii','WiiU','Switch','GB','GBC','GBA','DS','3DS','PCE','MD','SS','DC','PS','PS2','PS3','PS4','PSP','PSV','Xbox','Xbox360','GG','WS','NGP','MSX'];
      return targets.every(code=>(stats.platformCounts.get(code)||0)>0)&&stats.platformCompletionValues.some(row=>row.percent>=100);
    }
  }
  return false;
}

const PROFILE_V201_REMOTE_GRANTS_STORAGE_KEY='fujiya_collection_profile_v20_1_remote_title_grants';
const PROFILE_V201_CLAIMED_PARTS_STORAGE_KEY='fujiya_collection_profile_v20_1_claimed_title_parts_v1';
function profileV201StoredRemoteRows(){
  const rows=[];
  const addRows=value=>{
    const list=Array.isArray(value)?value:(Array.isArray(value?.grants)?value.grants:[]);
    list.forEach(raw=>{
      const id=String(raw?.partId||raw?.part_id||'').trim();
      const text=String(raw?.partText||raw?.part_text||'').trim();
      if(!id||!text)return;
      const rawKind=String(raw?.partKind||raw?.part_kind||'');
      const kind=id.startsWith('lower_')||rawKind.includes('下')?'lower':'upper';
      rows.push({
        id,
        text,
        kind,
        origin:String(raw?.reason||raw?.source||'限定特典').trim()||'限定特典'
      });
    });
  };
  try{addRows(JSON.parse(localStorage.getItem(PROFILE_V201_REMOTE_GRANTS_STORAGE_KEY)||'null'));}catch(error){}
  try{addRows(JSON.parse(localStorage.getItem(PROFILE_V201_CLAIMED_PARTS_STORAGE_KEY)||'null'));}catch(error){}
  const map=new Map();
  rows.forEach(row=>map.set(row.id,row));
  return Array.from(map.values());
}
function profileV201DefsWithRemote(defs){
  const kind=defs===PROFILE_V201_LOWER?'lower':'upper';
  const remote=profileV201StoredRemoteRows().filter(row=>row.kind===kind);
  if(!remote.length)return defs;
  const remoteIds=new Set(remote.map(row=>row.id));
  const remoteDefs=remote.map((row,index)=>({
    id:row.id,
    text:row.text,
    condition:'basic',
    origin:row.origin,
    category:'限定特典',
    no:-100000-index,
    remoteTitleGrant:true
  }));
  return [...remoteDefs,...defs.filter(def=>!remoteIds.has(String(def?.id||'')))];
}
function profileV201StoredRemoteCount(){return profileV201StoredRemoteRows().length;}
function profileV201VisibleDefs(defs){
  return profileV201DefsWithRemote(defs).filter(def=>!def?.legacyOnly||profileV201Unlocked(def));
}

function profileV201Available(defs){
  const previous=profileV201ActiveStats;
  if(!previous)profileV201ActiveStats=profileV201BuildStats();
  try{return profileV201DefsWithRemote(defs).filter(profileV201Unlocked);}
  finally{if(!previous)profileV201ActiveStats=null;}
}

const PROFILE_V201_UNLOCK_SEEN_KEY='fujiya_collection_profile_v20_1_seen_unlocks';
let profileV201UnlockNoticeOpen=false;
function profileV201UnlockedParts(){
  profileV201TrackActivityDay();
  return [
    ...profileV201Available(PROFILE_V201_UPPER).map(def=>({...def,kind:'上の句'})),
    ...profileV201Available(PROFILE_V201_LOWER).map(def=>({...def,kind:'下の句'}))
  ];
}
function profileV201ReadSeenUnlocks(){
  try{
    const value=JSON.parse(localStorage.getItem(PROFILE_V201_UNLOCK_SEEN_KEY)||'null');
    return Array.isArray(value)?value.map(String):null;
  }catch(error){return null;}
}
function profileV201WriteSeenUnlocks(ids){
  localStorage.setItem(PROFILE_V201_UNLOCK_SEEN_KEY,JSON.stringify(Array.from(new Set(ids.map(String)))));
}
function profileV201ShowUnlockNotice(parts){
  if(!Array.isArray(parts)||!parts.length||profileV201UnlockNoticeOpen) return;
  const visibleParts=parts.slice(0,12);
  const hiddenCount=Math.max(0,parts.length-visibleParts.length);
  profileV201UnlockNoticeOpen=true;
  document.getElementById('profileV201UnlockOverlay')?.remove();
  const overlay=document.createElement('div');
  overlay.id='profileV201UnlockOverlay';
  overlay.className='profile-unlock-overlay profile-unlock-nonblocking';
  overlay.innerHTML=`
    <section class="profile-unlock-dialog" role="status" aria-live="polite" aria-labelledby="profileUnlockTitle">
      <div class="profile-unlock-spark">NEW!</div>
      <h2 id="profileUnlockTitle">二つ名パーツ獲得！</h2>
      <p>新しく使える二つ名が増えました。</p>
      <div class="profile-unlock-list">${visibleParts.map(part=>`
        <div class="profile-unlock-item">
          <span>${profileV201Esc(part.kind)}</span>
          <strong>${profileV201Esc(part.text)}</strong>
          <small>${profileV201Esc(part.origin)}</small>
        </div>`).join('')}${hiddenCount?`<div class="profile-unlock-item"><span>ほか</span><strong>${hiddenCount}個の二つ名パーツ</strong><small>二つ名編集画面で確認できます</small></div>`:''}</div>
      <div class="profile-unlock-actions">
        <button type="button" data-profile-unlock-close>閉じる</button>
        <button type="button" class="primary" data-profile-unlock-open>二つ名を選ぶ</button>
      </div>
    </section>`;
  document.body.appendChild(overlay);
  requestAnimationFrame(()=>overlay.classList.add('show'));
  setTimeout(()=>{if(document.getElementById('profileV201UnlockOverlay')===overlay)profileV201CloseUnlockNotice();},12000);
  try{toast(`二つ名パーツを${parts.length}個獲得しました！`);}catch(error){}
}
function profileV201CloseUnlockNotice(){
  const overlay=document.getElementById('profileV201UnlockOverlay');
  if(!overlay){profileV201UnlockNoticeOpen=false;return;}
  overlay.classList.remove('show');
  setTimeout(()=>overlay.remove(),180);
  profileV201UnlockNoticeOpen=false;
}
function profileV201CheckNewUnlocks(){
  const current=profileV201UnlockedParts();
  const currentIds=current.map(part=>part.id);
  const seen=profileV201ReadSeenUnlocks();
  if(seen===null){
    profileV201WriteSeenUnlocks(currentIds);
    return;
  }
  const seenSet=new Set(seen);
  const newly=current.filter(part=>!seenSet.has(part.id));
  if(!newly.length) return;
  profileV201WriteSeenUnlocks([...seen,...currentIds]);
  setTimeout(()=>profileV201ShowUnlockNotice(newly),120);
}

function profileV201Resolve(defs,id,fallback){const merged=profileV201DefsWithRemote(defs);return merged.find(def=>def.id===id&&profileV201Unlocked(def))||merged.find(def=>def.id===fallback)||merged[0];}
function profileV201Nickname(profile=profileV201Read()){return `${profileV201Resolve(PROFILE_V201_UPPER,profile.upperId,'upper_retro').text}${profileV201Resolve(PROFILE_V201_LOWER,profile.lowerId,'lower_collector').text}`;}
function profileV201PlatformOptions(selected){
  const current=normalizePlatformName(selected||'');
  const values=[...PLATFORM_SUGGESTIONS];
  if(current&&current!=='PS6'&&!values.includes(current))values.push(current);
  return `<option value="">未設定</option>`+values.map(platform=>`<option value="${profileV201Esc(platform)}" ${platform===current?'selected':''}>${profileV201Esc(platform)}</option>`).join('');
}
function profileV201GameOptions(selected){
  const seen=new Set(),values=[];profileV201Entries().forEach(entry=>{const title=String(entry.canonicalTitle||entry.title||'').trim();if(title&&!seen.has(title)){seen.add(title);values.push(title);}});values.sort((a,b)=>a.localeCompare(b,'ja'));
  return `<option value="">未設定</option>`+values.map(title=>`<option value="${profileV201Esc(title)}" ${title===selected?'selected':''}>${profileV201Esc(title)}</option>`).join('');
}
function profileV201Stats(){const all=profileV201Entries(),owned=profileV201Owned();return {owned:owned.length,want:all.filter(entry=>!entry.owned).length,platforms:new Set(owned.map(entry=>normalizePlatformName(entry.platform)).filter(Boolean)).size};}
function profileV201PartButtons(defs,selected,kind){
  const previous=profileV201ActiveStats;
  if(!previous)profileV201ActiveStats=profileV201BuildStats();
  try{return profileV201VisibleDefs(defs).map(def=>{const unlocked=profileV201Unlocked(def);return `<button type="button" class="profile-v20-part ${selected===def.id?'active':''} ${unlocked?'':'locked'} ${def.remoteTitleGrant?'limited-title-core-v2035de':''}" ${unlocked?`data-profile-v201-kind="${kind}" data-profile-v201-id="${def.id}"`:'disabled'} title="${profileV201Esc(def.origin)}">${unlocked?profileV201Esc(def.text):'？？？'}</button>`;}).join('');}
  finally{if(!previous)profileV201ActiveStats=null;}
}
function profileV201UnlockCards(){return [...profileV201Available(PROFILE_V201_UPPER).map(def=>({...def,kind:'上の句'})),...profileV201Available(PROFILE_V201_LOWER).map(def=>({...def,kind:'下の句'}))].map(def=>`<div class="profile-v20-unlock"><strong>${profileV201Esc(def.kind)}：${profileV201Esc(def.text)}</strong><small>${profileV201Esc(def.origin)}</small></div>`).join('');}
function profileV201RenderPanel(){
  const root=$('profileV20Root');
  if(!root) return;
  const profile=profileV201Read();
  const upper=profileV201Resolve(PROFILE_V201_UPPER,profile.upperId,'upper_retro');
  const lower=profileV201Resolve(PROFILE_V201_LOWER,profile.lowerId,'lower_collector');
  const upperDefs=profileV201VisibleDefs(PROFILE_V201_UPPER);
  const lowerDefs=profileV201VisibleDefs(PROFILE_V201_LOWER);
  const upperUnlocked=profileV201Available(PROFILE_V201_UPPER).length;
  const lowerUnlocked=profileV201Available(PROFILE_V201_LOWER).length;
  root.innerHTML=`
    <div class="profile-v20-card profile-v20-hero nickname-v201-hero">
      <div class="profile-v20-kicker">CURRENT NICKNAME</div>
      <div class="profile-v20-nickname">${profileV201Esc(upper.text)}${profileV201Esc(lower.text)}</div>
      <div class="profile-v20-meta"><span>上の句 ${upperUnlocked}/${upperDefs.length}</span><span>下の句 ${lowerUnlocked}/${lowerDefs.length}</span>${profileV201StoredRemoteCount()?`<span>限定 ${profileV201StoredRemoteCount()}</span>`:''}</div>
    </div>
    <div class="profile-v20-card" style="margin-top:14px">
      <div class="profile-v20-section-title">二つ名を組み合わせる</div>
      <div class="profile-v20-origin">獲得済みの上の句と下の句を選ぶと、ステータスへすぐ反映されます。</div>
      <div class="profile-v20-parts nickname-v201-parts">
        <div><div class="profile-v20-section-title">上の句</div><div class="profile-v20-part-list">${profileV201PartButtons(PROFILE_V201_UPPER,upper.id,'upper')}</div></div>
        <div><div class="profile-v20-section-title">下の句</div><div class="profile-v20-part-list">${profileV201PartButtons(PROFILE_V201_LOWER,lower.id,'lower')}</div></div>
      </div>
    </div>
    <div class="profile-v20-card" style="margin-top:14px">
      <div class="profile-v20-section-title">獲得済み二つ名パーツ</div>
      <div class="profile-v20-unlock-grid">${profileV201UnlockCards()}</div>
    </div>`;
}
function profileV201SaveEditor(){const profile=profileV201Read();profile.name=String($('profileV20Name')?.value||'プレイヤー').trim().slice(0,20)||'プレイヤー';profile.bio=String($('profileV20Bio')?.value||'').trim().slice(0,200);profile.upperId=String($('profileV20Upper')?.value||profile.upperId);profile.lowerId=String($('profileV20Lower')?.value||profile.lowerId);profile.favoritePlatforms=Array.from(document.querySelectorAll('[data-profile-v201-platform]')).map(element=>String(element.value||'')).filter((value,index,array)=>value&&array.indexOf(value)===index).slice(0,3);profile.favoriteGames=Array.from(document.querySelectorAll('[data-profile-v201-game]')).map(element=>String(element.value||'')).filter((value,index,array)=>value&&array.indexOf(value)===index).slice(0,3);profileV201Write(profile);profileV201EditorOpen=false;render();toast('二つ名を保存しました');}
function profileV201Choose(kind,id){const defs=profileV201DefsWithRemote(kind==='upper'?PROFILE_V201_UPPER:PROFILE_V201_LOWER);const def=defs.find(item=>item.id===id);if(!def||!profileV201Unlocked(def)) return;const profile=profileV201Read();if(kind==='upper') profile.upperId=id;else profile.lowerId=id;profileV201Write(profile);render();}
function profileV201QuickPartButtons(defs,selected,kind){
  const available=profileV201Available(defs);
  if(!available.length) return '<div class="quick-nickname-empty">まだ獲得した候補がありません。</div>';
  return available.map(def=>`<button type="button" class="profile-v20-part quick-nickname-choice ${selected===def.id?'active':''}" data-profile-v201-kind="${kind}" data-profile-v201-id="${def.id}" title="${profileV201Esc(def.origin)}">${profileV201Esc(def.text)}</button>`).join('');
}
