/* V20.2.28 好きなゲーム：17,000件DBでも固まらない軽量予測変換 */
const PROFILE_V201_GAME_SEARCH_MIN_CHARS=2;
const PROFILE_V201_GAME_SEARCH_DELAY=280;
const PROFILE_V201_GAME_SEARCH_LIMIT=10;
const profileV201GameCandidateCache=new Map();
let profileV201GameSearchTimer=0;
let profileV201GameSearchSequence=0;

function profileV201TrimGameCandidateCache(){
  while(profileV201GameCandidateCache.size>80){
    const first=profileV201GameCandidateCache.keys().next().value;
    profileV201GameCandidateCache.delete(first);
  }
}
function profileV201CloseGameSuggestions(exceptInput=null){
  document.querySelectorAll('[data-quick-profile-game-menu]').forEach(menu=>{
    const wrap=menu.closest('.quick-profile-game-autocomplete');
    const input=wrap?.querySelector('[data-quick-profile-game]');
    if(exceptInput&&input===exceptInput) return;
    menu.hidden=true;
    menu.innerHTML='';
    input?.setAttribute('aria-expanded','false');
    input?.removeAttribute('aria-activedescendant');
    input?.removeAttribute('aria-busy');
  });
}
function profileV201GameCandidates(query){
  const qKey=titleKey(String(query||'').trim());
  if(qKey.length<PROFILE_V201_GAME_SEARCH_MIN_CHARS) return [];
  if(profileV201GameCandidateCache.has(qKey)) return profileV201GameCandidateCache.get(qKey).slice();

  const rows=getMasterSearchIndex().all;
  const matches=[];
  for(let rowIndex=0;rowIndex<rows.length;rowIndex++){
    const row=rows[rowIndex];
    let score=0;
    for(let keyIndex=0;keyIndex<row.titleKeys.length;keyIndex++){
      const key=row.titleKeys[keyIndex];
      if(key===qKey){score=500;break;}
      if(key.startsWith(qKey)) score=Math.max(score,380-Math.min(100,key.length-qKey.length));
      else if(key.includes(qKey)) score=Math.max(score,270-Math.min(80,key.length-qKey.length));
      else if(qKey.length>=4&&qKey.startsWith(key)) score=Math.max(score,190-Math.min(60,qKey.length-key.length));
    }
    if(!score&&qKey.length>=3&&row.searchKey.includes(qKey)) score=120;
    if(score) matches.push({master:row.master,score});
  }

  const result=matches
    .sort((a,b)=>b.score-a.score||String(a.master.platform||'').localeCompare(String(b.master.platform||''),'ja')||String(a.master.canonicalTitle||'').localeCompare(String(b.master.canonicalTitle||''),'ja'))
    .slice(0,PROFILE_V201_GAME_SEARCH_LIMIT)
    .map(item=>item.master);
  profileV201GameCandidateCache.set(qKey,result);
  profileV201TrimGameCandidateCache();
  return result.slice();
}
function profileV201RenderGameSuggestions(input,expectedValue=''){
  if(!input||!input.isConnected) return;
  const wrap=input.closest('.quick-profile-game-autocomplete');
  const menu=wrap?.querySelector('[data-quick-profile-game-menu]');
  if(!menu) return;
  const query=String(input.value||'').trim();
  if(expectedValue&&query!==expectedValue) return;
  const qKey=titleKey(query);
  profileV201CloseGameSuggestions(input);
  input.removeAttribute('aria-busy');
  if(qKey.length<PROFILE_V201_GAME_SEARCH_MIN_CHARS){
    menu.hidden=true;
    menu.innerHTML='';
    input.setAttribute('aria-expanded','false');
    return;
  }
  const candidates=profileV201GameCandidates(query);
  if(!candidates.length){
    menu.hidden=true;
    menu.innerHTML='';
    input.setAttribute('aria-expanded','false');
    return;
  }
  menu.innerHTML=candidates.map((master,index)=>`
    <button type="button" class="quick-profile-game-candidate" data-quick-profile-game-choice="${profileV201Esc(master.canonicalTitle||'')}" role="option" id="quickProfileGameCandidate${input.dataset.profileGameIndex||'0'}_${index}">
      <strong>${profileV201Esc(master.canonicalTitle||'')}</strong>
      <span>${profileV201Esc(master.platform||'機種不明')}${master.maker?` / ${profileV201Esc(master.maker)}`:''}</span>
    </button>`).join('');
  menu.hidden=false;
  input.setAttribute('aria-expanded','true');
}
function profileV201ScheduleGameSuggestions(input,immediate=false){
  if(!input) return;
  clearTimeout(profileV201GameSearchTimer);
  const sequence=++profileV201GameSearchSequence;
  const expectedValue=String(input.value||'').trim();
  const qKey=titleKey(expectedValue);
  if(qKey.length<PROFILE_V201_GAME_SEARCH_MIN_CHARS){
    profileV201CloseGameSuggestions();
    return;
  }
  input.setAttribute('aria-busy','true');
  profileV201GameSearchTimer=setTimeout(()=>{
    if(sequence!==profileV201GameSearchSequence||!input.isConnected) return;
    profileV201RenderGameSuggestions(input,expectedValue);
  },immediate?20:PROFILE_V201_GAME_SEARCH_DELAY);
}
function profileV201SelectGameCandidate(button){
  const wrap=button?.closest('.quick-profile-game-autocomplete');
  const input=wrap?.querySelector('[data-quick-profile-game]');
  if(!input) return;
  clearTimeout(profileV201GameSearchTimer);
  profileV201GameSearchSequence++;
  input.value=String(button.dataset.quickProfileGameChoice||'');
  input.dispatchEvent(new Event('change',{bubbles:true}));
  profileV201CloseGameSuggestions();
  input.focus();
}
document.addEventListener('input',event=>{
  const input=event.target.closest?.('[data-quick-profile-game]');
  if(!input) return;
  profileV201ScheduleGameSuggestions(input,false);
},true);
document.addEventListener('focusin',event=>{
  const input=event.target.closest?.('[data-quick-profile-game]');
  if(!input) return;
  if(titleKey(input.value).length>=PROFILE_V201_GAME_SEARCH_MIN_CHARS) profileV201ScheduleGameSuggestions(input,true);
},true);
document.addEventListener('keydown',event=>{
  const input=event.target.closest?.('[data-quick-profile-game]');
  if(!input) return;
  const menu=input.closest('.quick-profile-game-autocomplete')?.querySelector('[data-quick-profile-game-menu]');
  if(!menu||menu.hidden) return;
  const buttons=Array.from(menu.querySelectorAll('[data-quick-profile-game-choice]'));
  if(!buttons.length) return;
  let active=buttons.findIndex(button=>button.classList.contains('active'));
  if(event.key==='ArrowDown'||event.key==='ArrowUp'){
    event.preventDefault();
    active=event.key==='ArrowDown'?(active+1)%buttons.length:(active<=0?buttons.length-1:active-1);
    buttons.forEach((button,index)=>button.classList.toggle('active',index===active));
    buttons[active].scrollIntoView({block:'nearest'});
    input.setAttribute('aria-activedescendant',buttons[active].id);
    return;
  }
  if(event.key==='Enter'&&active>=0){
    event.preventDefault();
    profileV201SelectGameCandidate(buttons[active]);
    return;
  }
  if(event.key==='Escape'){
    event.preventDefault();
    clearTimeout(profileV201GameSearchTimer);
    profileV201GameSearchSequence++;
    profileV201CloseGameSuggestions();
  }
},true);
document.addEventListener('click',event=>{
  const choice=event.target.closest?.('[data-quick-profile-game-choice]');
  if(choice){
    event.preventDefault();
    event.stopPropagation();
    profileV201SelectGameCandidate(choice);
    return;
  }
  if(!event.target.closest?.('.quick-profile-game-autocomplete')) profileV201CloseGameSuggestions();
},true);
window.addEventListener('fujiya:product-master-updated',()=>{
  profileV201GameCandidateCache.clear();
  profileV201CloseGameSuggestions();
});

setTimeout(()=>{profileV201RenameNavigation();if(state.activeTab==='growth')profileV201RenderPanel();},0);

