    function makeAvatarThumbnail(source){
      return new Promise(resolve=>{
        const value=String(source||'');
        if(!/^data:image\//i.test(value)){resolve('');return;}
        const img=new Image();
        img.onload=()=>{
          try{
            const maxSide=160;
            const ratio=Math.min(1,maxSide/img.width,maxSide/img.height);
            const width=Math.max(1,Math.round(img.width*ratio));
            const height=Math.max(1,Math.round(img.height*ratio));
            const canvas=document.createElement('canvas');
            canvas.width=width;
            canvas.height=height;
            const ctx=canvas.getContext('2d');
            ctx.drawImage(img,0,0,width,height);
            let out=canvas.toDataURL('image/webp',.68);
            if(out.length>48000)out=canvas.toDataURL('image/jpeg',.58);
            resolve(out.length<=60000?out:'');
          }catch(error){resolve('');}
        };
        img.onerror=()=>resolve('');
        img.src=value;
      });
    }
